#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define GPIO_CE0 8
#define ADC_CHANNEL 0

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int spi_fd, adc_value;
    struct timespec ts;
    uint8_t tx[3] = {1, 0x80 | (ADC_CHANNEL >> 4), ADC_CHANNEL << 4};
    uint8_t rx[3];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if ((spi_fd = spiOpen(0, SPI_SPEED, SPI_CHANNEL)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_CE0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        spiClose(spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        gpioWrite(GPIO_CE0, PI_LOW);
        if (spiXfer(spi_fd, tx, rx, sizeof(tx)) != sizeof(tx)) {
            fprintf(stderr, "Failed to transfer data via SPI\n");
            break;
        }
        gpioWrite(GPIO_CE0, PI_HIGH);

        adc_value = ((rx[1] & 3) << 8) | rx[2];
        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%ld.%09ld: ADC value: %d\n", ts.tv_sec, ts.tv_nsec, adc_value);

        sleep(1);
    }

    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_DEVICE "/dev/spidev0.0"

#define FLAME_SENSOR_GPIO 4
#define MCP3008_CE_GPIO 8

#define ADC_CHANNEL 0
#define ADC_REF_VOLTAGE 3.3
#define ADC_RESOLUTION 1024

#define FLAME_DETECTED_THRESHOLD 500

static bool running = true;

void sigint_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *flame_sensor_line, *mcp3008_ce_line;
    int spi_fd, ret;
    uint8_t tx[3] = {1, 0x84, 0};
    uint8_t rx[3];
    int adc_value;
    float temperature;
    FILE *file;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    mcp3008_ce_line = gpiod_chip_get_line(chip, MCP3008_CE_GPIO);
    if (!mcp3008_ce_line) {
        fprintf(stderr, "Failed to get MCP3008 CE line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = fopen("flame_data.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open flame_data.csv\n");
        close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Flame Detected,Temperature\n");

    while (running) {
        struct timespec ts;
        bool flame_detected;
        char timestamp[26];

        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        ret = gpiod_line_set_value(flame_sensor_line, 0);
        if (ret < 0) {
            fprintf(stderr, "Failed to set flame sensor line\n");
            continue;
        }

        ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request flame sensor line\n");
            continue;
        }

        flame_detected = gpiod_line_get_value(flame_sensor_line) > 0;

        gpiod_line_release(flame_sensor_line);

        tx[1] = 0x84 | (ADC_CHANNEL >> 2);
        tx[2] = (ADC_CHANNEL << 6);

        ret = write(spi_fd, tx, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to SPI device\n");
            continue;
        }

        ret = read(spi_fd, rx, 3);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from SPI device\n");
            continue;
        }

        adc_value = ((rx[1] & 0x0F) << 8) | rx[2];
        temperature = (adc_value * ADC_REF_VOLTAGE) / ADC_RESOLUTION;

        fprintf(file, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);

        sleep(1);
    }

    fclose(file);
    close(spi_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <i2c/smbus.h>
#include <linux/i2c-dev.h>

#define FLAME_SENSOR 4
#define HEAT_SENSOR 0
#define BUZZER 27
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define LOG_FILE "fire_log.txt"
#define FLAME_THRESHOLD 1
#define TEMP_THRESHOLD 60
#define POLLING_INTERVAL 0.1
#define DEBOUNCE_TIME 0.05
#define BUZZ_DURATION 2

int running = 1;
int flame_detected = 0;
int temp_detected = 0;
int buzzer_on = 0;
time_t start_time;

FILE *log_file;

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_file;
    int temp_value;
    int flame_value;
    int ret;

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, FLAME_SENSOR);
    if (!line) {
        fprintf(stderr, "Failed to get line for flame sensor\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request input for flame sensor\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize I2C
    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = ioctl(i2c_file, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_file);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize buzzer
    line = gpiod_chip_get_line(chip, BUZZER);
    if (!line) {
        fprintf(stderr, "Failed to get line for buzzer\n");
        close(i2c_file);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line, "buzzer", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output for buzzer\n");
        close(i2c_file);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_file);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Read flame sensor
        flame_value = gpiod_line_get_value(line);
        if (flame_value == FLAME_THRESHOLD) {
            flame_detected = 1;
            start_time = time(NULL);
        } else if (flame_detected && time(NULL) - start_time > DEBOUNCE_TIME) {
            flame_detected = 0;
        }

        // Read temperature sensor
        temp_value = i2c_smbus_read_word_data(i2c_file, HEAT_SENSOR);
        if (temp_value < 0) {
            fprintf(stderr, "Failed to read temperature sensor\n");
            continue;
        }

        temp_value = temp_value >> 8;
        if (temp_value > TEMP_THRESHOLD) {
            temp_detected = 1;
            start_time = time(NULL);
        } else if (temp_detected && time(NULL) - start_time > DEBOUNCE_TIME) {
            temp_detected = 0;
        }

        // Check for fire condition
        if (flame_detected && temp_detected) {
            if (!buzzer_on) {
                gpiod_line_set_value(line, 1);
                buzzer_on = 1;
                start_time = time(NULL);
            } else if (time(NULL) - start_time > BUZZ_DURATION) {
                gpiod_line_set_value(line, 0);
                buzzer_on = 0;
            }

            fprintf(log_file, "Fire detected at %ld\n", time(NULL));
        } else if (flame_detected) {
            fprintf(log_file, "Flame detected at %ld\n", time(NULL));
        } else if (temp_detected) {
            fprintf(log_file, "Temperature above threshold at %ld\n", time(NULL));
        }

        // Sleep for a bit
        usleep(POLLING_INTERVAL * 1000000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_FAN 18
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_CHIP_NAME_PI5 "gpiochip5"
#define ADC_THRESHOLD 0x7FF  // 1023 in decimal
#define LOG_FILE "current_log.txt"

int spi_fd, gpio_fd;
struct spi_ioc_transfer spi_xfer;
uint8_t rx[3];

void cleanup() {
    if (spi_fd >= 0) close(spi_fd);
    if (gpio_fd >= 0) close(gpio_fd);
    gpio_fan(0);
}

void gpio_fan(int state) {
    struct gpiod_line_request req;
    struct gpiod_line *line = gpiod_chip_get_line(gpio_fd, GPIO_FAN);
    gpiod_line_request_input(line, "fan_control");
    gpiod_line_set_value(line, state);
}

void log_current(char *timestamp, uint16_t current) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    fprintf(file, "%s: %d\n", timestamp, current);
    fclose(file);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open SPI device\n");
        return -1;
    }

    int mode = SPI_MODE_0;
    int bits = 8;
    int speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        printf("Failed to configure SPI device\n");
        return -1;
    }

    if ((gpio_fd = gpiod_chip_open_by_name(GPIO_CHIP_NAME_PI5)) < 0) {
        gpio_fd = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    }
    if (gpio_fd < 0) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    while (1) {
        memset(rx, 0, sizeof(rx));
        spi_xfer.tx_buf = 0;
        spi_xfer.rx_buf = (unsigned long)rx;
        spi_xfer.len = 3;
        spi_xfer.delay_usecs = 0;
        spi_xfer.speed_hz = speed;
        spi_xfer.bits_per_word = bits;
        spi_xfer.cs_change = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            printf("Failed to read from SPI device\n");
            continue;
        }

        uint16_t current = (rx[1] << 8) | rx[2];
        if (current == 0 || current == 0xFFFF) {
            printf("Sensor absent\n");
            continue;
        }

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strcspn(timestamp, "\n")] = 0;
        log_current(timestamp, current);

        gpio_fan(current > ADC_THRESHOLD);
        sleep(1);
    }

    cleanup();
    return 0;
}

