FILE *alert_log_file;

void close_files_and_exit() {
    fclose(co_log_file);
    fclose(alert_log_file);
    gpioTerminate();
    exit(0);
}

void handle_signal(int signum) {
    close_files_and_exit();
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t buffer[4];
    int16_t co_value, no2_value;
    float co_ppm;

    // Initialize GPIO and I2C
    chip = gpiochip_open(0);
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        printf("Failed to get GPIO line\n");
        gpiochip_close(chip);
        return -1;
    }

    if (gpio_request(line, "i2c") < 0) {
        printf("Failed to request GPIO line\n");
        gpiochip_close(chip);
        return -1;
    }

    if (gpio_direction_input(line) < 0) {
        printf("Failed to set GPIO line direction\n");
        gpiochip_close(chip);
        return -1;
    }

    if (gpio_i2c_open(line, I2C_BUS, I2C_ADDRESS) < 0) {
        printf("Failed to open I2C bus\n");
        gpiochip_close(chip);
        return -1;
    }

    // Open log files
    co_log_file = fopen("co_log.txt", "w");
    if (!co_log_file) {
        printf("Failed to open CO log file\n");
        gpiochip_close(chip);
        return -1;
    }

    alert_log_file = fopen("alert_log.txt", "w");
    if (!alert_log_file) {
        printf("Failed to open alert log file\n");
        fclose(co_log_file);
        gpiochip_close(chip);
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        // Read CO and NO2 values
        if (gpio_i2c_read_device(line, buffer, 4) < 0) {
            printf("Failed to read from I2C device\n");
            close_files_and_exit();
        }

        co_value = (buffer[1] << 8) | buffer[0];
        no2_value = (buffer[3] << 8) | buffer[2];

        // Convert CO value to ppm
        co_ppm = (float)co_value / 65536 * 2000;

        // Log CO value
        fprintf(co_log_file, "%f\n", co_ppm);

        // Check for alert
        if (co_ppm >= ALERT_THRESHOLD) {
            fprintf(alert_log_file, "CO alert: %f ppm\n", co_ppm);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

