    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    int h = i2cOpen(1, I2C_ADDRESS, 0);
    if (h < 0) {
        printf("i2cOpen failed\n");
        gpioTerminate();
        return 1;
    }

    FILE *file = fopen("audio_log.txt", "w");
    if (file == NULL) {
        printf("Failed to open file\n");
        gpioTerminate();
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int64_t start_time = ts.tv_sec;

    while (1) {
        int16_t left = 0, right = 0;
        int ret = i2cReadDevice(h, (char*)&left, sizeof(left));
        if (ret != sizeof(left)) {
            fprintf(file, "%ld, -999.0\n", (long)(ts.tv_sec - start_time));
        } else {
            ret = i2cReadDevice(h, (char*)&right, sizeof(right));
            if (ret != sizeof(right)) {
                fprintf(file, "%ld, -999.0\n", (long)(ts.tv_sec - start_time));
            } else {
                int16_t avg = (left + right) / 2;
                fprintf(file, "%ld, %d\n", (long)(ts.tv_sec - start_time), avg);
            }
        }

        fflush(file);
        clock_nanosleep(CLOCK_REALTIME, 0, (struct timespec){.tv_sec = 0, .tv_nsec = 100000000L}, NULL);
    }

    fclose(file);
    i2cClose(h);
    gpioTerminate();
    return 0;
}

