#define ADS1115_CONVERT 0x01
#define ADS1115_CONFIG 0x01
#define ADS1115_DRATE_10SPS 0x08
#define ADS1115_PGA_4_096V 0x00
#define MLX91204_LSB 0.00125

#define GPIO17 17
#define GPIO2 2
#define GPIO3 3

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd, ret;
    uint16_t raw;
    float current;
    float sum = 0;
    int count = 0;
    float avg;

    // Initialize GPIO17
    chip = gpiod_chip_open_by_name("gpiochip0");
    line = gpiod_chip_get_line(chip, GPIO17);
    gpiod_line_request_output(line, "blink", 0);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    // Configure ADS1115
    uint16_t config = ADS1115_CONVERT | ADS1115_DRATE_10SPS | ADS1115_PGA_4_096V;
    ret = i2c_smbus_write_word_data(i2c_fd, ADS1115_CONFIG, config);
    if (ret < 0) {
        perror("Failed to write config to ADS1115");
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!stop) {
        // Read from ADS1115
        ret = i2c_smbus_read_word_data(i2c_fd, ADS1115_CONVERT);
        if (ret < 0) {
            perror("Failed to read from ADS1115");
            return 1;
        }

        raw = ret;
        current = raw * MLX91204_LSB;

        // Add to sum and count
        sum += current;
        count++;

        // Check if average exceeds threshold
        if (count == 100) {
            avg = sum / 100;
            if (avg > 50.0) {
                gpiod_line_set_value(line, 1);
            }
            sum = 0;
            count = 0;
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Turn off LED
    gpiod_line_set_value(line, 0);

    // Close I2C and GPIO
    close(i2c_fd);
    gpiod_chip_close(chip);

    return 0;
}

