#include <gpiod.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_ID 0x44

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static int consecutive_failures = 0;

static void cleanup(void) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum + 128);
}

static int i2c_write_byte(uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    if (write(i2c_fd, buffer, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_byte(uint8_t reg, uint8_t *data) {
    if (write(i2c_fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(i2c_fd, data, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_sensor_values(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buffer[8];
    if (i2c_write_byte(0x80 | 0x94, 0x01) != 0) {
        return -1;
    }
    usleep(3000);
    if (i2c_write_byte(0x80 | 0x94, 0x00) != 0) {
        return -1;
    }
    if (i2c_read_byte(0x80 | 0x94, buffer) != 0) {
        return -1;
    }
    *clear = (buffer[1] << 8) | buffer[2];
    *red = (buffer[3] << 8) | buffer[4];
    *green = (buffer[5] << 8) | buffer[6];
    *blue = (buffer[7] << 8) | buffer[8];
    return 0;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
