    }

    uint8_t id;
    if (i2c_read_byte(0x80 | 0x92, &id) != 0 || id != TCS34725_ID) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return 1;
    }

    csv_file = fopen("color_log.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    fprintf(csv_file, "Timestamp,clear,red,green,blue\n");

    while (1) {
        uint16_t clear, red, green, blue;
        if (read_sensor_values(&clear, &red, &green, &blue) != 0) {
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Failed to read sensor values\n");
                return 1;
            }
        } else {
            consecutive_failures = 0;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);

        sleep(1);
    }

    cleanup();
    return 0;
}

