    uint8_t rx[3];

    if (spi_xfer(spi_fd, tx, rx, 3) < 0) {
        write_log("Error reading sensor 1");
        return;
    }

    int sensor1_value = ((rx[1] & 3) << 8) | rx[2];

    tx[1] = (SENSOR2_CHANNEL << 4) | 0x08;
    if (spi_xfer(spi_fd, tx, rx, 3) < 0) {
        write_log("Error reading sensor 2");
        return;
    }

    int sensor2_value = ((rx[1] & 3) << 8) | rx[2];

    char buffer[256];
    time_t now = time(NULL);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    write_log(buffer);
    sprintf(buffer, "%d,%d", sensor1_value, sensor2_value);
    write_log(buffer);
}

