        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;
    spi.speed_hz = SPI_SPEED;
    spi.delay_usecs = SPI_DELAY;
    spi.bits_per_word = SPI_BITS;
    spi.cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to get SPI mode\n");
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "Failed to get SPI bits per word\n");
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
