#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define CURRENT_THRESHOLD 10.0

static int spi_fd;
static int motor_shutdown_fd;
static FILE *log_file;

void cleanup() {
    if (spi_fd >= 0) close(spi_fd);
    if (motor_shutdown_fd >= 0) gpiod_line_release(motor_shutdown_fd);
    if (log_file) fclose(log_file);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

uint16_t read_adc() {
    uint8_t tx[3] = {1, (ADC_CHANNEL >> 8) & 0x07, ADC_CHANNEL & 0xff};
    uint8_t rx[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = sizeof(tx),
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI IOCTL failed");
        return 0;
    }
    return (rx[1] << 8) | rx[2];
}

float convert_to_amperes(uint16_t adc_value) {
    // Conversion formula depends on the specific MLX91211 sensor
    // This is a placeholder formula
    return (float)adc_value / 4095.0 * 20.0;
}

void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file);
}

int main() {
    struct sigaction sigact;
    sigact.sa_handler = handle_sigint;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    motor_shutdown_fd = gpiod_open_line("gpiochip0", MOTOR_SHUTDOWN_PIN, 0);
    if (!motor_shutdown_fd) {
        perror("Failed to open motor shutdown GPIO line");
        return 1;
    }

    log_file = fopen("current_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    gpiod_line_set_value(motor_shutdown_fd, 1);

    while (true) {
        uint16_t adc_value = read_adc();
        float current = convert_to_amperes(adc_value);
        log_current(current);

        if (current > CURRENT_THRESHOLD) {
            gpiod_line_set_value(motor_shutdown_fd, 0);
            log_current(current);
            sleep(1);
            gpiod_line_set_value(motor_shutdown_fd, 1);
        }

        sleep(1);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x28
#define LOG_FILE_NAME "pressure_log.csv"

static gpiod_chip *chip;
static gpiod_line *scl, *sda;
static FILE *log_file;
static int sensor_present = 1;

void cleanup_and_exit(int exit_code) {
    if (scl) gpiod_line_release(scl);
    if (sda) gpiod_line_release(sda);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    exit(exit_code);
}

void signal_handler(int signum) {
    cleanup_and_exit(0);
}

int main() {
    struct timespec sleep_time = {.tv_sec = 1, .tv_nsec = 0};
    uint8_t reg = 0x00;
    uint8_t data[2];
    char timestamp[26];
    char log_line[50];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup_and_exit(1);
    }

    // Request lines for SCL and SDA
    scl = gpiod_chip_get_line(chip, 5);
    sda = gpiod_chip_get_line(chip, 4);
    if (!scl || !sda) {
        fprintf(stderr, "Failed to get I2C lines\n");
        cleanup_and_exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(1);
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Pressure(kPa)\n");

    while (1) {
        // Read from sensor
        if (gpiod_i2c_transfer(scl, sda, SENSOR_ADDRESS, &reg, 1, data, 2) != 2) {
            if (sensor_present) {
                fprintf(stderr, "Failed to read from sensor, register: 0x%02X, error: %s\n", reg, strerror(errno));
                sensor_present = 0;
            }
            continue;
        }

        // Sensor is present again
        if (!sensor_present) {
            sensor_present = 1;
        }

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));

        // Write to log file
        snprintf(log_line, sizeof(log_line), "%s,%d.%d\n", timestamp, data[0], data[1]);
        if (fputs(log_line, log_file) == EOF) {
            fprintf(stderr, "Failed to write to log file\n");
            cleanup_and_exit(1);
        }

        // Flush log file
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file\n");
            cleanup_and_exit(1);
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    cleanup_and_exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDRESS 0x48
#define MLX90834_CHANNEL 0x00
#define NTC_CHANNEL 0x01
#define GPIO17 17
#define PRESSURE_THRESHOLD 105.0

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup() {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "warning_led", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (true) {
        uint16_t pressure, temperature;
        int retry_count = 3;

        while (retry_count--) {
            if (write(i2c_fd, &MLX90834_CHANNEL, 1) != 1 || read(i2c_fd, &pressure, 2) != 2) {
                fprintf(stderr, "Failed to read pressure from sensor\n");
                continue;
            }

            if (write(i2c_fd, &NTC_CHANNEL, 1) != 1 || read(i2c_fd, &temperature, 2) != 2) {
                fprintf(stderr, "Failed to read temperature from sensor\n");
                continue;
            }

            break;
        }

        if (retry_count < 0) {
            fprintf(stderr, "Failed to read sensor data after retries\n");
            continue;
        }

        float pressure_kpa = (pressure >> 3) * 0.1875;
        float temperature_c = (temperature >> 3) * 0.125;

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kpa, temperature_c);

        if (pressure_kpa > PRESSURE_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod/gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define MAX_CURRENT 10.0
#define LOG_FILE "current_log.txt"

int main() {
    int spi_fd, adc_value;
    struct spi_ioc_transfer spi_xfer;
    FILE *log_file;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    bool overcurrent = false;

    // Initialize SPI
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)&ADC_CHANNEL;
    spi_xfer.rx_buf = (unsigned long)&adc_value;
    spi_xfer.len = sizeof(adc_value);
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = 8;
    spi_xfer.cs_change = 1;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 27);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(line, "motor_shutdown", 0);

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!overcurrent) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
            perror("Failed to transfer SPI data");
            break;
        }

        // Check for overcurrent
        if (adc_value > MAX_CURRENT) {
            overcurrent = true;
            fprintf(log_file, "OVERCURRENT at %ld\n", time(NULL));
            gpiod_line_set_value(line, 1);
        }

        // Log the current reading
        fprintf(log_file, "Current reading: %d at %ld\n", adc_value, time(NULL));
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
