#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "methane_log.txt"
#define ALARM_THRESHOLD 1000

int spi_fd;
FILE *log_file;

void close_spi() {
    close(spi_fd);
    fclose(log_file);
}

void handle_signal(int signum) {
    close_spi();
    exit(signum);
}

int main() {
    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)malloc(3);
    spi.rx_buf = (unsigned long)malloc(3);
    spi.len = 3;
    spi.delay_usecs = 0;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = 8;
    spi.cs_change = 0;
    spi.pad = 0;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
            perror("Failed to transfer SPI message");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char buffer[20];

        time(&rawtime);
        timeinfo = localtime_r(&rawtime, buffer);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s %d\n", buffer, spi.rx_buf[1] << 8 | spi.rx_buf[2]);

        if (spi.rx_buf[1] << 8 | spi.rx_buf[2] > ALARM_THRESHOLD) {
            fprintf(stderr, "ALARM: Methane concentration exceeds threshold\n");
        }

        sleep(1);
    }

    free(spi.tx_buf);
    free(spi.rx_buf);
    close_spi();

    return 0;
}

