#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADC_CHANNEL 0
#define PRESSURE_MIN 0
#define PRESSURE_MAX 100000
#define LOG_FILE "pressure_log.txt"

int main() {
    int i2c_fd, adc_fd;
    uint16_t adc_value;
    float pressure;
    struct timespec ts;
    struct gpiod_chip *chip;
    struct gpiod_line_request req;
    struct gpiod_line *line;

    // Open I2C bus
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open ADC channel
    if ((adc_fd = open("/sys/bus/iio/devices/iio:device0/in_voltage0_raw", O_RDONLY)) < 0) {
        perror("Failed to open ADC channel");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    chip = gpiod_chip_open("/dev/gpiochip0");
    line = gpiod_chip_get_line(chip, 18);
    memset(&req, 0, sizeof(req));
    req.consumer = "pressure_sensor";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    gpiod_line_request(line, &req, 0);

    // Main loop
    while (true) {
        // Read ADC value
        if (read(adc_fd, &adc_value, sizeof(adc_value)) < 0) {
            perror("Failed to read ADC value");
            break;
        }

        // Convert ADC value to pressure
        pressure = (float)adc_value / 65536 * (PRESSURE_MAX - PRESSURE_MIN) + PRESSURE_MIN;

        // Check if pressure is within valid range
        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            // Get current time
            clock_gettime(CLOCK_REALTIME, &ts);

            // Log pressure and timestamp
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Failed to open log file");
                break;
            }
            fprintf(log_file, "%ld.%09ld %f\n", ts.tv_sec, ts.tv_nsec, pressure);
            fclose(log_file);
        }

        // Wait for next sample
        usleep(1000000);
    }

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(adc_fd);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

