    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec sleep_time = {1, 0}; // sleep for 1 second
    int i2c_fd;
    uint16_t ir, red;
    int error;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open GPIO chip and line for I2C SCL
    chip = gpiod_chip_open("/dev/gpiochip0");
    line = gpiod_chip_get_line(chip, 5); // GPIO 5
    gpiod_line_request_output(line, "i2c_scl", 0);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Write header to log file
    fprintf(log_file, "Unix timestamp,HR (bpm),SpO₂ (%),Error flag\n");

    // Main loop
    while (running) {
        // Read IR and RED values from sensor
        error = si1172_read(i2c_fd, SI1172_ADDRESS, &ir, &red);
        if (error) {
            // Log error and continue
            fprintf(log_file, "%ld,0,0,1\n", time(NULL));
            continue;
        }

        // Log raw values
        fprintf(log_file, "%ld,%d,%d,0\n", time(NULL), ir, red);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C device and GPIO line
    close(i2c_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Close log file
    fclose(log_file);

    return EXIT_SUCCESS;
}

