#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0

int main() {
    int spi_fd;
    uint8_t tx_buffer[3] = {1, 0x84, 0};
    uint8_t rx_buffer[3];
    float voltage, flow_rate;
    time_t timer;
    struct tm* time_info;
    char time_string[26];
    FILE* log_file;

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("flow_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Send the ADC read command
        if (spiXfer(spi_fd, tx_buffer, rx_buffer, 3) != 3) {
            fprintf(stderr, "Failed to read ADC\n");
            break;
        }

        // Convert the ADC value to voltage
        voltage = (rx_buffer[1] << 8 | rx_buffer[2]) * 3.3 / 4095;

        // Convert the voltage to flow rate
        flow_rate = voltage / 0.002; // Assuming 2mV/L/min

        // Validate the flow rate
        if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
            fprintf(stderr, "Flow rate out of range: %f\n", flow_rate);
            continue;
        }

        // Get the current time
        timer = time(NULL);
        time_info = localtime(&timer);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Log the measurement
        fprintf(log_file, "%s,%f\n", time_string, flow_rate);
        fflush(log_file);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_fd);

    return EXIT_SUCCESS;
}

