        return EXIT_FAILURE;
    }

    fprintf(csv_fd, "Timestamp,Pressure (Pa),Temperature (C)\n");

    while (running) {
        uint8_t buffer[6];
        int ret;

        ret = write(i2c_fd, buffer, 1);
        if (ret < 0) {
            perror("Failed to write to I2C device");
            continue;
