#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define LOG_FILE "moisture_log.txt"

int spi_fd;
FILE *log_file;

void cleanup(int signum) {
    close(spi_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct timespec ts = {60, 0}; // 60 seconds
    uint8_t tx[3] = {1, 0x80 | (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];
    int adc_value;
    char timestamp[26];
    struct tm *gmtm;
    time_t now;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpioTerminate();
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        close(spi_fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (write(spi_fd, tx, sizeof(tx)) != sizeof(tx)) {
            fprintf(stderr, "Failed to write to SPI device\n");
            cleanup(EXIT_FAILURE);
        }

        if (read(spi_fd, rx, sizeof(rx)) != sizeof(rx)) {
            fprintf(stderr, "Failed to read from SPI device\n");
            cleanup(EXIT_FAILURE);
        }

        adc_value = ((rx[1] & 3) << 8) | rx[2];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            cleanup(EXIT_FAILURE);
        }

        time(&now);
        gmtm = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtm);

        if (fprintf(log_file, "%s,%d\n", timestamp, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            cleanup(EXIT_FAILURE);
        }

        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file\n");
            cleanup(EXIT_FAILURE);
        }

        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define ADC_CHANNEL 0
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define FLAME_LOG_FILE "flame_log.txt"
#define BUZZER_GPIO 18
#define SAMPLE_INTERVAL 500

int main() {
    int spi_fd, gpio_fd;
    struct spi_ioc_transfer spi_xfer;
    unsigned char tx_buf[3] = {1, 0x08, 0};
    unsigned char rx_buf[3];
    float ambient_temp = 25.0;
    FILE *log_file;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret, i;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    // Open GPIO device
    gpio_fd = gpiod_chip_open_by_name("gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        return -1;
    }

    // Get buzzer line
    line = gpiod_chip_get_line(gpio_fd, BUZZER_GPIO);
    if (!line) {
        perror("Failed to get buzzer line");
        return -1;
    }

    // Set buzzer line to output
    ret = gpiod_line_request_output(line, "buzzer", 0);
    if (ret < 0) {
        perror("Failed to set buzzer line to output");
        return -1;
    }

    // Open log file
    log_file = fopen(FLAME_LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    // Read ambient temperature
    FILE *temp_file = fopen(AMBIENT_TEMP_FILE, "r");
    if (temp_file) {
        fscanf(temp_file, "%f", &ambient_temp);
        fclose(temp_file);
    }

    // Main loop
    while (1) {
        // Perform SPI transfer
        spi_xfer.tx_buf = (unsigned long)tx_buf;
        spi_xfer.rx_buf = (unsigned long)rx_buf;
        spi_xfer.len = 3;
        spi_xfer.delay_usecs = SPI_DELAY;
        spi_xfer.speed_hz = SPI_SPEED;
        spi_xfer.bits_per_word = SPI_BITS;
        spi_xfer.cs_change = 0;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            fprintf(log_file, "Failed to perform SPI transfer\n");
            continue;
        }

        // Check ADC value
        int adc_value = (rx_buf[1] << 8) | rx_buf[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(log_file, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Perform temperature compensation
        float voltage = adc_value / 1024.0 * 3.3;
        float compensated_voltage = voltage / (1 + 0.0005 * (ambient_temp - 25));

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(log_file, "%s,%d,%.2f,%.2f,%.2f,%d\n", timestamp, adc_value, voltage, compensated_voltage, ambient_temp, adc_value > 500);

        // Set buzzer state
        gpiod_line_set_value(line, adc_value > 500);

        // Sleep for a while
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(gpio_fd);
    close(spi_fd);

    return 0;
}

