#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define LED_PIN 17
#define WATER_LEVEL_PIN 8
#define WATER_LEVEL_THRESHOLD_HIGH 75
#define WATER_LEVEL_THRESHOLD_LOW 70
#define JSON_FILE_NAME "water_levels.json"
#define READ_INTERVAL 5
#define SLEEP_INCREMENT 100

int spi_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *json_file;

void cleanup() {
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);
    fclose(json_file);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = &handle_sigint;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get LED line\n");
        return 1;
    }

    if (gpiod_line_request_output(line, "water_level_led", 0)) {
        fprintf(stderr, "Failed to request LED line as output\n");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return 1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to get SPI mode\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &SPI_BITS) < 0) {
        fprintf(stderr, "Failed to get SPI bits per word\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to get SPI speed\n");
        return 1;
    }

    json_file = fopen(JSON_FILE_NAME, "w");
    if (!json_file) {
        fprintf(stderr, "Failed to open JSON file\n");
        return 1;
    }

    fprintf(json_file, "[");

    while (1) {
        uint8_t tx[3] = {1, 0, 0};
        uint8_t rx[3];

        if (write(spi_fd, tx, 3) != 3) {
            fprintf(stderr, "Failed to write to SPI device\n");
            continue;
        }

        if (read(spi_fd, rx, 3) != 3) {
            fprintf(stderr, "Failed to read from SPI device\n");
            continue;
        }

        int percentage = (rx[1] << 8) | rx[2];
        percentage = (percentage * 100) / 1024;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T.%3z", t);

        fprintf(stdout, "%s: %d%%\n", timestamp, percentage);
        fprintf(json_file, "{\"timestamp\":\"%s\",\"percentage\":%d},", timestamp, percentage);

        if (percentage > WATER_LEVEL_THRESHOLD_HIGH) {
            gpiod_line_set_value(line, 1);
        } else if (percentage < WATER_LEVEL_THRESHOLD_LOW) {
            gpiod_line_set_value(line, 0);
        }

        usleep(SLEEP_INCREMENT * 1000);
    }

    cleanup();
    return 0;
}

