#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define SENSOR_THRESHOLD 512
#define LOG_FILE "soil_moisture.log"

int spi_fd;
FILE *log_file;

void cleanup(int signum) {
    close(spi_fd);
    fclose(log_file);
    printf("Exiting...\n");
    exit(0);
}

int main(int argc, char *argv[]) {
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {1, 0x80 | (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];
    int interval = 1;
    int moisture;

    if (argc > 1) {
        interval = atoi(argv[1]);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        memset(rx, 0, sizeof(rx));
        tr.tx_buf = (unsigned long)tx;
        tr.rx_buf = (unsigned long)rx;
        tr.len = sizeof(tx);
        tr.delay_usecs = 0;
        tr.speed_hz = SPI_SPEED;
        tr.bits_per_word = 8;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to send SPI message");
            continue;
        }

        moisture = ((rx[1] & 3) << 8) | rx[2];
        if (moisture < 0 || moisture > ADC_MAX) {
            printf("Invalid ADC value: %d\n", moisture);
            continue;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

        fprintf(log_file, "%s, %d, %d\n", timestamp, moisture, (int)((100.0 / ADC_MAX) * moisture));

        sleep(interval);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
