#include <sys/types.h>
#include <sys/stat.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define SOIL_MOISTURE_MAX 1000

static int spi_fd = -1;
static bool running = true;

static void cleanup(int signum) {
    running = false;
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(signum);
}

static int open_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to configure SPI device");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc() {
    uint8_t tx[3] = {1, (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];

    if (write(spi_fd, tx, 3) != 3) {
        perror("Failed to write to SPI device");
        return -1;
    }

    if (read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from SPI device");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

static void print_moisture(int adc_value) {
    if (adc_value < 0) {
        printf("Error reading ADC\n");
        return;
    }

    float voltage = adc_value * 3.3 / ADC_MAX;
    float moisture = voltage * SOIL_MOISTURE_MAX / 3.3;

    printf("ADC: %d, Voltage: %.2fV, Moisture: %.2f%%\n", adc_value, voltage, moisture);
}

int main() {
    struct sigaction sa = {
        .sa_handler = cleanup,
    };

    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (open_spi() < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        int adc_value = read_adc();
        print_moisture(adc_value);
        sleep(5);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
