#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define ADC_CHANNEL 0
#define PRESSURE_SENSOR_VOLTAGE 3.3
#define ADC_MAX_VALUE 1023
#define PRESSURE_SENSOR_MAX_VALUE 4095
#define PRESSURE_SENSOR_MIN_VALUE 0

int main(int argc, char *argv[]) {
    int spiHandle;
    int adcValue;
    float pressure;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if ((spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        printf("Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if ((adcValue = spiTransfer(spiHandle, ADC_CHANNEL)) < 0) {
            printf("Failed to read from ADC\n");
            spiClose(spiHandle);
            return EXIT_FAILURE;
        }

        pressure = (float)adcValue / ADC_MAX_VALUE * PRESSURE_SENSOR_VOLTAGE;
        pressure = (pressure - PRESSURE_SENSOR_MIN_VALUE) / (PRESSURE_SENSOR_MAX_VALUE - PRESSURE_SENSOR_MIN_VALUE) * PRESSURE_SENSOR_VOLTAGE;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        printf("%s Pressure: %f\n", buffer, pressure);

        sleep(1);
    }

    spiClose(spiHandle);
    return EXIT_SUCCESS;
}

