void log_entry(int moisture_level, int pump_state) {
    time(&buffer[buffer_head].timestamp);
    buffer[buffer_head].moisture_level = moisture_level;
    buffer[buffer_head].pump_state = pump_state;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

void print_buffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_head + i) % BUFFER_SIZE;
        printf("%ld: Moisture level: %d, Pump state: %d\n", buffer[index].timestamp, buffer[index].moisture_level, buffer[index].pump_state);
    }
}

