        uint8_t tx[] = {0x01, 0x80 | VH400_CHANNEL << 4, 0x00};
        uint8_t rx[3];

        bcm2835_gpio_write(WATER_PUMP_PIN, WATER_PUMP_OFF);

        if (!bcm2835_spi_transfernb(tx, rx, sizeof(tx))) {
            printf("bcm2835_spi_transfernb failed.\n");
            continue;
