        int moisture_level = ((rx[1] & 0x0F) << 8) | rx[2];

        if (moisture_level < LOW_THRESHOLD) {
            bcm2835_gpio_write(WATER_PUMP_PIN, WATER_PUMP_ON);
        } else if (moisture_level > HIGH_THRESHOLD) {
            bcm2835_gpio_write(WATER_PUMP_PIN, WATER_PUMP_OFF);
        }

