    gpiod_chip_close(chip);
    close(spi_fd);
}

void sigint_handler(int signum) {
    printf("Caught SIGINT, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    buzzer = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer) {
        fprintf(stderr, "Failed to get buzzer line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(buzzer, &buzzer_request)) {
        fprintf(stderr, "Failed to request buzzer line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
