        uint8_t tx[3] = {1, (ADC_CHANNEL << 4), 0};
        uint8_t rx[3];

        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            cleanup();
            return EXIT_FAILURE;
        }

        int adc_value = (rx[1] << 8) | rx[2];
        bool buzzer_on = adc_value >= ADC_THRESHOLD;

        if (gpiod_line_set_value(buzzer, buzzer_on)) {
            fprintf(stderr, "Failed to set buzzer value\n");
            cleanup();
            return EXIT_FAILURE;
        }

        usleep(SPI_READ_DELAY * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

