        fprintf(log_file, "Moisture reading: %d\n", value);

        if (value < threshold) {
            if (!pump_on) {
                pump_on = 1;
                gpiod_line_set_value(line, 1);
                req.tv_sec = pump_duration;
                req.tv_nsec = 0;
                nanosleep(&req, &rem);
                gpiod_line_set_value(line, 0);
                pump_on = 0;
                fprintf(log_file, "Pump activated for %d seconds\n", pump_duration);
            }
        }

        req.tv_sec = sleep_interval;
        req.tv_nsec = 0;
        nanosleep(&req, &rem);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
