#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL 10000 // 10ms

int spi_fd;
int log_fd;

void cleanup() {
    close(spi_fd);
    close(log_fd);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
        .delay_usecs = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to configure SPI device");
        return -1;
    }

    return 0;
}

int log_init() {
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0666);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

int spi_read(int channel, uint16_t *value) {
    uint8_t tx[3] = {1, (channel << 4), 0};
    uint8_t rx[3];

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("Failed to read from SPI device");
        return -1;
    }

    memcpy(rx, &tx[1], 2);
    *value = (rx[0] << 8) | rx[1];

    return 0;
}

int log_write(const char *message) {
    if (write(log_fd, message, strlen(message)) < 0) {
        perror("Failed to write to log file");
        return -1;
    }

    return 0;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if (spi_init() < 0) {
        return -1;
    }

    if (log_init() < 0) {
        return -1;
    }

    atexit(cleanup);

    while (1) {
        uint16_t value;
        if (spi_read(ADC_CHANNEL, &value) < 0) {
            return -1;
        }

        char message[256];
        time_t now = time(NULL);
        strftime(message, sizeof(message), "%FT%TZ ", gmtime(&now));
        sprintf(message + strlen(message), "%d\n", value);

        if (log_write(message) < 0) {
            return -1;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

