#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDRESS 0x48
#define PCF8591_CHANNEL 0

static int i2c_fd = -1;
static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static int open_i2c_bus() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

static int set_i2c_address(uint8_t address) {
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C address");
        return -1;
    }
    return 0;
}

static int read_i2c_byte(uint8_t *data) {
    if (read(i2c_fd, data, 1) != 1) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

static void close_i2c_bus() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    if (open_i2c_bus() < 0) {
        return EXIT_FAILURE;
    }

    if (set_i2c_address(PCF8591_ADDRESS) < 0) {
        close_i2c_bus();
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t data;
        if (read_i2c_byte(&data) < 0) {
            close_i2c_bus();
            return EXIT_FAILURE;
        }
        printf("ADC value: %d\n", data);
        usleep(100000); // sleep for 100ms
    }

    close_i2c_bus();
    return EXIT_SUCCESS;
}

