#define ADC_MAX 4095
#define VOLTAGE_MAX 3.3
#define GAUSS_THRESHOLD 500

static gpiod_chip *chip;
static int adc_fd;
static int buffer_size = 60;
static int buffer_index = 0;
static int buffer[60] = {0};

void cleanup() {
    gpiod_set_value(chip, GPIO_PIN, 0);
    gpiod_chip_close(chip);
    close(adc_fd);
    closelog();
}

