    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    openlog("Hall Sensor", LOG_PID, LOG_USER);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line_request req = {
        .consumer = "Hall Sensor",
        .request_type = GPIO_REQUEST_OUTPUT,
        .flags = 0
    };

    if (gpiod_chip_get_line(chip, GPIO_PIN) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(chip, GPIO_PIN, &req) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line");
        return EXIT_FAILURE;
    }

    gpiod_set_value(chip, GPIO_PIN, 0);

    adc_fd = open("/dev/i2c-1", O_RDWR);
    if (adc_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(adc_fd, I2C_SLAVE, 0x48) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address");
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t value = i2c_smbus_read_word_data(adc_fd, ADC_CHANNEL);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue;
        }

        float voltage = (float)value / ADC_MAX * VOLTAGE_MAX;
        if (voltage < 0 || voltage > VOLTAGE_MAX) {
            syslog(LOG_ERR, "Invalid voltage value");
            continue;
        }

        int gauss = voltage * 1000; // Assuming 1mV/Gauss
        buffer[buffer_index] = gauss;
        buffer_index = (buffer_index + 1) % buffer_size;

        int sum = 0;
        for (int i = 0; i < buffer_size; i++) {
            sum += buffer[i];
        }

        int average = sum / buffer_size;
        if (average > GAUSS_THRESHOLD) {
            gpiod_set_value(chip, GPIO_PIN, 1);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

