        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    uint8_t tx[3] = {1, (1 << 6) | (ADC_CHANNEL << 3), 0};
    uint8_t rx[3];

    while (running) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            fprintf(stderr, "Failed to perform SPI transfer\n");
            continue;
        }

        memcpy(rx, &xfer.rx_buf, 3);
        uint16_t adc_value = (rx[1] << 8) | rx[2];

        uint32_t pwm_value = (uint32_t)((double)adc_value / 1023.0 * PWM_RANGE);
        pwm_value = (pwm_value * PWM_FREQ) / 1000;

        printf("ADC: %u, PWM: %u\n", adc_value, pwm_value);

        gpiod_line_set_value(pwm_pin, 1);
        usleep(pwm_value);
        gpiod_line_set_value(pwm_pin, 0);
        usleep(PWM_RANGE - pwm_value);

        usleep(ADC_READ_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

