#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0
#define SPI_CS 8
#define SPI_CLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define VDD 3.3
#define VREF 3.3

int spi_fd;
struct spi_ioc_transfer spi_xfer;

void cleanup() {
    if (spi_fd >= 0) close(spi_fd);
}

void error_exit(const char *msg) {
    perror(msg);
    cleanup();
    exit(EXIT_FAILURE);
}

void setup_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) error_exit("Failed to open SPI device");

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) error_exit("Failed to set SPI mode");

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) error_exit("Failed to set SPI speed");

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) error_exit("Failed to set SPI bits per word");

    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)malloc(3);
    spi_xfer.rx_buf = (unsigned long)malloc(3);
    spi_xfer.len = 3;
    spi_xfer.delay_usecs = 0;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = 8;
}

void read_adc() {
    uint8_t tx_data[3] = {1, (SPI_CHANNEL << 6), 0};
    memcpy((void *)spi_xfer.tx_buf, tx_data, 3);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) error_exit("Failed to read from ADC");

    uint16_t raw_value = ((uint16_t)spi_xfer.rx_buf[1] << 8) | spi_xfer.rx_buf[2];
    float voltage = (VREF / 1024.0) * raw_value;

    printf("Raw value: %d, Voltage: %.2f V\n", raw_value, voltage);
}

int main() {
    atexit(cleanup);
    signal(SIGINT, exit);

    setup_spi();

    while (true) {
        read_adc();
        usleep(500000);
    }

    return 0;
}

