int running = 1;

void cleanup() {
    running = 0;
    gpiod_set_value(motor1_fd, 0);
    gpiod_set_value(motor2_fd, 0);
    close(spi_fd);
    gpiod_close(motor1_fd);
    gpiod_close(motor2_fd);
    printf("Cleanup complete\n");
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    motor1_fd = gpiod_open_by_number(MOTOR1_PIN, GPIOD_OPEN_AS_OUTPUT);
    if (!motor1_fd) {
        perror("Failed to open motor1 pin");
        return -1;
    }

    motor2_fd = gpiod_open_by_number(MOTOR2_PIN, GPIOD_OPEN_AS_OUTPUT);
    if (!motor2_fd) {
        perror("Failed to open motor2 pin");
        return -1;
    }

    while (running) {
        uint8_t tx[] = {0x01, 0x80};
        uint8_t rx[2];
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), tx);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            continue;
        }

        int noise_level = (rx[0] << 8) | rx[1];
        if (noise_level > THRESHOLD) {
            gpiod_set_value(motor1_fd, 1);
            gpiod_set_value(motor2_fd, 1);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file) {
                fprintf(log_file, "Vibration event at %ld\n", time(NULL));
                fclose(log_file);
            }
        } else {
            gpiod_set_value(motor1_fd, 0);
            gpiod_set_value(motor2_fd, 0);
        }

        usleep(10000);
    }

    cleanup();
    return 0;
}

