#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define GPIO_PIN 17
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 30
#define RETRIES 3

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {1, 0x40 | (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];
    int spi_fd, ret, i;
    bool pump_on = false;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    // Set up GPIO line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        goto cleanup_chip;
    }

    // Set up SPI transfer
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = sizeof(tx);
    tr.delay_usecs = SPI_DELAY;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;

    // Main loop
    while (true) {
        // Read from ADC
        for (i = 0; i < RETRIES; i++) {
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
            if (ret < 0) {
                perror("Failed to read from ADC");
                continue;
            }

            // Check if below threshold
            if ((rx[1] & 0x0F) < ADC_THRESHOLD) {
                if (!pump_on) {
                    // Turn on pump
                    gpiod_line_set_value(line, 1);
                    pump_on = true;
                }
            } else {
                if (pump_on) {
                    // Turn off pump
                    gpiod_line_set_value(line, 0);
                    pump_on = false;
                }
            }

            // Log reading
            printf("Moisture reading: %d%%\n", (rx[1] & 0x0F) * 100 / 0x0F);
            break;
        }

        // Wait for 60 seconds
        sleep(60);
    }

cleanup_chip:
    gpiod_chip_close(chip);

cleanup:
    close(spi_fd);

    return EXIT_FAILURE;
}

