                    pump_on = false;
                }
            }

            // Log reading
            printf("Moisture reading: %d%%\n", (rx[1] & 0x0F) * 100 / 0x0F);
            break;
        }

        // Wait for 60 seconds
        sleep(60);
    }

cleanup_chip:
    gpiod_chip_close(chip);

cleanup:
    close(spi_fd);

    return EXIT_FAILURE;
}
