#define SAMPLE_INTERVAL 5
#define LOG_FILE "soil_data.txt"

static int spi_fd = -1;
static bool running = true;

static void signal_handler(int signum) {
    running = false;
}

static int open_spi() {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
        .pad = 0
    };

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        close(spi_fd);
        return -1;
    }

    return 0;
}

static int close_spi() {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    return 0;
}

static int read_adc() {
    uint8_t tx[3] = {1, (8 + ADC_CHANNEL) << 4, 0};
    uint8_t rx[3] = {0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
        .pad = 0
    };

    for (int i = 0; i < SPI_MAX_RETRIES; i++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 3) << 8) + rx[2];
        }
        usleep((1 << i) * 1000);
    }

    return -1;
}

static int write_log(const char *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        return -1;
    }

    fprintf(file, "%s\n", data);
    fclose(file);
    return 0;
}

static int main() {
    struct sigaction action;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1000000};
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    char buffer[256];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (line == NULL) {
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "spi_ce0", 0) < 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    if (open_spi() < 0) {
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    while (running) {
        clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL);

        int value = read_adc();
        if (value < 0) {
            sprintf(buffer, "Error reading ADC");
        } else {
            int percent = (value - ADC_MIN_VALUE) * (MOISTURE_MAX_PERCENT - MOISTURE_MIN_PERCENT) / (ADC_MAX_VALUE - ADC_MIN_VALUE) + MOISTURE_MIN_PERCENT;
            sprintf(buffer, "ADC value: %d, Moisture percent: %d", value, percent);
        }

        write_log(buffer);
    }

    close_spi();
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

