#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define RETRIES 3
#define RETRY_DELAY 100
#define LOW_THRESHOLD 20
#define HIGH_THRESHOLD 50

int main(int argc, char *argv[]) {
    FILE *log_file;
    int spi_fd, adc_value, i;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        printf("Error opening SPI channel\n");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("alcohol_log.txt", "a")) == NULL) {
        printf("Error opening log file\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(8, PI_OUTPUT);

    while (1) {
        for (i = 0; i < RETRIES; i++) {
            adc_value = spiTransfer(spi_fd, ADC_CHANNEL << 4);
            if (adc_value >= 0 && adc_value <= 1023) {
                break;
            }
            usleep(RETRY_DELAY * 1000);
        }

        if (i == RETRIES) {
            printf("Failed to read ADC value\n");
            continue;
        }

        time(&rawtime);
        timeinfo = gmtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        fprintf(log_file, "%s: %d\n", buffer, adc_value);

        if (adc_value == 0 || adc_value == 1023) {
            printf("Sensor absent\n");
        } else if (adc_value < LOW_THRESHOLD) {
            printf("Sobriety confirmed.\n");
        } else if (adc_value > HIGH_THRESHOLD) {
            printf("Alcohol detected! Limit exceeded.\n");
        } else {
            printf("Alcohol level within acceptable range.\n");
        }

        sleep(1);
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

