int main() {
    struct timespec ts = {60, 0};
    uint8_t tx[3] = {1, 0, 0};
    uint16_t rx;
    int moisture;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return EXIT_FAILURE;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI interface\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        cleanup(EXIT_FAILURE);
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        tx[1] = (SPI_CHANNEL >> 8) & 0x07;
        tx[2] = SPI_CHANNEL & 0xff;

        if (write(spi_fd, tx, 3) != 3) {
            fprintf(stderr, "Failed to write to SPI interface\n");
            continue;
        }

        if (read(spi_fd, &rx, 2) != 2) {
            fprintf(stderr, "Failed to read from SPI interface\n");
            continue;
        }

        moisture = ((rx & 0x0fff) - 0.5) * 1000 / 1024;

        if (moisture < THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        time_t now = time(NULL);
        char *timestamp = ctime(&now);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove newline

        fprintf(log_fd, "%s, Moisture: %d, Pump: %s\n", timestamp, moisture, gpioRead(RELAY_PIN) ? "ON" : "OFF");

        nanosleep(&ts, NULL);
    }

    return EXIT_SUCCESS;
}

