#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define GPIO_LED 17
#define NOISE_SAMPLES 50
#define SOUND_THRESHOLD 500
#define DEBOUNCE_TIME 0.01

static gpiod_chip *chip;
static gpiod_line *led_line;
static int spi_fd;

void cleanup_and_exit(int status) {
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    close(spi_fd);
    gpiod_chip_close(chip);
    exit(status);
}

void handle_sigint(int signum) {
    printf("SIGINT received, cleaning up and exiting...\n");
    cleanup_and_exit(0);
}

int main() {
    struct sigaction sigact;
    sigact.sa_handler = handle_sigint;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(led_line, "sound_detector", 0) < 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    int noise_sum = 0;
    for (int i = 0; i < NOISE_SAMPLES; i++) {
        uint8_t tx[3] = {1, 0, SPI_CHANNEL << 6};
        tr.tx_buf = (unsigned long)tx;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "Failed to read from SPI device\n");
            cleanup_and_exit(EXIT_FAILURE);
        }
        noise_sum += tx[1] << 8 | tx[2];
        usleep(1000);
    }

    int noise_level = noise_sum / NOISE_SAMPLES;
    printf("Calibrated noise level: %d\n", noise_level);

    int last_sample = 0;
    while (1) {
        uint8_t tx[3] = {1, 0, SPI_CHANNEL << 6};
        tr.tx_buf = (unsigned long)tx;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            fprintf(stderr, "Failed to read from SPI device\n");
            cleanup_and_exit(EXIT_FAILURE);
        }
        int sample = tx[1] << 8 | tx[2];
        if (sample > noise_level + SOUND_THRESHOLD && sample != last_sample) {
            gpiod_line_set_value(led_line, 1);
            usleep(DEBOUNCE_TIME * 1000000);
            gpiod_line_set_value(led_line, 0);
            last_sample = sample;
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
