#include <bcm2835.h>
#include <wiringPiSPI.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL 100 // ms
#define ADC_CHANNEL 0
#define LOG_FILE "airflow_log.txt"

static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int spi_fd;
    FILE *log_file;
    uint16_t adc_value;
    float voltage, airflow;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    // Setup signal handler for graceful exit on SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "ERROR: Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        fprintf(stderr, "ERROR: Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if ((spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED)) < 0) {
        fprintf(stderr, "ERROR: Failed to open SPI\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read ADC value
        if (wiringPiSPIDataRW(SPI_CHANNEL, &adc_value, 2) < 0) {
            fprintf(stderr, "ERROR: ADC read failed\n");
            continue;
        }

        // Convert ADC value to voltage
        voltage = (float)adc_value / 1024.0;

        // Convert voltage to airflow using calibration curve
        // This is a placeholder for the actual conversion formula
        airflow = voltage * 1000.0;

        // Get current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log reading to file
        fprintf(log_file, "%s, %.2f\n", buffer, airflow);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(log_file);
    wiringPiSPIDataRW(SPI_CHANNEL, NULL, 0);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

