#define SPI_SPEED 1000
#define SPI_MODE 0
#define SPI_BITS 8
#define GPIO_MCP3008_CS 8
#define GPIO_MCP3008_MOSI 10
#define GPIO_MCP3008_MISO 9
#define GPIO_MCP3008_SCLK 11
#define ADC_CHANNEL 0
#define LOG_FILE "audio_log.txt"

int main() {
    int spi_fd, log_fd;
