    bcm2835_gpio_fsel(GPIO_MCP3008_MISO, BCM2835_GPIO_FSEL_INPT);
    bcm2835_gpio_fsel(GPIO_MCP3008_SCLK, BCM2835_GPIO_FSEL_OUTP);

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return -1;
    }

    // Configure SPI transfer
    memset(&spi_xfer, 0, sizeof(spi_xfer));
    spi_xfer.tx_buf = (unsigned long)tx_buf;
    spi_xfer.rx_buf = (unsigned long)rx_buf;
    spi_xfer.len = 3;
    spi_xfer.delay_usecs = 0;
    spi_xfer.speed_hz = SPI_SPEED;
    spi_xfer.bits_per_word = SPI_BITS;

    // Main loop
    while (1) {
        // Request ADC sample
        tx_buf[0] = 0x01 | (ADC_CHANNEL >> 2);
        tx_buf[1] = (ADC_CHANNEL << 6);
        tx_buf[2] = 0x00;
        bcm2835_gpio_write(GPIO_MCP3008_CS, LOW);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
