        // Read ADC sample
        raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC_RAW, &sleep_time);

        // Write to log file
        char log_line[64];
        sprintf(log_line, "%lld|%u\n", sleep_time.tv_sec * 1000000000LL + sleep_time.tv_nsec, raw_adc_value);
        write(log_fd, log_line, strlen(log_line));

        // Sleep until next sample
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, &remaining_time);
    }

    // Release resources
    close(spi_fd);
    close(log_fd);
    bcm2835_close();

    return 0;
