#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 30
#define LOG_FILE "watering.log"

void log_event(const char *event) {
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strcspn(time_str, "\n")] = 0;
    FILE *log = fopen(LOG_FILE, "a");
    fprintf(log, "[%s] %s\n", time_str, event);
    fclose(log);
}

void error(const char *msg) {
    perror(msg);
    log_event(msg);
    exit(EXIT_FAILURE);
}

int main() {
    log_event("Program started");

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) error("Failed to open GPIO chip");

    struct gpiod_line *pump_line = gpiod_chip_get_line(chip, PUMP_GPIO);
    if (!pump_line) error("Failed to get pump GPIO line");

    if (gpiod_line_request_output(pump_line, "Pump", 0)) error("Failed to request pump GPIO line as output");

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) error("Failed to open SPI device");

    struct spi_ioc_transfer spi_xfer = {
        .tx_buf = (unsigned long)&ADC_CHANNEL,
        .rx_buf = (unsigned long)&ADC_CHANNEL,
        .len = 1,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) error("Failed to send SPI message");

    int adc_value = ADC_CHANNEL;
    int pump_on = 0;

    struct sigaction sigint_action = {
        .sa_handler = SIG_DFL
    };

    struct sigaction sigterm_action = {
        .sa_handler = SIG_DFL
    };

    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigterm_action, NULL);

    while (1) {
        if (adc_value < ADC_THRESHOLD && !pump_on) {
            if (gpiod_line_set_value(pump_line, 1)) error("Failed to set pump GPIO line to high");
            pump_on = 1;
            log_event("Pump turned on");
        } else if (adc_value >= ADC_THRESHOLD && pump_on) {
            if (gpiod_line_set_value(pump_line, 0)) error("Failed to set pump GPIO line to low");
            pump_on = 0;
            log_event("Pump turned off");
        }

        sleep(60);
    }

    gpiod_line_release(pump_line);
    gpiod_chip_close(chip);
    close(spi_fd);
    log_event("Program terminated");
    return 0;
}

