        json_object *led_state_obj;
        if(!json_object_object_get_ex(parsed_json, "led_state", &led_state_obj)) {
            fprintf(stderr, "Key 'led_state' not found in JSON\n");
            return;
        }
        if(!json_object_is_type(led_state_obj, json_type_boolean)) {
            fprintf(stderr, "Value of 'led_state' is not a boolean\n");
            return;
