        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop) {
        // Wait for event
        if (gpiod_line_event_wait(line, &event) < 0) {
            perror("Failed to wait for event");
            break;
        }

        // Log event
        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        sprintf(log_message, "%s: Vibration detected\n", buffer);

        if (fwrite(log_message, 1, strlen(log_message), log_file) != strlen(log_message)) {
            perror("Failed to write to log file");
            break;
        }

        if (fflush(log_file) != 0) {
            perror("Failed to flush log file");
            break;
        }

        // Print event to stdout
        printf("%s", log_message);

        // Shutdown system
        system("sudo shutdown -h now");
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

