    uint8_t tx[3] = {1, (8 + channel) << 4, 0};
    uint8_t rx[3];

    if (write(spi_fd, tx, 3) != 3 || read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from ADC");
        return -1;
    }

    return ((rx[1] & 3) << 8) | rx[2];
}

