#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <spidev.h>

#define ADC_CHANNEL 0
#define ADC_THRESHOLD 512
#define LED_GPIO 16
#define DEBOUNCE_DELAY 500000
#define SPI_SPEED 1000000
#define SPI_MODE 0

int main(int argc, char *argv[]) {
    int spi_fd, adc_value, ret;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    // Initialize pigpio and spidev
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", ret);
        return EXIT_FAILURE;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set SPI parameters
    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
        .cs_change = 0,
        .pad = 0
    };

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "Failed to set SPI mode: %d\n", ret);
        goto cleanup;
    }

    // Set ADC channel
    tr.tx_buf = (1 << 7) | (ADC_CHANNEL << 4);
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        fprintf(stderr, "Failed to set ADC channel: %d\n", ret);
        goto cleanup;
    }

    // Read ADC value
    ret = read(spi_fd, &adc_value, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to read ADC value: %d\n", ret);
        goto cleanup;
    }

    // Check if ADC value exceeds threshold
    if (adc_value > ADC_THRESHOLD) {
        // Turn on LED
        gpioSetMode(LED_GPIO, PI_OUTPUT);
        gpioWrite(LED_GPIO, PI_HIGH);

        // Log event
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        FILE *file = fopen("sound_events.log", "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            goto cleanup;
        }
        fprintf(file, "%s: Sound detected\n", buffer);
        fclose(file);

        // Apply debounce delay
        usleep(DEBOUNCE_DELAY);
    }

cleanup:
    // Clean up resources
    gpioSetMode(LED_GPIO, PI_INPUT);
    close(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <bcm2835.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RAIN_THRESHOLD 5
#define MOTOR_PIN1 17
#define MOTOR_PIN2 18
#define MOTOR_ENA 27

volatile sig_atomic_t stop_flag = 0;

void signal_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    int spi_fd, log_fd;
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int rain_level;
    struct timespec ts;

    if (!bcm2835_init()) {
        printf("bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        printf("Failed to open SPI device\n");
        bcm2835_close();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) < 0) {
        printf("Failed to set SPI mode\n");
        close(spi_fd);
        bcm2835_close();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        printf("Failed to set SPI speed\n");
        close(spi_fd);
        bcm2835_close();
        return 1;
    }

    if ((log_fd = open("rain_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0666)) < 0) {
        printf("Failed to open log file\n");
        close(spi_fd);
        bcm2835_close();
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        close(log_fd);
        close(spi_fd);
        bcm2835_close();
        return 1;
    }

    gpiod_line_request req = {
        .consumer = "rain_sensor",
        .request_type = GPIO_REQUEST_OUTPUT,
        .default_value = 0,
    };

    gpiod_line *line = gpiod_chip_get_line(chip, MOTOR_PIN1);
    if (!line || gpiod_line_request(line, &req) < 0) {
        printf("Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        close(log_fd);
        close(spi_fd);
        bcm2835_close();
        return 1;
    }

    while (!stop_flag) {
        if (write(spi_fd, tx, 3) != 3) {
            printf("Failed to write to SPI device\n");
            break;
        }

        if (read(spi_fd, rx, 3) != 3) {
            printf("Failed to read from SPI device\n");
            break;
        }

        rain_level = ((rx[1] & 0x0F) << 8) | rx[2];
        clock_gettime(CLOCK_REALTIME, &ts);
        dprintf(log_fd, "%ld.%09ld %d\n", ts.tv_sec, ts.tv_nsec, rain_level);

        if (rain_level > RAIN_THRESHOLD) {
            gpiod_line_set_value(line, 1);
            usleep(3000000);
            gpiod_line_set_value(line, 0);
        } else {
            gpiod_line_set_value(line, 0);
            usleep(3000000);
            gpiod_line_set_value(line, 1);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(log_fd);
    close(spi_fd);
    bcm2835_close();

    return 0;
}

