#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define ADC_PIN 26
#define LED_PIN 16
#define DEBOUNCE_TIME 50 // ms

static struct gpiod_chip *chip;
static struct gpiod_line *adc_line, *led_line;
static int adc_value, last_adc_value;
static struct timespec debounce_start;

static void cleanup() {
    gpiod_line_release(adc_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum) {
    printf("Interrupt received, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    struct gpiod_line_bulk lines;
    int ret;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    if (sigaction(SIGINT, &action, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up ADC line
    adc_line = gpiod_chip_get_line(chip, ADC_PIN);
    if (!adc_line) {
        fprintf(stderr, "Failed to get ADC line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up lines for bulk operations
    ret = gpiod_line_bulk_add(&lines, adc_line, led_line);
    if (ret < 0) {
        fprintf(stderr, "Failed to add lines to bulk operation\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up debounce timer
    clock_gettime(CLOCK_MONOTONIC, &debounce_start);

    // Main loop
    while (1) {
        // Read ADC value
        ret = gpiod_line_get_value(adc_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            cleanup();
            return EXIT_FAILURE;
        }
        adc_value = ret;

        // Check for clap event
        if (adc_value != last_adc_value && clock_gettime(CLOCK_MONOTONIC, &debounce_start) == 0) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (now.tv_sec - debounce_start.tv_sec > DEBOUNCE_TIME / 1000) {
                printf("Clap detected at %ld.%09ld\n", now.tv_sec, now.tv_nsec);
                gpiod_line_set_value(led_line, 1);
                usleep(500000);
                gpiod_line_set_value(led_line, 0);
            }
        }
        last_adc_value = adc_value;

        // Sleep for a short amount of time
        usleep(1000);
    }

    // Clean up
    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200

static void sig_handler(int signum) {
    printf("Caught signal %d, exiting...\n", signum);
    gpiod_unexport(chip, GPIO_PIN);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int distance, ret;
    FILE *log_file;

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "GP2Y0A21YK0F");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    while (1) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            sleep(1);
            continue;
        }

        distance = (ret == 0) ? 1 : 0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s Distance: %d\n", timestamp, distance);
        fflush(log_file);

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <spidev.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define PUMP_PIN 17
#define MOISTURE_THRESHOLD 500
#define SPI_SPEED 500000
#define LOG_FILE "soil_moisture.log"

int spi_fd;
FILE *log_file;

void close_spi() {
    close(spi_fd);
}

void close_log() {
    fclose(log_file);
}

void shutdown(int signum) {
    gpioWrite(PUMP_PIN, 0);
    close_log();
    close_spi();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct timespec sleep_time = {60, 0};
    uint8_t tx[3] = {1, 0x80 | (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];
    int moisture_level;
    int pump_status;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close_spi();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    atexit(close_spi);
    atexit(close_log);
    signal(SIGINT, shutdown);

    while (1) {
        if (write(spi_fd, tx, sizeof(tx)) != sizeof(tx)) {
            fprintf(stderr, "Failed to write to SPI device\n");
            continue;
        }

        if (read(spi_fd, rx, sizeof(rx)) != sizeof(rx)) {
            fprintf(stderr, "Failed to read from SPI device\n");
            continue;
        }

        moisture_level = ((rx[1] & 0x03) << 8) | rx[2];
        pump_status = (moisture_level < MOISTURE_THRESHOLD) ? 1 : 0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, Moisture: %d, Pump: %s\n", timestamp, moisture_level, pump_status ? "ON" : "OFF");

        gpioWrite(PUMP_PIN, pump_status);

        nanosleep(&sleep_time, NULL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 500
#define VOLTAGE_REF 3.3
#define B_mT_per_V 0.001 // Assuming a constant conversion factor

static int spi_fd = -1;
static int log_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_fd != -1) {
        fclose(log_fd);
    }
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    return ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
}

static int read_adc() {
    uint8_t tx[3] = {1, (ADC_CHANNEL << 4), 0};
    uint8_t rx[3];
    if (spi_transfer(tx, rx, sizeof(tx)) < 0) {
        return -1;
    }
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static void log_sample(int adc_value) {
    if (log_fd == -1) {
        log_fd = open("magnetic_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0666);
        if (log_fd == -1) {
            perror("Failed to open log file");
            return;
        }
    }
    if (adc_value < 0) {
        fprintf(stderr, "Failed to read ADC\n");
        return;
    }
    double voltage = adc_value / 1024.0 * VOLTAGE_REF;
    double B_mT = voltage * B_mT_per_V;
    time_t now = time(NULL);
    char buffer[256];
    sprintf(buffer, "%ld,%.2f\n", (long)now, B_mT);
    if (fwrite(buffer, 1, strlen(buffer), log_fd) != strlen(buffer)) {
        perror("Failed to write to log file");
    }
}

int main() {
    atexit(cleanup);
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "magnetic_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    while (true) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("Failed to set GPIO line high");
            return EXIT_FAILURE;
        }
        usleep(SAMPLE_INTERVAL * 1000);
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("Failed to set GPIO line low");
            return EXIT_FAILURE;
        }
        int adc_value = read_adc();
        log_sample(adc_value);
    }

    return EXIT_SUCCESS;
}

