#define LED_PIN 21
#define THRESHOLD 10.0
#define SAMPLE_INTERVAL 100 // in milliseconds

int spi_fd;
FILE *log_file;

void cleanup(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, cleanup);

    spi_fd = spiOpen(SPI_CHANNEL, 500000, 0);
    if (spi_fd < 0) {
        printf("Failed to open SPI interface\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        uint16_t value = spiTransfer(spi_fd, 0x01 | (ADC_CHANNEL << 6), 0x00);
        if (value & 0x8000) {
            printf("Failed to read ADC value\n");
            continue;
        }

        float magnetic_field = (value * 3.3) / 1024.0; // assuming 10-bit ADC

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %.2f mT\n", timestamp, magnetic_field);

        if (magnetic_field > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CS 0

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *file;
    struct timespec ts;
    int spi_fd, adc_value;
    char buffer[100];

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open SPI interface
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        printf("Failed to open SPI interface\n");
        return -1;
    }

    // Open file for logging
    file = fopen("moisture_log.txt", "a");
    if (!file) {
        printf("Failed to open log file\n");
        spiClose(spi_fd);
        return -1;
    }

    while (!stop) {
        // Read ADC value
        adc_value = spiTransfer(spi_fd, SPI_CS, 0x0000, 0x0000);
        if (adc_value < 0) {
            // Log error
            clock_gettime(CLOCK_REALTIME, &ts);
            sprintf(buffer, "%ld-%ld-%ld %ld:%ld:%ld -1\n",
                    ts.tv_sec / (3600 * 24) + 1,
                    (ts.tv_sec / 3600) % 24,
                    (ts.tv_sec / 60) % 60,
                    ts.tv_sec % 60);
            fputs(buffer, file);
        } else {
            // Log value
            clock_gettime(CLOCK_REALTIME, &ts);
            sprintf(buffer, "%ld-%ld-%ld %ld:%ld:%ld %d\n",
                    ts.tv_sec / (3600 * 24) + 1,
                    (ts.tv_sec / 3600) % 24,
                    (ts.tv_sec / 60) % 60,
                    ts.tv_sec % 60,
                    adc_value);
            fputs(buffer, file);
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Close SPI interface
    spiClose(spi_fd);

    // Close file
    fclose(file);

    return 0;
}

