#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define VOLTAGE_THRESHOLD 5.0

volatile sig_atomic_t stop;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int spi_fd;
    uint8_t tx_buffer[3] = {1, 0x80 | (ADC_CHANNEL << 4), 0};
    uint8_t rx_buffer[3];
    float voltage;
    FILE *log_file;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize SPI
    spi_fd = spi_open(0, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        spi_close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Open log file
    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        spi_close(spi_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop) {
        // Send SPI transaction
        if (spi_xfer(spi_fd, tx_buffer, rx_buffer, sizeof(tx_buffer)) < 0) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Calculate voltage
