#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define DEBOUNCE_COUNT 5

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static struct gpiod_line_event events[2];

static void cleanup(int signum) {
    gpiod_line_event_wait(chip, &lines, 0, 0);
    gpiod_line_release_bulk(chip, &lines);
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    struct gpiod_line_bulk lines;
    struct gpiod_line_event events[2];
    int sensor1, sensor2, sensor1_count, sensor2_count;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines = (struct gpiod_line_bulk) {
        .offsets = {SENSOR1_PIN, SENSOR2_PIN},
        .count = 2
    };

    if (gpiod_line_request_bulk(chip, &lines, "sensor_monitor", 0) < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);

    while (1) {
        sensor1_count = 0;
        sensor2_count = 0;

        for (int i = 0; i < DEBOUNCE_COUNT; i++) {
            gpiod_line_event_read(chip, &lines, events, 2);
            sensor1_count += events[0].event_type == GPIOD_LINE_EVENT_RISING_EDGE;
            sensor2_count += events[1].event_type == GPIOD_LINE_EVENT_RISING_EDGE;
            usleep(2000);
        }

        sensor1 = sensor1_count > DEBOUNCE_COUNT / 2;
        sensor2 = sensor2_count > DEBOUNCE_COUNT / 2;

        printf("%d\n", sensor1);
        printf("%d\n", sensor2);

        if (sensor1 && sensor2) {
            printf("ALERT: Both sensors detect object\n");
        }
    }

    cleanup(0);
    return EXIT_SUCCESS;
}

