#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_FORMAT "jpeg"
#define CAPTURE_FILENAME "motion-%Y%m%dT%H%M%S.%03d.jpeg"

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct camera_manager *manager;
static struct camera *camera;
static struct camera_controls controls;
static struct camera_metadata *metadata;
static struct camera_framebuffer *framebuffer;

static void cleanup() {
    if (framebuffer) {
        camera->release_framebuffer(framebuffer);
    }
    if (metadata) {
        free(metadata);
    }
    if (camera) {
        camera_manager_close(manager, camera);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    closelog();
}

static void handle_signal(int signum) {
    running = 0;
}

static int capture_image() {
    int ret;
    char filename[256];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(filename, sizeof(filename), CAPTURE_FILENAME, t);

    ret = snprintf(filename, sizeof(filename), CAPTURE_DIR "%s", filename);
    if (ret < 0 || ret >= sizeof(filename)) {
        syslog(LOG_ERR, "Failed to construct filename");
        return -1;
    }

    ret = camera->capture(camera, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to capture image: %d", ret);
        return -1;
    }

    ret = camera->wait_for_frame(camera, &framebuffer);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to wait for frame: %d", ret);
        return -1;
    }

    ret = camera->save_frame(camera, framebuffer, filename);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to save frame: %d", ret);
        return -1;
    }

    syslog(LOG_INFO, "Image captured and saved as %s", filename);
    return 0;
}

