    char *dev_name = (argc == 2) ? argv[1] : "/dev/video0";
    int frame_number = 1;

    if ((fd = open(dev_name, O_RDWR)) == -1) {
        perror("Cannot open device");
        return EXIT_FAILURE;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Cannot set format");
        return EXIT_FAILURE;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &buf) == -1) {
        perror("Cannot request buffers");
        return EXIT_FAILURE;
    }

    struct v4l2_buffer *buffers = malloc(buf.count * sizeof(*buffers));
    if (!buffers) {
        perror("Cannot allocate memory for buffers");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < buf.count; ++i) {
        CLEAR(buffers[i]);
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].index = i;
        buffers[i].memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) == -1) {
            perror("Cannot query buffer");
            return EXIT_FAILURE;
        }

        void *ptr = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (ptr == MAP_FAILED) {
            perror("Cannot map buffer");
            return EXIT_FAILURE;
        }

        buffers[i].m.userptr = (unsigned long)ptr;
    }

    for (int i = 0; i < buf.count; ++i) {
        if (ioctl(fd, VIDIOC_QBUF, &buffers[i]) == -1) {
            perror("Cannot queue buffer");
            return EXIT_FAILURE;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Cannot start streaming");
        return EXIT_FAILURE;
    }

