        if (r == -1) {
            perror("select");
            return EXIT_FAILURE;
        }

        if (r == 0) {
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            if (errno == EAGAIN) {
                continue;
            } else {
                perror("Cannot dequeue buffer");
                return EXIT_FAILURE;
            }
        }

        char filename[20];
        sprintf(filename, "image_%04d.pgm", frame_number++);
        FILE *file = fopen(filename, "wb");
        if (!file) {
            perror("Cannot open file");
            return EXIT_FAILURE;
        }

        fwrite(buffers[buf.index].m.userptr, 1, buf.bytesused, file);
        fclose(file);

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Cannot queue buffer");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < buf.count; ++i) {
        munmap((void *)buffers[i].m.userptr, buffers[i].length);
    }

    free(buffers);
    close(fd);

    return EXIT_SUCCESS;
}

