#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"

int main() {
    int video_fd = open(VIDEO_DEVICE, O_RDWR);
    if (video_fd < 0) {
        perror("Error opening video device");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(video_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying video device capabilities");
        close(video_fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    if (ioctl(video_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting video format");
        close(video_fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(video_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting video buffers");
        close(video_fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    for (int i = 0; i < req.count; i++) {
        buf.index = i;
        if (ioctl(video_fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying video buffer");
            close(video_fd);
            return EXIT_FAILURE;
        }

        void *mem = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, buf.m.offset);
        if (mem == MAP_FAILED) {
            perror("Error mapping video buffer");
            close(video_fd);
            return EXIT_FAILURE;
        }

        // Start streaming
        if (ioctl(video_fd, VIDIOC_STREAMON, &buf.type) < 0) {
            perror("Error starting video streaming");
            close(video_fd);
            return EXIT_FAILURE;
        }

        // Asynchronous I/O
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(video_fd, &fds);
        struct timeval tv;
        tv.tv_sec = 1;
        tv.tv_usec = 0;
        if (select(video_fd + 1, &fds, NULL, NULL, &tv) > 0) {
            if (ioctl(video_fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("Error dequeuing video buffer");
                close(video_fd);
                return EXIT_FAILURE;
            }

            // Log the timestamp
            struct timeval tv;
            gettimeofday(&tv, NULL);
            FILE *log_file = fopen(FRAME_LOG_FILE, "a");
            if (log_file == NULL) {
                perror("Error opening log file");
                close(video_fd);
                return EXIT_FAILURE;
            }
            fprintf(log_file, "%ld.%06ld\n", tv.tv_sec, tv.tv_usec);
            fclose(log_file);

            // Requeue the buffer
            if (ioctl(video_fd, VIDIOC_QBUF, &buf) < 0) {
                perror("Error queuing video buffer");
                close(video_fd);
                return EXIT_FAILURE;
            }
        }
    }

    // Stop streaming
    if (ioctl(video_fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("Error stopping video streaming");
        close(video_fd);
        return EXIT_FAILURE;
    }

    close(video_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define MAX_FRAGMENTS 16
#define MAX_DATAGRAM_SIZE 65000

typedef struct {
    int index;
    int total_fragments;
    int fragment_index;
    int payload_size;
    char payload[MAX_DATAGRAM_SIZE];
} DatagramHeader;

int main(int argc, char *argv[]) {
    int fd, i;
    struct v4l2_buffer buf;
    struct v4l2_requestbuffers req;
    struct sockaddr_in addr;
    int sock;
    DatagramHeader header;
    char *data;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <target IP> <target port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if ((fd = open("/dev/video0", O_RDWR)) < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("ioctl");
        close(fd);
        return EXIT_FAILURE;
    }

    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("ioctl");
            close(fd);
            return EXIT_FAILURE;
        }

        data = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (data == MAP_FAILED) {
            perror("mmap");
            close(fd);
            return EXIT_FAILURE;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("ioctl");
            close(fd);
            return EXIT_FAILURE;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &req.type) < 0) {
        perror("ioctl");
        close(fd);
        return EXIT_FAILURE;
    }

    if ((sock = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        close(fd);
        return EXIT_FAILURE;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(argv[1]);
    addr.sin_port = htons(atoi(argv[2]));

    while (1) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("ioctl");
            break;
        }

        header.index = buf.index;
        header.total_fragments = req.count;
        header.fragment_index = 0;
        header.payload_size = buf.bytesused;

        if (sendto(sock, &header, sizeof(header), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("sendto");
            break;
        }

        if (sendto(sock, data, buf.bytesused, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("sendto");
            break;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("ioctl");
            break;
        }
    }

    ioctl(fd, VIDIOC_STREAMOFF, &req.type);

    for (i = 0; i < req.count; i++) {
        munmap(data, buf.length);
    }

    close(sock);
    close(fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <signal.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE "/dev/video0"
#define IMAGE_FILE "image.jpg"

int fd = -1;
struct v4l2_buffer buf;
struct v4l2_capability cap;
struct v4l2_format fmt;
unsigned int n_buffers;
struct buffer {
    void *start;
    size_t length;
} *buffers;

void stop_capturing() {
    enum v4l2_buf_type type;
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == ioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
        exit(EXIT_FAILURE);
    }
}

void uninit_device() {
    unsigned int i;
    for (i = 0; i < n_buffers; ++i)
        if (-1 == munmap(buffers[i].start, buffers[i].length))
            perror("munmap");
    free(buffers);
}

void init_mmap() {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (-1 == ioctl(fd, VIDIOC_REQBUFS, &req)) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }
    n_buffers = req.count;
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }
    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = n_buffers;
        if (-1 == ioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            exit(EXIT_FAILURE);
        }
        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }
}

void init_device() {
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = stop_capturing;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);
    if (-1 == ioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        exit(EXIT_FAILURE);
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        exit(EXIT_FAILURE);
    }
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 192;
    fmt.fmt.pix.height = 1080;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (-1 == ioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }
    init_mmap();
    enum v4l2_buf_type type;
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == ioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        exit(EXIT_FAILURE);
    }
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (-1 == ioctl(fd, VIDIOC_DQBUF, &buf)) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }
    if (buf.bytesused <= 0) {
        fprintf(stderr, "No data in buffer\n");
        exit(EXIT_FAILURE);
    }
    FILE *file = fopen(IMAGE_FILE, "wb");
    if (!file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fwrite(buffers[buf.index].start, 1, buf.bytesused, file);
    fclose(file);
}

int main() {
    fd = open(DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }
    init_device();
    uninit_device();
    close(fd);
    return 0;
}

