        if (event.chip == chip && event.line_offset == TILT_UP_BUTTON) {
            tilt_pos = (tilt_pos + TILT_STEP <= TILT_MAX) ? tilt_pos + TILT_STEP : TILT_MAX;
        } else if (event.chip == chip && event.line_offset == TILT_DOWN_BUTTON) {
            tilt_pos = (tilt_pos - TILT_STEP >= TILT_MIN) ? tilt_pos - TILT_STEP : TILT_MIN;
        } else if (event.chip == chip && event.line_offset == PAN_LEFT_BUTTON) {
            pan_pos = (pan_pos - PAN_STEP >= PAN_MIN) ? pan_pos - PAN_STEP : PAN_MIN;
        } else if (event.chip == chip && event.line_offset == PAN_RIGHT_BUTTON) {
            pan_pos = (pan_pos + PAN_STEP <= PAN_MAX) ? pan_pos + PAN_STEP : PAN_MAX;
        }

        gpioSetPWMdutycycle(PAN_SERVO, pan_pos);
        gpioSetPWMdutycycle(TILT_SERVO, tilt_pos);

        usleep(50000);
    }

    gpioSetPWMdutycycle(PAN_SERVO, PAN_CENTER);
    gpioSetPWMdutycycle(TILT_SERVO, TILT_CENTER);

    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <libgpiod.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

int main(int argc, char **argv) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int timeout = 2000000; // 2 seconds
    int r;

    // Open the USB camera
    fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Cannot open /dev/video0");
        return EXIT_FAILURE;
    }

    // Get capabilities of the device
    CLEAR(cap);
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Cannot get capabilities");
        goto cleanup;
    }

    // Request buffers
    CLEAR(req);
    req.count = 4;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Cannot request buffers");
        goto cleanup;
    }

    // Map the buffers
    for (int i = 0; i < req.count; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Cannot query buffer");
            goto cleanup;
        }

        void *ptr = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (ptr == MAP_FAILED) {
            perror("Cannot memory-map buffer");
            goto cleanup;
        }
    }

    // Queue the buffers
    for (int i = 0; i < req.count; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Cannot queue buffer");
            goto cleanup;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Cannot start streaming");
        goto cleanup;
    }

    // Wait for a frame
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    r = select(fd + 1, &fds, NULL, NULL, &timeout);
    if (r == 0) {
        fprintf(stderr, "Timeout occurred\n");
        goto cleanup;
    } else if (r < 0) {
        perror("select");
        goto cleanup;
    }

    // Dequeue the captured frame
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Cannot dequeue buffer");
        goto cleanup;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Cannot stop streaming");
        goto cleanup;
    }

cleanup:
    if (fd >= 0) close(fd);
    return EXIT_SUCCESS;
}

