#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define PAN_PIN 4
#define TILT_PIN 5
#define UP_PIN 6
#define DOWN_PIN 7
#define LEFT_PIN 8
#define RIGHT_PIN 9
#define PAN_CENTER 1500
#define TILT_CENTER 1500
#define PAN_MIN 1000
#define PAN_MAX 2000
#define TILT_MIN 1000
#define TILT_MAX 2000
#define PAN_STEP 10
#define TILT_STEP 10
#define DELAY 50

static gpiod_chip *chip;
static gpiod_line *pan_line;
static gpiod_line *tilt_line;
static gpiod_line_event event;
static int pan_pulse_width = PAN_CENTER;
static int tilt_pulse_width = TILT_CENTER;

static void cleanup() {
    gpiod_line_set_pulsewidth(pan_line, 0);
    gpiod_line_set_pulsewidth(tilt_line, 0);
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_chip_close(chip);
}

static void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    pan_line = gpiod_chip_get_line(chip, PAN_PIN);
    if (!pan_line) {
        fprintf(stderr, "Failed to get line for pan servo\n");
        cleanup();
        return EXIT_FAILURE;
    }

    tilt_line = gpiod_chip_get_line(chip, TILT_PIN);
    if (!tilt_line) {
        fprintf(stderr, "Failed to get line for tilt servo\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Servo control program started\n");
    printf("Pan servo on GPIO%d\n", PAN_PIN);
    printf("Tilt servo on GPIO%d\n", TILT_PIN);
    printf("Center position: Pan %d, Tilt %d\n", PAN_CENTER, TILT_CENTER);

    gpiod_line_request_pwm(pan_line, 50, PAN_CENTER);
    gpiod_line_request_pwm(tilt_line, 50, TILT_CENTER);

    while (1) {
        gpiod_line_event_wait(pan_line, GPIOD_LINE_EVENT_BOTH_EDGES, &event);
        if (event.event_type & GPIOD_LINE_EVENT_RISING_EDGE) {
            if (pan_pulse_width < PAN_MAX) {
                pan_pulse_width += PAN_STEP;
            }
        } else if (event.event_type & GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (pan_pulse_width > PAN_MIN) {
                pan_pulse_width -= PAN_STEP;
            }
        }

        gpiod_line_event_wait(tilt_line, GPIOD_LINE_EVENT_BOTH_EDGES, &event);
        if (event.event_type & GPIOD_LINE_EVENT_RISING_EDGE) {
            if (tilt_pulse_width < TILT_MAX) {
                tilt_pulse_width += TILT_STEP;
            }
        } else if (event.event_type & GPIOD_LINE_EVENT_FALLING_EDGE) {
            if (tilt_pulse_width > TILT_MIN) {
                tilt_pulse_width -= TILT_STEP;
            }
        }

        gpiod_line_set_pulsewidth(pan_line, pan_pulse_width);
        gpiod_line_set_pulsewidth(tilt_line, tilt_pulse_width);

        usleep(DELAY * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

