    }

    struct sigaction sigint_action, sigterm_action;
    sigint_action.sa_handler = handle_sigint;
    sigterm_action.sa_handler = handle_sigterm;
    sigaction(SIGINT, &sigint_action, NULL);
    sigaction(SIGTERM, &sigterm_action, NULL);

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "PIR sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
