        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(line, GPIOD_LINE_FLAG_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    curl_easy_setopt(curl, CURLOPT_URL, HTTP_ENDPOINT);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);

    DIR *dir = opendir("motion_captures");
    if (!dir) {
        mkdir("motion_captures", 0777);
    } else {
        closedir(dir);
    }

    int motion_status = MOTION_NOT_DETECTED;
    struct timespec last_motion_time = {0, 0};
    while (running) {
        int current_motion_status = gpiod_line_get_value(line);
        if (current_motion_status == MOTION_DETECTED && motion_status == MOTION_NOT_DETECTED) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
            if (last_motion_time.tv_sec == 0 || (current_time.tv_sec - last_motion_time.tv_sec) >= MOTION_DETECTED_DURATION) {
                last_motion_time = current_time;
                motion_status = MOTION_DETECTED;
            }
        } else if (current_motion_status == MOTION_NOT_DETECTED) {
            motion_status = MOTION_NOT_DETECTED;
        }

        if (motion_status == MOTION_DETECTED) {
            // Capture image and create JSON payload
            // ...
        }

        sleep(POLLING_INTERVAL);
    }

    gpiod_chip_close(chip);
    curl_easy_cleanup(curl);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 50 // in milliseconds
#define CAPTURE_COMMAND "raspistill -o /home/pi/images/%Y%m%d_%H%M%S_%3N.jpg -w 640 -h 480 -q 85 -t 2000 -n"

FILE *log_file;
gpiod_chip *chip;
gpiod_line *line;
struct timespec debounce_start;

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

void capture_image() {
    char command[256];
    strftime(command, sizeof(command), CAPTURE_COMMAND, localtime(&debounce_start.tv_sec));
    log_event(command);
    int result = system(command);
    if (result != 0) {
        log_event("Capture command failed");
    }
}

void handle_motion_event() {
    clock_gettime(CLOCK_MONOTONIC, &debounce_start);
    struct timespec timeout = {0, 50000000}; // 50ms timeout
    while (1) {
        struct timespec remaining;
        clock_gettime(CLOCK_MONOTONIC, &remaining);
        remaining.tv_sec -= debounce_start.tv_sec;
        remaining.tv_nsec -= debounce_start.tv_nsec;
        if (remaining.tv_nsec < 0) {
            remaining.tv_sec--;
            remaining.tv_nsec += 1000000000;
        }
        if (remaining.tv_sec < 0) {
            break;
        }
        if (nanosleep(&remaining, &timeout) == -1) {
            break;
        }
        if (gpiod_line_event_wait(line, 0) == 0) {
            break;
        }
    }
    capture_image();
}

int main() {
    atexit(cleanup);
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    log_file = fopen("/home/pi/motion_capture.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line, "motion_sensor") != 0) {
        fprintf(stderr, "Failed to request falling edge events\n");
        return EXIT_FAILURE;
    }

    while (1) {
        if (gpiod_line_event_wait(line, 0) == 0) {
            handle_motion_event();
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
