#define WIDTH 640
#define HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_OFFSET_X 0
#define CROP_OFFSET_Y 0

int main() {
    int fd = open("/dev/video0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/video0");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Failed to query buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    void *mem = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (mem == MAP_FAILED) {
        perror("Failed to map buffer");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Failed to queue buffer");
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("Failed to start streaming");
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        perror("select");
        ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (r == 0) {
        printf("Timeout occurred! No data from device.\n");
        ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Failed to dequeue buffer");
        ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (buf.fmt.pix.width != WIDTH || buf.fmt.pix.height != HEIGHT || buf.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        printf("Unexpected frame dimensions or pixel format\n");
        ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    int cropped_fd = open("cropped.yuv", O_WRONLY | O_CREAT, 0666);
    if (cropped_fd < 0) {
        perror("Failed to open cropped.yuv");
        ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
        munmap(mem, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < HEIGHT; i += 2) {
        for (int j = 0; j < WIDTH; j += 2) {
            uint8_t y0 = ((uint8_t *)mem)[i * WIDTH * 2 + j * 2];
            uint8_t u = ((uint8_t *)mem)[i * WIDTH * 2 + j * 2 + 1];
            uint8_t y1 = ((uint8_t *)mem)[(i + 1) * WIDTH * 2 + j * 2];
            uint8_t v = ((uint8_t *)mem)[(i + 1) * WIDTH * 2 + j * 2 + 1];

            if (write(cropped_fd, &y0, 1) < 0 || write(cropped_fd, &u, 1) < 0 || write(cropped_fd, &y1, 1) < 0 || write(cropped_fd, &v, 1) < 0) {
                perror("Failed to write to cropped.yuv");
                close(cropped_fd);
                ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
                munmap(mem, buf.length);
                close(fd);
                return EXIT_FAILURE;
            }
        }
    }

    close(cropped_fd);
    ioctl(fd, VIDIOC_STREAMOFF, &buf.type);
    munmap(mem, buf.length);
    close(fd);

    return EXIT_SUCCESS;
}

