#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <wiringPi.h>
#include <pigpio.h>

#define PAN_PIN 17
#define TILT_PIN 18
#define PAN_CENTER 1500
#define TILT_CENTER 1500
#define PAN_MIN 1000
#define PAN_MAX 2000
#define TILT_MIN 1000
#define TILT_MAX 2000
#define DELAY 100

int pan_pos = PAN_CENTER;
int tilt_pos = TILT_CENTER;

void cleanup() {
    gpioServo(PAN_PIN, PAN_CENTER);
    gpioServo(TILT_PIN, TILT_CENTER);
    gpioTerminate();
    exit(0);
}

void handle_sigint(int signum) {
    cleanup();
}

void move_servo(int pin, int *pos, int min, int max, int step) {
    if (*pos + step < min || *pos + step > max) {
        printf("Error: Out of range.\n");
        return;
    }
    *pos += step;
    gpioServo(pin, *pos);
    delay(DELAY);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Error: GPIO initialization failed.\n");
        return 1;
    }

    signal(SIGINT, handle_sigint);

    if (gpioSetMode(PAN_PIN, PI_OUTPUT) < 0) {
        printf("Error: Failed to set mode for PAN_PIN.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(TILT_PIN, PI_OUTPUT) < 0) {
        printf("Error: Failed to set mode for TILT_PIN.\n");
        cleanup();
        return 1;
    }

    gpioServo(PAN_PIN, PAN_CENTER);
    gpioServo(TILT_PIN, TILT_CENTER);

    while (1) {
        char c = getchar();
        switch (c) {
            case 'q':
                cleanup();
                return 0;
            case 'a':
                move_servo(PAN_PIN, &pan_pos, PAN_MIN, PAN_MAX, -5);
                break;
            case 'd':
                move_servo(PAN_PIN, &pan_pos, PAN_MIN, PAN_MAX, 5);
                break;
            case 'w':
                move_servo(TILT_PIN, &tilt_pos, TILT_MIN, TILT_MAX, -5);
                break;
            case 's':
                move_servo(TILT_PIN, &tilt_pos, TILT_MIN, TILT_MAX, 5);
                break;
            default:
                break;
        }
    }

    cleanup();
    return 0;
}

