#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define LCD_FUNCTION (1<<2) | (1<<1) | (1<<0)
#define LCD_CLEARDISPLAY 0x01
#define LCD_ENTRYMODESET (1<<1) | (1<<0)
#define LCD_DISPLAYCONTROL (1<<3) | (1<<2) | (1<<1) | (1<<0)
#define LCD_DISPLAYON 0x04
#define LCD_BACKLIGHT 0x08
#define LCD_CHR(c) ((c) | LCD_BACKLIGHT)

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = true;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd, ret;
    uint8_t buffer[2];
    uint32_t count = 0;
    uint32_t total_volume = 0;
    uint32_t flow_rate = 0;
    uint32_t last_count = 0;
    uint32_t last_volume = 0;
    uint32_t last_time = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "flow_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop) {
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            break;
        }

        if (ret) {
            count++;
        }

        uint32_t current_time = time(NULL);
        if (current_time - last_time >= 1) {
            flow_rate = count - last_count;
            total_volume += flow_rate;
            last_count = count;
            last_time = current_time;

            printf("Flow rate: %u pulses/s, Total volume: %u pulses\n", flow_rate, total_volume);

            buffer[0] = 0x80; // Set cursor to beginning of first line
            buffer[1] = LCD_CHR('F') | LCD_CHR('l') | LCD_CHR('o') | LCD_CHR('w') | LCD_CHR(' ') | LCD_CHR('R') | LCD_CHR('a') | LCD_CHR('t') | LCD_CHR('e') | LCD_CHR(':') | LCD_CHR(' ') | LCD_CHR('0' + flow_rate / 1000);
            write(i2c_fd, buffer, 2);

            buffer[0] = 0xC0; // Set cursor to beginning of second line
            buffer[1] = LCD_CHR('T') | LCD_CHR('o') | LCD_CHR('t') | LCD_CHR('a') | LCD_CHR('l') | LCD_CHR(' ') | LCD_CHR('V') | LCD_CHR('o') | LCD_CHR('l') | LCD_CHR('u') | LCD_CHR('m') | LCD_CHR('e') | LCD_CHR(':') | LCD_CHR(' ') | LCD_CHR('0' + total_volume / 1000);
            write(i2c_fd, buffer, 2);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

