#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PROXIMITY 4
#define GPIO_LED 17
#define PROXIMITY_LOG "proximity.log"
#define POLLING_INTERVAL 100 // ms

static gpiod_chip *chip;
static gpiod_line *line_proximity;
static gpiod_line *line_led;
static int proximity_detected = 0;
static struct timespec last_detection_time = {0, 0};

static void cleanup() {
    gpiod_line_set_value(line_led, 0);
    gpiod_line_release(line_proximity);
    gpiod_line_release(line_led);
    gpiod_chip_close(chip);
}

static void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

static void proximity_callback(gpiod_line_event event) {
    if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
        struct timespec current_time;
        clock_gettime(CLOCK_REALTIME, &current_time);
        if (last_detection_time.tv_sec == 0 && last_detection_time.tv_nsec == 0 || 
            current_time.tv_sec - last_detection_time.tv_sec > 1 || 
            (current_time.tv_sec - last_detection_time.tv_sec == 1 && current_time.tv_nsec - last_detection_time.tv_nsec > 0)) {
            proximity_detected = 1;
            last_detection_time = current_time;
        }
    }
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        chip = gpiod_chip_open("/dev/gpiochip");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_proximity = gpiod_chip_get_line(chip, GPIO_PROXIMITY);
    if (!line_proximity) {
        fprintf(stderr, "Failed to get proximity line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    line_led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line_led) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_falling_edge_events(line_proximity, "proximity_sensor") < 0) {
        fprintf(stderr, "Failed to request falling edge events\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_value(line_led, 0) < 0) {
        fprintf(stderr, "Failed to set LED line value\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpiod_line_event_callback(line_proximity, proximity_callback, NULL);

    FILE *log_file = fopen(PROXIMITY_LOG, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        if (proximity_detected) {
            proximity_detected = 0;
            gpiod_line_set_value(line_led, 1);
            usleep(100 * 1000);
            gpiod_line_set_value(line_led, 0);
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
            char time_str[26];
            strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", gmtime(&current_time.tv_sec));
            fprintf(log_file, "%s Object detected\n", time_str);
            fflush(log_file);
        }
        usleep(POLLING_INTERVAL * 1000);
    }

    fclose(log_file);
    cleanup();
    return EXIT_SUCCESS;
}

