#include <time.h>

#define SI1145_ADDRESS 0x60
#define PART_ID 0x14

int file;
struct timespec sleep_time = {1, 0};

void signal_handler(int signum) {
    close(file);
    printf("Exiting program\n");
    exit(0);
}

int main() {
    int part_id;
    int proximity;
    int ambient_light;
    struct tm *timeinfo;
    char buffer[80];
    char log_buffer[256];

    signal(SIGINT, signal_handler);

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, SI1145_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave\n");
        exit(1);
    }

    // Read PART_ID
    if (write(file, &PART_ID, 1) != 1) {
        printf("Failed to write to the i2c bus\n");
        exit(1);
    }

    if (read(file, &part_id, 1) != 1) {
        printf("Failed to read from the i2c bus\n");
        exit(1);
    }

    if (part_id != 0x14) {
        printf("Sensor not found\n");
        exit(1);
    }

    int log_file = open("biometric_data.log", O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (log_file < 0) {
        printf("Failed to open log file\n");
        exit(1);
    }

    while (1) {
        // Read proximity
        if (write(file, &0x22, 1) != 1) {
            printf("Failed to write to the i2c bus\n");
            exit(1);
        }

        if (read(file, &proximity, 2) != 2) {
            printf("Failed to read from the i2c bus\n");
            exit(1);
        }

        // Read ambient light
        if (write(file, &0x23, 1) != 1) {
            printf("Failed to write to the i2c bus\n");
            exit(1);
        }

        if (read(file, &ambient_light, 2) != 2) {
            printf("Failed to read from the i2c bus\n");
            exit(1);
        }

        time_t rawtime;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        sprintf(log_buffer, "%s,%d,%d\n", buffer, proximity, ambient_light);

        if (write(log_file, log_buffer, strlen(log_buffer)) != strlen(log_buffer)) {
            printf("Failed to write to the log file\n");
            exit(1);
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

