        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        sprintf(log_buffer, "%s,%d,%d\n", buffer, proximity, ambient_light);

        if (write(log_file, log_buffer, strlen(log_buffer)) != strlen(log_buffer)) {
            printf("Failed to write to the log file\n");
            exit(1);
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}
