                goto cleanup;
            }
        }

        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_REALTIME, &end_time) == -1) {
                fprintf(stderr, "Failed to get time\n");
                goto cleanup;
            }
            if ((end_time.tv_sec - start_time.tv_sec) > 0) {
                fprintf(stderr, "Timeout waiting for echo fall\n");
                goto cleanup;
            }
        }

        duration = (end_time.tv_sec - start_time.tv_sec) * 1e9 + (end_time.tv_nsec - start_time.tv_nsec);
        distance = duration / 58;

