#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define LOG_FILE_NAME "distance_log.txt"
#define SAMPLE_INTERVAL 200
#define TRIGGER_INTERVAL 50
#define BUFFER_SIZE 64

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL * 1000 * 1000};
    struct timespec trigger_time = {0, TRIGGER_INTERVAL * 1000 * 1000};
    char buffer[BUFFER_SIZE];
    time_t rawtime;
    struct tm *timeinfo;
    int i2c_handle;
    int distance;

    signal(SIGINT, signal_handler);

    if ((log_file = fopen(LOG_FILE_NAME, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDRESS, 0);

    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (!stop) {
        if (gpioI2CWriteByteData(i2c_handle, 0x00, 0x01) < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            continue;
        }

        nanosleep(&trigger_time, NULL);

        if (gpioI2CReadByteData(i2c_handle, 0x01, &distance) < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S, ", timeinfo);
        fprintf(log_file, "%s%d\n", buffer, distance);
        fprintf(stdout, "%s%d\n", buffer, distance);
    }

    gpioI2CWriteByteData(i2c_handle, 0x00, 0x00);
    gpioI2CClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return EXIT_SUCCESS;
}

