#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_PIN 17
#define SAMPLE_INTERVAL 100 // ms
#define DISTANCE_THRESHOLD 20 // cm

static int i2c_fd, gpio_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup() {
    if (i2c_fd >= 0) close(i2c_fd);
    if (gpio_fd >= 0) close(gpio_fd);
    if (chip) gpiod_chip_close(chip);
    if (line) gpiod_line_release(line);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire I2C address");
        return 1;
    }

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO_PIN)) == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if (gpiod_line_request_output(line, "distance_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return 1;
    }

    while (1) {
        uint8_t buffer[2];
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C device");
            return 1;
        }

        int distance = buffer[0] << 8 | buffer[1];
        if (distance < DISTANCE_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        FILE *log_file = fopen("distance_log.txt", "a");
        if (!log_file) {
            perror("Failed to open log file");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%FT%T%z", t);

        fprintf(log_file, "%s,%d\n", timestamp, distance);
        fclose(log_file);

        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

