#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <pigpio.h>

#define WHO_AM_I 0x0F
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x29
#define GPIO_LED 17
#define POLLING_INTERVAL 50 // ms
#define DEFAULT_THRESHOLD 100 // mm

int running = 1;
int threshold = DEFAULT_THRESHOLD;
FILE *log_file;

void cleanup() {
    if (log_file) fclose(log_file);
    gpioTerminate();
    i2cClose(I2C_BUS);
}

void sigint_handler(int signum) {
    running = 0;
}

int check_sensor() {
    uint8_t who_am_i;
    if (i2cReadReg8(I2C_BUS, SENSOR_ADDRESS, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != 0x01) {
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc > 1) {
        threshold = atoi(argv[1]);
    }

    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (check_sensor() < 0) {
        fprintf(stderr, "Failed to check sensor\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("tof_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t distance;
        if (i2cReadReg16(I2C_BUS, SENSOR_ADDRESS, 0x0D, &distance) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            return EXIT_FAILURE;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld: %d\n", ts.tv_sec, ts.tv_nsec, distance);

        if (distance < threshold) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        usleep(POLLING_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x29
#define HEADER_VALUE 0xFA
#define LOG_FILE "intrusion_log.txt"

int i2c_fd;
FILE *log_fd;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_fd);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = cleanup;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    unsigned char buffer[15];
    int distance_sum = 0;
    int count = 0;

    while (1) {
        memset(buffer, 0, sizeof(buffer));

        buffer[0] = 0x01;
        buffer[1] = 0x02;
        buffer[2] = 0x03;
        buffer[3] = 0x04;

        if (write(i2c_fd, buffer, 4) != 4) {
            perror("Failed to write to i2c device");
            return 1;
        }

        usleep(10000);

        if (read(i2c_fd, buffer, 15) != 15) {
            perror("Failed to read from i2c device");
            return 1;
        }

        if (buffer[0] != HEADER_VALUE) {
            printf("Invalid header value\n");
            continue;
        }

        int distance = (buffer[11] << 8) | buffer[12];

        distance_sum += distance;
        count++;

        if (count == 10) {
            int average_distance = distance_sum / count;
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_fd, "%ld.%06ld - Average distance: %d\n", tv.tv_sec, tv.tv_usec, average_distance);

            if (average_distance < 1000) {
                printf("Intrusion detected!\n");
            }

            distance_sum = 0;
            count = 0;
        }

        usleep(100000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L0X_I2C_ADDR 0x29
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xc0
#define VL53L0X_IDENTIFICATION_MODEL_ID 0xEE
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct timespec ts;
    int i2c_handle;
    uint8_t model_id;
    uint16_t distance;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(1, VL53L0X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioI2CReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (model_id != VL53L0X_IDENTIFICATION_MODEL_ID) {
        fprintf(stderr, "Model ID mismatch: expected 0x%02X, got 0x%02X\n", VL53L0X_IDENTIFICATION_MODEL_ID, model_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (gpioI2CReadWordData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &distance) < 0) {
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n", 
               ts.tv_sec / 3600 / 24 + 1970, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60, ts.tv_sec % 60, ts.tv_nsec / 1e6);

        gpioDelay(500000000); // 500ms
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
