#include <libgpiod.h>

#define I2C_BUS 1
#define SI1182_ADDRESS 0x39

static int keep_running = 1;

void intHandler(int dummy) {
    keep_running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request req;
    struct gpiod_line *sda, *scl;
    int ret, val;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 2);
    if (!sda) {
        fprintf(stderr, "Failed to get SDA line\n");
        return EXIT_FAILURE;
    }

    scl = gpiod_chip_get_line(chip, 3);
    if (!scl) {
        fprintf(stderr, "Failed to get SCL line\n");
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.consumer = "i2c";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    ret = gpiod_line_request(sda, &req, 0);
    if (ret) {
        fprintf(stderr, "Failed to request SDA line\n");
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request(scl, &req, 0);
    if (ret) {
        fprintf(stderr, "Failed to request SCL line\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, intHandler);

    while (keep_running) {
        ret = gpiod_line_get_value(sda);
        if (ret < 0) {
            fprintf(stderr, "Failed to read SDA line\n");
            break;
        }

        ret = gpiod_line_get_value(scl);
        if (ret < 0) {
            fprintf(stderr, "Failed to read SCL line\n");
            break;
        }

        printf("SDA: %d, SCL: %d\n", ret, val);
        usleep(500000);
    }

    gpiod_line_release(sda);
    gpiod_line_release(scl);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

