#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SLAVE_ADDRESS 0x28
#define I2C_BUS "/dev/i2c-1"

int main() {
    int file;
    struct timespec req, rem;
    unsigned char buffer[2];
    int distance;

    // Open the I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the I2C bus");
        return 1;
    }

    // Set the slave address
    if (ioctl(file, I2C_SLAVE, SLAVE_ADDRESS) < 0) {
        perror("Failed to set the slave address");
        close(file);
        return 1;
    }

    // Request for 2 bytes of data
    buffer[0] = 0x00;
    buffer[1] = 0x01;
    if (write(file, buffer, 2) != 2) {
        perror("Failed to write to the I2C device");
        close(file);
        return 1;
    }

    // Set up the SIGINT handler
    struct sigaction sigact;
    sigact.sa_handler = &sigint_handler;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    if (sigaction(SIGINT, &sigact, NULL) < 0) {
        perror("Failed to set up the SIGINT handler");
        close(file);
        return 1;
    }

    // Main loop
    req.tv_sec = 0;
    req.tv_nsec = 500000000;
    while (1) {
        if (read(file, buffer, 2) != 2) {
            perror("Failed to read from the I2C device");
            continue;
        }
        distance = (buffer[0] << 8) | buffer[1];
        printf("Distance: %d mm\n", distance);
        nanosleep(&req, &rem);
    }

    close(file);
    return 0;
}

void sigint_handler(int signum) {
    printf("Caught SIGINT, exiting...\n");
    exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x4A
#define REG_DISTANCE 0x50
#define REG_AMBIENT_LIGHT 0x51
#define REG_ERROR_FLAGS 0x52

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetSignalFunc(SIGINT, signal_handler) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        uint8_t buffer[3];
        int ret = i2cReadFile(i2c_handle, buffer, sizeof(buffer));
        if (ret != sizeof(buffer)) {
            fprintf(stderr, "Failed to read from sensor\n");
            break;
        }

        uint16_t distance = (buffer[0] << 8) | buffer[1];
        uint16_t ambient_light = (buffer[2] << 8) | buffer[3];
        printf("Distance: %d, Ambient Light: %d\n", distance, ambient_light);

        gpioDelay(500000); // wait for 500ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_DURATION 38000 // 38ms in microseconds
#define MIN_DURATION 1 // 1µs in microseconds
#define PULSE_WIDTH 10 // 10µs in microseconds

static bool running = true;

void handle_signal(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    struct timespec start_time, end_time;
    long duration;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(trigger_line, "HC-SR04 Trigger", 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(echo_line, "HC-SR04 Echo");
    if (ret) {
        fprintf(stderr, "Failed to request echo line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        ret = gpiod_line_set_value(trigger_line, 1);
        if (ret) {
            fprintf(stderr, "Failed to set trigger line high\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        nanosleep(&((struct timespec){0, PULSE_WIDTH * 1000}), NULL);

        ret = gpiod_line_set_value(trigger_line, 0);
        if (ret) {
            fprintf(stderr, "Failed to set trigger line low\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_wait_for_edge(echo_line, GPIOD_LINE_EVENT_BOTH_EDGES, 200000);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for echo edge\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_event_read(echo_line, &start_time, &end_time);
        if (ret) {
            fprintf(stderr, "Failed to read echo line event\n");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        duration = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        if (duration <= MIN_DURATION || duration > MAX_DURATION) {
            printf("Invalid duration: %ld µs\n", duration);
        } else {
            printf("Distance: %.2f cm\n", duration / 58.0);
        }

        nanosleep(&((struct timespec){1, 0}), NULL);
    }

    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define UART_PORT "/dev/serial0"
#define THRESHOLD 100 // 1 meter in cm

static int uart_fd;
static int gpio_fd;

void cleanup(int signum) {
    close(uart_fd);
    close(gpio_fd);
    exit(signum);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *log_file = fopen("intrusion_log.csv", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpio_fd = gpiod_chip_request_output(chip, GPIO_PIN, "intrusion_led", 0);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO output");
        return EXIT_FAILURE;
    }

    uart_fd = open(UART_PORT, O_RDONLY | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        perror("Failed to open UART port");
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

    while (1) {
        uint8_t buffer[132];
        ssize_t bytes_read = read(uart_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("Failed to read from UART port");
            return EXIT_FAILURE;
        }

        if (bytes_read == sizeof(buffer) && memcmp(buffer, "MAGICWORD", 8) == 0) {
            uint16_t *distances = (uint16_t *)(buffer + 8);
            for (int i = 0; i < 64; i++) {
                if (distances[i] < THRESHOLD) {
                    fprintf(log_file, "%s,%d\n", timestamp, distances[i] / 100);
                    gpiod_set_value(gpio_fd, 1);
                    usleep(2000000);
                    gpiod_set_value(gpio_fd, 0);
                    break;
                }
            }
        }
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    close(uart_fd);
    return EXIT_SUCCESS;
}

