void log_transition(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    fprintf(log_file, "%s - %s\n", buffer, state ? "Obstacle detected" : "Obstacle removed");
    fflush(log_file);
}

void activate_buzzer(int state) {
    gpiod_line_set_value(buzzer_line, state);
}

void handle_signal(int signum) {
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int prev_state = -1;
    while (1) {
        int state = gpiod_line_get_value(sensor_line);
        if (state != prev_state) {
            log_transition(state);
            activate_buzzer(state);
            prev_state = state;
        }
        usleep(POLL_INTERVAL * 1000000);
    }

    return EXIT_SUCCESS;
}

