#define SENSOR_ADDRESS 0x29
#define MEAS_STATUS_REG 0x01
#define DISTANCE_REG 0x02
#define TIMEOUT 50000 // 50ms timeout

int i2c_fd;
FILE *csv_fd;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(csv_fd);
    exit(signum);
}

int main() {
    struct sigaction act;
    memset(&act, '\0', sizeof(act));
    act.sa_handler = &cleanup;
    sigaction(SIGINT, &act, NULL);
    sigaction(SIGTERM, &act, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((csv_fd = fopen("distance_log.csv", "w")) == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

