        uint8_t buffer[2];
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        // Write MEAS_STATUS_REG to start measurement
        buffer[0] = MEAS_STATUS_REG;
        buffer[1] = 0x01;
        if (write(i2c_fd, buffer, 2) != 2) {
            perror("Failed to write to sensor");
            continue;
        }

        // Wait for measurement to complete
        usleep(TIMEOUT);

        // Read distance
        buffer[0] = DISTANCE_REG;
        if (write(i2c_fd, buffer, 1) != 1) {
            perror("Failed to write to sensor");
