    shutdown_line = gpiod_chip_get_line(chip, VL53L1X_SHUTDOWN_PIN);
    interrupt_line = gpiod_chip_get_line(chip, VL53L1X_INTERRUPT_PIN);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    // Initialize VL53L1X
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        printf("Failed to select VL53L1X\n");
        return -1;
    }

    // Check VL53L1X model ID
    if (read(i2c_fd, &distance, 2) != 2 || distance != VL53L1X_MODEL_ID) {
        printf("VL53L1X model ID mismatch\n");
        return -1;
    }

    // Initialize servo
    if (gpioSetPWMmode(SERVO_PIN, PI_PWMMODE_MS) < 0) {
