        printf("Failed to open log file\n");
        return -1;
    }

    // Main loop
    while (!stop) {
        // Read distance from VL53L1X
        if (read(i2c_fd, &distance, 2) != 2) {
            printf("Failed to read distance from VL53L1X\n");
            break;
        }

        // Check if distance is within range
        if (distance < OPEN_DISTANCE) {
            // Open gate
            gpioPWM(SERVO_PIN, 1000); // Set servo to 1ms pulse (90 degrees)
            timestamp = time(NULL);
            fprintf(log_file, "Gate opened at %s with distance %d\n", ctime(&timestamp), distance);
        } else if (distance > CLOSE_DISTANCE) {
            // Close gate
            gpioPWM(SERVO_PIN, 2000); // Set servo to 2ms pulse (0 degrees)
            timestamp = time(NULL);
