#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pigpio.h>

#define VL53L1X_MODEL_ID 0xEE
#define VL53L1X_I2C_ADDRESS 0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INTERRUPT_PIN 24
#define SERVO_PIN 18
#define OPEN_DISTANCE 50
#define CLOSE_DISTANCE 60

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *shutdown_line, *interrupt_line;
    int i2c_fd, distance;
    time_t timestamp;
    FILE *log_file;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    shutdown_line = gpiod_chip_get_line(chip, VL53L1X_SHUTDOWN_PIN);
    interrupt_line = gpiod_chip_get_line(chip, VL53L1X_INTERRUPT_PIN);

    // Initialize I2C
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    // Initialize VL53L1X
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_I2C_ADDRESS) < 0) {
        printf("Failed to select VL53L1X\n");
        return -1;
    }

    // Check VL53L1X model ID
    if (read(i2c_fd, &distance, 2) != 2 || distance != VL53L1X_MODEL_ID) {
        printf("VL53L1X model ID mismatch\n");
        return -1;
    }

    // Initialize servo
    if (gpioSetPWMmode(SERVO_PIN, PI_PWMMODE_MS) < 0) {
        printf("Failed to set PWM mode\n");
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("parking_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    // Main loop
    while (!stop) {
        // Read distance from VL53L1X
        if (read(i2c_fd, &distance, 2) != 2) {
            printf("Failed to read distance from VL53L1X\n");
            break;
        }

        // Check if distance is within range
        if (distance < OPEN_DISTANCE) {
            // Open gate
            gpioPWM(SERVO_PIN, 1000); // Set servo to 1ms pulse (90 degrees)
            timestamp = time(NULL);
            fprintf(log_file, "Gate opened at %s with distance %d\n", ctime(&timestamp), distance);
        } else if (distance > CLOSE_DISTANCE) {
            // Close gate
            gpioPWM(SERVO_PIN, 2000); // Set servo to 2ms pulse (0 degrees)
            timestamp = time(NULL);
            fprintf(log_file, "Gate closed at %s with distance %d\n", ctime(&timestamp), distance);
        }

        // Wait for interrupt
        gpiod_line_event_wait(interrupt_line, NULL);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(interrupt_line);
    gpiod_chip_close(chip);

    return 0;
}
