#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define VL53L1X_ADDRESS 0x29
#define GPIO_TRIGGER 18
#define GPIO_ECHO 19
#define TIMEOUT 20000 // 20cm
#define LOG_FILE "gate_events.log"

int i2c_fd, log_fd;
struct gpiod_chip *chip;
struct gpiod_line *trigger, *echo;

void cleanup() {
    gpiod_line_set_value(echo, 0);
    gpiod_line_set_value(trigger, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(log_fd);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    trigger = gpiod_chip_get_line(chip, GPIO_TRIGGER);
    echo = gpiod_chip_get_line(chip, GPIO_ECHO);

    gpiod_line_request_output(trigger, "trigger", 0);
    gpiod_line_request_output(echo, "echo", 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open the i2c bus");
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        cleanup();
        return 1;
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (log_fd < 0) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    while (1) {
        gpiod_line_set_value(trigger, 1);
        usleep(500);
        gpiod_line_set_value(trigger, 0);

        struct timeval tv;
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(echo->fd, &readfds);
        tv.tv_sec = 0;
        tv.tv_usec = 500000;

        int rv = select(echo->fd + 1, &readfds, NULL, NULL, &tv);
        if (rv == -1) {
            perror("select()");
            cleanup();
            return 1;
        } else if (rv == 0) {
            continue;
        }

        uint8_t data[2];
        if (read(echo->fd, data, 2) != 2) {
            perror("Failed to read from echo");
            cleanup();
            return 1;
        }

        uint16_t distance = (data[0] << 8) | data[1];
        if (distance < TIMEOUT) {
            gpiod_line_set_value(trigger, 1);
            gpiod_line_set_value(echo, 1);
            write(log_fd, "Gate opened at ", 16);
            time_t now = time(NULL);
            char *time_str = ctime(&now);
            write(log_fd, time_str, strlen(time_str));
        } else {
            gpiod_line_set_value(trigger, 0);
            gpiod_line_set_value(echo, 0);
            write(log_fd, "Gate closed at ", 16);
            time_t now = time(NULL);
            char *time_str = ctime(&now);
            write(log_fd, time_str, strlen(time_str));
        }
    }

    cleanup();
    return 0;
}

