#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SOUND_SPEED 0.0343 // m/s
#define MIN_DISTANCE 0.02 // m
#define MAX_DISTANCE 0.4 // m
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t stop_flag = 0;

void sigint_handler(int signum) {
    stop_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *trigger_line, *echo_line;
    FILE *log_file;
    struct timespec start_time, end_time;
    long echo_duration;
    double distance;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request trigger and echo lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop_flag) {
        // Trigger the sensor
        gpiod_line_set_value(trigger_line, 0);
        nanosleep((const struct timespec[]){{0, 5000}}, NULL); // 5 us
        gpiod_line_set_value(trigger_line, 1);
        nanosleep((const struct timespec[]){{0, 10000}}, NULL); // 10 us
        gpiod_line_set_value(trigger_line, 0);

        // Wait for echo
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (gpiod_line_get_value(echo_line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1 || 
                (end_time.tv_sec - start_time.tv_sec) * 1000 + 
                (end_time.tv_nsec - start_time.tv_nsec) / 1000000 > 30) {
                fprintf(stderr, "Echo never rises\n");
                break;
            }
        }

        // Measure echo duration
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1 || 
                (end_time.tv_sec - start_time.tv_sec) * 1000 + 
                (end_time.tv_nsec - start_time.tv_nsec) / 1000000 > 30) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
        }
        echo_duration = (end_time.tv_sec - start_time.tv_sec) * 1000000 + 
                         (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        // Compute distance
        distance = echo_duration * SOUND_SPEED / 2;

        // Check if distance is within valid range
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Distance out of range\n");
            continue;
        }

        // Log distance
        fprintf(log_file, "%ld.%09ld %f\n", 
                start_time.tv_sec, start_time.tv_nsec, distance);
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE 4.0 // in meters
#define MIN_DISTANCE 1.0 // in meters
#define MAX_PULSE_WIDTH 25000 // in microseconds
#define MIN_PULSE_WIDTH 5800 // in microseconds
#define LOG_FILE "distance_log.txt"

static gpiod_chip *chip;
static gpiod_line *trig_line;
static gpiod_line *echo_line;
static FILE *log_file;
static struct timespec start_time;
static struct timespec end_time;
static int running = 1;

void handle_interrupt() {
    running = 0;
}

void measure_distance() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    long long elapsed_time = (current_time.tv_sec - start_time.tv_sec) * 1000000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000;
    if (elapsed_time > MAX_PULSE_WIDTH || elapsed_time < MIN_PULSE_WIDTH) {
        return;
    }
    double distance = (double)elapsed_time / 58.0;
    if (distance > MAX_DISTANCE || distance < MIN_DISTANCE) {
        return;
    }
    fprintf(log_file, "%lld %f\n", elapsed_time, distance);
    fflush(log_file);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_interrupt;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(trig_line, "TRIG", 0);
    gpiod_line_request_input(echo_line, "ECHO");

    while (running) {
        gpiod_line_set_value(trig_line, 1);
        nanosleep((const struct timespec[]){{0, 1000000}}, NULL); // 1ms
        gpiod_line_set_value(trig_line, 0);
        while (!gpiod_line_get_value(echo_line)) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }
        while (gpiod_line_get_value(echo_line)) {
            clock_gettime(CLOCK_MONOTONIC, &end_time);
        }
        measure_distance();
    }

    fclose(log_file);
    gpiod_line_release(trig_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

