#include <syslog.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDRESS 0x29
#define GPIO_XSHUT 27

static int keep_running = 1;

void terminate(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_handle, distance;
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, terminate);
    signal(SIGTERM, terminate);

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure XSHUT pin
    gpioSetMode(GPIO_XSHUT, PI_OUTPUT);
    gpioWrite(GPIO_XSHUT, 1);

    // Main loop
    while (keep_running) {
        // Read distance
        if (vl53l1x_read_distance(i2c_handle, &distance) < 0) {
            syslog(LOG_ERR, "Failed to read distance");
        } else {
            // Log distance
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            syslog(LOG_INFO, "Distance: %d mm at %s", distance, buffer);
        }

        // Wait for 100ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define VL53L1X_ADDRESS 0x29
#define GATE_PIN 24
#define LOG_FILE "gate_log.txt"
#define DISTANCE_THRESHOLD 20000 // 20cm in mm

int main() {
    FILE *logFile;
    int i2cHandle, distance, gateState = 0;
    struct timespec ts;

    // Open log file
    logFile = fopen(LOG_FILE, "w");
    if (!logFile) {
        printf("Error opening log file\n");
        return -1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        printf("Error initializing pigpio\n");
        fclose(logFile);
        return -1;
    }

    // Open I2C bus
    i2cHandle = i2cOpen(1, VL53L1X_ADDRESS, 0);
    if (i2cHandle < 0) {
        printf("Error opening I2C bus\n");
        gpioTerminate();
        fclose(logFile);
        return -1;
    }

    // Set up GPIO pin
    gpioSetMode(GATE_PIN, PI_OUTPUT);
    gpioWrite(GATE_PIN, PI_LOW);

    // Main loop
    while (1) {
        // Read distance from sensor
        if (i2cReadWordData(i2cHandle, 0x14) < 0) {
            printf("Error reading distance from sensor\n");
            break;
        }
        distance = i2cReadWordData(i2cHandle, 0x14);

        // Convert to centimeters
        distance = (distance * 25) / 1000;

        // Log distance
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(logFile, "%ld.%09ld Distance: %dcm\n", ts.tv_sec, ts.tv_nsec, distance);

        // Check if gate should be opened or closed
        if (distance < DISTANCE_THRESHOLD && gateState == 0) {
            gpioWrite(GATE_PIN, PI_HIGH);
            gateState = 1;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(logFile, "%ld.%09ld Gate opened\n", ts.tv_sec, ts.tv_nsec);
        } else if (distance >= DISTANCE_THRESHOLD && gateState == 1) {
            gpioWrite(GATE_PIN, PI_LOW);
            gateState = 0;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(logFile, "%ld.%09ld Gate closed\n", ts.tv_sec, ts.tv_nsec);
        }

        // Sleep for a bit
        gpioDelay(100000000);
    }

    // Clean up
    i2cClose(i2cHandle);
    gpioTerminate();
    fclose(logFile);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/ioctl.h>
#include <linux/watchdog.h>
#include <bcm2835.h>

#define TRIG_PIN RPI_GPIO_P1_23
#define ECHO_PIN RPI_GPIO_P1_24
#define SERVO_PIN RPI_GPIO_P1_18

#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500
#define PULSE_WIDTH_MID 1500
#define PULSE_WIDTH_RANGE (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN)

#define DISTANCE_MIN 2
#define DISTANCE_MAX 400
#define DISTANCE_INVALID -1.0

#define MOVING_AVERAGE_SIZE 5

volatile sig_atomic_t stop_requested = false;

void handle_sigint(int signum) {
    stop_requested = true;
}

int main() {
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed\n");
        return EXIT_FAILURE;
    }

    if (!bcm2835_gpio_fsel(TRIG_PIN, BCM2835_GPIO_FSEL_OUTP)) {
        fprintf(stderr, "Failed to set TRIG_PIN as output\n");
        return EXIT_FAILURE;
    }

    if (!bcm2835_gpio_fsel(ECHO_PIN, BCM2835_GPIO_FSEL_INPT)) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        return EXIT_FAILURE;
    }

    if (!bcm2835_gpio_fsel(SERVO_PIN, BCM2835_GPIO_FSEL_OUTP)) {
        fprintf(stderr, "Failed to set SERVO_PIN as output\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    FILE *file = fopen("distance_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open distance_log.csv\n");
        return EXIT_FAILURE;
    }

    fprintf(file, "Timestamp,Distance,Angle\n");

    uint32_t last_time = bcm2835_st_read();
    uint32_t last_pulse = 0;
    uint32_t pulse_width = PULSE_WIDTH_MID;
    bool new_pulse = false;

    while (!stop_requested) {
        uint32_t time = bcm2835_st_read();
        uint32_t elapsed = time - last_time;

        if (elapsed >= 1000000) {
            last_time = time;
            bcm2835_gpio_write(TRIG_PIN, HIGH);
            bcm2835_delayMicroseconds(10);
            bcm2835_gpio_write(TRIG_PIN, LOW);
        }

        if (new_pulse) {
            uint32_t duration = time - last_pulse;
            if (duration < 30000) {
                float distance = (float)duration / 58.0;
                if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                    fprintf(file, "%u,%f,%f\n", time, distance, pulse_width / 1000.0);
                    fflush(file);
                } else {
                    fprintf(file, "%u,%f,%f\n", time, DISTANCE_INVALID, pulse_width / 1000.0);
                    fflush(file);
                }
            }
            new_pulse = false;
        }

        if (bcm2835_gpio_lev(ECHO_PIN) == HIGH) {
            last_pulse = time;
            new_pulse = true;
        }

        bcm2835_delayMicroseconds(100);
    }

    fclose(file);
