        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set GPIO line direction to output
    if (gpiod_line_request_output(line, "VL53L1X warning", 0)) {
        fprintf(stderr, "Failed to set GPIO line direction\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open I2C bus
    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(file, I2C_SLAVE, VL53L1X_ADDRESS) < 0) {
