#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <pthread.h>
#include <libgpiod.h>

#define SI1102_ADDRESS 0x3E
#define GPIO_PIN 27
#define THRESHOLD 1000

int i2c_fd, gpio_fd;
pthread_t thread_id;
volatile sig_atomic_t stop = 0;

void *interrupt_handler(void *arg) {
    while (!stop) {
        // Check for interrupt
        // Read proximity value
        // Compare to threshold
        // Append to log file
    }
    return NULL;
}

void sigint_handler(int signum) {
    stop = 1;
    pthread_join(thread_id, NULL);
    close(i2c_fd);
    close(gpio_fd);
    exit(0);
}

int main(int argc, char *argv[]) {
    struct sigaction action;
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line;
    int opt, threshold = THRESHOLD, address = SI1102_ADDRESS;

    while ((opt = getopt(argc, argv, "t:a:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'a':
                address = (int)strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-a i2c_address]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Failed to set i2c address");
        exit(EXIT_FAILURE);
    }

    if ((gpio_fd = gpiod_chip_open("/dev/gpiochip0")) < 0) {
        perror("Failed to open gpio device");
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_get(gpio_fd);
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    memset(&request, 0, sizeof(request));
    request.consumer = "Si1102";
    request.request_type = GPIOD_LINE_REQUEST_DIRECTION_FALLING;
    if (gpiod_line_request(line, &request) < 0) {
        perror("Failed to request gpio line");
        exit(EXIT_FAILURE);
    }

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    if (sigaction(SIGINT, &action, NULL) < 0) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&thread_id, NULL, interrupt_handler, NULL) < 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);
    close(i2c_fd);
    close(gpio_fd);
    return 0;
}

