#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiPWM.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 0
#define MAX_DISTANCE 200
#define MIN_DISTANCE 2

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Failed to setup GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    wiringPiPWMSetClock(1);
    wiringPiPWMSetRange(SPEAKER_PIN, 1024);
    wiringPiPWM(SPEAKER_PIN, 0);

    while (!stop) {
        gpioWrite(TRIG_PIN, PI_HIGH);
        usleep(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        uint32_t start = 0, end = 0;
        while (gpioRead(ECHO_PIN) == PI_LOW && !stop) {
            if (start == 0) {
                start = micros();
            }
        }

        while (gpioRead(ECHO_PIN) == PI_HIGH && !stop) {
            end = micros();
        }

        if (start != 0 && end != 0) {
            uint32_t duration = end - start;
            float distance = duration / 58.0;

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                float frequency = 200 * pow(2, (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
                int pwm_value = (int) (frequency / 1000 * 1024);
                wiringPiPWM(SPEAKER_PIN, pwm_value);
            }
        }
    }

    wiringPiPWM(SPEAKER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define BUZZ_PIN 18
#define MAX_DISTANCE 50
#define MIN_DISTANCE 5
#define MAX_FREQUENCY 2000
#define MIN_FREQUENCY 200
#define SENSOR_TIMEOUT 100000 // 100ms

static gpiod_chip *chip;
static gpiod_line *trig_line;
static gpiod_line *echo_line;
static gpiod_line *buzz_line;
static int running = 1;

static void cleanup() {
    gpiod_line_set_value(echo_line, 0);
    gpiod_line_set_value(trig_line, 0);
    gpiod_line_set_value(buzz_line, 0);
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_line_release(buzz_line);
    gpiod_chip_close(chip);
}

static void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    buzz_line = gpiod_chip_get_line(chip, BUZZ_PIN);
    if (!buzz_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig_line, "trigger", 0) ||
        gpiod_line_request_input(echo_line, "echo") ||
        gpiod_line_request_output(buzz_line, "buzzer", 0)) {
        fprintf(stderr, "Failed to request line directions\n");
        cleanup();
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    while (running) {
        uint64_t start_time, end_time, echo_time;
        float distance, frequency;

        gpiod_line_set_value(trig_line, 0);
        usleep(2);
        gpiod_line_set_value(trig_line, 1);
        usleep(10);
        gpiod_line_set_value(trig_line, 0);

        start_time = gpiod_line_get_value_time(echo_line);
        while (gpiod_line_get_value(echo_line) == 0) {
            if (gpiod_line_get_value_time(echo_line) - start_time > SENSOR_TIMEOUT) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
        }

        end_time = gpiod_line_get_value_time(echo_line);
        echo_time = end_time - start_time;

        distance = (float)echo_time / 58.0;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance: %f\n", distance);
            continue;
        }

        frequency = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) + MIN_FREQUENCY;
        gpiod_line_set_frequency(buzz_line, frequency);

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        usleep(10000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define MIN_DISTANCE_WARNING 10
#define MEASUREMENT_INTERVAL 500

static bool exit_flag = false;

static void sigint_handler(int signum) {
    exit_flag = true;
}

static float convert_duration_to_distance(long duration) {
    float distance = duration / 58.0;
    return distance;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *trigger_line, *echo_line;
    struct timespec timeout = {0, 50000000}; // 50ms timeout
    long duration;
    float distance;

    signal(SIGINT, sigint_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        goto cleanup;
    }

    gpiod_line_request_input(trigger_line, "trigger");
    gpiod_line_request_input(echo_line, "echo");

    while (!exit_flag) {
        gpiod_line_set_value(trigger_line, 0);
        nanosleep(&timeout, NULL);
        gpiod_line_set_value(trigger_line, 1);
        nanosleep(&timeout, NULL);
        gpiod_line_set_value(trigger_line, 0);

        duration = gpiod_line_wait_for_edge(echo_line, GPIOD_LINE_EVENT_BOTH_EDGES, &timeout);
        if (duration < 0) {
            printf("Invalid reading\n");
            continue;
        }

        distance = convert_duration_to_distance(duration);
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
            continue;
        }

        printf("Distance: %.2f cm", distance);
        if (distance < MIN_DISTANCE_WARNING) {
            printf("Too close!");
        }
        printf("\n");

        nanosleep(&timeout, NULL);
    }

cleanup:
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_CS 8
#define CSV_FILE_NAME "distance_log.csv"

void write_to_csv(time_t timestamp, int distance) {
    FILE *file = fopen(CSV_FILE_NAME, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        return;
    }
    fprintf(file, "%ld,%d\n", timestamp, distance);
    fclose(file);
}

void signal_handler(int signum) {
    printf("Caught signal %d\n", signum);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_CS, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up/down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_CS, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        time_t timestamp = time(NULL);
        int distance = spiReadByte(SPI_CHANNEL);
        write_to_csv(timestamp, distance);
        sleep(100);
    }

    spiClose(SPI_CHANNEL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI1175_ADDRESS 0x39
#define ALS_VISIBLE_REG 0x22
#define LOG_FILE "proximity_log.csv"

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int file;
    uint8_t buf[2];
    time_t t;
    struct tm *tmp;
    char timestamp[64];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, SI1175_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        close(file);
        return EXIT_FAILURE;
    }

    FILE *log = fopen(LOG_FILE, "w");
    if (!log) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        close(file);
        return EXIT_FAILURE;
    }

    fprintf(log, "timestamp,als_visible\n");

    while (1) {
        if (gpiod_line_request_input(line, "SI1175") < 0) {
            fprintf(stderr, "Failed to request line\n");
            break;
        }

        if (write(file, &ALS_VISIBLE_REG, 1) != 1) {
            fprintf(stderr, "Failed to write register\n");
            break;
        }

        if (read(file, buf, 2) != 2) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        t = time(NULL);
        tmp = localtime(&t);
        if (!tmp) {
            fprintf(stderr, "Failed to get local time\n");
            break;
        }

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tmp);
        fprintf(log, "%s,%d\n", timestamp, (buf[0] << 8) | buf[1]);

        sleep(5);
    }

    fclose(log);
    close(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

