#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define SI1182_ADDRESS 0x39
#define SI1182_PART_ID 0x02
#define SI1182_MEAS_RATE 0x03

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    char buf[10];
    int part_id, meas_rate;
    struct timespec ts;
    FILE *log_file;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, SI1182_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    if (write(file, &SI1182_PART_ID, 1) != 1) {
        perror("Failed to write to the i2c bus");
        exit(1);
    }

    if (read(file, buf, 1) != 1) {
        perror("Failed to read from the i2c bus");
        exit(1);
    }

    part_id = buf[0];

    if (part_id != 0x11) {
        printf("Sensor not found\n");
        exit(1);
    }

    if (write(file, &SI1182_MEAS_RATE, 1) != 1) {
        perror("Failed to write to the i2c bus");
        exit(1);
    }

    if (read(file, buf, 2) != 2) {
        perror("Failed to read from the i2c bus");
        exit(1);
    }

    meas_rate = (buf[0] << 8) | buf[1];

    if (meas_rate != 0x1234) {
        printf("Failed to configure measurement rate\n");
        exit(1);
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld-%ld-%ld %ld:%ld:%ld.%ld,", ts.tv_sec, ts.tv_nsec);
        if (write(file, &SI1182_MEAS_RATE, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(file, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        int lux = (buf[0] << 8) | buf[1];
        fprintf(log_file, "%d,", lux);

        if (write(file, &SI1182_MEAS_RATE, 1) != 1) {
            perror("Failed to write to the i2c bus");
            exit(1);
        }

        if (read(file, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            exit(1);
        }

        int proximity = (buf[0] << 8) | buf[1];
        fprintf(log_file, "%d\n", proximity);

        fflush(log_file);
        printf("%ld-%ld-%ld %ld:%ld:%ld.%ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, ts.tv_sec, ts.tv_nsec, ts.tv_sec, ts.tv_nsec, ts.tv_sec, lux, proximity);
        usleep(100000);
    }

    fclose(log_file);
    close(file);
    return 0;
}

