#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>

#define SI1145_ADDRESS 0x60
#define RETRIES 3

int file;
int retry_count = 0;

void signal_handler(int signum) {
    close(file);
    printf("Interrupt signal received, closing file and exiting...\n");
    exit(0);
}

int i2c_write(int file, char *buf, int len) {
    if (write(file, buf, len) != len) {
        printf("Failed to write to i2c device\n");
        return -1;
    }
    return 0;
}

int i2c_read(int file, char *buf, int len) {
    if (read(file, buf, len) != len) {
        printf("Failed to read from i2c device\n");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = signal_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, SI1145_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave\n");
        exit(1);
    }

    while (1) {
        char buf[2] = {0x22, 0x00};
        if (i2c_write(file, buf, 2) < 0) {
            retry_count++;
            if (retry_count > RETRIES) {
                printf("Failed to write to Si1145 after %d retries\n", RETRIES);
                exit(1);
            }
            continue;
        }
        retry_count = 0;

        if (i2c_read(file, buf, 2) < 0) {
            retry_count++;
            if (retry_count > RETRIES) {
                printf("Failed to read from Si1145 after %d retries\n", RETRIES);
                exit(1);
            }
            continue;
        }
        retry_count = 0;

        int proximity = (buf[0] << 8) | buf[1];

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        FILE *log_file = fopen("proximity_log.txt", "a");
        if (log_file == NULL) {
            printf("Failed to open log file\n");
            exit(1);
        }

        fprintf(log_file, "%s Proximity: %d\n", timestamp, proximity);
        fclose(log_file);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MIN_DISTANCE 20

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static void echo_callback(struct gpiod_line *line, uint32_t event_mask, void *data) {
    static bool rising_edge = false;
    static uint64_t start_time = 0;
    uint64_t current_time = gpiod_line_get_time_ns(line);

    if (rising_edge) {
        uint64_t duration = current_time - start_time;
        float distance = duration * 0.034 / 2.0; // Speed of sound is 340 m/s
        printf("Distance: %.2f cm\n", distance);

        if (distance < MIN_DISTANCE) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        rising_edge = false;
    } else {
        start_time = current_time;
        rising_edge = true;
    }
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    if (sigaction(SIGINT, &action, NULL) == -1) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        goto cleanup;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) ||
        gpiod_line_request_input(echo_line, "echo") ||
        gpiod_line_request_output(buzzer_line, "buzzer", 0)) {
        perror("Failed to request lines");
        goto cleanup;
    }

    if (gpiod_line_event_wait(echo_line, GPIOD_LINE_EVENT_BOTH_EDGES, echo_callback, NULL)) {
        perror("Failed to set up echo line event");
        goto cleanup;
    }

    while (running) {
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);
        sleep(1);
    }

    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(buzzer_line);

cleanup:
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <pigpio.h>
#include <signal.h>
#include <stdbool.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define MIN_DISTANCE 20
#define MAX_DISTANCE 110
#define MIN_ANGLE 0
#define MAX_ANGLE 180

volatile sig_atomic_t stop = false;

void signal_handler(int signum) {
    stop = true;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        printf("Failed to set signal handler\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    uint32_t start, end, pulsewidth;
    float distance, angle;

    while (!stop) {
        gpioWrite(TRIG_PIN, PI_LOW);
        gpioDelay(2);
        gpioWrite(TRIG_PIN, PI_HIGH);
        gpioDelay(10);
        gpioWrite(TRIG_PIN, PI_LOW);

        start = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_LOW) {
            if (gpioTick() - start > 10000000) {
                printf("Echo timeout\n");
                break;
            }
        }

        end = gpioTick();
        while (gpioRead(ECHO_PIN) == PI_HIGH) {
            if (gpioTick() - end > 10000000) {
                printf("Echo timeout\n");
                break;
            }
        }

        distance = (end - start) / 58.0;
        if (distance < 0) {
            distance = -1.0;
        }

        printf("Distance: %.2f cm\n", distance);

        if (distance < MIN_DISTANCE) {
            angle = MAX_ANGLE;
        } else if (distance > MAX_DISTANCE) {
            angle = MIN_ANGLE;
        } else {
            angle = MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (1 - (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
        }

        pulsewidth = (uint32_t)(angle / 180.0 * 2000) + 500;
        gpioServo(SERVO_PIN, pulsewidth);

        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TRIG_PULSE_WIDTH 10
#define MEASUREMENT_INTERVAL 100
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define MIN_ANGLE 0
#define MAX_ANGLE 180

volatile sig_atomic_t stop = false;

void handle_sigint(int signum) {
    stop = true;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *trig_line, *echo_line, *servo_line;
    uint64_t start_time, end_time, duration;
    float distance, angle;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request GPIO lines
    gpiod_line_request_input(&request, "echo");
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    ret = gpiod_line_request(echo_line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request echo line\n");
        goto cleanup;
    }

    gpiod_line_request_input(&request, "trigger");
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    ret = gpiod_line_request(trig_line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request trigger line\n");
        goto cleanup;
    }

    gpiod_line_request_output(&request, "servo", 0);
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    ret = gpiod_line_request(servo_line, &request, 0);
    if (ret) {
        fprintf(stderr, "Failed to request servo line\n");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (!stop) {
        // Send trigger pulse
        gpiod_line_set_value(trig_line, 1);
        usleep(TRIG_PULSE_WIDTH * 1000);
        gpiod_line_set_value(trig_line, 0);

        // Wait for echo pulse
        start_time = gettime();
        while (gpiod_line_get_value(echo_line) == 0) {
            if (gettime() - start_time > 50000000) {
                distance = -1.0;
                break;
            }
        }
        end_time = gettime();
        while (gpiod_line_get_value(echo_line) == 1) {
            if (gettime() - end_time > 50000000) {
                distance = -1.0;
                break;
            }
        }
        if (distance != -1.0) {
            duration = end_time - start_time;
            distance = duration / 58.0;
        }

        // Calculate angle
        if (distance < MIN_DISTANCE) {
            angle = MIN_ANGLE;
        } else if (distance > MAX_DISTANCE) {
            angle = MAX_ANGLE;
        } else {
            angle = MIN_ANGLE + (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE);
        }

        // Set servo angle
        gpiod_line_set_value(servo_line, angle);

        // Print distance and angle
        printf("Distance: %.2f cm, Angle: %.2f°\n", distance, angle);

        // Wait for next measurement
        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    // Clean up
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;

cleanup:
    gpiod_line_release(echo_line);
    gpiod_line_release(trig_line);
    gpiod_line_release(servo_line);
    gpiod_chip_close(chip);
    return EXIT_FAILURE;
}

