#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define SI7005_ADDRESS 0x40
#define CONFIG_REGISTER 0xE0
#define READ_REGISTER 0xE1
#define I2C_BUS "/dev/i2c-1"

int i2c_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;

void close_i2c() {
    close(i2c_fd);
    gpiod_chip_close(chip);
}

void sigint_handler(int signum) {
    printf("Caught SIGINT, shutting down...\n");
    close_i2c();
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sigint_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        printf("Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI7005_ADDRESS) < 0) {
        printf("Failed to set I2C slave address\n");
        close_i2c();
        return -1;
    }

    while (1) {
        if (gpiod_line_set_value(line, 1) < 0) {
            printf("Failed to set GPIO line value\n");
            close_i2c();
            return -1;
        }

        if (write(i2c_fd, &CONFIG_REGISTER, 1) < 0) {
            printf("Failed to write to I2C device\n");
            close_i2c();
            return -1;
        }

        usleep(10000);

        if (write(i2c_fd, &READ_REGISTER, 1) < 0) {
            printf("Failed to write to I2C device\n");
            close_i2c();
            return -1;
        }

        usleep(10000);

        uint8_t buffer[2];
        if (read(i2c_fd, buffer, 2) < 0) {
            printf("Failed to read from I2C device\n");
            close_i2c();
            return -1;
        }

        printf("Humidity: %d.%d%%, Temperature: %d.%d°C\n", buffer[0], buffer[1], buffer[2], buffer[3]);

        usleep(2000000);
    }

    close_i2c();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
