#define MPU6050_ADDRESS 0x68
#define WHO_AM_I 0x75
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define TEMP_OUT_H 0x41
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

static bool running = true;
static struct gpiod_chip *chip;
static struct gpiod_line *sda_line;
static struct gpiod_line *scl_line;

void cleanup() {
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(chip);
}

void sig_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_line_request req_sda = {
        .consumer = "mpu6050-sda",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN,
    };

    struct gpiod_line_request req_scl = {
        .consumer = "mpu6050-scl",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_OPEN_DRAIN,
    };

    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip\n");
        return EXIT_FAILURE;
    }

    sda_line = gpiod_chip_get_line(chip, 2);
    if (!sda_line) {
        fprintf(stderr, "Failed to get SDA line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    scl_line = gpiod_chip_get_line(chip, 3);
    if (!scl_line) {
        fprintf(stderr, "Failed to get SCL line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(&sda_line, &req_sda)) {
        fprintf(stderr, "Failed to request SDA line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(&scl_line, &req_scl)) {
        fprintf(stderr, "Failed to request SCL line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    printf("Starting MPU6050 data logger\n");

    while (running) {
        uint8_t who_am_i;
        if (gpiod_i2c_read_reg(chip, MPU6050_ADDRESS, WHO_AM_I, &who_am_i, 1) != 1) {
            fprintf(stderr, "Failed to read WHO_AM_I register\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (who_am_i != 0x68) {
            fprintf(stderr, "MPU6050 not found\n");
            cleanup();
            return EXIT_FAILURE;
        }

        uint8_t data[14];
        if (gpiod_i2c_read_reg(chip, MPU6050_ADDRESS, ACCEL_XOUT_H, data, 14) != 14) {
            fprintf(stderr, "Failed to read data registers\n");
            cleanup();
            return EXIT_FAILURE;
        }

        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyro_x = (data[8] << 8) | data[9];
        int16_t gyro_y = (data[10] << 8) | data[11];
        int16_t gyro_z = (data[12] << 8) | data[13];

        printf("Accel: %d, %d, %d\n", accel_x, accel_y, accel_z);
        printf("Temp: %d\n", temp);
        printf("Gyro: %d, %d, %d\n", gyro_x, gyro_y, gyro_z);

        usleep(100000);
    }

    printf("Shutting down MPU6050 data logger\n");

    cleanup();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define SHT40_ADDRESS 0x44
#define SHT40_MEASUREMENT_CMD 0x2C06
#define SHT40_READ_CMD 0x0000
#define SHT40_CRC_POLYNOMIAL 0x131
#define SHT40_CRC_INIT_VALUE 0xFF

static bool running = true;

static void sig_handler(int signum) {
    running = false;
}

static uint8_t crc8(const uint8_t *data, size_t len, uint8_t crc) {
    while (len--) {
        crc ^= *data++;
        for (int i = 0; i < 8; i++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht40(int fd, float *temp, float *humidity) {
    uint8_t tx_buf[2] = {SHT40_MEASUREMENT_CMD >> 8, SHT40_MEASUREMENT_CMD & 0xFF};
    uint8_t rx_buf[6];
    int ret;

    ret = gpiod_i2c_transfer(fd, tx_buf, sizeof(tx_buf), rx_buf, sizeof(rx_buf));
    if (ret != sizeof(rx_buf)) {
        fprintf(stderr, "Failed to read from SHT40: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw_temp = (rx_buf[0] << 8) | rx_buf[1];
    uint16_t raw_humidity = (rx_buf[3] << 8) | rx_buf[4];

    uint8_t crc = crc8(rx_buf, 2, SHT40_CRC_INIT_VALUE);
    if (crc != rx_buf[2]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }

    crc = crc8(rx_buf + 3, 2, SHT40_CRC_INIT_VALUE);
    if (crc != rx_buf[5]) {
        fprintf(stderr, "CRC error on humidity data\n");
        return -1;
    }

    *temp = 175.0 * raw_temp / 65535.0 - 45.0;
    *humidity = 100.0 * raw_humidity / 65535.0;

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request req;
    int fd;
    float temp, humidity;
    struct sigaction action;

    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = gpiod_chip_i2c_open(chip, 1);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.consumer = "SHT40";
    req.request_type = GPIO_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(&req, fd) < 0) {
        fprintf(stderr, "Failed to request line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        if (read_sht40(fd, &temp, &humidity) == 0) {
            printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humidity);
        } else {
            fprintf(stderr, "Failed to read from SHT40\n");
        }

        sleep(5);
    }

    gpiod_line_release(&req, fd);
    close(fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
