#include <unistd.h>
#include <time.h>
#include <signal.h>

#define MLX90614_ADDRESS 0x5A
#define MLX90614_TOBJ1 0x24
#define MLX90614_TAMB1 0x20

int file;
int logFile;
sig_atomic_t stop;

void close_files(int signum) {
    close(file);
    close(logFile);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = close_files;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, MLX90614_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((logFile = open("temperature_log.csv", O_WRONLY | O_CREAT | O_APPEND, 0666)) < 0) {
        perror("Failed to open log file");
        return 1;
    }

    while (!stop) {
        uint16_t tobj1, tamb1;
        char buffer[256];

        if (write(file, &MLX90614_TOBJ1, 1) != 1) {
            perror("Failed to write to device");
            return 1;
        }

        if (read(file, &tobj1, 2) != 2) {
            perror("Failed to read from device");
            return 1;
        }

        if (write(file, &MLX90614_TAMB1, 1) != 1) {
            perror("Failed to write to device");
            return 1;
        }

        if (read(file, &tamb1, 2) != 2) {
            perror("Failed to read from device");
            return 1;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);

        sprintf(buffer, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f\n", 
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, 
                t->tm_hour, t->tm_min, t->tm_sec, 
                (float)tobj1 * 0.02 - 273.15, (float)tamb1 * 0.02 - 273.15);

        if (write(logFile, buffer, strlen(buffer)) < 0) {
            perror("Failed to write to log file");
            return 1;
        }

        sleep(5);
    }

    return 0;
}

