        sprintf(buffer, "%ld.%09ld %d\n", ts.tv_sec, ts.tv_nsec, temp);
        write(file, buffer, strlen(buffer));

        sleep(SAMPLE_INTERVAL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(file);
    close(error_file);

    return EXIT_SUCCESS;
}

