#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/select.h>
#include <sys/signalfd.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDRESS 0x28
#define CSV_FILE "pressure_log.csv"

int main() {
    int i2c_fd, csv_fd;
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    unsigned char command[1] = {0x00};
    unsigned char data[9];
    unsigned char crc8;
    int pressure, temperature;
    struct timespec ts;
    struct timespec sleep_time = {0, 1000000}; // 1ms
    struct timespec wait_time = {0, 100000000}; // 100ms
    struct signalfd_siginfo fdsi;
    sigset_t mask;
    int ret;

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open CSV file
    if ((csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666)) < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    sigemptyset(&mask);
    sigaddset(&mask, SIGINT);
    sigaddset(&mask, SIGTERM);
    if (sigprocmask(SIG_BLOCK, &mask, NULL) < 0) {
        perror("Failed to set up signal handler");
        close(i2c_fd);
        close(csv_fd);
        return EXIT_FAILURE;
    }

    // Write header to CSV file
    write(csv_fd, "timestamp,pressure,temperature\n", 32);

    while (1) {
        // Send measurement command
        messages[0].addr = SDP810_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = sizeof(command);
        messages[0].buf = command;

        // Read data from sensor
        messages[1].addr = SDP810_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = sizeof(data);
        messages[1].buf = data;

        packets.msgs = messages;
        packets.nmsgs = 2;

        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            perror("Failed to read data from sensor");
            break;
        }

        // Validate CRC8
        crc8 = data[8];
        if (crc8 != 0xFF) {
            perror("Invalid CRC8");
            break;
        }

        // Convert raw values to pressure and temperature
        pressure = (data[0] << 8) | data[1];
        temperature = (data[2] << 8) | data[3];

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to CSV file
        char buffer[256];
        sprintf(buffer, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, pressure, temperature);
        write(csv_fd, buffer, strlen(buffer));

        // Sleep for 1ms
        nanosleep(&sleep_time, NULL);

        // Check for signals
        ret = signalfd(-1, &mask, 0);
        if (ret < 0) {
            perror("Failed to create signalfd");
            break;
        }

        ret = read(ret, &fdsi, sizeof(fdsi));
        if (ret < 0) {
            perror("Failed to read signalfd");
            break;
        }

        if (fdsi.ssi_signo == SIGINT || fdsi.ssi_signo == SIGTERM) {
            break;
        }

        // Wait for 100ms before next measurement
        nanosleep(&wait_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    close(csv_fd);

    return EXIT_SUCCESS;
}

