#define SHT40_ADDRESS 0x44
#define SHT40_HIGH_REP_CMD 0x2f
#define SHT40_MEASUREMENT_TIME 10
#define SHT40_POLYNOMIAL 0x31
#define SHT40_INIT_VALUE 0xFF
#define LOG_FILE "sht40_log.txt"

static bool running = true;
static int i2c_fd = -1;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    running = false;
