uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHT40_INIT_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x80) != 0) {
                crc = (crc << 1) ^ SHT40_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    struct gpiod_line_request request;
    memset(&request, 0, sizeof(request));
    request.consumer = "SHT40";
    request.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    gpiod_chip_request_line(chip, 2, &request);
    gpiod_chip_request_line(chip, 3, &request);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (running) {
        uint8_t cmd = SHT40_HIGH_REP_CMD;
        if (write(i2c_fd, &cmd, 1) != 1) {
            perror("Failed to write command");
            continue;
        }

        usleep(SHT40_MEASUREMENT_TIME * 1000);

        uint8_t buffer[6];
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read data");
            continue;
        }

        if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        int16_t temp = (buffer[0] << 8) | buffer[1];
        int16_t humidity = (buffer[3] << 8) | buffer[4];

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s Temperature: %d.%d°C Humidity: %d.%d%%\n",
                timestamp, temp >> 8, (temp & 0xFF) * 100 / 65536,
                humidity >> 8, (humidity & 0xFF) * 100 / 65536);

        fflush(log_file);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

