#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define SCD40_ADDRESS 0x61
#define SCD40_MEASUREMENT_INTERVAL 5
#define SCD40_READ_INTERVAL 5
#define SCD40_MAX_READINGS 20
#define SCD40_WARNING_THRESHOLD 1000

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} SCD40_Reading;

SCD40_Reading readings[SCD40_MAX_READINGS];
int read_index = 0;
int write_index = 0;
int full = 0;

gpiod_chip *chip;
gpiod_line *line;

void handle_sigint(int signum) {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = handle_sigint;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    line = gpiod_chip_get_line(chip, 17);
    gpiod_line_request_output(line, "co2_warning", 0);

    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave.\n");
        return 1;
    }

    while (1) {
        // Write command to start measurement
        uint8_t command[2] = {0x21, 0x08};
        if (write(i2c_fd, command, 2) != 2) {
            perror("Failed to write to i2c device.\n");
            return 1;
        }

        // Wait for measurement to complete
        sleep(SCD40_MEASUREMENT_INTERVAL);

        // Read measurement data
        uint8_t data[8];
        if (read(i2c_fd, data, 8) != 8) {
            perror("Failed to read from i2c device.\n");
            return 1;
        }

        // Validate CRC
        uint8_t crc = data[2] ^ data[3] ^ data[4] ^ data[5] ^ data[6] ^ data[7];
        if (crc != 0xFF) {
            printf("Invalid CRC\n");
            continue;
        }

        // Store reading
        readings[write_index].co2 = (data[0] << 8) | data[1];
        readings[write_index].temperature = (data[3] << 8) | data[4];
        readings[write_index].humidity = (data[5] << 8) | data[6];
        write_index = (write_index + 1) % SCD40_MAX_READINGS;
        if (write_index == read_index) {
            full = 1;
            read_index = (read_index + 1) % SCD40_MAX_READINGS;
        }

        // Print reading
        printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f%%\n",
               readings[read_index].co2, readings[read_index].temperature,
               readings[read_index].humidity);

        // Check for warning
        if (readings[read_index].co2 > SCD40_WARNING_THRESHOLD) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }

        // Wait for next reading
        sleep(SCD40_READ_INTERVAL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5
#define TIMEOUT 5000000
#define MIN_TEMP -40
#define MAX_TEMP 150
#define ERROR_THRESHOLD 3

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        printf("Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int error_count = 0;
    int last_value = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        uint32_t level = 0;
        uint32_t tick = gpioTick();
        uint32_t high_ticks = 0;
        uint32_t low_ticks = 0;

        while (level != 1) {
            level = gpioReadRaw(GPIO_PIN);
