#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP810_ADDRESS 0x28
#define PRESSURE_CONVERSION 0x40
#define TEMPERATURE_CONVERSION 0x50
#define FILE_NAME "airflow.csv"

int i2c_fd;
FILE *file;

void signal_handler(int signum) {
    close(i2c_fd);
    fclose(file);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    if ((file = fopen(FILE_NAME, "w")) == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    fprintf(file, "Timestamp, Pressure (Pa), Temperature (C)\n");

    while (1) {
        uint8_t command = PRESSURE_CONVERSION;
        write(i2c_fd, &command, 1);

        usleep(45000);

        uint8_t data[9];
        read(i2c_fd, data, 9);

        // CRC validation and data conversion goes here

        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(file, "%ld.%06ld, %f, %f\n", tv.tv_sec, tv.tv_usec, pressure, temperature);

        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define SHT35_ADDRESS 0x44
#define SHT35_MEAS_HIGHREP_NOCLKSTRETCH 0x2f
#define SHT35_CRC_POLYNOMIAL 0x31
#define SHT35_CRC_INITIAL 0xFF

static int i2c_fd = -1;
static FILE *csv_fd = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_fd != NULL) {
        fclose(csv_fd);
    }
    exit(signum);
}

int main() {
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = cleanup;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT35_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    if ((csv_fd = fopen("environment.csv", "a")) == NULL) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    char header[] = "timestamp,temperature,humidity\n";
    if (ftell(csv_fd) == 0) {
        fwrite(header, sizeof(char), strlen(header), csv_fd);
    }

    while (1) {
        uint8_t command = SHT35_MEAS_HIGHREP_NOCLKSTRETCH;
        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to write command");
            continue;
        }

        usleep(15000);

        uint8_t buffer[6];
        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read data");
            continue;
        }

        uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
        uint16_t raw_humidity = (buffer[3] << 8) | buffer[4];

        float temperature = -45 + 175 * raw_temperature / 65535.0;
        float humidity = 100 * raw_humidity / 65535.0;

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

        fprintf(csv_fd, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        fflush(csv_fd);
        sleep(5);
    }

    return EXIT_SUCCESS;
}

