#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define CONVERSION_TIME 45000 // 45ms in microseconds
#define LOG_FILE "pressure_log.txt"

static bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *scl, *sda;
    FILE *log_file;
    uint8_t buffer[9];
    uint32_t timestamp;
    int ret;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    // Set up I2C lines
    scl = gpiod_chip_get_line(chip, 0);
    sda = gpiod_chip_get_line(chip, 1);
    if (!scl || !sda) {
        fprintf(stderr, "Failed to get I2C lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Send continuous measurement command
    ret = gpiod_i2c_write(chip, I2C_ADDRESS, (uint8_t[]){0x21}, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to send command\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Wait for conversion time
    usleep(CONVERSION_TIME);

    // Read response
    ret = gpiod_i2c_read(chip, I2C_ADDRESS, buffer, sizeof(buffer));
    if (ret < 0) {
        fprintf(stderr, "Failed to read response\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Validate CRC-8
    // This is a placeholder for the actual CRC-8 check
    // which would depend on the specific details of the sensor's communication protocol
    if (buffer[8] != 0) {
        fprintf(stderr, "CRC-8 check failed\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Log pressure reading and timestamp
    timestamp = (uint32_t)time(NULL);
    fprintf(log_file, "%u: %u.%u.%u\n", timestamp, buffer[0], buffer[1], buffer[2]);

    // Close resources
    fclose(log_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

