#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define STLM75_ADDRESS 0x48
#define GPIO_PIN 17
#define BUFFER_SIZE 10

float buffer[BUFFER_SIZE];
int buffer_head = 0;
float sum = 0.0;
float average = 0.0;

int read_temperature(int file) {
    uint8_t reg = 0x00;
    uint8_t data[2];
    if (write(file, &reg, 1) != 1) {
        return -1;
    }
    if (read(file, data, 2) != 2) {
        return -1;
    }
    int16_t raw = (data[0] << 8) | data[1];
    return raw * 0.125;
}

void update_average(int temp) {
    sum -= buffer[buffer_head];
    buffer[buffer_head] = temp;
    sum += temp;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    average = sum / BUFFER_SIZE;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int file;
    char *filename = "/dev/i2c-1";
    int temp;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if ((file = open(filename, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open the i2c bus\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, STLM75_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(line, "led", 0);

    while (1) {
        temp = read_temperature(file);
        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        update_average(temp);
        gpiod_line_set_value(line, average > 28.0);
        sleep(1);
    }

    close(file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

