#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28

int i2c_fd = -1;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    uint8_t buffer[2];
    int ret;

    // Register SIGINT and SIGTERM handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read pressure from sensor
        ret = read(i2c_fd, buffer, 2);
        if (ret < 0) {
            perror("Failed to read from sensor");
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Print timestamp and pressure
        printf("%ld.%09ld: %d.%d\n", ts.tv_sec, ts.tv_nsec, buffer[0], buffer[1]);

        // Wait for 1 second
        sleep(1);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define PRESSURE_FILE "pressure_log.txt"

int i2c_fd;
FILE *file;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(file);
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = cleanup;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    if ((file = fopen(PRESSURE_FILE, "w")) == NULL) {
        perror("Failed to open file");
        exit(1);
    }

    while (1) {
        // Trigger measurement
        uint8_t trigger_cmd = 0x01;
        write(i2c_fd, &trigger_cmd, 1);

        // Wait for measurement to complete
        usleep(45000);

        // Read 9 bytes
        uint8_t buffer[9];
        if (read(i2c_fd, buffer, 9) != 9) {
            perror("Failed to read from sensor");
            continue;
        }

        // Validate CRC
        uint8_t crc = 0xFF;
        for (int i = 0; i < 8; i++) {
            crc ^= buffer[i];
        }

        if (crc != buffer[8]) {
            printf("Invalid CRC\n");
            continue;
        }

        // Log to file
        struct timeval tv;
        gettimeofday(&tv, NULL);
        struct tm *timeinfo = localtime(&tv.tv_sec);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(file, "%s,%d,%d\n", time_str, (buffer[0] << 8) | buffer[1], (buffer[2] << 8) | buffer[3]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP800_ADDRESS 0x40
#define SDP800_CONVERT 0x40
#define SDP800_READ 0x41
#define SDP800_RESET 0x80
#define SDP800_CRC_POLYNOMIAL 0x31
#define SDP800_CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "airflow_log.csv"

static int running = 1;
static int fd = -1;
static FILE *log_file = NULL;

void cleanup() {
    if (fd >= 0) {
        close(fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t buffer[4];
    uint32_t pressure;
    struct timespec ts;
    time_t current_time;
    struct tm *timeinfo;
    char time_string[20];
    uint8_t crc = SDP800_CRC_INITIAL_VALUE;

    atexit(cleanup);
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 4);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(4, PI_OUTPUT);
    gpioWrite(4, 0);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return EXIT_FAILURE;
    }

    if (access(LOG_FILE, F_OK) != 0) {
        log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            return EXIT_FAILURE;
        }
        fprintf(log_file, "Timestamp,Pressure\n");
    } else {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            return EXIT_FAILURE;
        }
    }

    while (running) {
        gpioWrite(4, 1);
        usleep(8000);
        gpioWrite(4, 0);

        if (write(fd, &SDP800_CONVERT, 1) != 1) {
            fprintf(stderr, "Failed to write to I2C device\n");
            continue;
        }

        usleep(10000);

        if (read(fd, buffer, 3) != 3) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        crc = SDP800_CRC_INITIAL_VALUE;
        for (int i = 0; i < 2; i++) {
            crc ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                if (crc & 0x80) {
                    crc = (crc << 1) ^ SDP800_CRC_POLYNOMIAL;
                } else {
                    crc <<= 1;
                }
            }
        }

        if (crc != buffer[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        pressure = (buffer[0] << 8) | buffer[1];

        clock_gettime(CLOCK_REALTIME, &ts);
        current_time = ts.tv_sec;
        timeinfo = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%u\n", time_string, pressure);
        fflush(log_file);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define MLX90821_ADDRESS 0x28
#define PRESSURE_FILE "pressure_log.csv"
#define PRESSURE_MIN 200
#define PRESSURE_MAX 250

int i2c_fd;
FILE *log_file;

void close_and_exit(int signum) {
    close(i2c_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = close_and_exit;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90821_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((log_file = fopen(PRESSURE_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    while (1) {
        uint16_t pressure;
        if (read(i2c_fd, &pressure, sizeof(pressure)) != sizeof(pressure)) {
            perror("Failed to read from sensor");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            ioctl(i2c_fd, I2C_SLAVE, MLX90821_ADDRESS);
            continue;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s,%d\n", timestamp, pressure);

        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Warning: Pressure outside safe range: %d kPa\n", pressure);
        }

        sleep(1);
    }

    return 0;
}

