#define HIH6130_ADDRESS 0x27
#define LOG_FILE "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576 // 1MB

static int i2c_fd = -1;
static FILE *log_fd = NULL;

void cleanup(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fd != NULL) {
        fclose(log_fd);
    }
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = cleanup;
    sigaction(SIGINT, &action, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HIH6130_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        uint16_t raw_data[2];
        char buffer[256];
        time_t now;
        struct tm *timeinfo;

        // Trigger measurement
        if (write(i2c_fd, "\x03", 1) != 1) {
            perror("Failed to trigger measurement");
            continue;
        }

        // Wait for measurement to complete
        usleep(40000);

        // Read measurement data
        if (read(i2c_fd, raw_data, 4) != 4) {
            perror("Failed to read measurement data");
            continue;
        }

        // Validate status bits
        if ((raw_data[0] & 0x03) != 0) {
            fprintf(stderr, "Invalid status bits\n");
            continue;
        }

        // Get current time
        time(&now);
        timeinfo = localtime(&now);

        // Format log entry
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", timeinfo);
        sprintf(buffer + strlen(buffer), " Humidity: %d.%02d%% Temperature: %d.%02d°C\n",
                (raw_data[1] >> 8) * 6.25, (raw_data[1] & 0xFF) * 0.25,
                (raw_data[0] >> 8) * 6.25, (raw_data[0] & 0xFF) * 0.25);

        // Write log entry
        fputs(buffer, log_fd);

        // Truncate log file if it exceeds size limit
        if (ftell(log_fd) > LOG_SIZE_LIMIT) {
            fseek(log_fd, 0, SEEK_SET);
            truncate(LOG_FILE, 0);
        }

        // Wait for next measurement
        sleep(5);
    }

    return 0;
}

