static int i2c_write_byte(int file, uint8_t data) {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data packets;
    uint8_t buffer[1];

    buffer[0] = data;
    msg.addr = TMP117_ADDRESS;
    msg.flags = 0;
    msg.len = sizeof(buffer);
    msg.buf = buffer;

    packets.msgs = &msg;
    packets.nmsgs = 1;

    return ioctl(file, I2C_RDWR, &packets);
}

static int i2c_read_word(int file) {
    struct i2c_msg msgs[2];
    uint8_t read_buffer[2];
    int result;

    msgs[0].addr = TMP117_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &TMP117_REG_TEMP;

    msgs[1].addr = TMP117_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = read_buffer;

    result = ioctl(file, I2C_RDWR, msgs);
    if (result < 0) {
        return result;
    }

    return (read_buffer[0] << 8) | read_buffer[1];
}

static void save_buffer() {
    write(file_descriptor, buffer, sizeof(buffer));
}

int main() {
