#define SHTC3_MEAS_MEDREP_STRETCH 0x2C0D
#define SHTC3_MEAS_LOWREP_STRETCH 0x2C10
#define SHTC3_READOUT_CRC8_POLYNOMIAL 0x31
#define SHTC3_READOUT_CRC8_INITIAL_VALUE 0xFF
#define SHTC3_READOUT_DATA_LENGTH 6
#define SHTC3_TEMPERATURE_MIN -40
#define SHTC3_TEMPERATURE_MAX 125
#define SHTC3_HUMIDITY_MIN 0
#define SHTC3_HUMIDITY_MAX 100

int i2c_fd;
FILE *log_file;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_file);
    exit(signum);
}

