    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    uint8_t buffer[SHTC3_READOUT_DATA_LENGTH];
    uint16_t raw_temperature, raw_humidity;
    int16_t temperature, humidity;
    uint8_t crc8;
    int i;

    signal(SIGINT, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    line = gpiod_chip_get_line(chip, 2);
    gpiod_line_request_output(line, "SHTC3", 0);
    gpiod_line_set_value(line, 1);
    usleep(1000);
    gpiod_line_set_value(line, 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHTC3_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return 1;
    }

    log_file = fopen("shtc3_environment.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        if (write(i2c_fd, &SHTC3_MEAS_HIGHREP_STRETCH, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }

        usleep(12000);

        if (read(i2c_fd, buffer, SHTC3_READOUT_DATA_LENGTH) != SHTC3_READOUT_DATA_LENGTH) {
            perror("Failed to read from I2C device");
            continue;
        }

        crc8 = SHTC3_READOUT_CRC8_INITIAL_VALUE;
        for (i = 0; i < SHTC3_READOUT_DATA_LENGTH - 1; i++) {
            crc8 ^= buffer[i];
            for (int j = 0; j < 8; j++) {
                if (crc8 & 0x80) {
                    crc8 = (crc8 << 1) ^ SHTC3_READOUT_CRC8_POLYNOMIAL;
                } else {
                    crc8 <<= 1;
                }
            }
        }

        if (crc8 != buffer[SHTC3_READOUT_DATA_LENGTH - 1]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        raw_temperature = (buffer[0] << 8) | buffer[1];
        raw_humidity = (buffer[3] << 8) | buffer[4];

        temperature = (int16_t)((raw_temperature * 175) / 65535 - 45);
        humidity = (int16_t)((raw_humidity * 100) / 65535);

        if (temperature < SHTC3_TEMPERATURE_MIN || temperature > SHTC3_TEMPERATURE_MAX ||
            humidity < SHTC3_HUMIDITY_MIN || humidity > SHTC3_HUMIDITY_MAX) {
            fprintf(stderr, "Out of range\n");
            continue;
