        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%0.2f,%0.2f\n",
                ts.tv_sec / 3600 / 24 + 719468, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
                ts.tv_sec % 60, (float)temperature, (float)humidity);
        printf("%0.2f,%0.2f\n", (float)temperature, (float)humidity);
    }

    return 0;
}

