#include <sys/time.h>

#define TMP117_ADDRESS 0x48
#define TMP117_REG_TEMP 0x00
#define I2C_RETRIES 3

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    char buf[10];
    int temp;
    int retry_count = 0;
    struct timespec req, rem;
    struct tm *timeinfo;
    time_t rawtime;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, TMP117_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    while (1) {
        if (write(file, &TMP117_REG_TEMP, 1) != 1) {
            perror("Failed to write to the i2c bus");
            retry_count++;
            if (retry_count > I2C_RETRIES) {
                close(file);
                exit(1);
            }
            continue;
        }

        if (read(file, buf, 2) != 2) {
            perror("Failed to read from the i2c bus");
            retry_count++;
            if (retry_count > I2C_RETRIES) {
                close(file);
                exit(1);
            }
            continue;
        }

        retry_count = 0;

        temp = (buf[0] << 8) | buf[1];
        if (temp & 0x8000) {
            temp = -((~temp & 0x7FFF) + 1);
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", timeinfo);

        FILE *logfile = fopen("temperature_log.txt", "a");
        if (logfile == NULL) {
            perror("Failed to open log file");
            close(file);
            exit(1);
        }

        fprintf(logfile, "%s, Temperature: %d C\n", buf, temp);
        fclose(logfile);
    }

    close(file);
    return 0;
}

