#include <gpiod.h>

#define SHT31D_ADDRESS 0x44
#define SHT31D_MEASURE_HIGHREP_STRETCH 0x2F
#define SHT31D_READ 0x00
#define SHT31D_CRC8_POLYNOMIAL 0x31
#define SHT31D_CRC8_INITIAL_VALUE 0xFF
#define SHT31D_I2C_BUS 1
#define SHT31D_GPIO_SDA 2
#define SHT31D_GPIO_SCL 3
#define SHT31D_LOG_FILE "sht31d_data.log"
#define SHT31D_LOG_FORMAT "%s,%d,%d\n"

static int sht31d_i2c_fd = -1;
static int sht31d_log_fd = -1;
static struct gpiod_chip *sht31d_chip = NULL;

static uint8_t sht31d_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = SHT31D_CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc & 0x80) ? (crc << 1) ^ SHT31D_CRC8_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

static int sht31d_i2c_write(const uint8_t *data, size_t len) {
    if (write(sht31d_i2c_fd, data, len) != len) {
        return -1;
    }
    return 0;
}

static int sht31d_i2c_read(uint8_t *data, size_t len) {
    if (read(sht31d_i2c_fd, data, len) != len) {
        return -1;
    }
    return 0;
}

static int sht31d_log(const char *format, ...) {
    va_list args;
    va_start(args, format);
    if (vfprintf(sht31d_log_fd, format, args) < 0) {
        return -1;
    }
    va_end(args);
    return 0;
}

static void sht31d_exit(int status) {
    if (sht31d_chip) {
        gpiod_chip_close(sht31d_chip);
    }
    if (sht31d_i2c_fd >= 0) {
        close(sht31d_i2c_fd);
    }
    if (sht31d_log_fd >= 0) {
        close(sht31d_log_fd);
    }
    exit(status);
}

static void sht31d_signal_handler(int signum) {
    sht31d_exit(0);
}

