        if (crc != buffer[2]) {
            fprintf(stderr, "CRC8 validation failed for temperature\n");
            continue;
        }

        crc = sht31d_crc8(buffer + 3, 2);
        if (crc != buffer[5]) {
            fprintf(stderr, "CRC8 validation failed for humidity\n");
            continue;
        }

        int16_t temperature = (buffer[0] << 8) | buffer[1];
