#define MLX90824_ADDRESS 0x28
#define LOG_FILE "pressure_log.txt"

int main() {
    int file;
    int i2c;
    int result;
    uint8_t buffer[6];
    struct timespec ts;
    char timestamp[26];
    char log[256];

    // Open log file
    file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (file < 0) {
        printf("Failed to open log file\n");
        return -1;
    }

    // Initialize pigpio
    if ((i2c = piI2COpen(1, MLX90824_ADDRESS)) < 0) {
        printf("Failed to open I2C bus\n");
        close(file);
        return -1;
    }

    while (1) {
        // Read from sensor
        result = piI2CReadDevice(i2c, buffer, 6);
        if (result < 0) {
            // Log error with timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
            sprintf(log, "%s: Failed to read from sensor\n", timestamp);
            write(file, log, strlen(log));
        } else {
            // Log measurement with timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
            sprintf(log, "%s: Pressure: %d.%d, Temperature: %d.%d\n", timestamp, buffer[0], buffer[1], buffer[2], buffer[3]);
            write(file, log, strlen(log));
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Clean up
    piI2CClose(i2c);
    close(file);
    return 0;
}

