#include <signal.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75B_ADDRESS 0x48
#define GPIO_FAN 18
#define SAMPLES 60
#define TEMP_THRESHOLD 28.0
#define TEMP_THRESHOLD_OFF 26.0

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2c_fd, gpio_fd;
    float temp[SAMPLES];
    float avg_temp = 0.0;
    int index = 0;
    float sum = 0.0;
    int i;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_FAN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line, "fan", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75B_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop) {
        // Read temperature
        uint8_t buffer[2];
        if (read(i2c_fd, buffer, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        float temperature = (buffer[0] << 8 | buffer[1]) >> 7;
        temperature *= 0.125;

        // Store temperature in circular buffer
        sum -= temp[index];
        temp[index] = temperature;
        sum += temperature;
        index = (index + 1) % SAMPLES;

        // Compute running average
        avg_temp = sum / SAMPLES;

        // Drive cooling fan
        int fan_state = avg_temp > TEMP_THRESHOLD;
        if (gpiod_line_set_value(line, fan_state)) {
            fprintf(stderr, "Failed to set GPIO line value\n");
        }

        // Sleep for a second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <stdint.h>

#define SDP810_ADDRESS 0x40
#define SDP810_MEASUREMENT_COMMAND 0x03
#define SDP810_CRC8_POLYNOMIAL 0x31
#define SDP810_CRC8_INIT_VALUE 0xFF
#define LOG_FILE "airflow.log"

int i2c_fd;
FILE *log_fd;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_fd);
    exit(signum);
}

uint8_t calculate_crc8(uint8_t *data, size_t length) {
    uint8_t crc = SDP810_CRC8_INIT_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    struct sigaction sigact;
    memset(&sigact, 0, sizeof(sigact));
    sigact.sa_handler = cleanup;
    sigaction(SIGINT, &sigact, NULL);
    sigaction(SIGTERM, &sigact, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP810_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((log_fd = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log_fd, "timestamp,pressure,temperature\n");

    while (1) {
        uint8_t command[1] = {SDP810_MEASUREMENT_COMMAND};
        if (write(i2c_fd, command, 1) != 1) {
            perror("Failed to write to i2c device");
            continue;
        }

        usleep(45000);

        uint8_t response[9];
        if (read(i2c_fd, response, 9) != 9) {
            perror("Failed to read from i2c device");
            continue;
        }

        if (calculate_crc8(response, 8) != response[8]) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        struct timeval tv;
        gettimeofday(&tv, NULL);
        time_t timestamp = tv.tv_sec;
        double pressure = (response[0] << 8) | response[1];
        double temperature = (response[2] << 8) | response[3];

        fprintf(log_fd, "%ld,%f,%f\n", timestamp, pressure, temperature);

        if (pressure > 5.0) {
            fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
        }

        sleep(1);
    }

    return 0;
}

#include <stdio.h>
