#define I2C_BUS "/dev/i2c-1"
#define TEMP_SENSOR_ADDRESS 0x48
#define LED_PIN 17

int i2c_fd, led_fd;
bool led_state = false;

void cleanup() {
    if (led_fd >= 0) {
        gpiod_line_set_value(led_fd, 0);
        gpiod_line_release(led_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

void handle_sigint(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_sigint;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TEMP_SENSOR_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if ((led_fd = gpiod_open_by_number(LED_PIN, "LED", GPIOD_OPEN_AS_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open LED pin: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t temp_data[2];
        if (read(i2c_fd, temp_data, 2) != 2) {
            fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        int16_t temp = (temp_data[0] << 8) | temp_data[1];
        float temperature = temp / 16.0;

        printf("Temperature: %.2f°C\n", temperature);

        if (temperature > 28.0) {
            if (!led_state) {
                gpiod_line_set_value(led_fd, 1);
                led_state = true;
            }
        } else if (temperature < 27.0) {
            if (led_state) {
                gpiod_line_set_value(led_fd, 0);
                led_state = false;
            }
        }

        sleep(1);
    }

    cleanup();
    return EXIT_SUCCESS;
}

