#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x40
#define FLOW_DATA_FILE "flow_data.txt"

static int i2c_fd;
static int flow_data_fd;

void cleanup(int signum) {
    close(i2c_fd);
    close(flow_data_fd);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t buffer[9];
    int ret;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Open GPIO line
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, cleanup);

    // Open flow data file
    flow_data_fd = open(FLOW_DATA_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (flow_data_fd < 0) {
        perror("Failed to open flow data file");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Send measurement command
        buffer[0] = 0x21;
        if (write(i2c_fd, buffer, 1) < 0) {
            perror("Failed to send measurement command");
            continue;
        }

        // Wait for measurement to complete
        usleep(45000);

        // Read measurement result
        if (read(i2c_fd, buffer, 9) < 0) {
            perror("Failed to read measurement result");
            continue;
        }

        // Validate CRC bytes
        uint8_t crc8 = buffer[2];
        buffer[2] = 0;
        for (int i = 0; i < 2; i++) {
            crc8 = crc8_update(crc8, buffer[i]);
        }
        if (crc8 != buffer[2]) {
            fprintf(stderr, "Invalid CRC byte for differential pressure\n");
            continue;
        }

        crc8 = buffer[5];
        buffer[5] = 0;
        for (int i = 3; i < 5; i++) {
            crc8 = crc8_update(crc8, buffer[i]);
        }
        if (crc8 != buffer[5]) {
            fprintf(stderr, "Invalid CRC byte for temperature\n");
            continue;
        }

        // Log measurement result
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        dprintf(flow_data_fd, "%s, %d.%d, %d.%d\n", timestamp, buffer[0], buffer[1], buffer[3], buffer[4]);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(flow_data_fd);

    return EXIT_SUCCESS;
}

