#define SI7021_FIRMWARE_REV 0x11
#define SI7021_MEASURE_RH_NO_HOLD 0xE5
#define SI7021_MEASURE_TEMP_NO_HOLD 0xF3
#define SI7021_READ_TEMP_FROM_PREV_RH_MEAS 0xE0
#define I2C_RETRY_COUNT 3

static int i2c_fd;
static FILE *log_file;

void cleanup(int exit_code) {
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
    exit(exit_code);
}

void signal_handler(int signum) {
    cleanup(0);
}

int read_i2c_byte(int command) {
    int retry_count = 0;
    while (retry_count++ < I2C_RETRY_COUNT) {
        if (ioctl(i2c_fd, I2C_SLAVE, SI7021_I2C_ADDRESS) < 0) {
            perror("Failed to set I2C slave address");
            continue;
        }
        if (write(i2c_fd, &command, 1) != 1) {
            perror("Failed to write to I2C device");
            continue;
        }
        usleep(20000); // Wait at least 20ms
        unsigned char data[2];
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read from I2C device");
            continue;
        }
        return (data[0] << 8) | data[1];
    }
    return -1;
}

