        perror("Failed to open log file");
        cleanup(1);
    }

    while (1) {
        int rh = read_i2c_byte(SI7021_MEASURE_RH_NO_HOLD);
        if (rh < 0) {
            fprintf(stderr, "Failed to read humidity\n");
            cleanup(1);
        }
        int temp = read_i2c_byte(SI7021_MEASURE_TEMP_NO_HOLD);
        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            cleanup(1);
        }
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s, %d, %d\n", buffer, temp, rh);
        fflush(log_file);
        printf("%s, %d, %d\n", buffer, temp, rh);
        sleep(60); // Wait for 60 seconds
    }

