    usleep(HDC1080_CONVERSION_DELAY);
    if (read(i2c_fd, buffer, 4) != 4) {
        return -1;
    }
    *temperature = (buffer[0] << 8 | buffer[1]) * 0.1;
    *humidity = (buffer[2] << 8 | buffer[3]) * 0.1;
    return 0;
}

