#define SCD40_I2C_ADDRESS 0x61
#define SCD40_MEASUREMENT_INTERVAL 5
#define SCD40_LOG_INTERVAL 60
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INITIAL_VALUE 0xFF

volatile sig_atomic_t running = 1;

typedef struct {
    uint16_t co2;
    int16_t temperature;
    int16_t humidity;
} SCD40Data;

SCD40Data buffer[100];
int buffer_head = 0;
int buffer_tail = 0;

void* log_thread(void* arg) {
    while (running) {
        sleep(SCD40_LOG_INTERVAL);
        FILE* file = fopen("/var/log/scd40_data/data.csv", "a");
        if (file == NULL) {
            printf("Failed to open log file\n");
            continue;
        }
        for (int i = buffer_tail; i != buffer_head; i = (i + 1) % 100) {
            fprintf(file, "%d,%d,%d\n", buffer[i].co2, buffer[i].temperature, buffer[i].humidity);
        }
        fclose(file);
        buffer_tail = buffer_head;
    }
    return NULL;
}

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    signal(SIGINT, handle_sigint);

    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        printf("Failed to open the i2c bus\n");
        return 1;
    }

    if (ioctl(file, I2C_SLAVE, SCD40_I2C_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave\n");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, log_thread, NULL) != 0) {
        printf("Failed to create logging thread\n");
        return 1;
    }

    sleep(1);

    while (running) {
        uint8_t command[2] = {0x21, 0x08};
        if (write(file, command, 2) != 2) {
            printf("Failed to write command\n");
            continue;
        }

        sleep(SCD40_MEASUREMENT_INTERVAL);

        uint8_t data[6];
        if (read(file, data, 6) != 6) {
            printf("Failed to read data\n");
            continue;
        }

        uint8_t crc = data[2];
        for (int i = 0; i < 2; i++) {
            crc = (crc << 8) ^ SCD40_CRC_POLYNOMIAL;
            crc ^= data[i];
        }
        for (int i = 3; i < 5; i++) {
            crc = (crc << 8) ^ SCD40_CRC_POLYNOMIAL;
            crc ^= data[i];
        }

        if (crc != 0) {
            printf("CRC error\n");
            continue;
        }

        SCD40Data reading = {
            (data[0] << 8) | data[1],
            (data[3] << 8) | data[4],
            (data[5] << 8) | data[6]
        };

        buffer[buffer_head] = reading;
        buffer_head = (buffer_head + 1) % 100;

        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % 100;
        }
    }

    pthread_join(thread_id, NULL);

    close(file);

    return 0;
}

