                crc_calculated = (crc_calculated >> 1) ^ (0x31 * bit);
            }
            if (crc_calculated != crc) {
                printf("CRC failure for byte %d\n", i);
                continue;
            }
        }

        // Log the data
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        fprintf(log_file, "%s, %d, %d\n", asctime(timeinfo), (buf[2] << 8) | buf[3], (buf[4] << 8) | buf[5]);
        fflush(log_file);
    }

    return 0;
}
