#define MLX90614_ADDRESS 0x5A
#define MLX90614_TOBJ1 0x07
#define MLX90614_TAMB1 0x06
#define FAN_PIN 18
#define RETRIES 3
#define RETRY_DELAY 10e-3
#define MIN_TEMP 28
#define MAX_TEMP 30

static struct gpiod_chip *chip;
static struct gpiod_line *fan_line;
static int i2c_fd;
static FILE *log_file;

void cleanup() {
    fclose(log_file);
    gpiod_line_set_value(fan_line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    fan_line = gpiod_chip_get_line(chip, FAN_PIN);
    if (!fan_line) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", FAN_PIN);
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(fan_line, "fan", 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    uint16_t tobj, tamb;
    bool fan_on = false;
    struct timespec sleep_time = {0, 200000000}; // 2 seconds

    while (true) {
        for (int i = 0; i < RETRIES; ++i) {
            if (write(i2c_fd, &MLX90614_TOBJ1, 1) != 1 || read(i2c_fd, &tobj, 2) != 2 ||
                write(i2c_fd, &MLX90614_TAMB1, 1) != 1 || read(i2c_fd, &tamb, 2) != 2) {
                usleep(RETRY_DELAY * 1e6);
                continue;
            }
            break;
        }

        float object_temp = (tobj * 0.02) - 273.15;
        float ambient_temp = (tamb * 0.02) - 273.15;

        if (object_temp < MIN_TEMP || object_temp > MAX_TEMP) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s Ambient: %.2f°C Object: %.2f°C\n", buffer, ambient_temp, object_temp);

        if (object_temp > MAX_TEMP && !fan_on) {
            gpiod_line_set_value(fan_line, 1);
            fan_on = true;
        } else if (object_temp < MIN_TEMP && fan_on) {
            gpiod_line_set_value(fan_line, 0);
            fan_on = false;
        }

        nanosleep(&sleep_time, NULL);
    }

    return EXIT_SUCCESS;
}

