#define AHT20_STATUS_CMD 0x71
#define AHT20_DATA_LEN 6
#define AHT20_RETRY_COUNT 3
#define AHT20_RETRY_PAUSE 10000
#define AHT20_POLL_INTERVAL 5000
#define AHT20_HUMIDITY_THRESHOLD_LOW 55
#define AHT20_HUMIDITY_THRESHOLD_HIGH 60
#define GPIO_DEHUMIDIFIER 17

static int i2c_fd = -1;
static int dehumidifier_fd = -1;

static void cleanup(int status) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (dehumidifier_fd != -1) {
        gpioWrite(dehumidifier_fd, 0);
        gpioTerminate();
    }
    exit(status);
}

static int read_i2c(int address, uint8_t *data, size_t len) {
    int retries = AHT20_RETRY_COUNT;
    while (retries--) {
        if (write(i2c_fd, &address, 1) != 1) {
            return -1;
        }
        if (read(i2c_fd, data, len) != len) {
            usleep(AHT20_RETRY_PAUSE);
            continue;
        }
        return 0;
    }
    return -1;
}

static int read_sensor(float *humidity) {
    uint8_t cmd[] = {AHT20_MEASURE_CMD, 0x33, 0x00};
    uint8_t status;
    uint8_t data[AHT20_DATA_LEN];
    int ret;

    if ((ret = read_i2c(AHT20_ADDRESS, cmd, sizeof(cmd))) != 0) {
        return ret;
    }
    usleep(80000);
    if ((ret = read_i2c(AHT20_ADDRESS, data, sizeof(data))) != 0) {
        return ret;
    }
    if ((ret = read_i2c(AHT20_ADDRESS, &status, 1)) != 0) {
        return ret;
    }
    if ((status & 0x08) == 0) {
        return -1;
    }
    *humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) * 0.0006103515625;
    return 0;
}

static void handle_signal(int signum) {
    cleanup(0);
}

int main() {
    float humidity;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        cleanup(EXIT_FAILURE);
    }
    dehumidifier_fd = gpioOpen(GPIO_DEHUMIDIFIER, 0, 0);
    if (dehumidifier_fd < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", GPIO_DEHUMIDIFIER);
        cleanup(EXIT_FAILURE);
    }

    while (1) {
        if (read_sensor(&humidity) == 0) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Humidity: %.2f%% at %ld.%09ld\n", humidity, ts.tv_sec, ts.tv_nsec);
            if (humidity > AHT20_HUMIDITY_THRESHOLD_HIGH) {
                gpioWrite(dehumidifier_fd, 1);
            } else if (humidity < AHT20_HUMIDITY_THRESHOLD_LOW) {
                gpioWrite(dehumidifier_fd, 0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor\n");
        }
        usleep(AHT20_POLL_INTERVAL);
    }

    cleanup(EXIT_SUCCESS);
}

