#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x76
#define UDP_PORT 5000
#define UDP_IP "192.168.1.100"
#define JSON_BUFFER_SIZE 256

static int i2c_fd;
static int udp_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(udp_fd);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sockaddr_in server_addr;
    char json_buffer[JSON_BUFFER_SIZE];
    int16_t temperature, pressure;
    int ret;

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Open GPIO line
    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    // Create UDP socket
    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }

    // Set up server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    server_addr.sin_addr.s_addr = inet_addr(UDP_IP);

    // Main loop
    while (1) {
        // Wait for measurement to complete
        gpiod_line_wait_both_edges(line, 0);

        // Read temperature and pressure
        if (read(i2c_fd, &temperature, sizeof(temperature)) < 0) {
            perror("Failed to read temperature");
            continue;
        }
        if (read(i2c_fd, &pressure, sizeof(pressure)) < 0) {
            perror("Failed to read pressure");
            continue;
        }

        // Format into JSON
        snprintf(json_buffer, JSON_BUFFER_SIZE, "{\"temperature\": %d, \"pressure\": %d}", temperature, pressure);

        // Send UDP packet
        ret = sendto(udp_fd, json_buffer, strlen(json_buffer), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
        if (ret < 0) {
            perror("Failed to send UDP packet");
            continue;
        }
    }

    cleanup();
    return 0;
}

