#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <spi.h>

#define FAN_PIN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MAX31855_CS 8
#define TEMP_UPDATE_INTERVAL 1
#define FAN_UPDATE_INTERVAL 1
#define FAN_CURVE_POINTS 4
#define FAN_CURVE_MAX 255

typedef struct {
    uint32_t timestamp;
    float temperature;
    uint8_t duty_cycle;
} FanData;

FanData fan_buffer[20];
int buffer_head = 0;

float fan_curve[FAN_CURVE_POINTS][2] = {
    {0, 0},
    {25, 0},
    {40, 128},
    {60, 200},
    {255, 255}
};

int get_duty_cycle(float temp) {
    int i;
    for (i = 0; i < FAN_CURVE_POINTS - 1; i++) {
        if (temp >= fan_curve[i][0] && temp < fan_curve[i+1][0]) {
            float slope = (fan_curve[i+1][1] - fan_curve[i][1]) / (fan_curve[i+1][0] - fan_curve[i][0]);
            return (int)(fan_curve[i][1] + slope * (temp - fan_curve[i][0]));
        }
    }
    return FAN_CURVE_MAX;
}

void update_fan() {
    int spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI channel\n");
        return;
    }

    uint8_t tx_buf[3] = {0x01, 0x00, 0x00};
    uint8_t rx_buf[3];

    if (spiXfer(spi_fd, tx_buf, rx_buf, sizeof(tx_buf)) != sizeof(tx_buf)) {
        fprintf(stderr, "Error reading from MAX31855\n");
        spiClose(spi_fd);
        return;
    }

    spiClose(spi_fd);

    float temp = (rx_buf[1] << 8) | rx_buf[2];
    temp = temp * 0.25 - 50;

    int duty_cycle = get_duty_cycle(temp);

    gpioHardwarePWM(FAN_PIN, 1000, duty_cycle);

    fan_buffer[buffer_head].timestamp = time(NULL);
    fan_buffer[buffer_head].temperature = temp;
    fan_buffer[buffer_head].duty_cycle = duty_cycle;
    buffer_head = (buffer_head + 1) % 20;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, gpioTerminate);

    while (1) {
        update_fan();
        sleep(TEMP_UPDATE_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

