#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BMP180_I2C_ADDRESS 0x77
#define BMP180_OSS 3
#define ALTITUDE_LOG_FILE "altitude_log.txt"

static int i2c_fd;
static int log_fd;
static int logging = 0;

void cleanup(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpiod_close();
    exit(signum);
}

int read_i2c_reg(int fd, int reg) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];

    messages[0].addr = BMP180_I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &reg;

    messages[1].addr = BMP180_I2C_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 2;
    messages[1].buf = &reg;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if(ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from the i2c bus.");
        return -1;
    }

    return reg;
}

int write_i2c_reg(int fd, int reg, int value) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];
    char buf[3];

    buf[0] = reg;
    buf[1] = value >> 8;
    buf[2] = value & 0xFF;

    messages[0].addr = BMP180_I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 3;
    messages[0].buf = buf;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if(ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to write to the i2c bus.");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = cleanup;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if(i2c_fd < 0) {
        perror("Failed to open the i2c bus.");
        return -1;
    }

    log_fd = open(ALTITUDE_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if(log_fd < 0) {
        perror("Failed to open the log file.");
        return -1;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpio");
    struct gpiod_line *line = gpiod_chip_get_line(chip, 2);
    gpiod_line_request_input(line, "falling_edge");
    gpiod_line_set_falling_edge(line);

    while(1) {
        if(logging) {
            int reg = 0xF4;
            write_i2c_reg(i2c_fd, reg, 0x2E + (BMP180_OSS << 6));

            usleep(450000);

            int msb = read_i2c_reg(i2c_fd, 0xF6);
            int lsb = read_i2c_reg(i2c_fd, 0xF7);
            int xlsb = read_i2c_reg(i2c_fd, 0xF8);

            int raw = (msb << 16) | (lsb << 8) | xlsb;
            float pressure = (raw / 2.0) / (1 << BMP180_OSS);

            // TODO: Calculate temperature and altitude from pressure

            char buffer[256];
            time_t now = time(NULL);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
            write(log_fd, buffer, strlen(buffer));
            write(log_fd, ",", 1);
            sprintf(buffer, "%.2f,%.2f\n", temperature, pressure);
            write(log_fd, buffer, strlen(buffer));
        }

        struct timespec req, rem;
        req.tv_sec = 1;
        req.tv_nsec = 0;
        nanosleep(&req, &rem);
    }

    return 0;
}

