    packets.nmsgs = 2;

    if(ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from the i2c bus.");
        return -1;
    }

    return reg;
}

int write_i2c_reg(int fd, int reg, int value) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];
    char buf[3];

    buf[0] = reg;
    buf[1] = value >> 8;
    buf[2] = value & 0xFF;

    messages[0].addr = BMP180_I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 3;
    messages[0].buf = buf;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if(ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to write to the i2c bus.");
        return -1;
    }

    return 0;
}

