#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <wiringPiSPI.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define CE_PIN 8
#define FAULT_PIN 9
#define RTD_A 0x3FFFF
#define RTD_B 0x40000
#define RTD_C 0x3FFFF
#define RTD_D 0x40000
#define BIAS 0x8000
#define FAULT 0x2000

FILE *log_file;
bool running = true;

void signal_handler(int signum) {
    running = false;
}

void setup() {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    gpiod_line_request input_request = {
        .consumer = "rtd_reader",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = 0
    };
    gpiod_line_request output_request = {
        .consumer = "rtd_reader",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
        .flags = 0
    };
    gpiod_chip_get_line(chip, CE_PIN)->request = &input_request;
    gpiod_chip_get_line(chip, FAULT_PIN)->request = &output_request;
    gpiod_chip_close(chip);
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_file = fopen("rtd_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "Timestamp,Temperature\n");
}

void cleanup() {
    fclose(log_file);
}

int main() {
    setup();
    int spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    uint16_t rtd_data;
    while (running) {
        gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
        gpiod_line_set_value(chip->lines[CE_PIN], 1);
        rtd_data = wiringPiSPIDataRW(SPI_CHANNEL, &rtd_data, 2);
        gpiod_line_set_value(chip->lines[CE_PIN], 0);
        gpiod_chip_close(chip);
        if (rtd_data & FAULT) {
            fprintf(stderr, "Sensor fault detected\n");
            continue;
        }
        int rtd_count = (rtd_data & RTD_A) | ((rtd_data & RTD_B) << 16);
        float rtd_resistance = 32768.0 / rtd_count - 1.0;
        float temperature = 0.0;
        if (rtd_resistance > 0.0) {
            temperature = 100.0 * log(rtd_resistance);
            temperature = 1.0 / (0.001129148 + 0.000234125 * temperature + 0.0000000876741 * temperature * temperature) - 273.15;
        }
        time_t timestamp = time(NULL);
        struct tm *timeinfo = localtime(&timestamp);
        char buffer[20];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s,%.2f\n", buffer, temperature);
        sleep(5);
    }
    cleanup();
    return 0;
}

