#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BME280_I2C_ADDRESS 0x76
#define BME280_CHIP_ID 0x60

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request req;
    struct gpiod_line *line;
    int file;
    char filename[] = "/dev/i2c-1";
