    int chip_id;
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        printf("Failed to get SDA line\n");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.consumer = "BME280";
    req.request_type = GPIO_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(line, &req)) {
        printf("Failed to request SDA line\n");
        return -1;
    }

    file = open(filename, O_RDWR);
    if (file < 0) {
        printf("Failed to open I2C device\n");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, BME280_I2C_ADDRESS) < 0) {
        printf("Failed to set I2C address\n");
        return -1;
    }

    if (write(file, "\xF2", 1) < 0) {
        printf("Failed to write to I2C device\n");
        return -1;
    }

    if (read(file, buf, 1) < 0) {
        printf("Failed to read from I2C device\n");
        return -1;
    }

    chip_id = buf[0];
    if (chip_id != BME280_CHIP_ID) {
        printf("Invalid chip ID\n");
        return -1;
    }

    while (1) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (write(file, "\xF3", 1) < 0) {
            printf("Failed to write to I2C device\n");
            return -1;
        }

        if (read(file, buf, 6) < 0) {
            printf("Failed to read from I2C device\n");
            return -1;
        }

        float temperature = (buf[0] << 8 | buf[1]) / 100.0;
        float humidity = (buf[2] << 8 | buf[3]) / 1024.0;
        float pressure = (buf[4] << 8 | buf[5]) / 256.0;

        FILE *log_file = fopen("bme280_log.csv", "a");
        if (!log_file) {
            printf("Failed to open log file\n");
            return -1;
        }

        fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", time_str, temperature, humidity, pressure);
        fclose(log_file);

        sleep(5);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(file);

    return 0;
}

