    if (ret < 0) {
        perror("Failed to acquire I2C bus access and/or talk to slave");
        return EXIT_FAILURE;
    }

    log_file = fopen("bmp180_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
