        float press = (raw_press / 16384.0f) * 0.00006103515625f * 101325.0f;

        sprintf(buffer, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f °C, Pressure: %.2f hPa\n",
                ts.tv_sec / 3600 / 24 + 719468,
                (ts.tv_sec / 3600 + 4) % 24,
                (ts.tv_sec / 60) % 60,
                (ts.tv_sec % 60) / 60,
                (ts.tv_sec % 60) % 60,
                temp, press);
        write(file, buffer, strlen(buffer));

        clock_gettime(CLOCK_REALTIME, &ts);
        sleep(5);
    }

    close(file);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define LM75_ADDRESS 0x48
#define GPIO18 18
#define SAMPLES 60
#define ALERT_TEMP 28000

struct circular_buffer {
    int head, tail;
    int size;
    int *buffer;
};

struct circular_buffer cb;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_t thread_id;
gpiod_line *line;
int i2c_fd;

void *thread_func(void *arg) {
    while (true) {
        pthread_mutex_lock(&mutex);
        int temp = cb.buffer[cb.head];
        pthread_mutex_unlock(&mutex);
        if (temp > ALERT_TEMP) {
            gpiod_line_set_value(line, 1);
        } else {
            gpiod_line_set_value(line, 0);
        }
        sleep(1);
    }
    return NULL;
}

int main() {
    int temp;
    int running_avg = 0;
    int samples_count = 0;

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open the i2c bus\n");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave.\n");
        return EXIT_FAILURE;
    }

    if ((line = gpiod_line_request_output(gpiod_chip_find_line(gpiod_chip_open_by_name("gpiochip0"), GPIO18), "alert", 0)) == NULL) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return EXIT_FAILURE;
    }

    cb.size = SAMPLES;
    cb.head = cb.tail = 0;
    cb.buffer = malloc(sizeof(int) * SAMPLES);

    if (pthread_create(&thread_id, NULL, &thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return EXIT_FAILURE;
    }

    while (true) {
        if (read(i2c_fd, &temp, 2) != 2) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }

        pthread_mutex_lock(&mutex);
        cb.buffer[cb.head] = temp;
        cb.head = (cb.head + 1) % SAMPLES;
        samples_count++;
        if (samples_count > SAMPLES) {
            running_avg -= cb.buffer[cb.tail];
            cb.tail = (cb.tail + 1) % SAMPLES;
        } else {
            running_avg += temp;
        }
        pthread_mutex_unlock(&mutex);

        sleep(1);
    }

    free(cb.buffer);
    gpiod_line_release(line);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

