#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define BMP180_I2C_ADDRESS 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_REG_CALIB 0xAA

#define BMP180_OSS 0 // Oversampling setting

#define BMP180_TEMPERATURE 0x2E
#define BMP180_PRESSURE 0x34 + (BMP180_OSS << 6)

#define BMP180_TEMP_BASE 0x00
#define BMP180_PRESSURE_BASE 0x00 + (BMP180_OSS << 6)

#define BMP180_NUM_REGS 22

int fd;

int read_i2c_reg(int reg) {
    uint8_t buf[2] = {reg};
    if (write(fd, buf, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int write_i2c_reg(int reg, int value) {
    uint8_t buf[3] = {reg, value >> 8, value & 0xFF};
    return write(fd, buf, 3);
}

int main() {
    if ((fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP180_I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    int calib[BMP180_NUM_REGS];
    for (int i = 0; i < BMP180_NUM_REGS; i++) {
        calib[i] = read_i2c_reg(BMP180_REG_CALIB + i * 2);
        if (calib[i] < 0) {
            perror("Failed to read calibration data");
            return 1;
        }
    }

    int file = open("breach_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file < 0) {
        perror("Failed to open breach_log.txt");
        return 1;
    }

    while (1) {
        int raw_temp = read_i2c_reg(BMP180_REG_RESULT);
        int raw_pressure = read_i2c_reg(BMP180_REG_RESULT);
        if (raw_temp < 0 || raw_pressure < 0) {
            perror("Failed to read temperature or pressure");
            return 1;
        }

        int32_t true_temp = (raw_temp >> 8) * 0.1;
        int32_t true_pressure = (raw_pressure >> 8) * 0.1;

        if (true_temp > 30.0 || true_pressure < 950) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            char log[100];
            sprintf(log, "%s: Temperature = %.2f°C, Pressure = %.2fhPa\n", timestamp, true_temp, true_pressure);
            write(file, log, strlen(log));
        }

        sleep(1);
    }

    close(file);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <wiringPiI2C.h>
#include <gpiod.h>

#define BMP180_I2C_ADDRESS 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_OSS 0
#define GPIO_FAN 18

volatile sig_atomic_t stop = 0;

void handle_interrupt(int signum) {
    stop = 1;
}

int main() {
    int i2c_fd, gpio_fd;
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec ts;
    int16_t calib[11];
    int32_t ut, up, x1, x2, b5, t, p;
    int i;

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(BMP180_I2C_ADDRESS);
    if (i2c_fd < 0) {
        printf("Failed to initialize I2C\n");
        return -1;
    }

    // Initialize GPIO
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        printf("Failed to initialize GPIO\n");
        return -1;
    }

    // Request GPIO line
    memset(&request, 0, sizeof(request));
    request.consumer = "BMP180";
    request.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    if (gpiod_chip_get_line(gpio_fd, GPIO_FAN, &request) < 0) {
        printf("Failed to request GPIO line\n");
        return -1;
    }

    // Set up signal handler
    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    // Read calibration data
    for (i = 0; i < 11; i++) {
        calib[i] = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_CALIB + i * 2);
    }

    // Main loop
    while (!stop) {
        // Request temperature measurement
        wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x2E);

        // Wait for measurement to complete
        usleep(45000);

        // Read temperature measurement
        ut = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_RESULT);

        // Request pressure measurement
        wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6));

        // Wait for measurement to complete
        usleep(45000 << BMP180_OSS);

        // Read pressure measurement
        up = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_RESULT);

        // Convert raw measurements to temperature and pressure
        x1 = ((ut - calib[5]) * calib[2]) >> 15;
        x2 = ((calib[4] * (ut - calib[5])) >> 15) + (calib[3] << 2);
        b5 = x1 + x2;
        t = (b5 + 8) >> 4;
        p = (((up >> (8 - BMP180_OSS)) - calib[0]) * calib[1]) >> 12;

        // Print temperature and pressure
        printf("Temperature: %d°C, Pressure: %dPa\n", t, p);

        // Turn on fan if temperature exceeds 30°C
        if (t > 300) {
            gpiod_line_set_value(gpio_fd, GPIO_FAN, 1);
        } else {
            gpiod_line_set_value(gpio_fd, GPIO_FAN, 0);
        }

        // Sleep for 500ms
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_sec += 1;
        ts.tv_nsec += 500000000;
        clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);
    }

    // Turn off fan
    gpiod_line_set_value(gpio_fd, GPIO_FAN, 0);

    // Close I2C and GPIO handles
    close(i2c_fd);
    gpiod_chip_close(gpio_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <libgpiod/gpiod.h>

#define BMP180_I2C_ADDRESS 0x77
#define GPIO27 27
#define LOG_FILE "pressure_log.txt"
#define LOG_INTERVAL 2
#define DEBOUNCE_TIME 200000

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static int log_fd;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_line_event event;
    struct timespec ts;
    uint8_t raw_data[2];
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO27);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_falling_edge_events(line, "BMP180 interrupt");
    if (ret) {
        fprintf(stderr, "Failed to request falling edge events\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        ret = gpiod_line_event_wait(line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            clock_gettime(CLOCK_REALTIME, &ts);
            write(log_fd, &ts, sizeof(ts));
            write(log_fd, raw_data, sizeof(raw_data));
        }
    }

    close(log_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define CS_PIN 8
#define MISO_PIN 9
#define MOSI_PIN 10
#define SCLK_PIN 11
#define HEATER_PIN 17
#define TARGET_TEMP 25.0
#define MAX_DUTY_CYCLE 80

static int spi_fd;
static int heater_fd;
static FILE *log_file;

void cleanup() {
    gpiod_set_value(heater_fd, 0);
    close(spi_fd);
    fclose(log_file);
    gpiod_close(heater_fd);
}

void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer tr;
    unsigned char tx[3] = {0x00, 0x00, 0x00};
    unsigned char rx[3];
    float temp;
    int duty_cycle = 0;
    time_t now;
    struct tm *timeinfo;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI device
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Failed to configure SPI device");
        return -1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Request GPIO lines
    memset(&request, 0, sizeof(request));
    request.consumer = "heater";
    request.request_type = GPIO_REQUEST_OUTPUT;
    if (gpiod_chip_get_line(chip, CS_PIN, &request) < 0) {
        perror("Failed to request CS pin");
        return -1;
    }
    if (gpiod_chip_get_line(chip, HEATER_PIN, &request) < 0) {
        perror("Failed to request heater pin");
        return -1;
    }

    // Open heater pin
    heater_fd = gpiod_chip_get_line(chip, HEATER_PIN);
    if (!heater_fd) {
        perror("Failed to open heater pin");
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open log file
    log_file = fopen("heater_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    // Write log header
    fprintf(log_file, "Timestamp,Measurement,Duty Cycle\n");

    // Main loop
    while (1) {
        // Read temperature
        tx[0] = 0x01;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
            perror("Failed to read temperature");
            duty_cycle = 0;
            break;
        }
        temp = (rx[1] << 8) | rx[2];
        temp *= 0.25;

        // Update duty cycle
        if (temp < TARGET_TEMP) {
            duty_cycle += 5;
        } else {
            duty_cycle -= 5;
        }
        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > MAX_DUTY_CYCLE) {
            duty_cycle = MAX_DUTY_CYCLE;
        }

        // Set heater pin
        gpiod_set_value(heater_fd, duty_cycle > 0);

        // Write to log file
        time(&now);
        timeinfo = localtime(&now);
        fprintf(log_file, "%s,%f,%d\n", asctime(timeinfo), temp, duty_cycle);

        // Sleep for a bit
        sleep(1);
    }

    // Cleanup
    cleanup();

    return 0;
}

