#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <curl/curl.h>

#define GPIO_PIN 4
#define DHT22_DATA_BIT_COUNT 40
#define DHT22_CHECKSUM_BIT_COUNT 8
#define DHT22_RESPONSE_BIT_COUNT (DHT22_DATA_BIT_COUNT + DHT22_CHECKSUM_BIT_COUNT)
#define DHT22_MAX_RETRIES 3
#define DHT22_RETRY_DELAY 1
#define DHT22_HTTP_ENDPOINT "http://yourserver.com/api/humidity"

static bool running = true;

static void signal_handler(int signum) {
    running = false;
}

static int dht22_read_data(uint8_t *data) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t bit_count = 0;
    uint8_t byte_count = 0;
    uint8_t byte = 0;
    int retry_count = 0;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_request_input(line, "dht22");

    while (bit_count < DHT22_RESPONSE_BIT_COUNT && retry_count < DHT22_MAX_RETRIES) {
        if (gpiod_line_get_value(line) == 0) {
            usleep(1000);
            if (gpiod_line_get_value(line) == 0) {
                for (int i = 0; i < 8; i++) {
                    usleep(50);
                    uint8_t value = gpiod_line_get_value(line);
                    usleep(50);
                    if (value == 0) {
                        byte <<= 1;
                    } else {
                        byte <<= 1;
                        byte |= 1;
                    }
                    bit_count++;
                }
                data[byte_count++] = byte;
            }
        } else {
            retry_count++;
            usleep(DHT22_RETRY_DELAY * 1000);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return byte_count;
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((char *)userp)[size * nmemb] = 0;
    return size * nmemb;
}

static int dht22_post_data(uint8_t *data, size_t data_size) {
    CURL *curl;
    CURLcode res;
    char post_data[64];
    char response[32];

    curl = curl_easy_init();
    if (!curl) {
        return -1;
    }

    snprintf(post_data, sizeof(post_data), "{\"humidity\":%d,\"temperature\":%d}", data[0], data[1]);

    curl_easy_setopt(curl, CURLOPT_URL, DHT22_HTTP_ENDPOINT);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, post_data);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, response);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);

    return 0;
}

int main() {
    struct sigaction action;
    uint8_t data[2];

    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    while (running) {
        if (dht22_read_data(data) == 2 && data[0] + data[1] == data[2]) {
            if (dht22_post_data(data, 2) != 0) {
                fprintf(stderr, "Failed to post data\n");
            }
        } else {
            fprintf(stderr, "Failed to read data\n");
        }
        sleep(2);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define BMP180_I2C_ADDRESS 0x77
#define BMP180_OSS 3
#define BMP180_CONVERSION_DELAY 26
#define BUTTON_PIN 4
#define BUTTON_DEBOUNCE_TIME 200000

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static bool logging_enabled = false;
static uint64_t last_pressure_read_time = 0;

static void handle_sigint(int signum) {
    close(i2c_fd);
    gpiod_chip_close(chip);
    exit(0);
}

static int read_i2c_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];

    messages[0].addr = BMP180_I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &reg;

    messages[1].addr = BMP180_I2C_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = len;
    messages[1].buf = data;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

static int write_i2c_reg(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];
    uint8_t buffer[len + 1];

    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    messages[0].addr = BMP180_I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = len + 1;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if (ioctl(fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

static int read_pressure(int fd) {
    uint8_t data[3];
    int32_t raw_pressure;
    int32_t pressure;

    if (read_i2c_reg(fd, 0xF6, data, 3) < 0) {
        return -1;
    }

    raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    raw_pressure >>= (8 - BMP180_OSS);

    // Apply Bosch BMP180 compensation algorithm here...

    return pressure;
}

static void button_interrupt_handler(struct gpiod_line *line, uint32_t event_mask, void *user_data) {
    if (event_mask & GPIOD_LINE_EVENT_FALLING_EDGE) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        if (ts.tv_sec * 1000000 + ts.tv_nsec / 1000 - BUTTON_DEBOUNCE_TIME > last_pressure_read_time) {
            logging_enabled = !logging_enabled;
            if (logging_enabled) {
                printf("Logging enabled\n");
            } else {
                printf("Logging disabled\n");
            }
        }
    }
}

int main() {
    struct sigaction sigint_action;
    sigint_action.sa_handler = handle_sigint;
    sigaction(SIGINT, &sigint_action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    gpiod_line_request_input(line, "button");
    gpiod_line_event_set_type(line, GPIOD_LINE_EVENT_FALLING_EDGE);
    gpiod_line_event_set_debounce(line, BUTTON_DEBOUNCE_TIME);
    gpiod_line_event_enable(line);
    gpiod_line_set_falling_edge_action(line, button_interrupt_handler, NULL);

    while (1) {
        if (logging_enabled) {
            int pressure = read_pressure(i2c_fd);
            if (pressure < 0) {
                printf("Failed to read pressure\n");
                continue;
            }

            FILE *file = fopen("pressure_log.txt", "a");
            if (!file) {
                perror("Failed to open log file");
                continue;
            }

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(file, "%ld.%06ld %d\n", ts.tv_sec, ts.tv_nsec / 1000, pressure);
            fclose(file);

            last_pressure_read_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        }

        usleep(2000000);
    }

    return 0;
}

