#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define MAX_STATE "/sys/class/thermal/cooling_device0/max_state"
#define CUR_STATE "/sys/class/thermal/cooling_device0/cur_state"
#define TEMP "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "/var/log/fan_control.log"

void log_event(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        printf("Failed to open log file\n");
        return;
    }
    time_t now = time(NULL);
    char *time_str = ctime(&now);
    time_str[strlen(time_str) - 1] = '\0'; // Remove newline
    fprintf(log, "[%s] %s\n", time_str, message);
    fclose(log);
}

void set_fan_speed(int speed) {
    FILE *max_state = fopen(MAX_STATE, "r");
    if (max_state == NULL) {
        printf("Failed to open max_state file\n");
        return;
    }
    int max;
    fscanf(max_state, "%d", &max);
    fclose(max_state);

    if (speed > max) {
        printf("Invalid fan speed\n");
        return;
    }

    FILE *cur_state = fopen(CUR_STATE, "w");
    if (cur_state == NULL) {
        printf("Failed to open cur_state file\n");
        return;
    }
    fprintf(cur_state, "%d", speed);
    fclose(cur_state);

    log_event("Fan speed set to");
    char buffer[10];
    sprintf(buffer, "%d", speed);
    log_event(buffer);
}

void handle_sigint(int signum) {
    set_fan_speed(0);
    log_event("Program terminated by user");
    exit(0);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        FILE *temp = fopen(TEMP, "r");
        if (temp == NULL) {
            printf("Failed to open temp file\n");
            continue;
        }
        int cpu_temp;
        fscanf(temp, "%d", &cpu_temp);
        fclose(temp);

        int fan_speed;
        FILE *cur_state = fopen(CUR_STATE, "r");
        if (cur_state == NULL) {
            printf("Failed to open cur_state file\n");
            continue;
        }
        fscanf(cur_state, "%d", &fan_speed);
        fclose(cur_state);

        if (cpu_temp < 45000) {
            set_fan_speed(0);
        } else if (cpu_temp < 55000) {
            set_fan_speed(1);
        } else if (cpu_temp < 65000) {
            set_fan_speed(2);
        } else {
            set_fan_speed(3);
        }

        sleep(5);
    }

    return 0;
}

