#define SAMPLES_PER_SECOND 1

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    int spi = spiOpen(0, SPI_SPEED, 0);
    if (spi < 0) {
        printf("Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    int heater = gpioPWM(HEATER_GPIO, 0);
    if (heater < 0) {
        printf("Failed to initialize PWM\n");
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("heater_log.txt", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        gpioPWM(HEATER_GPIO, 0);
        spiClose(spi);
        gpioTerminate();
        return 1;
    }

    struct timespec ts;
    ts.tv_sec = 1;
    ts.tv_nsec = 0;

    int last_error = 0;
    double integral = 0;
    double last_temp = 0;

    while (1) {
        nanosleep(&ts, NULL);

        uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
        uint8_t rx[4];

        spiXfer(spi, tx, rx, 4);

        int16_t temp = (rx[1] << 8) | rx[2];
        double temperature = temp / 4.0;

        if (temperature > 100 || temperature < 0) {
            printf("Temperature out of range\n");
            gpioPWM(HEATER_GPIO, 0);
            spiClose(spi);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        int error = TARGET_TEMP - temperature;
        integral += error;
        double derivative = error - last_error;
        last_error = error;

        double output = KP * error + KI * integral + KD * derivative;

        int duty_cycle = (int) (output * 100);

        if (duty_cycle < 0) {
            duty_cycle = 0;
        } else if (duty_cycle > 100) {
            duty_cycle = 100;
        }

        gpioPWM(HEATER_GPIO, duty_cycle);

        fprintf(log_file, "%f, %d, %f\n", temperature, duty_cycle, output);

        fflush(log_file);
    }

    fclose(log_file);
    gpioPWM(HEATER_GPIO, 0);
    spiClose(spi);
    gpioTerminate();

    return 0;
}

