#define ADPD144RI_ADDRESS 0x1A
#define IR_THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define GPIO17 17

static int i2c_fd, gpio_fd;
static FILE *log_file;
static struct gpiod_line *led_line;

void cleanup() {
    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_fd);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((gpio_fd = gpiod_chip_open("/dev/gpiochip0")) < 0) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((led_line = gpiod_chip_get_line(gpio_fd, GPIO17)) < 0) {
        perror("Failed to get GPIO line");
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    fprintf(log_file, "timestamp,red,ir\n");

    while (1) {
        uint16_t red, ir;
        struct timespec ts;

        if (read(i2c_fd, &red, sizeof(red)) < 0) {
            perror("Failed to read red value");
            continue;
        }

        if (read(i2c_fd, &ir, sizeof(ir)) < 0) {
            perror("Failed to read IR value");
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld.%09ld,%u,%u\n", ts.tv_sec, ts.tv_nsec, red, ir);

        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000); // sleep for 100ms
    }

    cleanup();
    return 0;
}

#include <stdio.h>
