#include <pthread.h>

#define GPIO_PIN 18
#define PULSES_PER_REV 1
#define RPM_LOG_FILE "rpm_log.txt"

pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile unsigned int pulse_count = 0;
volatile time_t last_pulse_time = 0;
FILE *log_file;

void *pulse_counter_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count = 0;
        last_pulse_time = time(NULL);
        pthread_mutex_unlock(&pulse_mutex);
        sleep(1);
    }
    return NULL;
}

void pulse_isr(struct gpiod_line *line, uint32_t event_types, void *user_data) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void signal_handler(int signum) {
    gpiod_line_event_callback_set(gpiod_chip_get_line(chip, GPIO_PIN), NULL, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    pthread_t thread_id;
    struct sigaction action;
    int ret;

    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_input(line, "pulse_counter");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_event_callback_set(line, pulse_isr, NULL);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO line event callback\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_flags(line, GPIO_LINE_FLAG_BIAS_PULL_DOWN);
    if (ret) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(RPM_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = pthread_create(&thread_id, NULL, pulse_counter_thread, NULL);
    if (ret) {
        fprintf(stderr, "Failed to create pulse counter thread\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        if (pulse_count > 0) {
            float rpm = (60.0 / PULSES_PER_REV) / (time(NULL) - last_pulse_time);
            fprintf(log_file, "%.2f RPM\n", rpm);
            fflush(log_file);
        } else {
            fprintf(log_file, "0.00 RPM\n");
        }
        pthread_mutex_unlock(&pulse_mutex);
        sleep(1);
    }

    pthread_join(thread_id, NULL);
    gpiod_chip_close(chip);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);

    return EXIT_SUCCESS;
}

