#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"

int i2c_fd, led_fd;
FILE *log_file;

void cleanup() {
    if (i2c_fd >= 0) close(i2c_fd);
    if (led_fd >= 0) gpiod_close(led_fd);
    if (log_file) fclose(log_file);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((led_fd = gpiod_open_by_number(LED_PIN, "out")) < 0) {
        perror("Failed to open LED pin");
        return 1;
    }

    if (!(log_file = fopen(LOG_FILE, "w"))) {
        perror("Failed to open log file");
        return 1;
    }

    while (1) {
        uint16_t infrared;
        if (read(i2c_fd, &infrared, sizeof(infrared)) != sizeof(infrared)) {
            perror("Failed to read from sensor");
            return 1;
        }

        infrared = ntohs(infrared);

        fprintf(log_file, "%ld,%d\n", time(NULL), infrared);

        if (infrared > THRESHOLD) {
            gpiod_set_value(led_fd, 1);
        } else {
            gpiod_set_value(led_fd, 0);
        }

        usleep(100000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>

#define MIC_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL 10 // in milliseconds

int log_fd = -1;
int gain_pin_level = 0;

void close_log_file() {
    if (log_fd != -1) {
        close(log_fd);
    }
}

void write_to_log(int level) {
    time_t rawtime;
    struct tm * timeinfo;
    char buffer[80];

    time (&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", timeinfo);
    dprintf(log_fd, "%s%d\n", buffer, level);
}

void handle_signal(int signum) {
    close_log_file();
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    atexit(close_log_file);

    printf("Starting audio event detector\n");

    write_to_log(0);

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(GAIN_PIN, PI_OUTPUT);

    while (1) {
        int level = gpioRead(MIC_PIN);

        if (level == 1 && gain_pin_level == 0) {
            gpioWrite(GAIN_PIN, 1);
            gain_pin_level = 1;
            write_to_log(1);
        } else if (level == 0 && gain_pin_level == 1) {
            gpioWrite(GAIN_PIN, 0);
            gain_pin_level = 0;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

