#define SLF3S4000B_I2C_ADDRESS 0x28
#define SLF3S4000B_REG_READ 0x00
#define SLF3S4000B_REG_WRITE 0x01
#define SLF3S4000B_REG_CRC_POLYNOMIAL 0x31
#define SLF3S4000B_REG_CRC_INITIAL_VALUE 0xFF

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    char buf[3];
    int rc;
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];
    FILE *log_file;

    if ((file = open(filename, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, SLF3S4000B_I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        return -1;
    }

    while (1) {
        rc = write(file, &SLF3S4000B_REG_READ, 1);
        if (rc != 1) {
            syslog(LOG_ERR, "Failed to write to i2c device");
            continue;
        }

        rc = read(file, buf, 3);
        if (rc != 3) {
            syslog(LOG_ERR, "Failed to read from i2c device");
            continue;
        }

        if (buf[2] != ((buf[0] ^ buf[1]) & 0xFF)) {
            syslog(LOG_ERR, "CRC error");
            continue;
        }

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%d\n", time_str, (buf[0] << 8) | buf[1]);
        fflush(log_file);
    }

    fclose(log_file);
    close(file);
    return 0;
}

