    running = 0;
    gpiod_line_release(line);
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 500000000; // 500ms

    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 0);
    if (!line) {
        fprintf(stderr, "Failed to get I2C line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t data[2];
        if (gpiod_i2c_read(chip, SENSOR_ADDRESS, data, 2) != 2) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        int16_t tvoc = (data[0] << 8) | data[1];
        int16_t eco2 = (data[2] << 8) | data[3];

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %d, %d\n", timestamp, tvoc, eco2);

        nanosleep(&ts, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define POLLING_INTERVAL 100000 /* 100ms */
#define TOUCH_DURATION 5 /* 5 seconds */

static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct timespec last_touch_time;

static void cleanup_and_exit(int status) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(status);
}

static void handle_signal(int signum) {
    cleanup_and_exit(EXIT_FAILURE);
}

int main() {
    struct gpiod_line_request request;
    struct timespec current_time;
    int value;

    /* Set up signal handlers */
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    /* Open GPIO chip */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    /* Request GPIO line */
    memset(&request, 0, sizeof(request));
    strcpy(request.consumer, "ttp223_tamper");
    request.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }
    if (gpiod_line_request(line, &request, 0)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        cleanup_and_exit(EXIT_FAILURE);
    }

    /* Initialize last touch time */
    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    /* Main loop */
    while (1) {
        /* Read GPIO line */
        if (gpiod_line_get_value(line, &value)) {
            fprintf(stderr, "Failed to read GPIO line: %s\n", strerror(errno));
            cleanup_and_exit(EXIT_FAILURE);
        }

        /* Check for touch */
        if (value) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if (current_time.tv_sec - last_touch_time.tv_sec > TOUCH_DURATION) {
                printf("Intrusion alert!\n");
                last_touch_time = current_time;
            }
        } else {
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
        }

        /* Sleep for a bit */
        struct timespec sleep_time = {0, POLLING_INTERVAL};
        nanosleep(&sleep_time, NULL);
    }

    /* Cleanup and exit */
    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
