#define GPIO_PIN 17
#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define FILE_NAME "audio_capture.pcm"

static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i2s_fd, file_fd;
    uint16_t sample;
    ssize_t bytes_read;

    // Register signal handler for graceful termination
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Open GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to open GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line
    if (gpiod_line_request_output(line, "audio_capture", 0)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open I2S device
    i2s_fd = open(I2S_DEVICE, O_RDONLY);
    if (i2s_fd < 0) {
        fprintf(stderr, "Failed to open I2S device\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open file for writing
    file_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_fd < 0) {
        fprintf(stderr, "Failed to open file for writing\n");
        close(i2s_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    while (running) {
        // Set GPIO line to select left channel
        gpiod_line_set_value(line, 0);

        // Read sample from I2S device
        bytes_read = read(i2s_fd, &sample, sizeof(sample));
        if (bytes_read != sizeof(sample)) {
            fprintf(stderr, "Failed to read sample from I2S device\n");
            break;
        }

        // Write sample to file
        if (write(file_fd, &sample, sizeof(sample)) != sizeof(sample)) {
            fprintf(stderr, "Failed to write sample to file\n");
            break;
        }
    }

    // Clean up
    close(file_fd);
    close(i2s_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

