    }

    // Request GPIO line
    if (gpiod_line_request_output(line, "audio_capture", 0)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open I2S device
    i2s_fd = open(I2S_DEVICE, O_RDONLY);
    if (i2s_fd < 0) {
        fprintf(stderr, "Failed to open I2S device\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open file for writing
    file_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_fd < 0) {
        fprintf(stderr, "Failed to open file for writing\n");
        close(i2s_fd);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    while (running) {
        // Set GPIO line to select left channel
        gpiod_line_set_value(line, 0);

        // Read sample from I2S device
        bytes_read = read(i2s_fd, &sample, sizeof(sample));
        if (bytes_read != sizeof(sample)) {
            fprintf(stderr, "Failed to read sample from I2S device\n");
            break;
        }

        // Write sample to file
        if (write(file_fd, &sample, sizeof(sample)) != sizeof(sample)) {
            fprintf(stderr, "Failed to write sample to file\n");
            break;
        }
    }

    // Clean up
    close(file_fd);
    close(i2s_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
