#include <wiringPiPWM.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define DEBOUNCE_TIME 50
#define PWM_FREQ 100
#define TIMEOUT 5000 // 5 seconds

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];
    int sensor_value;
    int last_sensor_value = 1;
    int last_sensor_time = 0;
    int pwm_duty_cycle = 0;

    log_file = fopen("flame_log.txt", "w");
    if (log_file == NULL) {
        printf("Error opening file!\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    if (wiringPiSetup() == -1) {
        printf("wiringPi setup failed\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "Program started at %s\n", buffer);

    while (!stop) {
        sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value == 0 && last_sensor_value == 1) {
            last_sensor_time = gpioTick();
            pwm_duty_cycle = 1024;
            wiringPiPWMWrite(FAN_PIN, pwm_duty_cycle);
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "Flame detected at %s\n", buffer);
        } else if (sensor_value == 1 && last_sensor_value == 0) {
            pwm_duty_cycle = 0;
            wiringPiPWMWrite(FAN_PIN, pwm_duty_cycle);
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "Flame ended at %s\n", buffer);
        }

        if (gpioTick() - last_sensor_time > TIMEOUT) {
            pwm_duty_cycle = 0;
            wiringPiPWMWrite(FAN_PIN, pwm_duty_cycle);
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "Sensor timeout at %s\n", buffer);
        }

        last_sensor_value = sensor_value;
        usleep(50000); // 50ms
    }

    pwm_duty_cycle = 0;
    wiringPiPWMWrite(FAN_PIN, pwm_duty_cycle);

    gpioTerminate();

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "Program ended at %s\n", buffer);

    fclose(log_file);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define GPIO_TRIGGER 23
#define GPIO_INTERRUPT 24
#define FRAME_PERIOD 100
#define FRAME_SIZE 32768
#define LOG_FILE "log.bin"

static int spi_fd, gpio_trigger, gpio_interrupt;
static FILE *log_file;

void cleanup() {
    gpiod_set_value(gpio_trigger, 0);
    gpiod_close(gpio_trigger);
    gpiod_close(gpio_interrupt);
    close(spi_fd);
    fclose(log_file);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = sig_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi_xfer = {
        .tx_buf = 0,
        .rx_buf = 0,
        .len = FRAME_SIZE,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    gpio_trigger = gpiod_open_by_number(GPIO_TRIGGER, GPIOD_OUT_LOW);
    if (!gpio_trigger) {
        perror("Failed to open GPIO trigger");
        return -1;
    }

    gpio_interrupt = gpiod_open_by_number(GPIO_INTERRUPT, GPIOD_IN);
    if (!gpio_interrupt) {
        perror("Failed to open GPIO interrupt");
        return -1;
    }

    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    uint8_t buffer[FRAME_SIZE];
    uint64_t timestamp;
    uint32_t frame_number = 0;
    struct timespec sleep_time = {.tv_sec = 0, .tv_nsec = FRAME_PERIOD * 1000000L};

    while (true) {
        gpiod_set_value(gpio_trigger, 1);
        nanosleep(&sleep_time, NULL);
        gpiod_set_value(gpio_trigger, 0);

        if (gpiod_get_value(gpio_interrupt)) {
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi_xfer) < 0) {
                perror("Failed to read SPI data");
                return -1;
            }

            timestamp = gettime();
            fwrite(&timestamp, sizeof(timestamp), 1, log_file);
            fwrite(&frame_number, sizeof(frame_number), 1, log_file);
            fwrite(buffer, sizeof(buffer), 1, log_file);
            frame_number++;
        }
    }

    cleanup();
    return 0;
}

