#include <linux/i2c.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define SENSOR_DATA_FILE "light_data.txt"

gpiod_chip *chip;
gpiod_line *i2c_sda, *i2c_scl;
int i2c_fd;

void cleanup() {
    gpiod_line_set_value(i2c_sda, 1);
    gpiod_line_set_value(i2c_scl, 1);
    gpiod_line_release(i2c_sda);
    gpiod_line_release(i2c_scl);
    gpiod_chip_close(chip);
    close(i2c_fd);
}

void sig_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sig_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    i2c_sda = gpiod_chip_get_line(chip, 2);
    i2c_scl = gpiod_chip_get_line(chip, 3);

    if (!i2c_sda || !i2c_scl) {
        fprintf(stderr, "Failed to get I2C lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(i2c_sda, "i2c-sda", 1);
    gpiod_line_request_output(i2c_scl, "i2c-scl", 1);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *file = fopen(SENSOR_DATA_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    while (1) {
        uint16_t data;
        if (read(i2c_fd, &data, 2) != 2) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

        fprintf(file, "%s %d\n", timestamp, data);

        usleep(100000); // Wait for 100ms
    }

    fclose(file);
    cleanup();
    return EXIT_SUCCESS;
}

