#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line;
    int ret;

    // Request GPIO line 17 (BCM GPIO 17)
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "flame_detect";
    request.request_type = GPIO_LINE_REQUEST_DIRECTION_INPUT;
    request.flags = GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    ret = gpiod_line_request(line, &request, NULL);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (!stop) {
        struct timespec ts;
        int value;

        ret = gpiod_line_get_value(line, &value);
        if (ret) {
            fprintf(stderr, "Failed to get GPIO line value: %s\n", strerror(-ret));
            break;
        }

        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        printf("%s Flame Detected: %s\n", timestamp, value ? "NO" : "YES");

        sleep(1);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

