#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL 0.1 // 100ms

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int line_values[NUM_CHANNELS];

static void cleanup_and_exit(void) {
    if (lines.lines) {
        gpiod_line_release_bulk(lines.lines, NUM_CHANNELS);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

static void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    cleanup_and_exit();
}

int main(void) {
    struct sigaction sigact;
    sigact.sa_handler = handle_sigint;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.lines = calloc(NUM_CHANNELS, sizeof(struct gpiod_line *));
    if (!lines.lines) {
        fprintf(stderr, "Failed to allocate memory for lines\n");
        cleanup_and_exit();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines.lines[i] = gpiod_chip_get_line(chip, i + 2);
        if (!lines.lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", i + 2);
            cleanup_and_exit();
            return EXIT_FAILURE;
        }
    }

    if (gpiod_line_request_bulk(lines.lines, NUM_CHANNELS, "TTP226 reader") < 0) {
        fprintf(stderr, "Failed to request lines\n");
        cleanup_and_exit();
        return EXIT_FAILURE;
    }

    while (1) {
        struct timespec sleep_time = {0, POLL_INTERVAL * 1e6};
        nanosleep(&sleep_time, NULL);

        if (gpiod_line_get_value_bulk(lines.lines, NUM_CHANNELS, line_values) < 0) {
            fprintf(stderr, "Failed to get line values\n");
            cleanup_and_exit();
            return EXIT_FAILURE;
        }

