#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN_COUNT 8

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int keep_running = 1;

static void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        keep_running = 0;
    }
}

int main() {
    int i, ret;
    struct gpiod_line *line;
    unsigned int values[GPIO_PIN_COUNT];

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.num_lines = GPIO_PIN_COUNT;
    lines.lines = malloc(sizeof(struct gpiod_line *) * GPIO_PIN_COUNT);
    if (!lines.lines) {
        fprintf(stderr, "Failed to allocate memory for GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    for (i = 0; i < GPIO_PIN_COUNT; i++) {
        line = gpiod_chip_get_line(chip, i + 2);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line %d\n", i + 2);
            gpiod_chip_close(chip);
            free(lines.lines);
            return EXIT_FAILURE;
        }
        lines.lines[i] = line;
    }

    ret = gpiod_line_request_bulk(lines, GPIO_LINE_REQUEST_DIRECTION_INPUT, "TTP226 Sensor");
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        free(lines.lines);
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (keep_running) {
        ret = gpiod_line_get_value_bulk(lines, values);
        if (ret < 0) {
            fprintf(stderr, "Failed to get GPIO line values\n");
            break;
        }

        printf("[%+5.1f ms] ", gpiod_line_get_time_offset_ns(chip, line) / 1000000.0);
        for (i = 0; i < GPIO_PIN_COUNT; i++) {
            printf("CH%d=%d ", i + 1, values[i]);
        }
        printf("\n");
    }

    gpiod_line_release_bulk(lines);
    gpiod_chip_close(chip);
    free(lines.lines);

    return EXIT_SUCCESS;
}

