#define NUM_CHANNELS 8
#define CHANNEL_PINS {2, 3, 4, 17, 27, 22, 10, 9}
#define POLL_INTERVAL 50 // ms

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static int line_values[NUM_CHANNELS];
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static int setup_gpio() {
    int pin_nums[NUM_CHANNELS] = CHANNEL_PINS;
    struct gpiod_line_request_config config = {
        .consumer = "TTP226 Reader",
        .flags = GPIO_LINE_REQUEST_FLAG_BIAS_DISABLE,
    };

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    lines.num_lines = NUM_CHANNELS;
    lines.lines = malloc(sizeof(struct gpiod_line *) * NUM_CHANNELS);
    if (!lines.lines) {
        fprintf(stderr, "Failed to allocate memory for lines\n");
        return -1;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines.lines[i] = gpiod_chip_get_line(chip, pin_nums[i]);
        if (!lines.lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pin_nums[i]);
            return -1;
        }

        if (gpiod_line_request(lines.lines[i], &config, NULL)) {
            fprintf(stderr, "Failed to request line %d\n", pin_nums[i]);
            return -1;
        }
    }

    return 0;
}

static void cleanup_gpio() {
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);
    free(lines.lines);
}

static void read_sensors() {
    struct timespec ts = {0, POLL_INTERVAL * 1000000};
    nanosleep(&ts, NULL);

    if (!running) {
        return;
    }

    if (gpiod_line_get_value_bulk(lines.num_lines, lines.lines, line_values)) {
        fprintf(stderr, "Failed to read sensor values\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    printf("%s,", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        printf("%d,", line_values[i]);
    }
    printf("\n");
}

int main() {
    if (setup_gpio()) {
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        read_sensors();
    }

    cleanup_gpio();

    return EXIT_SUCCESS;
}

