#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>
#include <libcsv.h>

#define I2C_BUS 1
#define SENSOR_ADDRESS 0x60
#define LOG_FILE "uv_als_log.csv"

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

void signal_handler(int signum) {
    running = 0;
}

void close_resources() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct sigaction action;
    struct timespec req, rem;
    struct csv_parser parser;
    uint8_t buffer[2];
    int ret;

    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(close_resources);

    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, SENSOR_ADDRESS);
    if (!line) {
        fprintf(stderr, "Failed to get I2C line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    csv_init(&parser, 0);

    while (running) {
        ret = gpiod_line_request_read(line, "uv_als_sensor");
        if (ret < 0) {
            fprintf(stderr, "Failed to request read: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        ret = gpiod_line_read(line, buffer, sizeof(buffer));
        if (ret < 0) {
            fprintf(stderr, "Failed to read from sensor: %s\n", strerror(errno));
            return EXIT_FAILURE;
        }

        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        char timestamp[100];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        csv_write_field(&parser, timestamp, strlen(timestamp));
        csv_write_field(&parser, buffer, 2);
        csv_write_eol(&parser);

        char output[256];
        size_t outlen = sizeof(output);
        csv_parse(&parser, output, &outlen, 0);

        fprintf(log_file, "%s\n", output);

        req.tv_sec = 1;
        req.tv_nsec = 0;
        nanosleep(&req, &rem);
    }

    csv_free(&parser);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define SLF3S_I2C_ADDRESS 0x28
#define SLF3S_MEASUREMENT_INTERVAL 1000
#define SLF3S_CRC_POLYNOMIAL 0x31
#define SLF3S_CRC_INITIAL_VALUE 0xFF
#define ALARM_PIN 17

static bool running = true;
static int i2c_fd = -1;
static int log_fd = -1;
static struct gpiod_line *alarm_line = NULL;

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = SLF3S_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void handle_signal(int signum) {
    running = false;
}

static void open_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SLF3S_I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(EXIT_FAILURE);
    }
}

static void open_log() {
    log_fd = open("flow_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void close_log() {
    if (log_fd >= 0) {
        close(log_fd);
    }
}

static void setup_alarm() {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    alarm_line = gpiod_chip_get_line(chip, ALARM_PIN);
    if (!alarm_line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        perror("Failed to request GPIO line as output");
        exit(EXIT_FAILURE);
    }
}

static void cleanup_alarm() {
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
}

static void log_flow_rate(float flow_rate) {
    char buffer[256];
    sprintf(buffer, "%f\n", flow_rate);
    write(log_fd, buffer, strlen(buffer));
}

static void set_alarm(bool high) {
    gpiod_line_set_value(alarm_line, high);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    open_i2c();
    open_log();
    setup_alarm();

    while (running) {
        uint8_t command = 0x20;
        write(i2c_fd, &command, 1);
        usleep(100000);

        uint8_t response[3];
        if (read(i2c_fd, response, sizeof(response)) != sizeof(response)) {
            perror("Failed to read from I2C device");
            continue;
        }
        if (crc8(response, sizeof(response) - 1) != response[2]) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        float flow_rate = (response[0] << 8) | response[1];
        log_flow_rate(flow_rate);
        set_alarm(flow_rate < 0.5);
    }

    cleanup_alarm();
    close_log();
    close_i2c();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL 50 // in milliseconds

struct timespec ts;
int buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;
int running = 1;

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sigaction action;
    int value;

    action.sa_handler = handle_sigint;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line, "ky-033-sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    clock_gettime(CLOCK_REALTIME, &ts);

    while (running) {
        value = gpiod_line_get_value(line);
        buffer[buffer_head] = value;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        if (buffer_count < BUFFER_SIZE) {
            buffer_count++;
        } else {
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }

        if (value == 0) {
            printf("Detection at %ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
        }

        clock_nanosleep(CLOCK_REALTIME, 0, &ts, NULL);
        ts.tv_nsec += SAMPLE_INTERVAL * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Buffer dump:\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_tail + i) % BUFFER_SIZE;
        printf("%d\n", buffer[index]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x0A
#define SDA_PIN 2
#define SCL_PIN 3
#define MODE_REG 0x20
#define X_REG 0x28
#define Y_REG 0x2A
#define Z_REG 0x2C
#define CSV_FILE "fan_health.csv"
#define SAMPLE_INTERVAL 500 // ms
#define ACTIVE_TIMEOUT 1000 // ms

static int i2c_fd = -1;
static int csv_fd = -1;
static int active = 0;
static int mode = 0;

static void cleanup(int signum) {
    if (i2c_fd != -1) close(i2c_fd);
    if (csv_fd != -1) close(csv_fd);
    exit(signum);
}

static int i2c_write(int fd, uint8_t reg, uint8_t data) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];
    uint8_t buffer[2];

    buffer[0] = reg;
    buffer[1] = data;
    messages[0].addr = I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    return ioctl(fd, I2C_RDWR, &packets);
}

static int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    uint8_t buffer[1];

    buffer[0] = reg;
    messages[0].addr = I2C_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = buffer;

    messages[1].addr = I2C_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = len;
    messages[1].buf = data;

    packets.msgs = messages;
    packets.nmsgs = 2;

    return ioctl(fd, I2C_RDWR, &packets);
}

static void write_csv_header() {
    if (csv_fd == -1) return;
    dprintf(csv_fd, "timestamp,x,y,z\n");
}

static void write_csv_sample(struct timespec *ts, int16_t x, int16_t y, int16_t z) {
    if (csv_fd == -1) return;
    dprintf(csv_fd, "%ld.%09ld,%d,%d,%d\n", ts->tv_sec, ts->tv_nsec, x, y, z);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec ts;
    uint8_t buffer[6];
    int16_t x, y, z;
    int ret;

    // Set up signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line_request_input(&request, "SDA");
    gpiod_chip_get_line(chip, SDA_PIN)->request = &request;

    gpiod_line_request_input(&request, "SCL");
    gpiod_chip_get_line(chip, SCL_PIN)->request = &request;

    // Set up CSV file
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    write_csv_header();

    // Set sensor mode
    ret = i2c_write(i2c_fd, MODE_REG, mode);
    if (ret < 0) {
        perror("Failed to set sensor mode");
        return EXIT_FAILURE;
    }

    // Wait for sensor to become active
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += ACTIVE_TIMEOUT / 1000;
    ts.tv_nsec += (ACTIVE_TIMEOUT % 1000) * 1000000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_nsec -= 1000000000;
        ts.tv_sec++;
    }

    while (clock_gettime(CLOCK_REALTIME, &ts) < 0 && ts.tv_sec < ACTIVE_TIMEOUT / 1000) {
        usleep(1000);
    }

    if (ts.tv_sec >= ACTIVE_TIMEOUT / 1000) {
        fprintf(stderr, "Sensor did not become active within the timeout period\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read X, Y, Z values
        ret = i2c_read(i2c_fd, X_REG, buffer, sizeof(buffer));
        if (ret < 0) {
            perror("Failed to read sensor values");
            continue;
        }

        x = (int16_t)((buffer[0] << 8) | buffer[1]);
        y = (int16_t)((buffer[2] << 8) | buffer[3]);
        z = (int16_t)((buffer[4] << 8) | buffer[5]);

        // Write to CSV file
        clock_gettime(CLOCK_REALTIME, &ts);
        write_csv_sample(&ts, x, y, z);

        // Sleep for a while
        usleep(SAMPLE_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_OUT 23
#define SENSOR2_OUT 24
#define LED_PIN 25
#define POLLING_INTERVAL 100 // ms

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static struct gpiod_line_event event;
static int running = 1;

static void sig_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.offsets[0] = SENSOR1_OUT;
    lines.offsets[1] = SENSOR2_OUT;
    lines.offsets[2] = LED_PIN;
    if (gpiod_chip_get_lines(chip, &lines) < 0) {
        fprintf(stderr, "Failed to get lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(&lines.lines[0], "sensor1_out") < 0 ||
        gpiod_line_request_input(&lines.lines[1], "sensor2_out") < 0 ||
        gpiod_line_request_output(&lines.lines[2], "led_pin", 0) < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpiod_line_event_wait(&lines.lines[0], &event, POLLING_INTERVAL) < 0) {
            fprintf(stderr, "Failed to wait for event\n");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            gpiod_line_set_value(&lines.lines[2], 1);
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            gpiod_line_set_value(&lines.lines[2], 0);
        }
    }

    gpiod_line_release(&lines.lines[0]);
    gpiod_line_release(&lines.lines[1]);
    gpiod_line_release(&lines.lines[2]);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_LOG_FILE "stall_log.txt"
#define STALL_DURATION 2

static bool running = true;
static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static struct timespec last_stall_time;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = false;
    }
}

static bool read_sensors() {
    struct gpiod_line_bulk input_lines;
    struct gpiod_line_event event;
    int ret;

    gpiod_line_bulk_set(&input_lines, chip, SENSOR1_PIN, SENSOR2_PIN);
    ret = gpiod_line_event_wait_bulk(chip, &input_lines, &event, 0);
    if (ret < 0) {
        perror("Failed to read sensors");
        return false;
    }

    return (gpiod_line_event_get_level(&event) == 0);
}

static void log_stall() {
    FILE *file = fopen(STALL_LOG_FILE, "a");
    if (!file) {
        perror("Failed to open stall log file");
        return;
    }

    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    fprintf(file, "%ld.%09ld\n", now.tv_sec, now.tv_nsec);
    fclose(file);
}

int main() {
    struct sigaction action;
    action.sa_handler = sig_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_set(&lines, chip, SENSOR1_PIN, SENSOR2_PIN);
    if (gpiod_line_request_bulk(chip, &lines, "sensor_monitor", 0) < 0) {
        perror("Failed to request lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        bool sensors_read = read_sensors();
        if (!sensors_read) {
            clock_gettime(CLOCK_REALTIME, &last_stall_time);
        } else {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);
            if ((now.tv_sec - last_stall_time.tv_sec) > STALL_DURATION) {
                log_stall();
            }
        }
    }

    gpiod_line_release_bulk(chip, &lines);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

