        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, &event) < 0) {
            log_error("Failed to wait for GPIO line event");
            sleep(60);
            continue;
        }

        if (event.level) {
            log_alert();
        }

        sleep(SLEEP_TIME);
    }

    cleanup();
    return EXIT_SUCCESS;
}

