#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <stdint.h>

#define PULSE_PIN 4
#define SAMPLE_INTERVAL 1
#define LOG_FILE "rpm_log.txt"

static int running = 1;
static int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;

void *sample_rpm(void *arg) {
    while (running) {
        sleep(SAMPLE_INTERVAL);
        pthread_mutex_lock(&pulse_mutex);
        int count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);
        float rpm = count / 2.0f * 60.0f;
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char buffer[256];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S ", t);
        sprintf(buffer + strlen(buffer), "%.2f\n", rpm);
        printf("%s", buffer);
        if (log_file) {
            fwrite(buffer, 1, strlen(buffer), log_file);
            fflush(log_file);
        }
    }
    return NULL;
}

static void handle_signal(int signum) {
    running = 0;
}

static void alert_callback(struct gpiod_line *line, uint32_t event_mask) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

int main() {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, PULSE_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "pulse_input") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_flags(line, GPIO_LINE_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO line flags\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE, NULL) < 0) {
        fprintf(stderr, "Failed to set up GPIO line event\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    pthread_t sample_thread;
    if (pthread_create(&sample_thread, NULL, sample_rpm, NULL) < 0) {
        fprintf(stderr, "Failed to create sampling thread\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Failed to read GPIO line event\n");
            break;
        }
        alert_callback(line, event.event_type);
    }

    pthread_cancel(sample_thread);
    pthread_join(sample_thread, NULL);

    fclose(log_file);
    gpiod_chip_close(chip);
    gpiod_line_release(line);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <bcm2835.h>

#define GPIO_A 17
#define GPIO_B 27
#define ROTATION_LOG "rotation_log.txt"

static volatile sig_atomic_t running = 1;
static int log_fd;
static struct timespec ts;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

static void signal_handler(int signum) {
    running = 0;
}

static void log_rotation(char *direction) {
    pthread_mutex_lock(&mutex);
    clock_gettime(CLOCK_REALTIME, &ts);
    dprintf(log_fd, "%ld-%02ld-%02ld %02ld:%02ld:%02ld.%03ld %s\n",
            ts.tv_sec / (3600 * 24) + 1, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
            ts.tv_sec % 60, ts.tv_nsec / 1e6);
    pthread_mutex_unlock(&mutex);
}

static void* rotation_sensor_thread(void* arg) {
    int state = 0;
    int prev_state = 0;
    int a = 0;
    int b = 0;

    while (running) {
        a = bcm2835_gpio_lev(GPIO_A);
        b = bcm2835_gpio_lev(GPIO_B);

        state = (a << 1) | b;

        if (prev_state != state) {
            switch (state) {
                case 0b00:
                case 0b11:
                    break;
                case 0b01:
                case 0b10:
                    if (prev_state == 0b00 || prev_state == 0b11) {
                        log_rotation(state == 0b01 ? "CW" : "CCW");
                    }
                    break;
            }
            prev_state = state;
        }

        pthread_cond_wait(&cond, &mutex);
    }

    return NULL;
}

int main(int argc, char **argv) {
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed\n");
        return 1;
    }

    if ((log_fd = open(ROTATION_LOG, O_WRONLY | O_CREAT | O_APPEND, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_t thread;
    if (pthread_create(&thread, NULL, rotation_sensor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    while (running) {
        pthread_cond_signal(&cond);
        sleep(1);
    }

    pthread_join(thread, NULL);

    close(log_fd);
    bcm2835_close();

    return 0;
}

