#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO 18
#define I2C_BUS 1
#define VEML7700_ADDRESS 0x10
#define LOG_FILE "grow_log.txt"

int main() {
    int lux, pwm, fd;
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        printf("Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, VEML7700_ADDRESS, 0) < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        close(fd);
        return EXIT_FAILURE;
    }

    gpioSetPWMfrequency(GPIO, 1000);
    gpioSetPWMrange(GPIO, 100);

    while (1) {
        lux = i2cReadWordData(I2C_BUS, VEML7700_ADDRESS, 0x06);
        if (lux < 0) {
            printf("Failed to read from sensor\n");
            break;
        }

        if (lux < 100) {
            pwm = 100;
        } else if (lux < 500) {
            pwm = 75;
        } else if (lux < 1000) {
            pwm = 50;
        } else {
            pwm = 25;
        }

        gpioSetPWMdutycycle(GPIO, pwm);

        now = time(NULL);
        timeinfo = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        dprintf(fd, "%s, %d, %d, %d\n", buffer, lux, pwm, gpioGetError());

        fflush(fd);
        sleep(1);
    }

    gpioSetPWMdutycycle(GPIO, 0);
    gpioTerminate();
    close(fd);

    return EXIT_SUCCESS;
}

