    current_time = time(NULL);
    time_info = localtime(&current_time);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

    // Print and log lux value
    printf("%s, %.2f\n", time_string, lux_value / 100.0);
    file = fopen("light_data.txt", "a");
    if (!file) {
        perror("Failed to open log file");
        cleanup(EXIT_FAILURE);
    }
    fprintf(file, "%s, %.2f\n", time_string, lux_value / 100.0);
    fclose(file);

    // Repeat
    while (1) {
        nanosleep(&sleep_time, NULL);

        // Write configuration register
        if (write(i2c_fd, &configuration_register, 2) != 2) {
            perror("Failed to write configuration register");
            cleanup(EXIT_FAILURE);
        }

        // Wait for conversion to complete
        nanosleep(&wait_time, NULL);

        // Read result register
        if (read(i2c_fd, &result_register, 2) != 2) {
            perror("Failed to read result register");
            cleanup(EXIT_FAILURE);
        }

        // Swap bytes to convert from big-endian to little-endian
        lux_value = (result_register >> 8) | (result_register << 8);

        // Get current time
        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Print and log lux value
        printf("%s, %.2f\n", time_string, lux_value / 100.0);
        file = fopen("light_data.txt", "a");
        if (!file) {
            perror("Failed to open log file");
            cleanup(EXIT_FAILURE);
        }
        fprintf(file, "%s, %.2f\n", time_string, lux_value / 100.0);
        fclose(file);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *sensor_line;
static struct gpiod_line *alert_line;
static FILE *log_file;

void cleanup() {
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    struct timespec ts = {0, POLL_INTERVAL * 1000 * 1000};
    struct timespec remaining;
    int value;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        fprintf(stderr, "Failed to get alert line\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        if (gpiod_line_get_value(sensor_line, &value) < 0) {
            fprintf(stderr, "Failed to read sensor value\n");
            continue;
        }

        if (value == 0) {
            if (gpiod_line_set_value(alert_line, 1) < 0) {
                fprintf(stderr, "Failed to set alert pin high\n");
                continue;
            }
            nanosleep(&ts, &remaining);
            if (gpiod_line_set_value(alert_line, 0) < 0) {
                fprintf(stderr, "Failed to set alert pin low\n");
                continue;
            }
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec,
                value == 0 ? "Fire detected" : "No fire");
        fflush(log_file);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 4
#define DEBOUNCE_INTERVAL 50 // in milliseconds

gpiod_chip *chip;
gpiod_line *line;
FILE *log_file;

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set GPIO line bias\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int previous_value = -1;
    while (1) {
        int current_value = gpiod_line_get_value(line);
        if (current_value != previous_value) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char buffer[100];
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
            if (current_value == 1) {
                fprintf(log_file, "%s: Touch Detected\n", buffer);
            } else {
                fprintf(log_file, "%s: Touch Released\n", buffer);
            }
            fflush(log_file);
            previous_value = current_value;
        }
        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LEFT_SENSOR 17
#define MIDDLE_SENSOR 27
#define RIGHT_SENSOR 22
#define SLEEP_TIME 0.05
#define LOG_FILE "path_log.csv"

static bool running = true;

void signal_handler(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    struct timespec ts;
    FILE *log_file;
    int left, middle, right;

    signal(SIGINT, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.offsets[0] = LEFT_SENSOR;
    lines.offsets[1] = MIDDLE_SENSOR;
    lines.offsets[2] = RIGHT_SENSOR;
    lines.count = 3;

    if (gpiod_chip_get_lines(chip, &lines) < 0) {
        fprintf(stderr, "Failed to get lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_bulk(&lines, "input", 0) < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release_bulk(&lines);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(log_file, "timestamp,left,middle,right\n");

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);
        left = gpiod_line_get_value(lines.lines[0]);
        middle = gpiod_line_get_value(lines.lines[1]);
        right = gpiod_line_get_value(lines.lines[2]);

        fprintf(log_file, "%ld.%09ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, left, middle, right);

        usleep(SLEEP_TIME * 1e6);
    }

    fclose(log_file);
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

