#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP 4
#define LED_PIN 24
#define TOUCH_PIN 23
#define LOG_FILE "touch_log.txt"

static gpiod_chip *chip;
static gpiod_line *led_line, *touch_line;
static FILE *log_file;
static int running = 1;

static void cleanup() {
    if (led_line) gpiod_line_release(led_line);
    if (touch_line) gpiod_line_release(touch_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static void handle_signal(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %d\n", GPIO_CHIP);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d\n", LED_PIN);
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        fprintf(stderr, "Failed to get touch line %d\n", TOUCH_PIN);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request touch line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return EXIT_FAILURE;
    }

    while (running) {
        struct timespec timeout = {1, 0};
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(touch_line, &timeout);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for touch event\n");
            return EXIT_FAILURE;
        }

        if (ret == 0) {
            continue;
        }

        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "Failed to read touch event\n");
            return EXIT_FAILURE;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        int led_state = gpiod_line_get_value(led_line);
        fprintf(log_file, "%s: Touch detected, LED state is now %d\n", timestamp, led_state);

        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "Failed to set LED state\n");
            return EXIT_FAILURE;
        }
    }

    return EXIT_SUCCESS;
}

#include <errno.h>
#include <string.h>
