#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define SLEEP_TIME 500
#define BUZZER_DURATION 2000
#define BUZZER_PIN 18
#define FLAME_SENSOR_PIN 17

static struct gpiod_chip *chip;
static struct gpiod_line *buzzer_line;
static struct gpiod_line *flame_sensor_line;
static FILE *log_file;

void cleanup_and_exit(int status) {
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(flame_sensor_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(status);
}

void handle_signal(int signum) {
    cleanup_and_exit(0);
}

int main() {
    struct timespec sleep_time = {0, SLEEP_TIME * 1000 * 1000};
    struct timespec buzzer_duration = {0, BUZZER_DURATION * 1000 * 1000};
    int last_flame_state = 1;

    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }

    fprintf(log_file, "System started\n");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get flame sensor line: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) ||
        gpiod_line_request_input(flame_sensor_line, "flame_sensor")) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        cleanup_and_exit(1);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int current_flame_state = gpiod_line_get_value(flame_sensor_line);
        if (current_flame_state == 0 && last_flame_state == 1) {
            fprintf(log_file, "%ld FLAME DETECTED\n", time(NULL));
            gpiod_line_set_value(buzzer_line, 1);
            nanosleep(&buzzer_duration, NULL);
            gpiod_line_set_value(buzzer_line, 0);
        }
        last_flame_state = current_flame_state;
        nanosleep(&sleep_time, NULL);
    }

    cleanup_and_exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 10

static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *led_line;
static FILE *log_file;
static int led_state = 0;
static int last_sensor_state = 1;
static struct timespec debounce_timer = {0, 0};

static void cleanup_and_exit(int status) {
    gpiod_line_set_value(led_line, 0);
    fclose(log_file);
    gpiod_chip_close(chip);
    exit(status);
}

static void handle_signal(int signum) {
    cleanup_and_exit(0);
}

static void log_touch_event() {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now.tv_sec));
    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup_and_exit(1);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line\n");
        cleanup_and_exit(1);
    }

    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(1);
    }

    gpiod_line_request_input(sensor_line, "sensor");
    gpiod_line_request_output(led_line, "led", 0);

    while (1) {
        int sensor_state = gpiod_line_get_value(sensor_line);
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);

        if (sensor_state == 0 && last_sensor_state == 1 && now.tv_sec > debounce_timer.tv_sec) {
            led_state = !led_state;
            gpiod_line_set_value(led_line, led_state);
            log_touch_event();
            clock_gettime(CLOCK_REALTIME, &debounce_timer);
            debounce_timer.tv_sec += DEBOUNCE_TIME / 1000;
            debounce_timer.tv_nsec += (DEBOUNCE_TIME % 1000) * 1000000;
            if (debounce_timer.tv_nsec >= 1000000000) {
                debounce_timer.tv_nsec -= 1000000000;
                debounce_timer.tv_sec++;
            }
        }

        last_sensor_state = sensor_state;
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup_and_exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR_COUNT 3
#define POLL_INTERVAL 100 // ms
#define LOG_FILE "magnet_log.txt"

static gpiod_chip *chip;
static gpiod_line_bulk lines;
static FILE *log_file;
static int sensor_pins[SENSOR_COUNT] = {4, 17, 27};
static int sensor_states[SENSOR_COUNT] = {0};

void log_transition(int sensor_id, int new_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s Sensor %d: %s\n", timestamp, sensor_id, new_state ? "magnet removed" : "magnet present");
}

void handle_signal(int signum) {
    fclose(log_file);
    gpiod_chip_close(chip);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&lines);
    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line *line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!line) {
            fprintf(stderr, "Failed to get line %d\n", sensor_pins[i]);
            return EXIT_FAILURE;
        }
        gpiod_line_request_input(line, "magnet_sensor");
        gpiod_line_set_flags(line, GPIO_LINE_FLAG_BIAS_PULL_UP);
        gpiod_line_bulk_add(&lines, line);
        sensor_states[i] = gpiod_line_get_value(line);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_bulk_read(&lines);
        for (int i = 0; i < SENSOR_COUNT; i++) {
            int new_state = gpiod_line_get_value(lines.lines[i]);
            if (new_state != sensor_states[i]) {
                log_transition(i + 1, new_state);
                sensor_states[i] = new_state;
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

