    int pin = 4; // GPIO4
    int led = 17; // GPIO17

    if (gpioSetMode(pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", pin);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(led, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", led);
        gpioTerminate();
        return 1;
    }

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 125000; // 125 µs

