#include <signal.h>
#include <gpiod.h>

#define ALS_ADDRESS 0x39
#define ALS_REG_LSB 0x0E
#define ALS_REG_MSB 0x0F
#define ALS_INTERVAL 100000 /* 100ms */

static bool running = true;

static void sigint_handler(int signum) {
    running = false;
}

static int read_als(gpiod_chip *chip, gpiod_line *scl, gpiod_line *sda) {
    uint8_t reg = ALS_REG_LSB;
    uint8_t lsb, msb;
    int ret;

    /* Write register address */
    ret = gpiod_line_request_output(sda, "ALS reg", 0);
    if (ret) {
        fprintf(stderr, "Failed to request SDA line: %s\n", strerror(-ret));
        return ret;
    }

    ret = gpiod_line_request_output(scl, "ALS reg", 0);
    if (ret) {
        fprintf(stderr, "Failed to request SCL line: %s\n", strerror(-ret));
        return ret;
    }

    /* Send register address */
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(sda, (reg >> i) & 1);
        gpiod_line_set_value(scl, 1);
        gpiod_line_set_value(scl, 0);
    }

    /* Read data */
    gpiod_line_request_input(sda, "ALS data");
    gpiod_line_request_input(scl, "ALS data");

    lsb = 0;
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(scl, 1);
        lsb = (lsb << 1) | gpiod_line_get_value(sda);
        gpiod_line_set_value(scl, 0);
    }

    msb = 0;
    for (int i = 0; i < 8; i++) {
        gpiod_line_set_value(scl, 1);
        msb = (msb << 1) | gpiod_line_get_value(sda);
        gpiod_line_set_value(scl, 0);
    }

    printf("ALS: %d\n", (msb << 8) | lsb);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *scl, *sda;
    int ret;

    /* Request I2C lines */
    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    scl = gpiod_chip_get_line(chip, 0);
    if (!scl) {
        fprintf(stderr, "Failed to get SCL line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    sda = gpiod_chip_get_line(chip, 1);
    if (!sda) {
        fprintf(stderr, "Failed to get SDA line: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set up signal handler */
    signal(SIGINT, sigint_handler);

    /* Main loop */
    while (running) {
        ret = read_als(chip, scl, sda);
        if (ret) {
            fprintf(stderr, "Failed to read ALS: %s\n", strerror(-ret));
            break;
        }

        usleep(ALS_INTERVAL);
    }

    /* Clean up */
    gpiod_line_release(scl);
    gpiod_line_release(sda);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

