#define INTERVAL 5
#define STEPS 50

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

void set_color(int red, int green, int blue) {
    if (red > 255) red = 255;
    if (red < 0) red = 0;
    if (green > 255) green = 255;
    if (green < 0) green = 0;
    if (blue > 255) blue = 255;
    if (blue < 0) blue = 0;

    gpioHardwarePWM(RED_PIN, 1000, red * 1024 / 255);
    gpioHardwarePWM(GREEN_PIN, 1000, green * 1024 / 255);
    gpioHardwarePWM(BLUE_PIN, 1000, blue * 1024 / 255);
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO library");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    openlog("RGB LED Fader", LOG_PID, LOG_USER);

    int red, green, blue;
    int step = 0;
    int start_time = time(NULL);

    while (!stop) {
        int elapsed_time = time(NULL) - start_time;
        if (elapsed_time >= INTERVAL) {
            elapsed_time = INTERVAL;
        }

        step = (STEPS * elapsed_time) / INTERVAL;

        red = 255 - (255 * step) / STEPS;
        green = 255 - (255 * step) / STEPS;
        blue = 255 - (255 * step) / STEPS;

        set_color(red, green, blue);

        sleep(1);
    }

    set_color(0, 0, 0);

    closelog();
    gpioTerminate();

    return EXIT_SUCCESS;
}

