#define I2C_ADDRESS 0x23
#define LED_PIN 18
#define LED_COUNT 10

volatile sig_atomic_t stop = false;

void signal_handler(int signum) {
    stop = true;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t brightness[LED_COUNT];
    int i2c_handle;
    uint16_t lux;
    float log_lux;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    line = gpiod_chip_get_line(chip, LED_PIN);
    gpiod_line_request_output(line, "ws2812b", 0);

    i2c_handle = pi_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    while (!stop) {
        uint8_t buffer[2] = {0x20, 0x00};
        if (pi_i2c_write_device(i2c_handle, buffer, 2) < 0) {
            printf("Failed to write to BH1750\n");
            continue;
        }

        usleep(180000);

        if (pi_i2c_read_device(i2c_handle, buffer, 2) < 0) {
            printf("Failed to read from BH1750\n");
            continue;
        }

        lux = (buffer[0] << 8) | buffer[1];
        log_lux = log10f(lux);

        for (i = 0; i < LED_COUNT; i++) {
            brightness[i] = (uint8_t) (log_lux * 255 / log10f(65535));
        }

        for (i = 0; i < LED_COUNT; i++) {
            uint32_t color = (brightness[i] << 16) | (brightness[i] << 8) | brightness[i];
            gpiod_line_set_value(line, color);
            usleep(50);
        }
    }

    pi_i2c_close(i2c_handle);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <wiringPiSPI.h>

#define BH1750_ADDRESS 0x23
#define APA102_DATA_LENGTH 4
#define APA102_END_FRAME 0xFFFFFFFF
#define APA102_START_FRAME 0x00000000
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000

int main(int argc, char **argv) {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) < 0) {
        printf("Failed to initialize SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, BH1750_ADDRESS, 0);
    if (i2c_handle < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t light_level;
    while (1) {
        uint8_t buffer[2] = {0x20, 0x00};
        if (i2cWrite(i2c_handle, buffer, 2) != 2) {
            printf("Failed to write to BH1750\n");
            break;
        }

        sleep(120); // Wait for conversion

        if (i2cRead(i2c_handle, buffer, 2) != 2) {
            printf("Failed to read from BH1750\n");
            break;
        }

        light_level = (buffer[0] << 8) | buffer[1];

        uint32_t led_data[APA102_DATA_LENGTH] = {APA102_START_FRAME};
        for (int i = 0; i < APA102_DATA_LENGTH - 2; i++) {
            led_data[i + 1] = (light_level << 16) | (0 << 8) | (0 << 0); // Set brightness to light_level
        }
        led_data[APA102_DATA_LENGTH - 1] = APA102_END_FRAME;

        if (wiringPiSPIDataRW(SPI_CHANNEL, (char *)led_data, APA102_DATA_LENGTH * sizeof(uint32_t)) < 0) {
            printf("Failed to write to APA102\n");
            break;
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

