#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDRESS 0x10
#define WS2812B_GPIO 18
#define WS2812B_FREQ 800000
#define WS2812B_THRESHOLD 10000
#define RETRIES 3
#define RETRY_DELAY 100
#define PAUSE_DURATION 200

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = i2cOpen(I2C_BUS, VEML7700_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(WS2812B_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812B_GPIO, WS2812B_FREQ);

    while (!stop) {
        uint16_t lux = 0;
        for (int i = 0; i < RETRIES; ++i) {
            if (i2cReadDevice(i2c_fd, &lux, sizeof(lux)) == sizeof(lux)) {
                break;
            }
            usleep(RETRY_DELAY * 1000);
        }

        if (lux == 0) {
            fprintf(stderr, "Failed to read from VEML7700\n");
            continue;
        }

        uint8_t brightness = lux > WS2812B_THRESHOLD ? 255 : 0;
        gpioPWM(WS2812B_GPIO, brightness);

        printf("Lux: %d, Brightness: %d\n", lux, brightness);

        usleep(PAUSE_DURATION * 1000);
    }

    gpioPWM(WS2812B_GPIO, 0);
    gpioTerminate();
    i2cClose(i2c_fd);

    return EXIT_SUCCESS;
}

