#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define KY026_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

static struct gpiod_chip *chip;
static struct gpiod_line *ky026_line, *buzzer_line, *led_line;
static int running = 1;

static void cleanup() {
    gpiod_line_set_value(led_line, 0);
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(ky026_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
}

static void sig_handler(int signum) {
    if (signum == SIGINT) {
        running = 0;
    }
}

int main() {
    struct sigaction sigact;
    sigact.sa_handler = sig_handler;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    ky026_line = gpiod_chip_get_line(chip, KY026_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!ky026_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return 1;
    }

    if (gpiod_line_request_input(ky026_line, "ky026") ||
        gpiod_line_request_output(buzzer_line, "buzzer", 0) ||
        gpiod_line_request_output(led_line, "led", 0)) {
        fprintf(stderr, "Failed to request GPIO line\n");
        return 1;
    }

    // Perform startup self-test
    for (int i = 0; i < 2; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);

        for (int j = 0; j < 5; j++) {
            if (!gpiod_line_get_value(ky026_line)) {
                gpiod_line_set_value(led_line, 1);
                gpiod_line_set_value(buzzer_line, 1);
                usleep(200000);
                gpiod_line_set_value(buzzer_line, 0);
                usleep(200000);
                gpiod_line_set_value(buzzer_line, 1);
                usleep(600000);
                gpiod_line_set_value(buzzer_line, 0);
                usleep(200000);
                gpiod_line_set_value(led_line, 0);
                return 1;
            }
            usleep(100000);
        }
    }

    while (running) {
        if (!gpiod_line_get_value(ky026_line)) {
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            while (!gpiod_line_get_value(ky026_line)) {
                usleep(100000);
            }
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(50000);
    }

    return 0;
}

