#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define GYRO_ADDRESS 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define OUT_X_L 0x28
#define GYRO_SCALE 0.00875
#define FILE_NAME "gyro_log.txt"
#define SAMPLES 100
#define THRESHOLD 50
#define PERIOD 50

static int i2c_fd;
static FILE *log_file;
static struct timespec sleep_time = {0, 20000000}; // 20Hz

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    int16_t raw_data[3];
    float calibrated_data[3] = {0, 0, 0};
    int sample_count = 0;
    struct timespec start_time, current_time;
    float time_diff;

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    line = gpiod_chip_get_line(chip, 1);
    gpiod_line_request_output(line, "i2c-bus", 0);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, GYRO_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if (write(i2c_fd, &WHO_AM_I, 1) < 0) {
        perror("Failed to write to i2c slave");
        return 1;
    }

    if (read(i2c_fd, &value, 1) < 0) {
        perror("Failed to read from i2c slave");
        return 1;
    }

    if (value != GYRO_ADDRESS) {
        printf("Failed to detect gyroscope\n");
        return 1;
    }

    log_file = fopen(FILE_NAME, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        time_diff = (current_time.tv_sec - start_time.tv_sec) +
                     (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

        if (time_diff > PERIOD) {
            if (write(i2c_fd, &OUT_X_L, 1) < 0) {
                perror("Failed to write to i2c slave");
                return 1;
            }

            if (read(i2c_fd, raw_data, 6) < 0) {
                perror("Failed to read from i2c slave");
                return 1;
            }

            if (sample_count < SAMPLES) {
                calibrated_data[0] += raw_data[0] * GYRO_SCALE;
                calibrated_data[1] += raw_data[1] * GYRO_SCALE;
                calibrated_data[2] += raw_data[2] * GYRO_SCALE;
                sample_count++;
            } else {
                calibrated_data[0] /= SAMPLES;
                calibrated_data[1] /= SAMPLES;
                calibrated_data[2] /= SAMPLES;

                fprintf(log_file, "%f,%f,%f\n", calibrated_data[0], calibrated_data[1], calibrated_data[2]);

                if (fabs(calibrated_data[0]) > THRESHOLD || fabs(calibrated_data[1]) > THRESHOLD || fabs(calibrated_data[2]) > THRESHOLD) {
                    fprintf(log_file, "Alert: %f,%f,%f\n", calibrated_data[0], calibrated_data[1], calibrated_data[2]);
                    fprintf(stderr, "Alert: %f,%f,%f\n", calibrated_data[0], calibrated_data[1], calibrated_data[2]);
                }

                memset(calibrated_data, 0, sizeof(calibrated_data));
                sample_count = 0;
            }

            clock_gettime(CLOCK_MONOTONIC, &start_time);
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

