#include <gpiod.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID 0xE5
#define LED_PIN 17
#define SAMPLE_INTERVAL 100000 // 100ms

static int i2c_fd;
static int led_fd;
static FILE *log_file;

void cleanup() {
    if (i2c_fd >= 0) close(i2c_fd);
    if (led_fd >= 0) close(led_fd);
    if (log_file) fclose(log_file);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    led_fd = gpiod_open_by_number(LED_PIN, "out");
    if (led_fd < 0) {
        perror("Failed to open LED");
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return EXIT_FAILURE;
    }

    uint8_t devid;
    if (read(i2c_fd, &devid, 1) != 1 || devid != ADXL345_DEVID) {
        fprintf(stderr, "Failed to verify ADXL345 device ID\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("accel_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    uint8_t data[6];
    while (true) {
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read from ADXL345");
            return EXIT_FAILURE;
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        float g_x = x * 0.0039;
        float g_y = y * 0.0039;
        float g_z = z * 0.0039;

        fprintf(log_file, "%ld,%0.3f,%0.3f,%0.3f\n", time(NULL), g_x, g_y, g_z);

        bool high_accel = (fabs(g_x) > 2.0 || fabs(g_y) > 2.0 || fabs(g_z) > 2.0);
        gpiod_set_value(led_fd, high_accel);

        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

