#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define VL6180X_I2C_ADDR 0x29
#define VL6180X_ID 0xB4
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL6180X_REG_RESULT_RANGE_STATUS 0x001D
#define VL6180X_REG_SYSRANGE_START 0x0018
#define VL6180X_REG_SYSRANGE_MODE 0x001A
#define VL6180X_MODE_SINGLESHOT 0x03
#define VL6180X_REG_SYSRANGE_THRESH_HIGH 0x001E
#define VL6180X_REG_SYSRANGE_THRESH_LOW 0x001F
#define VL6180X_DISTANCE_THRESHOLD 100

static int i2c_fd;
static int log_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpiod_chip_close(chip);
    gpiod_line_release(line);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sigint_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        printf("Failed to open GPIO chip\n");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 18);
    if (!line) {
        printf("Failed to get GPIO line\n");
        return -1;
    }

    if (gpiod_line_request_output(line, "VL6180X", 0)) {
        printf("Failed to request GPIO line as output\n");
        return -1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL6180X_I2C_ADDR) < 0) {
        printf("Failed to set I2C address\n");
        return -1;
    }

    log_fd = open("distance_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        printf("Failed to open log file\n");
        return -1;
    }

    while (1) {
        uint8_t data[2];
        int distance;

        if (write(i2c_fd, &VL6180X_REG_SYSRANGE_START, 1) != 1) {
            printf("Failed to write to I2C device\n");
            continue;
        }

        if (read(i2c_fd, data, 2) != 2) {
            printf("Failed to read from I2C device\n");
            continue;
        }

        distance = (data[0] << 8) | data[1];

        if (distance < 0) {
            printf("Failed to read distance\n");
            continue;
        }

        char log[256];
        sprintf(log, "%d: %s\n", distance, distance < VL6180X_DISTANCE_THRESHOLD ? "DOOR_OPEN" : "DOOR_CLOSED");
        write(log_fd, log, strlen(log));

        gpiod_line_set_value(line, distance < VL6180X_DISTANCE_THRESHOLD ? 1 : 0);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SAMPLE_INTERVAL 10000 // 10ms
#define SENSOR_COUNT 2
#define LOG_FILE "audio_log.dat"

static gpiod_chip *chip;
static gpiod_line *lines[SENSOR_COUNT];
static FILE *log_file;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec ts;
    int16_t samples[SENSOR_COUNT];
    int16_t tdoa;
    struct sigaction action;

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;

    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open_by_name("i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < SENSOR_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", i);
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    fprintf(log_file, "sec,nsec,sensor1,sensor2,tdoa\n");

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        for (int i = 0; i < SENSOR_COUNT; i++) {
            samples[i] = gpiod_line_read(lines[i]);
            if (samples[i] < 0) {
                fprintf(stderr, "Failed to read sample from sensor %d\n", i);
                samples[i] = 0;
            }
        }

        tdoa = samples[0] - samples[1];

        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts.tv_sec, ts.tv_nsec, samples[0], samples[1], tdoa);

        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);

    for (int i = 0; i < SENSOR_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

