#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pigpio.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 16
#define SPI_LSBFIRST 0
#define SPI_CE0 8
#define SPI_READ_CMD 0x8000
#define SPI_DUMMY_VALUE 0xFFFF
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025
#define READ_INTERVAL 100

int main(int argc, char *argv[]) {
    int spiHandle, gpioHandle;
    uint16_t readCmd, dummyValue;
    uint16_t gyroData[3], accelData[3];
    int i;

    if ((spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        printf("Failed to open SPI channel\n");
        return EXIT_FAILURE;
    }

    if ((gpioHandle = gpioInitialise()) < 0) {
        printf("Failed to initialize GPIO\n");
        spiClose(spiHandle);
        return EXIT_FAILURE;
    }

    gpioSetMode(gpioHandle, SPI_CE0, PI_OUTPUT);

    readCmd = SPI_READ_CMD;
    dummyValue = SPI_DUMMY_VALUE;

    while (1) {
        for (i = 0; i < 3; i++) {
            if (spiXfer(spiHandle, &readCmd, 1, gyroData, 1) != 1) {
                printf("Failed to read gyro data\n");
                goto cleanup;
            }
            usleep(40);
            if (spiXfer(spiHandle, &dummyValue, 1, &gyroData[i], 1) != 1) {
                printf("Failed to read gyro data\n");
                goto cleanup;
            }
            gyroData[i] = (gyroData[i] >> 3) * GYRO_SCALE;
        }

        for (i = 0; i < 3; i++) {
            if (spiXfer(spiHandle, &readCmd, 1, accelData, 1) != 1) {
                printf("Failed to read accel data\n");
                goto cleanup;
            }
            usleep(40);
            if (spiXfer(spiHandle, &dummyValue, 1, &accelData[i], 1) != 1) {
                printf("Failed to read accel data\n");
                goto cleanup;
            }
            accelData[i] = (accelData[i] >> 3) * ACCEL_SCALE;
        }

        printf("Gyro: %d, %d, %d\n", gyroData[0], gyroData[1], gyroData[2]);
        printf("Accel: %d, %d, %d\n", accelData[0], accelData[1], accelData[2]);

        usleep(READ_INTERVAL * 1000);
    }

cleanup:
    gpioTerminate();
    spiClose(spiHandle);
    return EXIT_FAILURE;
}

