    if (gpiod_chip_request_line(chip, 0, &request) < 0) {
        fprintf(stderr, "Failed to request I2C line: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < I2C_RETRY_COUNT; i++) {
            if (write(i2c_fd, &MPU6886_ACCEL_XOUT_H, 1) != 1) {
                fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
                continue;
            }

            if (read(i2c_fd, buffer, 14) != 14) {
                fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
                continue;
            }

            accel = (buffer[0] << 8) | buffer[1];
            gyro = (buffer[4] << 8) | buffer[5];

            printf("Accel: %d, Gyro: %d\n", accel, gyro);
            break;
        }

        usleep(50000);
    }

    gpiod_chip_release_line(chip, 0);
    close(i2c_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID 0xE5
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define LED_PIN 17
#define SCALE_FACTOR 256
#define THRESHOLD 256 // 2.5g

static int i2c_fd;
static int led_fd;
static FILE *log_file;

void cleanup() {
    if (i2c_fd >= 0) close(i2c_fd);
    if (led_fd >= 0) gpiod_close(led_fd);
    if (log_file) fclose(log_file);
}

void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int read_register(uint8_t reg, uint8_t *data) {
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];

    messages[0].addr = ADXL345_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &reg;

    messages[1].addr = ADXL345_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 1;
    messages[1].buf = data;

    packets.msgs = messages;
    packets.nmsgs = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read from register");
        return -1;
    }

    return 0;
}

int write_register(uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[1];

    messages[0].addr = ADXL345_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 2;
    messages[0].buf = buffer;

    packets.msgs = messages;
    packets.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction action;
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    uint8_t id;
    int16_t x, y, z;
    float magnitude;
    time_t timestamp;

    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    led_fd = gpiod_chip_open_by_name("gpiochip0");
    if (led_fd < 0) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    if (write_register(0x2D, 0x08) < 0) return EXIT_FAILURE; // Power on, measurement mode
    if (write_register(0x31, 0x08) < 0) return EXIT_FAILURE; // Data format, full resolution, ±2g

    chip = gpiod_chip_get(led_fd);
    gpiod_line_request_input(chip, LED_PIN, "LED", &request);
    gpiod_line_set_value(chip, LED_PIN, 0);

    log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    while (1) {
        if (read_register(ADXL345_DEVID, &id) < 0) return EXIT_FAILURE;
        if (id != ADXL345_DEVID) {
            fprintf(stderr, "Incorrect device ID: 0x%02X\n", id);
            return EXIT_FAILURE;
        }

        if (read_register(ADXL345_DATAX0, (uint8_t *)&x) < 0) return EXIT_FAILURE;
        if (read_register(ADXL345_DATAY0, (uint8_t *)&y) < 0) return EXIT_FAILURE;
        if (read_register(ADXL345_DATAZ0, (uint8_t *)&z) < 0) return EXIT_FAILURE;

        magnitude = sqrt(x * x + y * y + z * z) / SCALE_FACTOR;
        if (magnitude > THRESHOLD) {
            gpiod_line_set_value(chip, LED_PIN, 1);
            usleep(500000);
            gpiod_line_set_value(chip, LED_PIN, 0);

            timestamp = time(NULL);
            fprintf(log_file, "%ld: %.2f, %.2f, %.2f, %.2f\n", timestamp, magnitude, x / SCALE_FACTOR, y / SCALE_FACTOR, z / SCALE_FACTOR);
            fflush(log_file);
        }

        usleep(10000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
