#include <errno.h>
#include <gpiod.h>

#define ICM20602_ADDRESS 0x68
#define ICM20602_ACCEL_XOUT_H 0x3B
#define ICM20602_GYRO_XOUT_H 0x43
#define ICM20602_BURST_READ_LEN 6

static int fd;
static FILE *file;

void cleanup(int signum) {
    if (file) fclose(file);
    if (fd >= 0) gpiod_close(fd);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec ts;
    uint8_t buffer[ICM20602_BURST_READ_LEN];
    int ret;

    // Open I2C bus
    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Request I2C access
    memset(&request, 0, sizeof(request));
    request.consumer = "ICM20602";
    request.request_type = GPIO_REQUEST_TYPE_OPEN_DRAIN;
    request.line_offset = 0;
    fd = gpiod_chip_request_line(chip, &request);
    if (fd < 0) {
        fprintf(stderr, "Failed to request I2C access: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open CSV file
    file = fopen("imu_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpiod_close(fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Write CSV header
    fprintf(file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    // Set up signal handler
    signal(SIGINT, cleanup);

    while (1) {
        // Read accelerometer and gyroscope data
        ret = gpiod_i2c_transfer(fd, ICM20602_ADDRESS, ICM20602_ACCEL_XOUT_H, buffer, ICM20602_BURST_READ_LEN);
        if (ret != ICM20602_BURST_READ_LEN) {
            fprintf(stderr, "Failed to read IMU data: %s\n", strerror(errno));
            cleanup(EXIT_FAILURE);
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write data to CSV file
        fprintf(file, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec,
                buffer[0] << 8 | buffer[1],
                buffer[2] << 8 | buffer[3],
                buffer[4] << 8 | buffer[5],
                buffer[6] << 8 | buffer[7],
                buffer[8] << 8 | buffer[9],
                buffer[10] << 8 | buffer[11]);

        // Wait for 100 ms
        usleep(100000);
    }

    cleanup(EXIT_SUCCESS);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GYRO_ADDRESS 0x1D
#define ID_REG 0x0D
#define XOUT8_REG 0x06
#define LED_PIN 17
#define SENSITIVITY 1024.0
#define THRESHOLD 2048.0
#define LOG_FILE "impact_log.txt"

int fd;
FILE *logFile;

void signal_handler(int signum) {
    gpioTerminate();
    i2cClose(fd);
    fclose(logFile);
    exit(signum);
}

int main() {
    struct timespec ts;
    int id, x, y, z;
    char buffer[256];

    if (gpioInitialise() < 0) {
        printf("pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fd = i2cOpen(1, GYRO_ADDRESS, 0);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    logFile = fopen(LOG_FILE, "w");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        gpioTerminate();
        i2cClose(fd);
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (1) {
        i2cReadByteData(fd, ID_REG, &id);
        if (id != 0x1A) {
            printf("Failed to verify sensor identity\n");
            break;
        }

        i2cReadByteData(fd, XOUT8_REG, (unsigned char *)&x);
        i2cReadByteData(fd, XOUT8_REG + 1, (unsigned char *)&y);
        i2cReadByteData(fd, XOUT8_REG + 2, (unsigned char *)&z);

        if (x > THRESHOLD || y > THRESHOLD || z > THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            nanosleep((const struct timespec[]){{0, 500000000L}}, NULL);
            gpioWrite(LED_PIN, PI_LOW);

            clock_gettime(CLOCK_REALTIME, &ts);
            sprintf(buffer, "%ld.%09ld: %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
            fwrite(buffer, strlen(buffer), 1, logFile);
            fflush(logFile);
        }

        nanosleep((const struct timespec[]){{0, 100000000L}}, NULL);
    }

    gpioTerminate();
    i2cClose(fd);
    fclose(logFile);

    return 0;
}

