        perror("Failed to write to the i2c bus");
        return -1;
    }

    if (read(file, &WHO_AM_I, 1) != 1) {
        perror("Failed to read from the i2c bus");
        return -1;
    }

    if (WHO_AM_I != 0x69) {
        printf("Device not found\n");
        return -1;
    }

    if (write(file, &CTRL1_XL, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    if (write(file, &CTRL2_G, 1) != 1) {
        perror("Failed to write to the i2c bus");
        return -1;
    }

    logfile = fopen(filename, "w");
    if (logfile == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        gettimeofday(&tv, NULL);
        timeinfo = localtime(&tv.tv_sec);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(logfile, "%s.%06ld,", buffer, tv.tv_usec);

        if (read(file, &OUTX_L_XL, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return -1;
        }

        if (read(file, &OUTX_H_XL, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return -1;
        }

        accel[0] = (int16_t)((OUTX_H_XL << 8) | OUTX_L_XL);

        if (read(file, &OUTY_L_XL, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return -1;
        }

        if (read(file, &OUTY_H_XL, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return -1;
        }

        accel[1] = (int16_t)((OUTY_H_XL << 8) | OUTY_L_XL);

        if (read(file, &OUTZ_L_XL, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return -1;
        }

        if (read(file, &OUTZ_H_XL, 1) != 1) {
            perror("Failed to read from the i2c bus");
            return -1;
        }

        accel[2] = (int16_t)((OUTZ_H_XL << 8) | OUTZ_L_XL);

        accel_magnitude = sqrt(accel[0] * accel[0] + accel[1] * accel[1] + accel[2] * accel[2]);

        switch (state) {
            case 0: // IDLE
                if (accel_magnitude < 0.2) {
                    state = 1;
                }
                break;
            case 1: // FREEFALL
                if (accel_magnitude > 2.5) {
                    state = 2;
                    fall_detected = 1;
                }
                break;
            case 2: // IMPACT
                if (accel_magnitude < 0.2) {
                    state = 0;
                    fall_detected = 0;
                }
                break;
        }

        if (fall_detected) {
            fprintf(logfile, "FALL DETECTED\n");
        }

        fprintf(logfile, "\n");
        fflush(logfile);
    }

    fclose(logfile);
    close(file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

