#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define WHO_AM_I 0x00
#define ANGULAR_RATE 0x01
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define SPI_DEV "/dev/spidev0.0"
#define GPIO_PIN 8
#define INTERVAL 10
#define SCALE_FACTOR 0.0305

int spi_fd, gpio_fd;
FILE *log_file;

void cleanup() {
    close(spi_fd);
    close(gpio_fd);
    fclose(log_file);
}

void sigint_handler(int signum) {
    printf("Interrupt signal received, cleaning up...\n");
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer tr;
    uint8_t tx[2], rx[2];
    int16_t raw_value;
    float value;
    struct timespec ts;

    // Register signal handler
    memset(&action, 0, sizeof(action));
    action.sa_handler = sigint_handler;
    sigaction(SIGINT, &action, NULL);

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Set SPI mode and speed
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Request GPIO line
    memset(&request, 0, sizeof(request));
    request.consumer = "gyro_spi";
    request.request_type = GPIO_LINE_REQUEST_DIRECTION_OUTPUT;
    gpio_fd = gpiod_chip_request_line(chip, GPIO_PIN, &request);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    // Verify WHO_AM_I register
    tx[0] = WHO_AM_I | 0x80;
    tx[1] = 0x00;
    if (write(spi_fd, tx, 2) < 0 || read(spi_fd, rx, 2) < 0) {
        perror("Failed to read WHO_AM_I register");
        return -1;
    }

    if (rx[1] != WHO_AM_I) {
        printf("WHO_AM_I register does not match\n");
        return -1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Angular Rate (deg/sec)\n");

    // Main loop
    while (1) {
        // Request GPIO line
        if (gpiod_line_set_value(gpio_fd, 1) < 0) {
            perror("Failed to set GPIO line");
            return -1;
        }

        // Send read command
        tx[0] = ANGULAR_RATE | 0x80;
        tx[1] = 0x00;
        if (write(spi_fd, tx, 2) < 0 || read(spi_fd, rx, 2) < 0) {
            perror("Failed to read ANGULAR_RATE register");
            return -1;
        }

        // Convert raw value to angular rate
        raw_value = (rx[0] << 8) | rx[1];
        value = raw_value * SCALE_FACTOR;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to log file
        fprintf(log_file, "%ld.%09ld,%f\n", ts.tv_sec, ts.tv_nsec, value);

        // Wait for next interval
        usleep(INTERVAL * 1000);
    }

    // Clean up
    cleanup();
    return 0;
}

