#include <libgpiod.h>

#define GYRO_ADDRESS 0x69
#define WHO_AM_I 0x0F
#define OUT_X_L 0x28
#define I2C_BUS 1
#define SENSITIVITY 8.75

int file;
int16_t raw_data[3];
char filename[] = "gyro_log.csv";

void signal_handler(int signum) {
    close(file);
    gpiod_close();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct timespec ts;
    int16_t data[3];
    int i, j;

    chip = gpiod_chip_open("/dev/i2c-1");
    if (!chip) {
        printf("Failed to open I2C bus\n");
        return 1;
    }

    gpiod_chip_set_slave_address(chip, GYRO_ADDRESS);

    memset(&request, 0, sizeof(request));
    request.consumer = "gyro_read";
    request.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    request.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE;

    if (gpiod_chip_get_line(chip, 0, &request)) {
        printf("Failed to get line\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    file = open(filename, O_WRONLY | O_CREAT, 0666);
    if (file < 0) {
        printf("Failed to open file\n");
        return 1;
    }

    char header[] = "Timestamp,X,Y,Z\n";
    write(file, header, strlen(header));

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        for (i = 0; i < 3; i++) {
            raw_data[i] = gpiod_chip_read(chip);
            data[i] = raw_data[i] / SENSITIVITY;
        }

        char buffer[256];
        sprintf(buffer, "%ld,%d,%d,%d\n", ts.tv_sec, data[0], data[1], data[2]);
        write(file, buffer, strlen(buffer));
        usleep(10000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define LOG_FILE_NAME "flame_events.log"
#define FLAME_DETECTED_MSG "FLAME DETECTED!"

static volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *log_file;
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Enable internal pull-up resistor
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request input line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Polling loop
    while (!stop_requested) {
        struct timespec ts = {0, 500000000}; // 500ms
        int value;

        // Read line
        value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            break;
        }

        // Write to log file
        if (log_file) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char buffer[80];
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s – Flame detected: %s\n", buffer, value ? "NO" : "YES");
            fflush(log_file);
        }

        // Print message to console
        if (!value) {
            printf("%s\n", FLAME_DETECTED_MSG);
        }

        // Sleep
        nanosleep(&ts, NULL);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Release line
    gpiod_line_release(line);

    // Close chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

