#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define I2C_ADDRESS 0x0A
#define REG_X 0x01
#define REG_Y 0x02
#define REG_Z 0x03

int i2c_fd;
FILE *csv_fd;

void sigint_handler(int signum) {
    close(i2c_fd);
    fclose(csv_fd);
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = sigint_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        return 1;
    }

    csv_fd = fopen("vibration_log.csv", "w");
    if (csv_fd == NULL) {
        perror("Failed to open CSV file");
        return 1;
    }

    fprintf(csv_fd, "Timestamp,X,Y,Z\n");

    while (1) {
        uint8_t buffer[6];
        struct timespec ts;

        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

        if (read(i2c_fd, buffer, 6) != 6) {
            perror("Failed to read from I2C device");
            continue;
        }

        fprintf(csv_fd, "%s,%d,%d,%d\n", timestamp, buffer[0], buffer[1], buffer[2]);
        usleep(100000); // sleep for 100ms
    }

    return 0;
}

