        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        int16_t tilt = abs(x) + abs(y) + abs(z);
        if (tilt > FALL_DEGREE) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            fprintf(log_fd, "%d-%02d-%02d %02d:%02d:%02d - X: %d, Y: %d, Z: %d\n",
                    t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                    t->tm_hour, t->tm_min, t->tm_sec, x, y, z);
            fflush(log_fd);
        }

        usleep(10000);
    }

    return 0;
}

