#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define LIS3MDL_ADDRESS 0x1E
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_WHO_AM_I 0x0F
#define LIS3MDL_MAGNETIC_GAIN 0.146
#define LIS3MDL_MAGNETIC_THRESHOLD 800

static int i2c_fd;
static FILE *log_file;

void cleanup(int signum) {
    close(i2c_fd);
    fclose(log_file);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = cleanup;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    const struct gpiod_chip *chip;
    const struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line, "i2c", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    log_file = fopen("magnetic_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    unsigned char who_am_i;
    ret = read(i2c_fd, &who_am_i, 1);
    if (ret != 1 || who_am_i != 0x3D) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    unsigned char ctrl_reg1 = 0x10;
    ret = write(i2c_fd, &ctrl_reg1, 1);
    if (ret != 1) {
        fprintf(stderr, "Failed to write CTRL_REG1 register\n");
        gpiod_chip_close(chip);
        fclose(log_file);
        return EXIT_FAILURE;
    }

    while (1) {
        int16_t x, y, z;
        ret = read(i2c_fd, &x, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to read X register\n");
            break;
        }

        ret = read(i2c_fd, &y, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to read Y register\n");
            break;
        }

        ret = read(i2c_fd, &z, 2);
        if (ret != 2) {
            fprintf(stderr, "Failed to read Z register\n");
            break;
        }

        x = (x >> 8) | (x << 8);
        y = (y >> 8) | (y << 8);
        z = (z >> 8) | (z << 8);

        float xf = x * LIS3MDL_MAGNETIC_GAIN;
        float yf = y * LIS3MDL_MAGNETIC_GAIN;
        float zf = z * LIS3MDL_MAGNETIC_GAIN;

        float magnitude = sqrt(xf * xf + yf * yf + zf * zf);

        if (magnitude > LIS3MDL_MAGNETIC_THRESHOLD) {
            fprintf(stderr, "Metal detector alert!\n");
        }

        fprintf(log_file, "%f,%f,%f\n", xf, yf, zf);
        fflush(log_file);
    }

    cleanup(EXIT_FAILURE);
}

