    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct spi_ioc_transfer tr;
    uint8_t tx[3] = {0x2D, 0x00, 0x00};
    uint8_t rx[3];
    int ret;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    // Configure SPI device
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.delay_usecs = SPI_DELAY;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("Failed to send SPI message");
        return -1;
    }

    // Configure GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "spi-test";
    request.request_type = GPIO_REQUEST_OUTPUT;
    request.line_offset = 8;

    ret = gpiod_chip_line_request(chip, &request);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        return -1;
    }

    // Set up signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open log file
    log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }

    // Main loop
    while (true) {
        // Send SPI message
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 0) {
            perror("Failed to send SPI message");
            continue;
        }

        // Log data
        fprintf(log_file, "%ld: %d, %d, %d\n", time(NULL), rx[0], rx[1], rx[2]);

        // Wait
        usleep(100000);
    }

    return 0;
}

