#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_CHANNEL 0
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.0025
#define DELAY 10000
#define SPI_FILE "/dev/spidev0.0"
#define CSV_FILE "imu_log.csv"

int spi_fd;
FILE *csv_fd;

void cleanup(int signum) {
    close(spi_fd);
    fclose(csv_fd);
    exit(signum);
}

int main() {
    struct spi_ioc_transfer spi;
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0x00, 0x00, 0x00};
    int16_t gyro[3], accel[3];
    struct timespec ts;
    char buffer[256];

    signal(SIGINT, cleanup);

    spi_fd = open(SPI_FILE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    csv_fd = fopen(CSV_FILE, "w");
    if (!csv_fd) {
        perror("Failed to open CSV file");
        return -1;
    }

    fprintf(csv_fd, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        tx[0] = 0x80 | 0x01; // Address with MSB set
        spi.tx_buf = (unsigned long)tx;
        spi.rx_buf = (unsigned long)rx;
        spi.len = sizeof(tx);
        spi.delay_usecs = 0;
        spi.speed_hz = SPI_SPEED;
        spi.bits_per_word = 8;
        spi.cs_change = 0;
        spi.pad = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
            perror("Failed to read from SPI device");
            continue;
        }

        gyro[0] = (rx[1] << 8) | rx[2];
        gyro[1] = (rx[1] << 8) | rx[2];
        gyro[2] = (rx[1] << 8) | rx[2];
        accel[0] = (rx[1] << 8) | rx[2];
        accel[1] = (rx[1] << 8) | rx[2];
        accel[2] = (rx[1] << 8) | rx[2];

        sprintf(buffer, "%ld.%09ld,%d,%d,%d,%d,%d,%d\n",
                ts.tv_sec, ts.tv_nsec, gyro[0] * GYRO_SCALE, gyro[1] * GYRO_SCALE, gyro[2] * GYRO_SCALE,
                accel[0] * ACCEL_SCALE, accel[1] * ACCEL_SCALE, accel[2] * ACCEL_SCALE);
        fputs(buffer, csv_fd);

        usleep(DELAY);
    }

    return 0;
}

#include <stdio.h>
