    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    int ret;

    /* Register SIGINT handler */
    signal(SIGINT, sigint_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_number(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    /* Request GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set line request */
    ret = gpiod_line_request_input(line, "E18-D80NK sensor");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (running) {
        /* Read line value */
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read GPIO line\n");
            break;
        }

        /* Check if obstacle is detected */
        if (ret == 0) {
            /* Log start of self-parking sequence */
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%09ld Self-parking sequence started\n", ts.tv_sec, ts.tv_nsec);

            /* Simulate self-parking sequence */
            sleep(2);

            /* Log end of self-parking sequence */
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%09ld Self-parking sequence completed\n", ts.tv_sec, ts.tv_nsec);
        }

        /* Wait for 1 second */
        sleep(1);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

