    gpiod_line_request_input(chip, SENSOR1_PIN, "sensor1");
    gpiod_line_request_input(chip, SENSOR2_PIN, "sensor2");
    gpiod_line_bulk_release(&lines);
    gpiod_chip_close(chip);
}

