    struct sigaction action;
    struct timespec req, rem;
    int ret;

    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines.offsets[0] = SENSOR1_PIN;
    lines.offsets[1] = SENSOR2_PIN;
    lines.count = 2;

    ret = gpiod_line_request_bulk(chip, &lines, "sensor_read");
    if (ret) {
        fprintf(stderr, "Failed to request lines\n");
        goto cleanup;
    }

    atexit(cleanup);

    req.tv_sec = 0;
    req.tv_nsec = POLL_INTERVAL_MS * 1000000L;

    while (running) {
        ret = gpiod_line_get_value_bulk(chip, &lines);
