#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define SAMPLE_INTERVAL 1000
#define WINDOW_INTERVAL 5
#define ALERT_THRESHOLD 3

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec window_start, window_end;
    int high_count = 0;
    int threshold;

    if (argc != 2 || sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    clock_gettime(CLOCK_MONOTONIC, &window_start);

    while (!stop) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &window_end);

        if (value == 1) {
            high_count++;
        }

        if (high_count >= threshold) {
            printf("%ld.%09ld ALERT\n", window_end.tv_sec, window_end.tv_nsec);
            high_count = 0;
        }

        if (window_end.tv_sec - window_start.tv_sec >= WINDOW_SIZE) {
            printf("%ld.%09ld %d\n", window_end.tv_sec, window_end.tv_nsec, high_count);
            high_count = 0;
            clock_gettime(CLOCK_MONOTONIC, &window_start);
        }

        nanosleep(&(struct timespec){0, SAMPLE_INTERVAL * 1000}, NULL);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

