#define BH1750_I2C_ADDRESS 0x23
#define BH1750_POWER_DOWN 0x00
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_READ_TIME 180

int file;
int stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    struct sigaction sigIntHandler;

    sigIntHandler.sa_handler = signal_handler;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;

    sigaction(SIGINT, &sigIntHandler, NULL);

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, BH1750_I2C_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave.\n");
        return -1;
    }

    if (write(file, &BH1750_POWER_ON, 1) != 1) {
        printf("Failed to write to the i2c bus.\n");
        return -1;
    }

    if (write(file, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        printf("Failed to write to the i2c bus.\n");
        return -1;
    }

    FILE *log_file = fopen("light_log.txt", "w");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return -1;
    }

    while (!stop) {
        uint16_t data[2];
        if (read(file, data, 2) != 2) {
            printf("Failed to read from the i2c bus.\n");
            break;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char buffer[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "Timestamp: %s, Lux: %d\n", buffer, (data[0] << 8) | data[1]);

        sleep(5);
    }

    fclose(log_file);
    close(file);

    return 0;
}

