#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <lsm303dlhc.h>

#define SDA1 2
#define SCL1 3
#define LED 17
#define SAMPLE_INTERVAL 100

static int keep_running = 1;

void intHandler(int dummy) {
    keep_running = 0;
}

int main() {
    int h, i2c, led;
    uint8_t buffer[6];
    float z_axis_magnitude;
    struct lsm303dlhc_data data;

    signal(SIGINT, intHandler);
    signal(SIGTERM, intHandler);

    if ((h = pigpio_start(NULL, NULL)) < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if ((i2c = i2cOpen(h, 1, SDA1, SCL1)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop(h);
        return EXIT_FAILURE;
    }

    if ((led = gpioPWM(h, LED, 0)) < 0) {
        fprintf(stderr, "Failed to initialize LED\n");
        i2cClose(h, i2c);
        pigpio_stop(h);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        if (lsm303dlhc_read_data(i2c, &data) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            continue;
        }

        z_axis_magnitude = sqrt(data.mx * data.mx + data.my * data.my + data.mz * data.mz);

        gpioPWM(h, LED, (int)(z_axis_magnitude * 65535 / 1000));

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioTerminate(h);
    i2cClose(h, i2c);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define HMC5883L_ADDRESS 0x1E
#define HMC5883L_REG_XMSB 0x03
#define HMC5883L_REG_XLSB 0x04
#define HMC5883L_REG_YMSB 0x07
#define HMC5883L_REG_YLSB 0x08
#define HMC5883L_REG_ZMSB 0x05
#define HMC5883L_REG_ZLSB 0x06

#define SAMPLE_COUNT 100
#define SAMPLE_INTERVAL 500000 // 500ms

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int16_t samples[SAMPLE_COUNT][3];
static int sample_index = 0;
static int sample_count = 0;

static void signal_handler(int signum) {
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    if (write(fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t size) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, size) != size) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void read_magnetometer() {
    uint8_t buffer[6];
    if (i2c_read(i2c_fd, HMC5883L_REG_XMSB, buffer, 6) == 0) {
        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[4] << 8) | buffer[5];
        int16_t z = (buffer[2] << 8) | buffer[3];
        samples[sample_index][0] = x;
        samples[sample_index][1] = y;
        samples[sample_index][2] = z;
        sample_index = (sample_index + 1) % SAMPLE_COUNT;
        if (sample_count < SAMPLE_COUNT) {
            sample_count++;
        }
    }
}

static void calculate_offsets() {
    int16_t offsets[3] = {0, 0, 0};
    for (int i = 0; i < sample_count; i++) {
        offsets[0] += samples[i][0];
        offsets[1] += samples[i][1];
        offsets[2] += samples[i][2];
    }
    offsets[0] /= sample_count;
    offsets[1] /= sample_count;
    offsets[2] /= sample_count;
    printf("Offsets: %d, %d, %d\n", offsets[0], offsets[1], offsets[2]);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request request;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    memset(&request, 0, sizeof(request));
    request.consumer = "HMC5883L";
    request.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(line, &request)) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HMC5883L_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (i2c_write(i2c_fd, 0x02, 0x00) < 0) {
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        read_magnetometer();
        usleep(SAMPLE_INTERVAL);
    }

    calculate_offsets();

    close(i2c_fd);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

