#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <syslog.h>
#include <time.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define POLL_INTERVAL 50
#define FAILSAFE_TIMEOUT 10

static struct gpiod_chip *chip;
static struct gpiod_line *pir_line;
static struct gpiod_line *relay_line;
static int running = 1;

void cleanup() {
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    closelog();
}

void handle_signal(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    openlog("PIR Sensor", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_LOCAL1);
    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get RELAY line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "PIR Sensor") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "Relay", 0) < 0) {
        syslog(LOG_ERR, "Failed to request RELAY line as output");
        return EXIT_FAILURE;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);
    int motion_detected = 0;
    while (running) {
        int value = gpiod_line_get_value(pir_line);
        if (value) {
            motion_detected = 1;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            gpiod_line_set_value(relay_line, 1);
            syslog(LOG_INFO, "Relay ON");
            usleep(1000 * 1000); // 1 second
            gpiod_line_set_value(relay_line, 0);
            syslog(LOG_INFO, "Relay OFF");
        } else if (motion_detected) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if ((current_time.tv_sec - start_time.tv_sec) > FAILSAFE_TIMEOUT) {
                gpiod_line_set_value(relay_line, 0);
                syslog(LOG_WARNING, "Failsafe triggered");
                motion_detected = 0;
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <syslog.h>

#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22
#define PULSE_DURATION 300
#define PAUSE_DURATION 60
#define CYCLE_DURATION 420

volatile sig_atomic_t stop = 0;

void handle_signal(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_bulk lines;
    struct timespec ts;
    int i;

    // Initialize GPIO lines
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    gpiod_chip_get_lines(chip, &lines);
    lines.offsets[0] = RELAY1;
    lines.offsets[1] = RELAY2;
    lines.offsets[2] = RELAY3;
    lines.offsets[3] = RELAY4;

    if (gpiod_line_request_bulk(&lines, "output", "irrigation_system") < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set all relays to OFF
    gpiod_line_set_value_bulk(&lines, 1);

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (!stop) {
        for (i = 0; i < 4; i++) {
            // Turn on the current relay
            gpiod_line_set_value_bulk(&lines, 0);
            gpiod_line_set_value(&lines.lines[i], 0);

            // Wait for the pulse duration
            ts.tv_sec = PULSE_DURATION;
            ts.tv_nsec = 0;
            nanosleep(&ts, NULL);

            // Turn off the current relay
            gpiod_line_set_value(&lines.lines[i], 1);

            // Wait for the pause duration
            ts.tv_sec = PAUSE_DURATION;
            ts.tv_nsec = 0;
            nanosleep(&ts, NULL);
        }
    }

    // Turn off all relays
    gpiod_line_set_value_bulk(&lines, 1);

    // Close syslog
    closelog();

    // Release GPIO resources
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

