#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/timerfd.h>
#include <time.h>

#define MPU6050_ADDRESS 0x68
#define SAMPLE_RATE 100 // Hz

// Circular buffer for storing samples
struct sample {
    int16_t x;
    int16_t y;
    int16_t z;
};
struct sample buffer[10]; // 10 samples
int buffer_head = 0;

// File descriptor for I2C device
int i2c_fd;

// Timer file descriptor
int timer_fd;

// Signal handler for cleaning up resources
void cleanup(int signum) {
    close(i2c_fd);
    close(timer_fd);
    exit(signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C device address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C device address");
        return 1;
    }

    // Create a timer
    struct itimerspec timer_spec;
    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        return 1;
    }

    // Configure the timer to interrupt every SAMPLE_RATE milliseconds
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 1000000 / SAMPLE_RATE;
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 1000000 / SAMPLE_RATE;
    if (timerfd_settime(timer_fd, 0, &timer_spec, NULL) < 0) {
        perror("Failed to set timer");
        return 1;
    }

    // Main loop
    while (1) {
        uint64_t expirations;
        read(timer_fd, &expirations, sizeof(expirations));

        // Read acceleration data from MPU6050
        uint8_t data[6];
        if (read(i2c_fd, data, sizeof(data)) != sizeof(data)) {
            perror("Failed to read from I2C device");
            continue;
        }

        // Store the data in the circular buffer
        struct sample sample = {
            .x = (int16_t)((data[0] << 8) | data[1]),
            .y = (int16_t)((data[2] << 8) | data[3]),
            .z = (int16_t)((data[4] << 8) | data[5])
        };
        buffer[buffer_head] = sample;
        buffer_head = (buffer_head + 1) % sizeof(buffer) / sizeof(struct sample);

        // Write the most recent sample to the driver library interface
        char path[256];
        sprintf(path, "/sys/kernel/mpu6050_accel/latest");
        int fd = open(path, O_WRONLY);
        if (fd < 0) {
            perror("Failed to open driver library interface");
            continue;
        }
        write(fd, &sample, sizeof(sample));
        close(fd);
    }

    return 0;
}

