    int16_t y;
    int16_t z;
};
struct sample buffer[10]; // 10 samples
int buffer_head = 0;

// File descriptor for I2C device
int i2c_fd;

// Timer file descriptor
int timer_fd;

// Signal handler for cleaning up resources
void cleanup(int signum) {
    close(i2c_fd);
    close(timer_fd);
    exit(signum);
}

