    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C device address");
        return 1;
    }

    // Create a timer
    struct itimerspec timer_spec;
    timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (timer_fd < 0) {
        perror("Failed to create timer");
        return 1;
    }

    // Configure the timer to interrupt every SAMPLE_RATE milliseconds
    timer_spec.it_value.tv_sec = 0;
    timer_spec.it_value.tv_nsec = 1000000 / SAMPLE_RATE;
    timer_spec.it_interval.tv_sec = 0;
    timer_spec.it_interval.tv_nsec = 1000000 / SAMPLE_RATE;
