#define SOUND_SENSOR 17
#define RELAY 27
#define POLL_INTERVAL 100
#define RELAY_DURATION 3

static int running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *sound_line, *relay_line;
static struct timespec last_activation;

void handle_signal(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_signal;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR);
    if (!sound_line) {
        fprintf(stderr, "Failed to get sound sensor line\n");
        goto close_chip;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        goto close_chip;
    }

    if (gpiod_line_request_input(sound_line, "sound_sensor") < 0) {
        fprintf(stderr, "Failed to request input for sound sensor\n");
        goto close_chip;
    }

    if (gpiod_line_request_output(relay_line, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request output for relay\n");
        goto close_chip;
    }

    FILE *log_file = fopen("alarm_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto close_chip;
    }

    clock_gettime(CLOCK_REALTIME, &last_activation);

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(sound_line, &event) < 0) {
            fprintf(stderr, "Failed to wait for sound sensor event\n");
            break;
        }

        if (event.level) {
            struct timespec now;
            clock_gettime(CLOCK_REALTIME, &now);

            if (now.tv_sec - last_activation.tv_sec >= RELAY_DURATION) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    fprintf(stderr, "Failed to activate relay\n");
                    break;
                }

                clock_gettime(CLOCK_REALTIME, &last_activation);
                fprintf(log_file, "%ld.%09ld\n", last_activation.tv_sec, last_activation.tv_nsec);
                fflush(log_file);

                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    fprintf(stderr, "Failed to deactivate relay\n");
                    break;
                }
            }
        }
    }

    fclose(log_file);
    gpiod_line_release(sound_line);
    gpiod_line_release(relay_line);
close_chip:
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

