    if (file < 0) {
        printf("Failed to open i2c bus\n");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        printf("Failed to select MPU6050\n");
        exit(1);
    }

    int16_t x, y, z;
    int16_t buffer[BUFFER_SIZE];
    int buffer_head = 0;

    while (!stop) {
        read_gyro_data(file, &x, &y, &z);
        buffer[buffer_head++] = abs(x) + abs(y) + abs(z);
