#define READ_TIMEOUT 1
#define READ_RETRIES 10

static int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    int uart_fd;
    struct timespec read_interval = {READ_INTERVAL, 0};
    struct timespec read_timeout = {READ_TIMEOUT, 0};
    struct timespec error_timestamp;
    struct timespec log_timestamp;
    char buffer[9];
    int bytes_read;
    int retries;
    int ppm;
    int checksum_error = 0;
    int error_flag = 0;
    FILE *log_file;
    FILE *error_file;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = open(UART, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART");
        return EXIT_FAILURE;
    }

    tcgetattr(uart_fd, &tty);
    cfsetospeed(&tty, BAUDRATE);
    cfsetispeed(&tty, BAUDRATE);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &tty);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    error_file = fopen(ERROR_FILE, "w");
    if (error_file == NULL) {
        perror("Failed to open error file");
        return EXIT_FAILURE;
    }

    while (running) {
        retries = READ_RETRIES;
        while (retries > 0) {
            bytes_read = read(uart_fd, buffer, sizeof(buffer));
            if (bytes_read == sizeof(buffer)) {
                break;
            }
            retries--;
            nanosleep(&read_timeout, NULL);
        }

        if (bytes_read != sizeof(buffer)) {
            error_flag = 1;
            clock_gettime(CLOCK_REALTIME, &error_timestamp);
            fprintf(error_file, "%ld.%09ld: Read timeout or checksum error\n", error_timestamp.tv_sec, error_timestamp.tv_nsec);
            continue;
        }

        ppm = (buffer[0] << 8) | buffer[1];
        int checksum = (buffer[0] + buffer[1] + buffer[2] + buffer[3] + buffer[4] + buffer[5] + buffer[6]) & 0xFF;
        if (checksum != buffer[7]) {
            error_flag = 1;
            clock_gettime(CLOCK_REALTIME, &error_timestamp);
            fprintf(error_file, "%ld.%09ld: Checksum error\n", error_timestamp.tv_sec, error_timestamp.tv_nsec);
            continue;
        }

        clock_gettime(CLOCK_REALTIME, &log_timestamp);
        fprintf(log_file, "{\"timestamp\":\"%ld.%09ld\", \"ppm\":%d, \"error\":%d}\n", log_timestamp.tv_sec, log_timestamp.tv_nsec, ppm, error_flag);
        fflush(log_file);
        printf("{\"timestamp\":\"%ld.%09ld\", \"ppm\":%d, \"error\":%d}\n", log_timestamp.tv_sec, log_timestamp.tv_nsec, ppm, error_flag);

        error_flag = 0;
        nanosleep(&read_interval, NULL);
    }

    fclose(log_file);
    fclose(error_file);
    close(uart_fd);

    return EXIT_SUCCESS;
}

