    stop = 1;
}

int main() {
    int hmc5883l_fd, gpio_fd;
    uint8_t buffer[6];
    float heading;
    float buffer[BUFFER_SIZE];
    int buffer_head = 0;
    float target_heading = 90.0;

    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    hmc5883l_fd = i2cOpen(1, HMC5883L_ADDRESS, 0);
    if (hmc5883l_fd < 0) {
        fprintf(stderr, "Failed to open HMC5883L\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(hmc5883l_fd, HMC5883L_REG_CONFIG_A, HMC5883L_RATE_15 | HMC5883L_GAIN_1370) < 0) {
        fprintf(stderr, "Failed to write to HMC5883L\n");
        i2cClose(hmc5883l_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(hmc5883l_fd, HMC5883L_REG_CONFIG_B, 0x00) < 0) {
        fprintf(stderr, "Failed to write to HMC5883L\n");
        i2cClose(hmc5883l_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(hmc5883l_fd, HMC5883L_REG_MODE, HMC5883L_MODE_CONTINUOUS) < 0) {
        fprintf(stderr, "Failed to write to HMC5883L\n");
        i2cClose(hmc5883l_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop) {
        if (i2cReadByteData(hmc5883l_fd, HMC5883L_REG_X_MSB, buffer, 6) < 0) {
            fprintf(stderr, "Failed to read from HMC5883L\n");
            continue;
        }

        heading = ((buffer[0] << 8) | buffer[1]) * 0.73 - 70.0;
        heading -= 100.0;
        heading -= 50.0;

        buffer[buffer_head] = heading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        if (fabs(heading - target_heading) > DEVIATION_THRESHOLD) {
            gpioWrite(gpio_fd, GPIO_PIN, 1);
        } else {
            gpioWrite(gpio_fd, GPIO_PIN, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    i2cClose(hmc5883l_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_ADDRESS 0x23
#define BH1750_POWER_DOWN 0x00
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_I2C_BUS 1

int main() {
    int fd, red, green, blue;
    uint16_t lux;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    if ((fd = pi_i2c_open(BH1750_I2C_BUS, BH1750_ADDRESS)) < 0) {
        printf("Failed to open I2C bus\n");
        return -1;
    }

    if (pi_i2c_write_byte_data(fd, BH1750_POWER_ON) < 0) {
        printf("Failed to write to I2C bus\n");
        return -1;
    }

    if (pi_i2c_write_byte_data(fd, BH1750_RESET) < 0) {
        printf("Failed to reset BH1750\n");
        return -1;
    }

    if (pi_i2c_write_byte_data(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        printf("Failed to set BH1750 mode\n");
        return -1;
    }

    if ((log_file = fopen("lighting_log.txt", "w")) == NULL) {
        printf("Failed to open log file\n");
        return -1;
    }

    red = pi_gpio_pin_to_handle(17);
    green = pi_gpio_pin_to_handle(27);
    blue = pi_gpio_pin_to_handle(22);

    if (red < 0 || green < 0 || blue < 0) {
        printf("Failed to get GPIO handles\n");
        return -1;
    }

    while (1) {
        if (pi_i2c_read_word_data(fd, BH1750_ADDRESS) < 0) {
            printf("Failed to read from I2C bus\n");
            return -1;
        }

        lux = pi_i2c_read_word_data(fd, BH1750_ADDRESS);

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, %d\n", buffer, lux);

        if (lux < 50) {
            pi_gpio_write(red, PI_HIGH);
            pi_gpio_write(green, PI_LOW);
            pi_gpio_write(blue, PI_LOW);
        } else if (lux < 150) {
            pi_gpio_write(red, PI_LOW);
            pi_gpio_write(green, PI_HIGH);
            pi_gpio_write(blue, PI_LOW);
        } else if (lux < 300) {
            pi_gpio_write(red, PI_LOW);
            pi_gpio_write(green, PI_LOW);
            pi_gpio_write(blue, PI_HIGH);
        } else {
            pi_gpio_write(red, PI_HIGH);
            pi_gpio_write(green, PI_HIGH);
            pi_gpio_write(blue, PI_HIGH);
        }

        sleep(1);
    }

    pi_i2c_close(fd);
    fclose(log_file);
    pi_gpio_write(red, PI_LOW);
    pi_gpio_write(green, PI_LOW);
    pi_gpio_write(blue, PI_LOW);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23
#define PWM_FREQ 1000
#define DISTANCE_MIN 10
#define DISTANCE_MAX 100
#define DISTANCE_THRESHOLD 50

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int distance_a = atoi(argv[1]);
    int distance_b = atoi(argv[2]);

    if (distance_a < DISTANCE_MIN || distance_a > DISTANCE_MAX || distance_b < DISTANCE_MIN || distance_b > DISTANCE_MAX) {
        printf("Distance values must be between %d and %d\n", DISTANCE_MIN, DISTANCE_MAX);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int motor_a_pwm = gpioPWM(MOTOR_A_IN2, PWM_FREQ);
    int motor_b_pwm = gpioPWM(MOTOR_B_IN4, PWM_FREQ);

    if (motor_a_pwm < 0 || motor_b_pwm < 0) {
        printf("Failed to initialize PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!stop) {
        int duty_a = (distance_a < DISTANCE_THRESHOLD) ? (distance_a * 255 / DISTANCE_THRESHOLD) : 255;
        int duty_b = (distance_b < DISTANCE_THRESHOLD) ? (distance_b * 255 / DISTANCE_THRESHOLD) : 255;

        gpioPWMWrite(MOTOR_A_IN2, duty_a);
        gpioPWMWrite(MOTOR_B_IN4, duty_b);

        gpioDelay(100000); // 100ms delay
    }

    gpioPWMWrite(MOTOR_A_IN2, 0);
    gpioPWMWrite(MOTOR_B_IN4, 0);

    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define IN1 17
#define IN2 18
#define IN3 27
#define IN4 22
#define LOCK 24
#define UNLOCK 23

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;
static struct gpiod_line_bulk lock_lines;
static struct gpiod_line_bulk unlock_lines;

static void cleanup(void) {
    gpiod_line_set_value_bulk(lines, 0);
    gpiod_line_release_bulk(lines);
    gpiod_chip_close(chip);
}

static void terminate(int signum) {
    printf("\nProgram terminated by signal %d\n", signum);
    cleanup();
    exit(signum);
}

int main(void) {
    struct gpiod_line_request req = {
        .consumer = "stepper_motor",
        .flags = GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    signal(SIGINT, terminate);
    signal(SIGTERM, terminate);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (gpiod_chip_get_lines(chip, IN1, IN2, IN3, IN4, LOCK, UNLOCK, NULL, &lines) < 0) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_bulk(lines, &req) < 0) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        cleanup();
        return EXIT_FAILURE;
    }

    lock_lines = lines;
    unlock_lines = lines;

    printf("Press LOCK button to lock the door\n");
    printf("Press UNLOCK button to unlock the door\n");

    while (1) {
        if (gpiod_line_event_wait_bulk(lines, 0) < 0) {
            fprintf(stderr, "Failed to wait for GPIO event\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_event_read_bulk(lines, NULL) < 0) {
            fprintf(stderr, "Failed to read GPIO event\n");
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_get_value(LOCK)) {
            printf("Locking the door...\n");
            gpiod_line_set_value_bulk(lock_lines, 1);
            sleep(1);
            gpiod_line_set_value_bulk(lock_lines, 0);
        }

        if (gpiod_line_get_value(UNLOCK)) {
            printf("Unlocking the door...\n");
            gpiod_line_set_value_bulk(unlock_lines, 1);
            sleep(1);
            gpiod_line_set_value_bulk(unlock_lines, 0);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include <string.h>
#include <time.h>
#include <dirent.h>
#include <math.h>

#define MPU6050_ADDRESS 0x68
#define I2C_BUS "/dev/i2c-1"
#define SERVO_PIN 18

int i2c_fd, servo_fd;
int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
float pitch, roll;

void read_mpu6050() {
    uint8_t buffer[14];
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];

    messages[0].addr = MPU6050_ADDRESS;
    messages[0].flags = 0;
    messages[0].len = 1;
    messages[0].buf = &buffer[0];
    messages[0].buf[0] = 0x3B;

    messages[1].addr = MPU6050_ADDRESS;
    messages[1].flags = I2C_M_RD;
    messages[1].len = 14;
    messages[1].buf = &buffer[1];

    packets.msgs = messages;
    packets.nmsgs = 2;

    if(ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
        perror("Failed to read MPU6050");
        exit(1);
    }

    accel_x = (buffer[1] << 8) | buffer[2];
    accel_y = (buffer[3] << 8) | buffer[4];
    accel_z = (buffer[5] << 8) | buffer[6];
    gyro_x = (buffer[7] << 8) | buffer[8];
    gyro_y = (buffer[9] << 8) | buffer[10];
    gyro_z = (buffer[11] << 8) | buffer[12];

    // Calculate pitch and roll
    float accel_angle_x = atan(accel_x / sqrt(pow(accel_y, 2) + pow(accel_z, 2))) * 180 / M_PI;
    float accel_angle_y = atan(accel_y / sqrt(pow(accel_x, 2) + pow(accel_z, 2))) * 180 / M_PI;
    pitch = accel_angle_x;
    roll = accel_angle_y;
}

void write_servo(int angle) {
    char buf[256];
    sprintf(buf, "echo %d > /sys/class/pwm/pwmchip2/pwm0/duty_cycle", angle * 1000);
    system(buf);
}

void log_data() {
    FILE *file = fopen("solar_tracker.log", "a");
    if(file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(file, "%ld.%06ld,%f,%f\n", tv.tv_sec, tv.tv_usec, pitch, roll);
    fclose(file);
}

void signal_handler(int signum) {
    close(i2c_fd);
    close(servo_fd);
    exit(signum);
}

int main() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if(i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if(ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(1);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while(1) {
        read_mpu6050();
        write_servo(roll);
        log_data();
        sleep(1);
    }

    return 0;
}

