#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_COUNT 4
#define SCHEDULE_FILE "lighting_schedule.txt"
#define FADE_TIME 1800
#define PWM_FREQ 100
#define PWM_DUTY_MAX 100

gpiod_chip *chip;
gpiod_line_bulk lines;
gpiod_line_request req;
struct timespec sleep_time = {.tv_sec = 1, .tv_nsec = 0};

void cleanup_and_exit(int exit_code) {
    gpiod_line_set_value_bulk(chip, &lines, 0);
    gpiod_chip_close(chip);
    exit(exit_code);
}

void handle_signal(int signum) {
    cleanup_and_exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set up signal handler for SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler for SIGTERM");
        return 1;
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    gpiod_line_bulk_init(&lines);
    gpiod_line_bulk_add(&lines, chip, GPIO_COUNT, (const uint32_t[]){4, 17, 27, 22});
    if (gpiod_line_request_bulk(chip, &lines, "output", &req) < 0) {
        perror("Failed to request lines");
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *schedule_file = fopen(SCHEDULE_FILE, "r");
    if (!schedule_file) {
        perror("Failed to open schedule file");
        cleanup_and_exit(1);
    }

    char line[256];
    struct tm next_transition_time;
    int next_relay, next_state;
    while (1) {
        while (fgets(line, sizeof(line), schedule_file)) {
            if (sscanf(line, "%d:%d:%d,%d,%d", &next_transition_time.tm_hour, &next_transition_time.tm_min, &next_transition_time.tm_sec, &next_relay, &next_state) != 5) {
                fprintf(stderr, "Invalid schedule entry: %s", line);
                continue;
            }
            if (next_relay < 0 || next_relay >= GPIO_COUNT || next_state < 0 || next_state > 1) {
                fprintf(stderr, "Invalid relay or state: %d, %d", next_relay, next_state);
                continue;
            }
            time_t now = time(NULL);
            struct tm *current_time = localtime(&now);
            if (current_time && mktime(current_time) < mktime(&next_transition_time)) {
                break;
            }
        }
        if (ferror(schedule_file)) {
            perror("Failed to read schedule file");
            cleanup_and_exit(1);
        }
        if (feof(schedule_file)) {
            fseek(schedule_file, 0, SEEK_SET);
        }

        int elapsed_time = difftime(mktime(&next_transition_time), current_time);
        if (elapsed_time > 0) {
            nanosleep(&sleep_time, NULL);
            continue;
        }

        gpiod_line_set_value(chip, lines.offsets[next_relay], next_state);
        if (next_state) {
            // Fade in
            for (int i = 0; i <= PWM_DUTY_MAX; i++) {
                gpiod_line_set_pwm(chip, lines.offsets[next_relay], PWM_FREQ, i);
                nanosleep(&sleep_time, NULL);
            }
        } else {
            // Fade out
            for (int i = PWM_DUTY_MAX; i >= 0; i--) {
                gpiod_line_set_pwm(chip, lines.offsets[next_relay], PWM_FREQ, i);
                nanosleep(&sleep_time, NULL);
            }
        }
    }

    cleanup_and_exit(0);
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <libgpiod.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_GAP 60000 // 60 ms
#define BUZZER_FREQ_MIN 20
#define BUZZER_FREQ_MAX 20000

static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static struct gpiod_line *buzzer_line;
static struct timespec last_measurement;

static void cleanup() {
    gpiod_line_set_value(trigger_line, 0);
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
}

static void handle_sigint(int signum) {
    cleanup();
    exit(0);
}

static int measure_distance() {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    if ((now.tv_sec - last_measurement.tv_sec) * 1000000 + (now.tv_nsec - last_measurement.tv_nsec) < MIN_GAP) {
        return -1;
    }
    last_measurement = now;

    gpiod_line_set_value(trigger_line, 1);
    nanosleep(&(struct timespec){0, 10}, NULL); // 10 us
    gpiod_line_set_value(trigger_line, 0);

    int timeout = 5000; // 5 ms
    while (gpiod_line_get_value(echo_line) == 0 && timeout > 0) {
        nanosleep(&(struct timespec){0, 1000}, NULL); // 1 us
        timeout--;
    }
    if (timeout == 0) {
        return -1;
    }

    timeout = 5000; // 5 ms
    while (gpiod_line_get_value(echo_line) == 1 && timeout > 0) {
        nanosleep(&(struct timespec){0, 1000}, NULL); // 1 us
        timeout--;
    }
    if (timeout == 0) {
        return -1;
    }

    return timeout;
}

int main() {
    struct sigaction action;
    action.sa_handler = handle_sigint;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        cleanup();
        return 1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        cleanup();
        return 1;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        cleanup();
        return 1;
    }

    gpiod_line_request_output(trigger_line, "theremin_trigger", 0);
    gpiod_line_request_input(echo_line, "theremin_echo");
    gpiod_line_request_output(buzzer_line, "theremin_buzzer", 0);

    while (true) {
        int distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to measure distance\n");
            continue;
        }

        int frequency = (distance / 58) + 20; // Convert distance to frequency
        if (frequency < BUZZER_FREQ_MIN) {
            frequency = BUZZER_FREQ_MIN;
        } else if (frequency > BUZZER_FREQ_MAX) {
            frequency = BUZZER_FREQ_MAX;
        }

        gpiod_line_set_value(buzzer_line, 1);
        nanosleep(&(struct timespec){0, 1000000 / frequency / 2}, NULL); // 50% duty cycle
        gpiod_line_set_value(buzzer_line, 0);
        nanosleep(&(struct timespec){0, 1000000 / frequency / 2}, NULL); // 50% duty cycle
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <math.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define FREQUENCY 1000

void exit_handler(int signum) {
    printf("Exiting...\n");
    gpioSetPWMdutycycle(RED_PIN, 0);
    gpioSetPWMdutycycle(GREEN_PIN, 0);
    gpioSetPWMdutycycle(BLUE_PIN, 0);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetPWMfrequency(FREQUENCY) < 0) {
        printf("Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set RED_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set GREEN_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        printf("Failed to set BLUE_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, exit_handler);

    while (1) {
        float proximity = sin(gpioTick() / 1000000.0);
        int duty_cycle = (int) (proximity * 255);

        gpioSetPWMdutycycle(RED_PIN, duty_cycle);
        gpioSetPWMdutycycle(GREEN_PIN, duty_cycle);
        gpioSetPWMdutycycle(BLUE_PIN, duty_cycle);

        usleep(1000);
    }

    return 0;
}

