#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define MELody_LENGTH 8
#define DEBOUNCE_TIME 50

volatile sig_atomic_t stop_flag = 0;

void button_isr(int gpio, int level, uint32_t tick) {
    static uint32_t last_interrupt_time = 0;
    uint32_t interrupt_time = tick / 1000; // convert to milliseconds

    // Debounce the button
    if (interrupt_time - last_interrupt_time > DEBOUNCE_TIME) {
        stop_flag = !stop_flag;
    }

    last_interrupt_time = interrupt_time;
}

void play_melody() {
    int melody[] = {261, 294, 330, 349, 392, 440, 494, 523}; // C4, D4, E4, F4, G4, A4, B4, C5
    int note_durations[] = {500, 500, 500, 500, 500, 500, 500, 500}; // quarter note

    for (int i = 0; i < MELody_LENGTH; i++) {
        if (stop_flag) {
            break;
        }

        // Generate the tone
        gpioHardwarePWM(BUZZER_PIN, melody[i], 50);

        // Wait for the note duration
        gpioDelay(note_durations[i] * 1000);

        // Stop the tone
        gpioHardwarePWM(BUZZER_PIN, 0, 0);
    }
}

void signal_handler(int signum) {
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the button GPIO
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    gpioSetAlertFunc(BUTTON_PIN, button_isr);

    // Set up the buzzer GPIO
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    while (1) {
        if (stop_flag) {
            play_melody();
            stop_flag = 0;
        }

        gpioDelay(1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

