        int value;

        if (gpiod_line_event_wait(line, &timeout) < 0) {
            fprintf(stderr, "Failed to wait for GPIO line event\n");
            break;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "Failed to read GPIO line event\n");
            break;
        }

