#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int i2c_fd, file_exists;
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    uint8_t buffer[6];
    FILE *file;
    double x, y, z, heading;
    char direction[9][4] = {"N", "NE", "E", "SE", "S", "SW", "W", "NW"};

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    file_exists = access("mag_log.csv", F_OK);
    file = fopen("mag_log.csv", "a");
    if (!file_exists) {
        fprintf(file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }

    while (!stop) {
        messages[0].addr = I2C_ADDRESS;
        messages[0].flags = 0;
        messages[0].len = 1;
        messages[0].buf = &buffer[0];
        messages[1].addr = I2C_ADDRESS;
        messages[1].flags = I2C_M_RD;
        messages[1].len = 6;
        messages[1].buf = &buffer[1];

        packets.msgs = messages;
        packets.nmsgs = 2;

        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            perror("Failed to read from the i2c bus");
            continue;
        }

        x = (buffer[1] << 8) | buffer[2];
        y = (buffer[3] << 8) | buffer[4];
        z = (buffer[5] << 8) | buffer[6];

        x -= X_OFFSET;
        y -= Y_OFFSET;
        z -= Z_OFFSET;

        heading = atan2(y, x) * 180 / M_PI;
        if (heading < 0) {
            heading += 360;
        }

        int index = (int)(heading / 45);
        if (index < 0) {
            index += 8;
        }

        fprintf(file, "%ld, %f, %f, %f, %f\n", time(NULL), x, y, z, heading);
        printf("Compass direction: %s, Heading: %f\n", direction[index], heading);
    }

    fclose(file);
    close(i2c_fd);

    return 0;
}

