static gpiod_line *line_relay;
static int relay_state = 0;
static time_t last_touch_time = 0;

void log_state_change() {
    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    FILE *file = fopen("relay_log.json", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "{\"timestamp\":\"%s\", \"relay_state\":\"%s\"}\n", timestamp, relay_state ? "ON" : "OFF");
    fclose(file);
}

void toggle_relay() {
    gpiod_line_set_value(line_relay, relay_state ? 0 : 1);
    relay_state = !relay_state;
    log_state_change();
}

void touch_interrupt(gpiod_line_event event) {
    time_t now = time(NULL);
    if (difftime(now, last_touch_time) < DEBOUNCE_TIME / 1000.0) {
        return;
    }
    last_touch_time = now;

    toggle_relay();
}

void sigint_handler(int signum) {
    toggle_relay();
    log_state_change();
    gpiod_chip_close(chip);
    exit(EXIT_SUCCESS);
}

