        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line_touch, "touch_input") < 0) {
        fprintf(stderr, "Failed to request touch input\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
