#define PULSE_WIDTH_0 500
#define PULSE_WIDTH_45 1000
#define PULSE_WIDTH_90 1500
#define PULSE_WIDTH_135 2000
#define PULSE_WIDTH_180 2500
#define OPEN_DURATION 2
#define HOLD_DURATION 5
#define CYCLE_DURATION 5

volatile sig_atomic_t stop_requested = 0;

void signal_handler(int signum) {
    stop_requested = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line18;
    int moisture = 20;
    int i;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO17);
    if (!line17) {
        fprintf(stderr, "Failed to get line for GPIO17\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO18);
    if (!line18) {
        fprintf(stderr, "Failed to get line for GPIO18\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line17);
        return EXIT_FAILURE;
    }

    while (!stop_requested) {
        if (moisture < 50) {
            for (i = 0; i < 3; i++) {
                if (gpiod_line_request_output(line17, "servo_valve", PULSE_WIDTH_OPEN) < 0) {
                    fprintf(stderr, "Failed to request output for GPIO17\n");
                    stop_requested = 1;
                    break;
                }

                sleep(OPEN_DURATION);

                if (gpiod_line_request_output(line17, "servo_valve", PULSE_WIDTH_CLOSE) < 0) {
                    fprintf(stderr, "Failed to request output for GPIO17\n");
                    stop_requested = 1;
                    break;
                }

                sleep(HOLD_DURATION);
            }

            if (!stop_requested) {
                for (i = 0; i < 5; i++) {
                    if (gpiod_line_request_output(line18, "servo_nozzle", PULSE_WIDTH_0 + i * 500) < 0) {
                        fprintf(stderr, "Failed to request output for GPIO18\n");
                        stop_requested = 1;
                        break;
                    }

                    sleep(OPEN_DURATION);
                }

                if (!stop_requested) {
                    sleep(HOLD_DURATION);
                }
            }
        }

        sleep(CYCLE_DURATION);
        moisture = (moisture + 20) % 100;
    }

    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

