int main() {
    struct gpiod_line_event event;
    int distance;
    int start_time, end_time;
    int timeout;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig_line, "trigger", 0) < 0) {
        fprintf(stderr, "Failed to request output on trigger line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        fprintf(stderr, "Failed to request input on echo line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        gpiod_line_set_value(trig_line, 1);
        usleep(TRIG_PULSE_WIDTH * 1000);
        gpiod_line_set_value(trig_line, 0);

        timeout = ECHO_TIMEOUT;
        while (gpiod_line_event_wait(echo_line, &event, timeout) > 0) {
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                start_time = event.timestamp;
            } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                end_time = event.timestamp;
                distance = (end_time - start_time) / 58;
                fprintf(log_file, "%d\n", distance);
                fflush(log_file);
                break;
            }
        }

        if (timeout <= 0) {
            fprintf(log_file, "-1\n");
            fflush(log_file);
        }

        usleep(MIN_PAUSE * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

