#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_ZOUT_H 0x47
#define WARNING_PIN 17
#define BUFFER_SIZE 64

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

typedef struct {
    uint32_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} Sample;

Sample buffer[BUFFER_SIZE];
int buffer_head = 0;

int spi_open() {
    return spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BPW);
}

void spi_close(int spi) {
    spiClose(spi);
}

int16_t spi_read(int spi, uint8_t reg) {
    uint8_t tx[2] = {reg, 0};
    uint8_t rx[2];
    spiXfer(spi, tx, rx, 2);
    return (int16_t)((rx[0] << 8) | rx[1]);
}

void blink(int pin) {
    gpioWrite(pin, 1);
    sleep(0.5);
    gpioWrite(pin, 0);
    sleep(0.5);
}

int main() {
    int spi = spi_open();
    if (spi < 0) {
        printf("Failed to open SPI\n");
        return -1;
    }

    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        spi_close(spi);
        return -1;
    }

    gpioSetMode(WARNING_PIN, PI_OUTPUT);
    signal(SIGINT, signal_handler);

    while (!stop) {
        int16_t x = spi_read(spi, MPU6050_REG_GYRO_XOUT_H);
        int16_t y = spi_read(spi, MPU6050_REG_GYRO_YOUT_H);
        int16_t z = spi_read(spi, MPU6050_REG_GYRO_ZOUT_H);

        if (x == 0 || y == 0 || z == 0) {
            printf("Failed to read from MPU6050\n");
            continue;
        }

        uint32_t timestamp = time(NULL);
        buffer[buffer_head].timestamp = timestamp;
        buffer[buffer_head].x = x;
        buffer[buffer_head].y = y;
        buffer[buffer_head].z = z;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        if (abs(x) > 200 || abs(y) > 200 || abs(z) > 200) {
            blink(WARNING_PIN);
        }
    }

    spi_close(spi);
    gpioTerminate();

    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%u,%d,%d,%d\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <wiringPi.h>
#include <i2c/smbus.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDRESS 0x68
#define MPU6050_ACCEL_XOUT_H 0x3B
#define LED_PIN 21
#define SAMPLE_INTERVAL 0.1

int file;
int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
float accel_x_scaled, accel_y_scaled, accel_z_scaled, gyro_x_scaled, gyro_y_scaled, gyro_z_scaled;
float roll, pitch;

void read_mpu6050_data() {
    accel_x = (int16_t) (i2c_smbus_read_byte_data(file, MPU6050_ACCEL_XOUT_H) << 8 | i2c_smbus_read_byte_data(file, MPU6050_ACCEL_XOUT_H + 1));
    accel_y = (int16_t) (i2c_smbus_read_byte_data(file, MPU6050_ACCEL_YOUT_H) << 8 | i2c_smbus_read_byte_data(file, MPU6050_ACCEL_YOUT_H + 1));
    accel_z = (int16_t) (i2c_smbus_read_byte_data(file, MPU6050_ACCEL_ZOUT_H) << 8 | i2c_smbus_read_byte_data(file, MPU6050_ACCEL_ZOUT_H + 1));
    gyro_x = (int16_t) (i2c_smbus_read_byte_data(file, MPU6050_GYRO_XOUT_H) << 8 | i2c_smbus_read_byte_data(file, MPU6050_GYRO_XOUT_H + 1));
    gyro_y = (int16_t) (i2c_smbus_read_byte_data(file, MPU6050_GYRO_YOUT_H) << 8 | i2c_smbus_read_byte_data(file, MPU6050_GYRO_YOUT_H + 1));
    gyro_z = (int16_t) (i2c_smbus_read_byte_data(file, MPU6050_GYRO_ZOUT_H) << 8 | i2c_smbus_read_byte_data(file, MPU6050_GYRO_ZOUT_H + 1));

    accel_x_scaled = accel_x / 16384.0;
    accel_y_scaled = accel_y / 16384.0;
    accel_z_scaled = accel_z / 16384.0;
    gyro_x_scaled = gyro_x / 131.0;
    gyro_y_scaled = gyro_y / 131.0;
    gyro_z_scaled = gyro_z / 131.0;

    roll = atan2(accel_y_scaled, accel_z_scaled) * (180.0 / M_PI);
    pitch = atan2(-accel_x_scaled, sqrt(accel_y_scaled * accel_y_scaled + accel_z_scaled * accel_z_scaled)) * (180.0 / M_PI);
}

void write_to_file() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *f = fopen("tilt_log.txt", "a");
    if (f == NULL) {
        printf("Error opening file!\n");
        exit(1);
    }

    fprintf(f, "%s,%f,%f\n", timestamp, roll, pitch);
    fclose(f);
}

void signal_handler(int signum) {
    digitalWrite(LED_PIN, LOW);
    close(file);
    exit(signum);
}

int main() {
    wiringPiSetup();
    pinMode(LED_PIN, OUTPUT);
    signal(SIGINT, signal_handler);

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        printf("Failed to open the i2c bus\n");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        printf("Failed to acquire bus access and/or talk to slave.\n");
        exit(1);
    }

    while (1) {
        read_mpu6050_data();
        printf("Roll: %f, Pitch: %f\n", roll, pitch);
        write_to_file();

        if (abs(roll) > 45 || abs(pitch) > 45) {
            digitalWrite(LED_PIN, HIGH);
        } else {
            digitalWrite(LED_PIN, LOW);
        }

        delay(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>

#define SI1145_ADDRESS 0x60
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "biometric_log.txt"
#define GPIO17 17
#define RETRIES 3
#define RETRY_DELAY 10
#define PROXIMITY_THRESHOLD 100

static int i2c_fd, log_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void close_program() {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(i2c_fd);
    close(log_fd);
    exit(0);
}

void signal_handler(int signum) {
    close_program();
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0666)) < 0) {
        perror("Failed to open log file");
        return 1;
    }

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    if ((line = gpiod_chip_get_line(chip, GPIO17)) == NULL) {
        perror("Failed to get GPIO line");
        return 1;
    }

    gpiod_line_request_output(line, "LED", 0);

    while (1) {
        for (int i = 0; i < RETRIES; i++) {
            uint8_t buffer[4];
            if (write(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
                usleep(RETRY_DELAY * 1000);
                continue;
            }

            if (read(i2c_fd, buffer, sizeof(buffer)) != sizeof(buffer)) {
                usleep(RETRY_DELAY * 1000);
                continue;
            }

            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

            char log_str[50];
            sprintf(log_str, "%s,AmbientLight:%d,Proximity:%d\n", time_str, buffer[0], buffer[1]);
            write(log_fd, log_str, strlen(log_str));

            if (buffer[1] > PROXIMITY_THRESHOLD) {
                gpiod_line_set_value(line, 1);
            } else {
                gpiod_line_set_value(line, 0);
            }

            break;
        }
    }

    close_program();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <bcm2835.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 1
#define SPI_DEVICE "/dev/spidev0.0"
#define FILE_NAME "gyro_data.csv"
#define MAX_RETRIES 3

volatile sig_atomic_t stop = 0;

void signal_handler(int signum) {
    stop = 1;
}

int main() {
    int spi_fd, file_fd, retries = 0;
    struct spi_ioc_transfer spi_msg;
    uint8_t tx[3], rx[3];
    struct timespec ts;
    FILE *file;

    if (!bcm2835_init()) {
        printf("bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        printf("Failed to open SPI device\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        printf("Failed to set SPI mode\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        printf("Failed to set SPI bits per word\n");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        printf("Failed to set SPI speed\n");
        return 1;
    }

    memset(&spi_msg, 0, sizeof(spi_msg));
    spi_msg.tx_buf = (unsigned long)tx;
    spi_msg.rx_buf = (unsigned long)rx;
    spi_msg.len = 3;
    spi_msg.delay_usecs = SPI_DELAY * 1000;

    signal(SIGINT, signal_handler);

    if ((file_fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        printf("Failed to open file\n");
        return 1;
    }

    file = fdopen(file_fd, "w");
    if (!file) {
        printf("Failed to open file stream\n");
        return 1;
    }

    fprintf(file, "Timestamp, X-axis, Y-axis\n");

    while (!stop && retries < MAX_RETRIES) {
        tx[0] = 0x20 | 0x40; // Register address OR'd with read bit
        tx[1] = 0x00; // Dummy byte
        if (write(spi_fd, &spi_msg, 1) < 0) {
            printf("Failed to write to SPI device\n");
            retries++;
            continue;
        }

        if (read(spi_fd, rx, 3) < 0) {
            printf("Failed to read from SPI device\n");
            retries++;
            continue;
        }

        retries = 0;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(file, "%ld.%09ld,%d,%d\n", ts.tv_sec, ts.tv_nsec, (int16_t)((rx[1] << 8) | rx[2]), (int16_t)((rx[1] << 8) | rx[2]));
        usleep(100000); // 10ms delay
    }

    fclose(file);
    close(spi_fd);
    bcm2835_close();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>

#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define ALERT_PIN 17
#define EVENT_DURATION 500 // ms
#define ALERT_DURATION 2000 // ms

static struct gpiod_chip *chip;
static struct gpiod_line *sensor1_line, *sensor2_line, *alert_line;
static FILE *log_file;
static int sensor1_high, sensor2_high;
static struct timespec last_event_time;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fclose(log_file);
        gpiod_line_set_value(alert_line, 0);
        gpiod_chip_close(chip);
        exit(0);
    }
}

static void sensor_callback(struct gpiod_line *line, struct gpiod_line_event event, void *data) {
    int pin = gpiod_line_offset(line);
    int high = gpiod_line_get_value(line);
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    if (pin == SENSOR1_PIN) {
        sensor1_high = high;
    } else if (pin == SENSOR2_PIN) {
        sensor2_high = high;
    }

    if (sensor1_high && sensor2_high) {
        if (now.tv_sec - last_event_time.tv_sec > EVENT_DURATION / 1000) {
            fprintf(log_file, "%ld-%ld - Seismic event detected!\n", now.tv_sec, now.tv_nsec);
            fflush(log_file);
            clock_gettime(CLOCK_REALTIME, &last_event_time);
            gpiod_line_set_value(alert_line, 1);
            usleep(ALERT_DURATION * 1000);
            gpiod_line_set_value(alert_line, 0);
        }
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = &handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Failed to get line for sensor 1\n");
        return -1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Failed to get line for sensor 2\n");
        return -1;
    }

    alert_line = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!alert_line) {
        fprintf(stderr, "Failed to get line for alert\n");
        return -1;
    }

    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Failed to request input for sensor 1\n");
        return -1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Failed to request input for sensor 2\n");
        return -1;
    }

    if (gpiod_line_request_output(alert_line, "alert", 0) < 0) {
        fprintf(stderr, "Failed to request output for alert\n");
        return -1;
    }

    log_file = fopen("seismic_events.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    gpiod_line_event_callback_set(sensor1_line, sensor_callback, NULL);
    gpiod_line_event_callback_set(sensor2_line, sensor_callback, NULL);

    while (1) {
        gpiod_line_event_wait(sensor1_line, NULL);
        gpiod_line_event_wait(sensor2_line, NULL);
    }

    return 0;
}

