}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s <duration>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = atoi(argv[1]);
    if (duration < DURATION_MIN || duration > DURATION_MAX) {
        printf("Duration must be between %d and %d seconds\n", DURATION_MIN, DURATION_MAX);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        printf("pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    printf("Starting smart sunset simulator for %d seconds\n", duration);

    gpioSetPWMfrequency(LAMP1, 100);
    gpioSetPWMfrequency(LAMP2, 100);
    gpioSetPWMfrequency(LAMP3, 100);

    for (int i = 0; i < duration && !stop; i++) {
        for (int duty = 0; duty <= 255 && !stop; duty++) {
            gpioPWM(LAMP1, duty);
            gpioPWM(LAMP2, duty);
