#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define MPR121_ADDRESS 0x5A
#define GPIO_PIN 17
#define DEBOUNCE_TIME 100
#define POLLING_INTERVAL 10

gpiod_chip *chip;
gpiod_line *line;
FILE *log_file;

void cleanup() {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = POLLING_INTERVAL * 1000000L;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen("touch_relay.log", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "touch_relay", 0) < 0) {
        perror("Failed to request GPIO line as output");
        return EXIT_FAILURE;
    }

    while (1) {
        uint8_t touch_status;
        if (i2c_read_reg(I2C_BUS, MPR121_ADDRESS, 0x00, &touch_status) < 0) {
            perror("Failed to read touch status");
            return EXIT_FAILURE;
        }

        if (touch_status & (1 << 0)) {
            nanosleep(&ts, NULL);
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Failed to set GPIO line value");
                return EXIT_FAILURE;
            }
            nanosleep(&ts, NULL);
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Failed to set GPIO line value");
                return EXIT_FAILURE;
            }
        }

        nanosleep(&ts, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

