#define GPIO1 17
#define GPIO2 27
#define DISPENSE_INTERVAL 1000
#define DISPENSE_HALF_INTERVAL (DISPENSE_INTERVAL / 2)

static gpiod_chip *chip;
static gpiod_line *line1, *line2;
static FILE *log_file;

void cleanup() {
    gpiod_line_set_value(line1, 0);
    gpiod_line_set_value(line2, 0);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);
    fclose(log_file);
}

void sigint_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, GPIO1);
    if (!line1) {
        fprintf(stderr, "Failed to get line for GPIO1\n");
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO2);
    if (!line2) {
        fprintf(stderr, "Failed to get line for GPIO2\n");
        return 1;
    }

    if (gpiod_line_request_output(line1, "dispense1", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO1 as output\n");
        return 1;
    }

    if (gpiod_line_request_output(line2, "dispense2", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO2 as output\n");
        return 1;
    }

    log_file = fopen("dispense_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (1) {
        gpiod_line_set_value(line1, 1);
        fprintf(log_file, "Dispense at %ld, GPIO1 high, GPIO2 low, duration %d ms\n", time(NULL), DISPENSE_HALF_INTERVAL);
        usleep(DISPENSE_HALF_INTERVAL * 1000);
        gpiod_line_set_value(line1, 0);

        gpiod_line_set_value(line2, 1);
        fprintf(log_file, "Dispense at %ld, GPIO1 low, GPIO2 high, duration %d ms\n", time(NULL), DISPENSE_HALF_INTERVAL);
        usleep(DISPENSE_HALF_INTERVAL * 1000);
        gpiod_line_set_value(line2, 0);

        usleep((5 - DISPENSE_INTERVAL) * 1000);
    }

    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25

volatile sig_atomic_t stop = 0;

void stop_handler(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    signal(SIGINT, stop_handler);

    FILE *log_file = fopen("balance_log.txt", "w");
    if (!log_file) {
        printf("Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    gpioWrite(ENA, PI_HIGH);
    gpioWrite(ENB, PI_HIGH);

    while (!stop) {
        float tilt_error = ((float) rand() / (RAND_MAX)) * 20.0 - 10.0;
        float distance = ((float) rand() / (RAND_MAX)) * 398.0 + 2.0;

        if (distance < 20.0) {
            gpioPWM(MOTOR_A_FORWARD, 128);
            gpioPWM(MOTOR_A_BACKWARD, 128);
            gpioPWM(MOTOR_B_FORWARD, 128);
            gpioPWM(MOTOR_B_BACKWARD, 128);
        } else {
            gpioPWM(MOTOR_A_FORWARD, 0);
            gpioPWM(MOTOR_A_BACKWARD, 0);
            gpioPWM(MOTOR_B_FORWARD, 0);
            gpioPWM(MOTOR_B_BACKWARD, 0);
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, %f, %f, %d, %d\n", timestamp, tilt_error, distance, 0, 0);

        usleep(50000);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_TIME 50000 // 50ms

static bool running = true;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = false;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;
    struct gpiod_line_event event;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        goto cleanup;
    }

    // Set up lines
    ret = gpiod_line_request_input(sensor_line, "sensor_line");
    if (ret) {
        fprintf(stderr, "Failed to request input for sensor line\n");
        goto cleanup;
    }

    ret = gpiod_line_request_output(relay_line, "relay_line", 0);
    if (ret) {
        fprintf(stderr, "Failed to request output for relay line\n");
        goto cleanup;
    }

    // Main loop
    while (running) {
        ret = gpiod_line_event_wait(sensor_line, &event);
        if (ret) {
            fprintf(stderr, "Failed to wait for event\n");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            usleep(DEBOUNCE_TIME);
            gpiod_line_set_value(relay_line, 1);
            usleep(DEBOUNCE_TIME);
            gpiod_line_set_value(relay_line, 0);
        }
    }

cleanup:
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

