#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 10000

static struct gpiod_chip *chip;
static struct gpiod_line_bulk lines;

static void cleanup(void) {
    gpiod_line_set_value_bulk(lines, GPIO_LOW);
    gpiod_chip_close(chip);
}

static void handle_sigint(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct gpiod_line_bulk lines = {
        .count = 4,
        .offsets = {17, 27, 22, 23}
    };

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_bulk(chip, lines, "sunrise_sunset", GPIO_LINE_REQUEST_DIRECTION_OUTPUT)) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        for (int i = 0; i <= 100; i++) {
            gpiod_line_set_value_bulk(lines, GPIO_LOW);
            usleep(SUNRISE_DURATION * i / 100);
            gpiod_line_set_value_bulk(lines, GPIO_HIGH);
            usleep(SUNRISE_DURATION * (100 - i) / 100);
        }

        for (int i = 0; i <= 100; i++) {
            gpiod_line_set_value_bulk(lines, GPIO_HIGH);
            usleep(DAYTIME_DURATION * i / 100);
            gpiod_line_set_value_bulk(lines, GPIO_LOW);
            usleep(DAYTIME_DURATION * (100 - i) / 100);
        }

        for (int i = 0; i <= 100; i++) {
            gpiod_line_set_value_bulk(lines, GPIO_LOW);
            usleep(SUNSET_DURATION * i / 100);
            gpiod_line_set_value_bulk(lines, GPIO_HIGH);
            usleep(SUNSET_DURATION * (100 - i) / 100);
        }

        for (int i = 0; i <= 100; i++) {
            gpiod_line_set_value_bulk(lines, GPIO_HIGH);
            usleep(NIGHTTIME_DURATION * i / 100);
            gpiod_line_set_value_bulk(lines, GPIO_LOW);
            usleep(NIGHTTIME_DURATION * (100 - i) / 100);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

