        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 0);
            }
            usleep(SUNRISE_DURATION * i / 100);
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 1);
            }
            usleep(SUNRISE_DURATION * (100 - i) / 100);
        }

        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 1);
            }
            usleep(DAYTIME_DURATION * i / 100);
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 0);
            }
            usleep(DAYTIME_DURATION * (100 - i) / 100);
        }

        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 0);
            }
            usleep(SUNSET_DURATION * i / 100);
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 1);
            }
            usleep(SUNSET_DURATION * (100 - i) / 100);
        }

        for (int i = 0; i <= 100; i++) {
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 1);
            }
            usleep(NIGHTTIME_DURATION * i / 100);
            for (int j = 0; j < 4; j++) {
                gpioWrite(gpios[j], 0);
            }
            usleep(NIGHTTIME_DURATION * (100 - i) / 100);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
