#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define RELAY_PIN_1 4
#define RELAY_PIN_2 17
#define RELAY_PIN_3 27
#define RELAY_PIN_4 22

FILE *log_file;

void signal_handler(int signum) {
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_offset(0, 0), RELAY_PIN_1), 1);
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_offset(0, 0), RELAY_PIN_2), 1);
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_offset(0, 0), RELAY_PIN_3), 1);
    gpiod_line_set_value(gpiod_chip_get_line(gpiod_chip_open_by_offset(0, 0), RELAY_PIN_4), 1);
    fclose(log_file);
    gpiod_cleanup();
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int moisture;
    time_t t;

    signal(SIGINT, signal_handler);

    if ((chip = gpiod_chip_open_by_offset(0, 0)) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    if ((line = gpiod_chip_get_line(chip, RELAY_PIN_1)) == NULL) {
        fprintf(stderr, "Failed to get line for GPIO pin %d\n", RELAY_PIN_1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "Greenhouse Irrigation System", 1) != 0) {
        fprintf(stderr, "Failed to request output for GPIO pin %d\n", RELAY_PIN_1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Repeat for other relays...

    log_file = fopen("irrigation_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (1) {
        srand((unsigned int) time(&t));
        moisture = rand() % 100;

        fprintf(log_file, "Moisture: %d\n", moisture);

        if (moisture < 30) {
            gpiod_line_set_value(line, 0);
            fprintf(log_file, "Relay 1: ON\n");
        } else {
            gpiod_line_set_value(line, 1);
            fprintf(log_file, "Relay 1: OFF\n");
        }

        // Repeat for other relays...

        fflush(log_file);
        sleep(5);
    }

    fclose(log_file);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

