#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>
#include <i2c/smbus.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define ALARM_PIN 27
#define LOG_FILE "freefall.log"

int file;
int freefall_count = 0;
int freefall_detected = 0;
time_t start_time, end_time;

void signal_handler(int signum) {
    close(file);
    digitalWrite(ALARM_PIN, LOW);
    exit(signum);
}

int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    int16_t raw_data[3];
    if (i2c_smbus_read_i2c_block_data(file, 0x32, 6, (uint8_t *)raw_data) < 0) {
        fprintf(stderr, "Failed to read from accelerometer\n");
        return -1;
    }
    *x = raw_data[0];
    *y = raw_data[1];
    *z = raw_data[2];
    return 0;
}

int main() {
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Failed to setup wiringPi\n");
        return EXIT_FAILURE;
    }

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open the i2c bus\n");
        return EXIT_FAILURE;
    }

    if (ioctl(file, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    pinMode(ALARM_PIN, OUTPUT);
    digitalWrite(ALARM_PIN, LOW);

    while (1) {
        int16_t x, y, z;
        if (read_accelerometer(&x, &y, &z) < 0) {
            continue;
        }

        if (abs(x) < FREEFALL_THRESHOLD && abs(y) < FREEFALL_THRESHOLD && abs(z) < FREEFALL_THRESHOLD) {
            if (freefall_detected == 0) {
                start_time = time(NULL);
                freefall_detected = 1;
            } else {
                end_time = time(NULL);
                if (difftime(end_time, start_time) > FREEFALL_DURATION) {
                    freefall_count++;
                    FILE *log_file = fopen(LOG_FILE, "a");
                    struct tm *timeinfo = localtime(&start_time);
                    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%0.3f,%0.3f,%0.3f\n",
                            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
                            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
                            (float)x / 256.0, (float)y / 256.0, (float)z / 256.0);
                    fclose(log_file);
                    digitalWrite(ALARM_PIN, HIGH);
                    sleep(5);
                    digitalWrite(ALARM_PIN, LOW);
                    freefall_detected = 0;
                }
            }
        } else {
            freefall_detected = 0;
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <pthread.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define TRIG_INTERVAL 200000000 // 200ms
#define MAX_PULSE_WIDTH 23200 // 23.2ms
#define TIMEOUT 100000000 // 100ms
#define LOG_FILE "distance_log.txt"

static gpiod_chip *chip;
static gpiod_line *trig_line;
static gpiod_line *echo_line;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file;
static uint64_t start_time;
static uint64_t last_trigger_time;

static void handle_sigint(int signum) {
    gpiod_line_event_cb_set(echo_line, NULL, NULL);
    fclose(log_file);
    gpiod_chip_close(chip);
    pthread_mutex_destroy(&mutex);
    exit(signum);
}

static void trig_pulse() {
    pthread_mutex_lock(&mutex);
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);
    pthread_mutex_unlock(&mutex);
}

static void echo_rising_edge(gpiod_line_event event) {
    pthread_mutex_lock(&mutex);
    start_time = gpiod_line_event_timestamp(&event);
    pthread_mutex_unlock(&mutex);
}

static void echo_falling_edge(gpiod_line_event event) {
    pthread_mutex_lock(&mutex);
    uint64_t end_time = gpiod_line_event_timestamp(&event);
    uint64_t pulse_width = end_time - start_time;
    if (pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %llu\n", pulse_width);
        goto out;
    }
    uint64_t current_time = gpiod_chip_get_monotonic_time(chip);
    if (current_time - last_trigger_time > TRIG_INTERVAL) {
        fprintf(stderr, "Sensor timeout\n");
        goto out;
    }
    fprintf(log_file, "%llu,%f\n", current_time, pulse_width / 58.0);
    fflush(log_file);
out:
    pthread_mutex_unlock(&mutex);
}

int main() {
    struct sigaction sigact;
    sigact.sa_handler = handle_sigint;
    sigemptyset(&sigact.sa_mask);
    sigact.sa_flags = 0;
    sigaction(SIGINT, &sigact, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig_line) {
        fprintf(stderr, "Failed to get TRIG line\n");
        return EXIT_FAILURE;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Failed to get ECHO line\n");
        return EXIT_FAILURE;
    }

    gpiod_line_request_output(trig_line, "TRIG", 0);
    gpiod_line_request_input(echo_line, "ECHO");

    gpiod_line_event_cb_set(echo_line, echo_rising_edge, echo_falling_edge);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (1) {
        uint64_t current_time = gpiod_chip_get_monotonic_time(chip);
        if (current_time - last_trigger_time > TRIG_INTERVAL) {
            trig_pulse();
            last_trigger_time = current_time;
        }
        usleep(1000);
    }

    return EXIT_SUCCESS;
}

