}

int main() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, LEFT_PIN);
    lines[1] = gpiod_chip_get_line(chip, CENTER_PIN);
    lines[2] = gpiod_chip_get_line(chip, RIGHT_PIN);

    for (int i = 0; i < 3; i++) {
        if (!gpiod_line_request_input(lines[i], "line_sensor")) {
            fprintf(stderr, "Failed to request line %d\n", i);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    struct gpiod_line_bulk lines_bulk = {
        .count = 3,
        .lines = lines
    };

    if (!gpiod_line_event_enable_bulk(&lines_bulk, GPIOD_LINE_EVENT_BOTH_EDGES)) {
        fprintf(stderr, "Failed to enable events\n");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

