#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define SI7210_ADDRESS 0x3E
#define SI7210_THRESHOLD 5.0
#define GPIO_PIN 17
#define SAMPLE_INTERVAL 0.1
#define RETRY_LIMIT 50

static volatile sig_atomic_t stop;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    int i2c_fd, retry_count;
    uint8_t reg_val;

    /* Set up GPIO */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line, "myprog", 0)) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Set up signal handler */
    signal(SIGINT, sigint_handler);

    /* Set up I2C */
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI7210_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!stop) {
        /* Read register value */
        retry_count = 0;
        do {
            if (read(i2c_fd, &reg_val, 1) < 0) {
                fprintf(stderr, "Failed to read from I2C device\n");
                break;
            }
            retry_count++;
        } while (reg_val != 0 && retry_count < RETRY_LIMIT);

        if (retry_count >= RETRY_LIMIT) {
            fprintf(stderr, "Timeout reading from I2C device\n");
            continue;
        }

        /* Check if threshold exceeded */
        if (reg_val > SI7210_THRESHOLD) {
            /* Set GPIO high */
            if (gpiod_line_set_value(line, 1)) {
                fprintf(stderr, "Failed to set GPIO line high\n");
            }
            /* Log event */
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(stderr, "%04d-%02d-%02d %02d:%02d:%02d - Field exceeded threshold\n",
                    ts.tv_sec / 3600 / 24 + 1970, (ts.tv_sec / 3600) % 24, (ts.tv_sec / 60) % 60,
                    ts.tv_sec % 60);
        } else {
            /* Set GPIO low */
            if (gpiod_line_set_value(line, 0)) {
                fprintf(stderr, "Failed to set GPIO line low\n");
            }
        }

        /* Wait for next sample */
        sleep(SAMPLE_INTERVAL);
    }

    /* Clean up */
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

