#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024

int server_fd, client_fd;
struct gpiod_chip *chip;
struct gpiod_line *line;
FILE *log_file;

void handle_sigint(int signum) {
    gpiod_line_set_value(line, 0);
    gpiod_chip_close(chip);
    close(server_fd);
    fclose(log_file);
    exit(signum);
}

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%d-%m-%Y %I:%M:%S", timeinfo);
    fprintf(log_file, "%s: %s\n", buffer, event);
    fflush(log_file);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    char *command;

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("gpiod_chip_open failed");
        exit(EXIT_FAILURE);
    }

    if ((line = gpiod_chip_get_line(chip, GPIO_PIN)) == NULL) {
        perror("gpiod_chip_get_line failed");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "relay", 0) < 0) {
        perror("gpiod_line_request_output failed");
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen("relay_log.txt", "a")) == NULL) {
        perror("fopen failed");
        exit(EXIT_FAILURE);
    }

    while (1) {
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen)) < 0) {
            perror("accept failed");
            continue;
        }

        if (read(client_fd, buffer, BUFFER_SIZE) < 0) {
            perror("read failed");
            close(client_fd);
            continue;
        }

        command = strtok(buffer, " \n");
        if (strcasecmp(command, "ON") == 0) {
            gpiod_line_set_value(line, 1);
            log_event("Relay turned ON");
        } else if (strcasecmp(command, "OFF") == 0) {
            gpiod_line_set_value(line, 0);
            log_event("Relay turned OFF");
        } else {
            log_event("Invalid command received");
        }

        close(client_fd);
    }

    return 0;
}

