#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_PIN_ENA 22
#define MOTOR_PIN_IN1 23
#define MOTOR_PIN_IN2 24
#define POLL_INTERVAL 200
#define MOTOR_DURATION 5000000
#define RAIN_SENSOR_THRESHOLD 3

static bool running = true;
static int rain_sensor_count = 0;

static void cleanup_and_exit(void) {
    gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_ENA), 0);
    gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_IN1), 0);
    gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_IN2), 0);
    gpiod_chip_close(chip);
    closelog();
    exit(EXIT_SUCCESS);
}

static void handle_signal(int signum) {
    running = false;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct sigaction sa;

    openlog("rain_window", LOG_CONS | LOG_PID | LOG_NDELAY, LOG_USER);
    syslog(LOG_INFO, "Startup");

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    if (!line) {
        syslog(LOG_ERR, "Failed to get line for rain sensor");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_request_input(line, "rain_sensor");
    gpiod_line_set_flags(line, GPIO_LINE_FLAG_PULL_UP);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set signal handler");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        struct gpiod_line_event event;
        int value = gpiod_line_get_value(line);

        if (!value) {
            rain_sensor_count++;
            if (rain_sensor_count >= RAIN_SENSOR_THRESHOLD) {
                gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_ENA), 1);
                gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_IN1), 1);
                gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_IN2), 0);
                usleep(MOTOR_DURATION);
                gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_ENA), 0);
                gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_IN1), 0);
                gpiod_line_set_value(gpiod_chip_get_line(chip, MOTOR_PIN_IN2), 0);
                rain_sensor_count = 0;
            }
        } else {
            rain_sensor_count = 0;
        }

        syslog(LOG_INFO, "Sensor value: %d", value);
        usleep(POLL_INTERVAL * 1000);
    }

    cleanup_and_exit();
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SERVO_PIN 18
#define LOCK_PIN 21
#define UNLOCK_PIN 22
#define DEBOUNCE_TIME 0.2 // in seconds
#define LOCK_PULSE_WIDTH 2000 // in microseconds
#define UNLOCK_PULSE_WIDTH 1000 // in microseconds

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *servo_line, *lock_line, *unlock_line;
    struct timespec debounce_time = {0, DEBOUNCE_TIME * 1e9};

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        fprintf(stderr, "Failed to get servo line\n");
        goto cleanup;
    }

    lock_line = gpiod_chip_get_line(chip, LOCK_PIN);
    if (!lock_line) {
        fprintf(stderr, "Failed to get lock line\n");
        goto cleanup;
    }

    unlock_line = gpiod_chip_get_line(chip, UNLOCK_PIN);
    if (!unlock_line) {
        fprintf(stderr, "Failed to get unlock line\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        fprintf(stderr, "Failed to request output for servo line\n");
        goto cleanup;
    }

    if (gpiod_line_request_input(lock_line, "lock", GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request input for lock line\n");
        goto cleanup;
    }

    if (gpiod_line_request_input(unlock_line, "unlock", GPIO_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request input for unlock line\n");
        goto cleanup;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!stop) {
        if (gpiod_line_get_value(lock_line)) {
            nanosleep(&debounce_time, NULL);
            if (gpiod_line_get_value(lock_line)) {
                printf("Locking...\n");
                if (gpiod_line_set_value(servo_line, 1) < 0 || gpiod_line_set_value(servo_line, 0) < 0) {
                    fprintf(stderr, "Failed to set servo line\n");
                    stop = 1;
                }
                nanosleep(&debounce_time, NULL);
            }
        }

        if (gpiod_line_get_value(unlock_line)) {
            nanosleep(&debounce_time, NULL);
            if (gpiod_line_get_value(unlock_line)) {
                printf("Unlocking...\n");
                if (gpiod_line_set_value(servo_line, 1) < 0 || gpiod_line_set_value(servo_line, 0) < 0) {
                    fprintf(stderr, "Failed to set servo line\n");
                    stop = 1;
                }
                nanosleep(&debounce_time, NULL);
            }
        }
    }

    printf("Stopping servo...\n");
    if (gpiod_line_set_value(servo_line, 1) < 0 || gpiod_line_set_value(servo_line, 0) < 0) {
        fprintf(stderr, "Failed to set servo line\n");
    }

cleanup:
    gpiod_line_release(servo_line);
    gpiod_line_release(lock_line);
    gpiod_line_release(unlock_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define MOTION_SENSOR 4
#define FLOODLIGHT 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL 100
#define FLOODLIGHT_DURATION 60

static volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    FILE *log_file;
    int ret;

    // Initialize GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request line for motion sensor
    line = gpiod_chip_get_line(chip, MOTION_SENSOR);
    if (!line) {
        fprintf(stderr, "Failed to get line for motion sensor\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line for floodlight
    struct gpiod_line *floodlight = gpiod_chip_get_line(chip, FLOODLIGHT);
    if (!floodlight) {
        fprintf(stderr, "Failed to get line for floodlight\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line request flags
    struct gpiod_line_request_config config = {
        .consumer = "motion_sensor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    // Request line for motion sensor
    ret = gpiod_line_request(line, &config, NULL);
    if (ret) {
        fprintf(stderr, "Failed to request line for motion sensor\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line request flags for floodlight
    struct gpiod_line_request_config floodlight_config = {
        .consumer = "floodlight",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT,
    };

    // Request line for floodlight
    ret = gpiod_line_request(floodlight, &floodlight_config, NULL);
    if (ret) {
        fprintf(stderr, "Failed to request line for floodlight\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (!stop) {
        // Poll motion sensor
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            fprintf(stderr, "Failed to get value from motion sensor\n");
            stop = 1;
            break;
        }

        // Check for rising edge
        if (ret == 1) {
            // Turn on floodlight
            ret = gpiod_line_set_value(floodlight, 1);
            if (ret) {
                fprintf(stderr, "Failed to set floodlight ON\n");
                stop = 1;
                break;
            }

            // Log event
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld Floodlight ON\n", ts.tv_sec, ts.tv_nsec);

            // Wait for floodlight duration
            struct timespec sleep_time = {FLOODLIGHT_DURATION, 0};
            nanosleep(&sleep_time, NULL);

            // Turn off floodlight
            ret = gpiod_line_set_value(floodlight, 0);
            if (ret) {
                fprintf(stderr, "Failed to set floodlight OFF\n");
                stop = 1;
                break;
            }

            // Log event
            clock_gettime(CLOCK_REALTIME, &ts);
            fprintf(log_file, "%ld.%09ld Floodlight OFF\n", ts.tv_sec, ts.tv_nsec);
        }

        // Wait for polling interval
        struct timespec sleep_time = {POLL_INTERVAL / 1000, (POLL_INTERVAL % 1000) * 1000000};
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Release resources
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

