#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <time.h>
#include <gpiod.h>
#include <stdarg.h>

#define GPIO_SERVO 17
#define GPIO_PIR 4
#define SERVO_FREQ 50
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define PIR_INTERVAL 2

int sockfd, newsockfd, portno, clilen;
struct sockaddr_in serv_addr, cli_addr;
char buffer[256];
FILE *logfile;

void log_message(int priority, const char *format, ...) {
    va_list args;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(logfile, "[%s] ", buffer);

    va_start(args, format);
    vfprintf(logfile, format, args);
    va_end(args);

    closelog();
}

int main(int argc, char *argv[]) {
    // Initialize GPIO
    struct gpiod_chip *chip;
    struct gpiod_line *line_servo, *line_pir;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_servo = gpiod_chip_get_line(chip, GPIO_SERVO);
    if (!line_servo) {
        log_message(LOG_ERR, "Failed to get servo GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_pir = gpiod_chip_get_line(chip, GPIO_PIR);
    if (!line_pir) {
        log_message(LOG_ERR, "Failed to get PIR GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize TCP server
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        log_message(LOG_ERR, "Failed to open socket\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    bzero((char *)&serv_addr, sizeof(serv_addr));
    portno = 5000;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = INADDR_ANY;
    serv_addr.sin_port = htons(portno);

    if (bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_message(LOG_ERR, "Failed to bind socket\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    listen(sockfd, 5);
    clilen = sizeof(cli_addr);

    // Initialize log file
    logfile = fopen("security.log", "a");
    if (!logfile) {
        log_message(LOG_ERR, "Failed to open log file\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        newsockfd = accept(sockfd, (struct sockaddr *)&cli_addr, &clilen);
        if (newsockfd < 0) {
            log_message(LOG_ERR, "Failed to accept connection\n");
            continue;
        }

        bzero(buffer, 256);
        read(newsockfd, buffer, 255);

        if (strncmp(buffer, "the library's API call", 24) == 0) {
            int angle = atoi(buffer + 25);
            if (angle < 0 || angle > 180) {
                log_message(LOG_ERR, "Invalid angle: %d\n", angle);
                continue;
            }

            int pulse_width = SERVO_MIN + (SERVO_MAX - SERVO_MIN) * angle / 180;
            ret = gpiod_line_request_output(line_servo, "servo", 0);
            if (ret < 0) {
                log_message(LOG_ERR, "Failed to request servo GPIO line\n");
                continue;
            }

            ret = gpiod_line_set_value(line_servo, 1);
            if (ret < 0) {
                log_message(LOG_ERR, "Failed to set servo GPIO line\n");
                continue;
            }

            usleep(pulse_width * 1000);
            ret = gpiod_line_set_value(line_servo, 0);
            if (ret < 0) {
                log_message(LOG_ERR, "Failed to set servo GPIO line\n");
                continue;
            }

            usleep((1000000 / SERVO_FREQ - pulse_width) * 1000);
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int value;
            ret = gpiod_line_request_input(line_pir, "pir");
            if (ret < 0) {
                log_message(LOG_ERR, "Failed to request PIR GPIO line\n");
                continue;
            }

            value = gpiod_line_get_value(line_pir);
            if (value < 0) {
                log_message(LOG_ERR, "Failed to get PIR GPIO line\n");
                continue;
            }

            sprintf(buffer, "PIR:%d\n", value);
            write(newsockfd, buffer, strlen(buffer));
        } else {
            log_message(LOG_ERR, "Unknown command: %s\n", buffer);
        }

        close(newsockfd);
    }

    // Cleanup
    fclose(logfile);
    gpiod_line_release(line_servo);
    gpiod_line_release(line_pir);
    gpiod_chip_close(chip);
    close(sockfd);

    return EXIT_SUCCESS;
}

#include <stdio.h>
