    unsigned int duration = POLL_INTERVAL;
    struct timespec ts = {0, 0};

    openlog("weight_monitor", LOG_PID, LOG_USER);

    if (argc > 1) {
        for (i = 1; i < argc; i++) {
            if (strcmp(argv[i], "--scale") == 0) {
