#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define DEBOUNCE_TIME 50 // ms
#define SLEEP_TIME 10 // ms

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_touch, *line_relay;
    struct timespec ts;
    int touch_state, relay_state;
    int ret;

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Request lines
    line_touch = gpiod_chip_get_line(chip, GPIO_TOUCH);
    line_relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line_touch || !line_relay) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        ret = EXIT_FAILURE;
        goto cleanup;
    }

    // Set lines as inputs and outputs
    ret = gpiod_line_request_input(line_touch, "touch_sensor");
    ret |= gpiod_line_request_output(line_relay, "relay", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO lines\n");
        goto cleanup;
    }

    // Initialize states
    touch_state = 0;
    relay_state = 0;

    // Main loop
    while (!stop) {
        // Read touch sensor
        ret = gpiod_line_get_value(line_touch);
        if (ret < 0) {
            fprintf(stderr, "Failed to read touch sensor\n");
            goto cleanup;
        }

        // Debounce stabilization
        if (ret == touch_state) {
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_nsec += DEBOUNCE_TIME * 1000000;
            nanosleep(&ts, NULL);
            ret = gpiod_line_get_value(line_touch);
            if (ret < 0) {
                fprintf(stderr, "Failed to read touch sensor\n");
                goto cleanup;
            }
        }

        // Toggle relay state on valid touch detection
        if (ret != touch_state) {
            touch_state = ret;
            if (touch_state == 1) {
                relay_state = !relay_state;
                ret = gpiod_line_set_value(line_relay, relay_state);
                if (ret) {
                    fprintf(stderr, "Failed to set relay state\n");
                    goto cleanup;
                }
                printf("%ld.%09ld: Relay is now %s\n", ts.tv_sec, ts.tv_nsec, relay_state ? "ON" : "OFF");
            }
        }

        // Sleep before next iteration
        clock_nanosleep(CLOCK_REALTIME, 0, &(struct timespec){0, SLEEP_TIME * 1000000}, NULL);
    }

    printf("Exiting program\n");

cleanup:
    gpiod_line_release(line_touch);
    gpiod_line_release(line_relay);
    gpiod_chip_close(chip);
    return ret ? EXIT_FAILURE : EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>
#include <libgpiod.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define FLOW_SENSOR_DEBOUNCE_TIMEOUT 1
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5

pthread_mutex_t flow_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;
int flow_count = 0;
int solenoid_state = 1;

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", 
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, 
            t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

void handle_signal(int signum) {
    log_event("Received signal, shutting down.");
    gpiod_set_value(SOLENOID_PIN, 1);
    fclose(log_file);
    pthread_mutex_destroy(&flow_mutex);
    gpiod_cleanup();
    exit(0);
}

void* flow_sensor_thread(void* arg) {
    while (1) {
        pthread_mutex_lock(&flow_mutex);
        int new_count = gpiod_get_value(FLOW_SENSOR_PIN);
        if (new_count > flow_count) {
            flow_count = new_count;
            log_event("Flow sensor triggered.");
        }
        pthread_mutex_unlock(&flow_mutex);
        sleep(1);
    }
    return NULL;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen("water_flow.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip.\n");
        return 1;
    }

    gpiod_line_request req = {
        .consumer = "water_flow",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP,
    };

    gpiod_line *line = gpiod_chip_get_line(chip, FLOW_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line for flow sensor.\n");
        return 1;
    }

    if (gpiod_line_request(line, &req, FLOW_SENSOR_DEBOUNCE_TIMEOUT) < 0) {
        fprintf(stderr, "Failed to request line for flow sensor.\n");
        return 1;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, flow_sensor_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create flow sensor thread.\n");
        return 1;
    }

    while (1) {
        pthread_mutex_lock(&flow_mutex);
        float flow_rate = flow_count / 7.5; // Assuming 7.5 pulses per liter
        if (flow_rate > FLOW_THRESHOLD_HIGH) {
            if (solenoid_state) {
                gpiod_set_value(SOLENOID_PIN, 0);
                log_event("Solenoid valve closed.");
                solenoid_state = 0;
            }
        } else if (flow_rate < FLOW_THRESHOLD_LOW && !solenoid_state) {
            gpiod_set_value(SOLENOID_PIN, 1);
            log_event("Solenoid valve opened.");
            solenoid_state = 1;
        }
        pthread_mutex_unlock(&flow_mutex);
        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>
#include <libconfig.h>
#include <gpiod.h>
#include <pigpio.h>

#define DATA_PIN 23
#define SCK_PIN 24
#define SERVO_PIN 18
#define LOAD_CELL_OFFSET 0
#define LOAD_CELL_SCALE 1.0
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define SOCKET_PORT 12345
#define SOCKET_ADDRESS "127.0.0.1"
#define TIMEOUT_ATTEMPTS 1000
#define SERVO_MIN_PULSEWIDTH 1000
#define SERVO_MAX_PULSEWIDTH 2000
#define LOG_FILE "dispensing_log.json"

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *sck_line;
    struct pigpio_i2c i2c;
    struct sockaddr_in server_addr;
    int sock, bytes_received, target_weight, actual_weight;
    float calibration_factor;
    config_t cfg;
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[256], log_entry[512];

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    sck_line = gpiod_chip_get_line(chip, SCK_PIN);

    // Initialize I2C
    gpio_i2c_open(&i2c, 1, 0x68);

    // Initialize socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SOCKET_PORT);
    server_addr.sin_addr.s_addr = inet_addr(SOCKET_ADDRESS);
    connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr));

    // Initialize config
    config_init(&cfg);

    // Load calibration factor
    if (!config_lookup_float(&cfg, "calibration_factor", &calibration_factor)) {
        calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }

    // Main loop
    while (1) {
        // Receive target weight
        bytes_received = recv(sock, buffer, sizeof(buffer), 0);
        target_weight = atoi(buffer);

        // Dispense ingredient
        gpio_i2c_write(&i2c, 0x00, target_weight / calibration_factor);

        // Wait for load cell to stabilize
        sleep(1);

        // Read actual weight
        actual_weight = gpio_i2c_read(&i2c, 0x00);

        // Map target weight to pulse width
        int pulse_width = (int)((float)target_weight / calibration_factor * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH) + SERVO_MIN_PULSEWIDTH);

        // Send actual weight back to client
        sprintf(buffer, "%d", actual_weight);
        send(sock, buffer, strlen(buffer), 0);

        // Append to log
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(log_entry, sizeof(log_entry), "{\"date\":\"%Y-%m-%d\",\"time\":\"%H:%M:%S\",\"target_weight\":%d,\"actual_weight\":%d,\"error\":\"%s\"}\n", timeinfo, target_weight, actual_weight, "");
        FILE *log_file = fopen(LOG_FILE, "a");
        fwrite(log_entry, strlen(log_entry), 1, log_file);
        fclose(log_file);
    }

    // Clean up
    config_destroy(&cfg);
    gpio_i2c_close(&i2c);
    gpiod_line_release(data_line);
    gpiod_line_release(sck_line);
    gpiod_chip_close(chip);
    close(sock);

    return 0;
}

