    int last_sensor_state = 0;

    while (!stop) {
        int sensor_state = gpioRead(SENSOR_PIN);
        if (sensor_state == 1 && last_sensor_state == 0) {
            relay_state = !relay_state;
            gpioWrite(RELAY_PIN, relay_state);
            char *state_str = relay_state ? "ON" : "OFF";
            char time_str[20];
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
            printf("%s Relay: %s\n", time_str, state_str);
        }
        last_sensor_state = sensor_state;
        nanosleep(&ts, NULL);
        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += debounce_interval * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
