#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_FREQ 50
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define ANGLE_MIN 0
#define ANGLE_MAX 180
#define ANGLE_STEP 10

int main() {
    int angle = 90;
    int width;
    struct termios oldt, newt;
    char c;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ) < 0) {
        fprintf(stderr, "failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(SERVO_PIN, SERVO_MAX - SERVO_MIN) < 0) {
        fprintf(stderr, "failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);

    printf("Servo control\n");
    printf("Press '+' to increase angle, '-' to decrease angle\n");
    printf("Press 'q' to quit\n");

    while (1) {
        c = getchar();

        if (c == '+') {
            angle = (angle + ANGLE_STEP > ANGLE_MAX) ? ANGLE_MAX : angle + ANGLE_STEP;
        } else if (c == '-') {
            angle = (angle - ANGLE_STEP < ANGLE_MIN) ? ANGLE_MIN : angle - ANGLE_STEP;
        } else if (c == 'q') {
            break;
        }

        width = SERVO_MIN + (SERVO_MAX - SERVO_MIN) * angle / ANGLE_MAX;
        if (gpioPWM(SERVO_PIN, width) < 0) {
            fprintf(stderr, "failed to set PWM\n");
            break;
        }

        printf("Current angle: %d\n", angle);
    }

    gpioPWM(SERVO_PIN, 0);
    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000
#define SAMPLE_INTERVAL 5000000
#define LOG_FILE "motor_rpm.log"

static gpiod_chip *chip;
static gpiod_line *line;
static FILE *log_file;
static int running = 1;
static uint64_t last_time = 0;
static uint64_t pulse_count = 0;

void signal_handler(int signum) {
    running = 0;
}

void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    struct sigaction action;
    struct timespec ts;
    uint64_t current_time, rpm;

    action.sa_handler = signal_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    atexit(cleanup);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "belt_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to enable internal pull-up bias\n");
        return EXIT_FAILURE;
    }

    if (gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE, DEBOUNCE_TIME) < 0) {
        fprintf(stderr, "Failed to set up event detection\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpiod_line_event_read(line, &ts) < 0) {
            fprintf(stderr, "Failed to read event\n");
            return EXIT_FAILURE;
        }

        current_time = ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        pulse_count++;

        if (current_time - last_time >= SAMPLE_INTERVAL) {
            rpm = (pulse_count * 1000000) / (current_time - last_time) / 2;
            fprintf(log_file, "%s,%.2f\n", ctime(&ts.tv_sec), rpm / 100.0);
            fflush(log_file);
            printf("Motor RPM: %.2f\n", rpm / 100.0);
            last_time = current_time;
            pulse_count = 0;
        }
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
