#define GPIO_TOUCH 4
#define GPIO_RELAY 17
#define POLLING_INTERVAL 50
#define LONG_PRESS_TIME 10000

volatile sig_atomic_t stop;

void signal_handler(int signum) {
    stop = true;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line_touch, *line_relay;
    struct timespec ts;
    int value, relay_state = 0;
    bool long_press = false;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    line_touch = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!line_touch) {
        fprintf(stderr, "Failed to get line for touch sensor\n");
        goto cleanup;
    }

    line_relay = gpiod_chip_get_line(chip, GPIO_RELAY);
    if (!line_relay) {
        fprintf(stderr, "Failed to get line for relay\n");
        goto cleanup;
    }

    if (gpiod_line_request_input(line_touch, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request input for touch sensor\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(line_relay, "relay", 0) < 0) {
        fprintf(stderr, "Failed to request output for relay\n");
        goto cleanup;
    }

    while (!stop) {
        value = gpiod_line_get_value(line_touch);
        if (value < 0) {
            fprintf(stderr, "Failed to get value for touch sensor\n");
            goto cleanup;
        }

        if (value == 1 && !long_press) {
            relay_state = !relay_state;
            gpiod_line_set_value(line_relay, relay_state);
            clock_gettime(CLOCK_REALTIME, &ts);
            ts.tv_sec += LONG_PRESS_TIME / 1000;
            ts.tv_nsec += (LONG_PRESS_TIME % 1000) * 1000000;
            if (nanosleep(&ts, NULL) < 0) {
                fprintf(stderr, "Failed to sleep\n");
                goto cleanup;
            }
            long_press = true;
        } else if (value == 0) {
            long_press = false;
        }

        nanosleep(&(struct timespec){0, POLLING_INTERVAL * 1000000}, NULL);
    }

cleanup:
    gpiod_line_release(line_touch);
    gpiod_line_release(line_relay);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

