static int i2c_write_byte(uint8_t reg, uint8_t data) {
    uint8_t buffer[2] = {reg, data};
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

static int i2c_read_byte(uint8_t reg, uint8_t *data) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }
    if (read(i2c_fd, data, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

static int mpr121_init(void) {
    if (i2c_write_byte(MPR121_ELECTRODE_CONFIGURATION, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_ELECTRODE_CURRENT, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_FILTER_CONFIGURATION, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_CHARGE_TIME_CONFIGURATION, 0x00) < 0) {
        return -1;
    }
