        return -1;
    }
    if (i2c_write_byte(MPR121_NHD_R, 0x01) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_NCL_R, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_FDL_R, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_MHD_F, 0x01) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_NHD_F, 0x01) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_NCL_F, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_FDL_F, 0x00) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_ELECTRODE_TOUCH_THRESHOLD, 0x0A) < 0) {
        return -1;
    }
    if (i2c_write_byte(MPR121_ELECTRODE_RELEASE_THRESHOLD, 0x0A) < 0) {
        return -1;
    }
    usleep(100000); // 100ms delay
    if (i2c_write_byte(MPR121_ELECTRODE_CONFIGURATION, 0x8F) < 0) {
        return -1;
    }
    return 0;
}

