#define PIR_PIN 17
#define RELAY_PIN 18
#define LOG_FILE "door_events.log"
#define MOTION_DETECTED "Motion detected at %ld ms\n"
#define DOOR_UNLOCKED "Door unlocked at %ld ms\n"
#define RATE_LIMITED "Rate limited at %ld ms\n"

static bool running = true;
static struct timespec last_motion_time;

static void cleanup() {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fclose(log_file);
    }
    gpiod_ctxless_close();
}

static void handle_sigint(int signum) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *pir_line, *relay_line;
    struct timespec current_time;
    long elapsed_ms;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    atexit(cleanup);

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR line\n");
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "PIR") ||
        gpiod_line_request_output(relay_line, "Relay", 0)) {
        fprintf(stderr, "Failed to request line\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    while (running) {
        if (gpiod_line_get_value(pir_line)) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            elapsed_ms = current_time.tv_sec * 1000 + current_time.tv_nsec / 1e6;
            fprintf(log_file, MOTION_DETECTED, elapsed_ms);

            if (clock_gettime(CLOCK_MONOTONIC, &last_motion_time) == 0) {
                elapsed_ms = (current_time.tv_sec - last_motion_time.tv_sec) * 1000 +
                              (current_time.tv_nsec - last_motion_time.tv_nsec) / 1e6;
                if (elapsed_ms < 2000) {
                    fprintf(log_file, RATE_LIMITED, elapsed_ms);
                    continue;
                }
            }

            gpiod_line_set_value(relay_line, 1);
            fprintf(log_file, DOOR_UNLOCKED, elapsed_ms);

            usleep(500000);

            gpiod_line_set_value(relay_line, 0);
            clock_gettime(CLOCK_MONOTONIC, &last_motion_time);
        }
    }

    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

