#include <libgpiod.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_INTERVAL 500 // ms
#define READ_TIMEOUT 500 // us

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip;
static struct gpiod_line *hx711_data_line;
static struct gpiod_line *hx711_clock_line;
static struct gpiod_line *solenoid_line;
static float scale_factor = 1.0;
static float offset = 0.0;
static float threshold = 10.0; // kg

void cleanup() {
    gpiod_line_set_value(solenoid_line, 0);
    gpiod_line_release(hx711_data_line);
    gpiod_line_release(hx711_clock_line);
    gpiod_chip_close(chip);
    fclose(fopen(LOG_FILE, "w"));
}

void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct sigaction action;
    action.sa_handler = sigint_handler;
    sigemptyset(&action.sa_mask);
    action.sa_flags = 0;
    sigaction(SIGINT, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    hx711_data_line = gpiod_chip_get_line(chip, HX711_DATA_PIN);
    if (!hx711_data_line) {
        fprintf(stderr, "Failed to get HX711 data line\n");
        goto cleanup;
    }

    hx711_clock_line = gpiod_chip_get_line(chip, HX711_CLOCK_PIN);
    if (!hx711_clock_line) {
        fprintf(stderr, "Failed to get HX711 clock line\n");
        goto cleanup;
    }

    solenoid_line = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!solenoid_line) {
        fprintf(stderr, "Failed to get solenoid line\n");
        goto cleanup;
    }

    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file) {
        fscanf(calibration_file, "%f %f", &scale_factor, &offset);
        fclose(calibration_file);
    }

    gpiod_line_request_input(hx711_data_line, "hx711_data");
    gpiod_line_request_output(hx711_clock_line, "hx711_clock", 0);
    gpiod_line_request_output(solenoid_line, "solenoid", 0);

    struct timespec sleep_time = {0, READ_INTERVAL * 1000 * 1000};
    struct timespec timeout = {0, READ_TIMEOUT * 1000};
    clockid_t clk_id;
    clock_gettime(CLOCK_REALTIME, &clk_id);

    while (running) {
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_REALTIME, &start_time);

        gpiod_line_set_value(hx711_clock_line, 1);
        nanosleep(&timeout, NULL);
        gpiod_line_set_value(hx711_clock_line, 0);
        nanosleep(&timeout, NULL);

        int data = gpiod_line_get_value(hx711_data_line);
        float weight = (data - offset) * scale_factor;

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            struct timespec current_time;
            clock_gettime(CLOCK_REALTIME, &current_time);
            fprintf(log_file, "%ld.%09ld %f\n", current_time.tv_sec, current_time.tv_nsec, weight);
            fclose(log_file);
        }

        if (weight > threshold) {
            gpiod_line_set_value(solenoid_line, 1);
        } else {
            gpiod_line_set_value(solenoid_line, 0);
        }

        clock_gettime(CLOCK_REALTIME, &end_time);
        if ((end_time.tv_sec - start_time.tv_sec) * 1000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000000 < READ_INTERVAL) {
            nanosleep(&sleep_time, NULL);
        }
    }

cleanup:
    cleanup();
    return EXIT_SUCCESS;
}

