#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/time.h>
#include <libgpiod.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define DOOR_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define TIMEOUT 100 // ms
#define THRESHOLD 5000 // micrograms

static volatile sig_atomic_t stop = false;

void sigint_handler(int signum) {
    stop = true;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *door_line;
    int fd_cal, fd_log;
    int32_t calibration_factor = 0;
    int32_t weight = 0;
    struct timeval start, end;
    double elapsed;

    // Setup GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    door_line = gpiod_chip_get_line(chip, DOOR_PIN);

    gpiod_line_request_input(data_line, "HX711 data line");
    gpiod_line_request_output(clock_line, "HX711 clock line");
    gpiod_line_request_output(door_line, "Door lock line");

    // Setup signal handler
    signal(SIGINT, sigint_handler);

    // Calibration
    fd_cal = open(CALIBRATION_FILE, O_RDONLY);
    if (fd_cal < 0) {
        fprintf(stderr, "Failed to open calibration file\n");
        return EXIT_FAILURE;
    }

    if (read(fd_cal, &calibration_factor, sizeof(calibration_factor)) != sizeof(calibration_factor)) {
        fprintf(stderr, "Failed to read calibration factor\n");
        return EXIT_FAILURE;
    }

    close(fd_cal);

    // Log file
    fd_log = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0666);
    if (fd_log < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop) {
        // Request a reading from the HX711
        gpiod_line_set_value(clock_line, 0);
        usleep(1);
        gpiod_line_set_value(clock_line, 1);
        usleep(1);

        // Read the 24-bit value
        weight = 0;
        for (int i = 0; i < 24; i++) {
            gpiod_line_set_value(clock_line, 0);
            usleep(1);
            gpiod_line_set_value(clock_line, 1);
            usleep(1);

            weight <<= 1;
            weight |= gpiod_line_get_value(data_line);
        }

        // Apply calibration factor
        weight = (weight - 8388608) * calibration_factor;

        // Check if weight exceeds threshold
        if (weight > THRESHOLD) {
            gettimeofday(&start, NULL);

            // Lock door
            gpiod_line_set_value(door_line, 1);
            usleep(5000000);

            // Unlock door
            gpiod_line_set_value(door_line, 0);

            gettimeofday(&end, NULL);
            elapsed = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;

            // Log to file
            char buffer[256];
            sprintf(buffer, "%ld.%06ld %d\n", start.tv_sec, start.tv_usec, weight);
            write(fd_log, buffer, strlen(buffer));

            // Wait for door to close
            while (elapsed < 5.0) {
                gettimeofday(&end, NULL);
                elapsed = (end.tv_sec - start.tv_sec) + (end.tv_usec - start.tv_usec) / 1000000.0;
            }
        }
    }

    // Cleanup
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(door_line);
    gpiod_chip_close(chip);
    close(fd_log);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static gpiod_chip *chip;
static gpiod_line *sensor_line;
static gpiod_line *relay_line;
static FILE *log_file;

void cleanup_and_exit(int status) {
    if (sensor_line) gpiod_line_release(sensor_line);
    if (relay_line) gpiod_line_release(relay_line);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
    exit(status);
}

void log_event(const char *state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%FT%T%z", t);
    fprintf(log_file, "%s: %s\n", timestamp, state);
    fflush(log_file);
}

void handle_signal(int signum) {
    cleanup_and_exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = handle_signal;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Failed to get sensor line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Failed to get relay line\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_and_exit(EXIT_FAILURE);
    }

    gpiod_line_request_input(sensor_line, "sensor");
    gpiod_line_request_output(relay_line, "relay", 0);

    int last_state = 1;
    while (1) {
        int state = gpiod_line_get_value(sensor_line);
        if (state != last_state) {
            last_state = state;
            int relay_state = !state;
            gpiod_line_set_value(relay_line, relay_state);
            log_event(relay_state ? "Relay ON" : "Relay OFF");
        }
    }

    cleanup_and_exit(EXIT_SUCCESS);
}

#include <stdio.h>
