#define PIR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "motion_log.txt"

static gpiod_chip *chip;
static gpiod_line *pir_line;
static gpiod_line *buzzer_line;
static FILE *log_file;

void cleanup() {
    gpiod_line_set_value(buzzer_line, 0);
    fclose(log_file);
    gpiod_line_release(pir_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(struct sigaction));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        fprintf(stderr, "Failed to get PIR line\n");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get buzzer line\n");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    gpiod_line_request_input(pir_line, "PIR sensor");
    gpiod_line_request_output(buzzer_line, "Buzzer");

    while (1) {
        int value = gpiod_line_get_value(pir_line);
        if (value) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s\n", timestamp);

            gpiod_line_set_value(buzzer_line, 1);
            usleep(2000000);
            gpiod_line_set_value(buzzer_line, 0);
        }
    }

cleanup:
    cleanup();
    return EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t stop = 0;

void sig_handler(int signum) {
    stop = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    FILE *file;
    char buffer[256];
    unsigned int duration;
    int ret;

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Open GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set up GPIO line
    ret = gpiod_line_request_output(line, "watering", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line as output\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Read duration from config file
    file = fopen(CONFIG_FILE, "r");
    if (!file) {
        fprintf(stderr, "Failed to open config file\n");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    if (fgets(buffer, sizeof(buffer), file) == NULL || sscanf(buffer, "duration=%u", &duration) != 1 || duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in config file\n");
        fclose(file);
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    fclose(file);

    // Activate valve
    gpiod_line_set_value(line, 1);
    printf("Valve on\n");

    // Wait for duration
    while (duration > 0 && !stop) {
        sleep(1);
        duration--;
    }

    // Deactivate valve
    gpiod_line_set_value(line, 0);
    printf("Valve off\n");

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

