#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>

#define BH1750_ADDRESS 0x23
#define BH1750_POWER_DOWN 0x00
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_I2C_BUS "/dev/i2c-1"
#define RELAY_PIN 23
#define LOG_FILE "grow_log.txt"

int i2c_fd;
FILE *log_fd;

void cleanup(int signum) {
    close(i2c_fd);
    digitalWrite(RELAY_PIN, LOW);
    fclose(log_fd);
    exit(signum);
}

int main() {
    if ((i2c_fd = open(BH1750_I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Unable to setup wiringPi: %s\n", strerror(errno));
        return 1;
    }

    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW);

    signal(SIGINT, cleanup);

    log_fd = fopen(LOG_FILE, "w");
    if (!log_fd) {
        perror("Failed to open log file");
        return 1;
    }

    uint16_t lux;
    while (1) {
        uint8_t buffer[2];
        buffer[0] = BH1750_POWER_ON;
        buffer[1] = BH1750_CONTINUOUS_HIGH_RES_MODE;
        if (write(i2c_fd, buffer, 2) != 2) {
            perror("Failed to write to BH1750");
            continue;
        }

        delay(180);

        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from BH1750");
            continue;
        }

        lux = (buffer[0] << 8) | buffer[1];

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_fd, "%s: %d lux\n", timestamp, lux);

        if (lux < 150) {
            if (digitalRead(RELAY_PIN) == LOW) {
                digitalWrite(RELAY_PIN, HIGH);
                fprintf(log_fd, "%s: Relay turned ON\n", timestamp);
            }
        } else {
            if (digitalRead(RELAY_PIN) == HIGH) {
                digitalWrite(RELAY_PIN, LOW);
                fprintf(log_fd, "%s: Relay turned OFF\n", timestamp);
            }
        }
    }

    return 0;
}

