        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_LOCK_PIN, PI_PUD_UP) < 0) {
        printf("Failed to set pull-up for BUTTON_LOCK_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(BUTTON_UNLOCK_PIN, PI_PUD_UP) < 0) {
