#include <czmq.h>

static zsock_t *pub_sock = NULL;
static zsock_t *sub_sock = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

static void cleanup() {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (sub_sock) {
        zsock_destroy(&sub_sock);
    }
    if (pub_sock) {
        zsock_destroy(&pub_sock);
    }
}

static void handle_signal(int signum) {
    cleanup();
    exit(signum);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *mode = argv[1];
    if (strcmp(mode, "sound_sensor") == 0) {
        // Sound sensor mode
        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }

        line = gpiod_chip_get_line(chip, 17);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line\n");
            return EXIT_FAILURE;
        }

        gpiod_line_request_input(line, "sound_sensor");

        pub_sock = zsock_new_pub("tcp://*:5555");
        if (!pub_sock) {
            fprintf(stderr, "Failed to create publisher socket\n");
            return EXIT_FAILURE;
        }

        signal(SIGINT, handle_signal);
        signal(SIGTERM, handle_signal);

        while (true) {
            struct gpiod_line_event event;
            gpiod_line_event_read(line, &event);
            if (event.level == 0) {
                zmsg_t *msg = zmsg_new();
                zmsg_addstr(msg, "SOUND_ALERT");
                zmsg_send(&msg, pub_sock);
            }
            usleep(10000);
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        // Alarm node mode
        sub_sock = zsock_new_sub("tcp://localhost:5555", "SOUND_ALERTS");
        if (!sub_sock) {
            fprintf(stderr, "Failed to create subscriber socket\n");
            return EXIT_FAILURE;
        }

        chip = gpiod_chip_open_by_name("gpiochip0");
        if (!chip) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            return EXIT_FAILURE;
        }

        line = gpiod_chip_get_line(chip, 27);
        if (!line) {
            fprintf(stderr, "Failed to get GPIO line\n");
            return EXIT_FAILURE;
        }

        gpiod_line_request_output(line, "alarm_node", 0);

        signal(SIGINT, handle_signal);
        signal(SIGTERM, handle_signal);

        while (true) {
            zmsg_t *msg = zmsg_recv(sub_sock);
            if (msg) {
                gpiod_line_set_value(line, 1);
                usleep(1000000);
                gpiod_line_set_value(line, 0);
                zmsg_destroy(&msg);
            }
        }
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

