```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BH1750FVI_ADDRESS 0x23
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDRESS "239.255.255.250"
#define MULTICAST_PORT 5005

volatile sig_atomic_t terminate = 0;

void signal_handler(int signum) {
    terminate = 1;
}

int main() {
    int i2c_fd, udp_fd;
    struct i2c_rdwr_ioctl_data packets;
    struct i2c_msg messages[2];
    struct sockaddr_in multicast_addr;
    uint8_t buffer[2];
    uint16_t lux_values[4] = {0};

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set up UDP socket
    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDRESS);
    multicast_addr.sin_port = htons(MULTICAST_PORT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 4; i++) {
            // Set I2C address
            if (ioctl(i2c_fd, I2C_SLAVE, BH1750FVI_ADDRESS + i) < 0) {
                perror("Failed to set I2C address");
                continue;
            }

            // Send start conversion command
            buffer[0] = 0x20;
            buffer[1] = 0x00;
            messages[0].addr = BH1750FVI_ADDRESS + i;
            messages[0].flags = 0;
            messages[0].len = 2;
            messages[0].buf = buffer;

            // Read data
            messages[1].addr = BH1750FVI_ADDRESS + i;
            messages[1].flags = I2C_M_RD;
            messages[1].len = 2;
            messages[1].buf = buffer;

            packets.msgs = messages;
            packets.nmsgs = 2;

            if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
                perror("Failed to read from I2C bus");
                lux_values[i] = NAN;
                continue;
            }

            // Convert data to lux
            lux_values[i] = (buffer[0] << 8) | buffer[1];
            usleep(180000); // Wait 180ms
        }

        // Broadcast UDP packet
        char packet[256];
        sprintf(packet, "1,%f;2,%f;3,%f;4,%f", lux_values[0], lux_values[1], lux_values[2], lux_values[3]);
        if (sendto(udp_fd, packet, strlen(packet), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        sleep(1); // Wait 1 second
    }

    // Clean up
    close(i2c_fd);
    close(udp_fd);

    return EXIT_SUCCESS;
}
