#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define RETRIES 3
#define RETRY_DELAY 100000 /* 100ms */

static int i2c_fd;
static FILE *log_fd;

void sigint_handler(int signum) {
    close(i2c_fd);
    fclose(log_fd);
    exit(signum);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    uint8_t buffer[2];
    uint16_t flow;
    struct timespec ts;
    int ret, retry_count;

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    /* Set up signal handler */
    signal(SIGINT, sigint_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open("/dev/gpio");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Get I2C SCL line */
    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get I2C SCL line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Set I2C SCL line to output */
    ret = gpiod_line_request_output(line, "i2c-scl", 0);
    if (ret < 0) {
        perror("Failed to set I2C SCL line to output");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Get I2C SDA line */
    line = gpiod_chip_get_line(chip, 5);
    if (!line) {
        perror("Failed to get I2C SDA line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Set I2C SDA line to output */
    ret = gpiod_line_request_output(line, "i2c-sda", 0);
    if (ret < 0) {
        perror("Failed to set I2C SDA line to output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_fd = fopen(LOG_FILE, "a");
    if (!log_fd) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        /* Generate start condition */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set I2C SDA line to high");
            break;
        }
        usleep(1000);
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set I2C SDA line to low");
            break;
        }
        usleep(1000);

        /* Read two bytes from sensor */
        retry_count = 0;
        while (retry_count < RETRIES) {
            ret = read(i2c_fd, buffer, sizeof(buffer));
            if (ret == sizeof(buffer)) {
                break;
            } else if (ret < 0 && (errno == ENXIO || errno == EIO)) {
                retry_count++;
                usleep(RETRY_DELAY);
            } else {
                perror("Failed to read from sensor");
                break;
            }
        }

        if (ret < 0) {
            break;
        }

        /* Mask and convert flow value */
        flow = (buffer[0] << 8) | buffer[1];
        flow &= 0x3FFF;
        flow = (flow * 100) / 16384;

        /* Log timestamped flow rate */
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_fd, "%ld.%09ld: %d SLPM\n", ts.tv_sec, ts.tv_nsec, flow);

        /* Wait for 1 second */
        sleep(1);
    }

    /* Clean up */
    fclose(log_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

