#include <time.h>

#define AS7341_ADDRESS 0x39
#define SENSORS_NUM 10

int main() {
    int file;
    char *filename = "/dev/i2c-1";
    char buf[10];
    int res;
    int lux;
    struct timespec ts;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, AS7341_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(1);
    }

    while (1) {
        // Write to the device
        buf[0] = 0x00; // PON bit
        if (write(file, buf, 1) != 1) {
            perror("Failed to write to the i2c device");
            exit(1);
        }

        // Read from the device
        if (read(file, buf, SENSORS_NUM) != SENSORS_NUM) {
            perror("Failed to read from the i2c device");
            exit(1);
        }

        // Compute lux
        lux = (buf[0] + buf[1] + buf[2] + buf[3] + buf[4] + buf[5] + buf[6] + buf[7] + buf[8] + buf[9]) / 10;

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);

        // Write to log file
        FILE *log_file = fopen("spectral_log.csv", "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(1);
        }
        fprintf(log_file, "%ld.%09ld,%d\n", ts.tv_sec, ts.tv_nsec, lux);
        fclose(log_file);

        // Wait for 5 seconds
        sleep(5);
    }

    close(file);
    return 0;
}

