        sleep(interval);
    }

    fclose(csv_file);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define BH1750_ADDRESS 0x23
#define BH1750_POWER_DOWN 0x00
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_CONVERSION_TIME 18000

int i2c_fd, udp_fd;
struct sockaddr_in udp_addr;
char buffer[256];

void signal_handler(int signum) {
    close(i2c_fd);
    close(udp_fd);
    exit(signum);
}

int main() {
    struct sigaction action;
    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open the i2c bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return 1;
    }

    if (write(i2c_fd, &BH1750_POWER_ON, 1) < 0) {
        perror("Failed to write to i2c slave");
        return 1;
    }

    if (write(i2c_fd, &BH1750_RESET, 1) < 0) {
        perror("Failed to write to i2c slave");
        return 1;
    }

    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) < 0) {
        perror("Failed to write to i2c slave");
        return 1;
    }

    if ((udp_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("Failed to create socket");
        return 1;
    }

    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(5000);
    udp_addr.sin_addr.s_addr = inet_addr("239.255.255.250");

    while (1) {
        uint16_t raw;
        float lux;

        if (read(i2c_fd, &raw, 2) < 0) {
            perror("Failed to read from i2c slave");
            sleep(1);
            continue;
        }

        raw = (raw >> 8) | (raw << 8);
        lux = (float)raw / 1.2;

        sprintf(buffer, "%f", lux);
        if (sendto(udp_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>
#include <libgpiod.h>

#define UART "/dev/ttyS0"
#define BAUDRATE B921600
#define MAGIC_WORD 0xDEADBEEF
#define TLV_TYPE_RANGE 0x01
#define TLV_TYPE_VELOCITY 0x02
#define CSV_FILE "radar_data.csv"

int uart_fd;
FILE *csv_fd;

void cleanup(int signum) {
    close(uart_fd);
    fclose(csv_fd);
    gpiod_cleanup();
    exit(signum);
}

int main() {
    struct termios options;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    unsigned int magic_word;
    unsigned char buffer[256];
    int bytes_read, i;

    // Open UART
    uart_fd = open(UART, O_RDONLY | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    // Configure UART
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    tcsetattr(uart_fd, TCSANOW, &options);

    // Open CSV file
    csv_fd = fopen(CSV_FILE, "w");
    if (csv_fd == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    // Write CSV header
    fprintf(csv_fd, "timestamp,object_index,range_m,velocity_mps\n");

    // Setup GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, 18);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    // Setup signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            perror("Error reading UART");
            continue;
        }

        for (i = 0; i < bytes_read; i++) {
            // Check for magic word
            magic_word = (magic_word << 8) | buffer[i];
            if (magic_word == MAGIC_WORD) {
                // Read TLV payload
                unsigned char tlv_type = buffer[i + 1];
                unsigned int tlv_length = buffer[i + 2];
                unsigned int tlv_value = buffer[i + 3];

                // Process TLV payload
                switch (tlv_type) {
                    case TLV_TYPE_RANGE:
                        // Write range to CSV
                        fprintf(csv_fd, "%ld,%d,%d\n", time(NULL), tlv_value, 0);
                        break;
                    case TLV_TYPE_VELOCITY:
                        // Write velocity to CSV
                        fprintf(csv_fd, "%ld,%d,%d\n", time(NULL), tlv_value, 1);
                        break;
                    default:
                        // Skip unknown TLV types
                        break;
                }

                // Skip TLV payload
                i += tlv_length + 3;
            }
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <termios.h>

#define UART "/dev/serial0"
#define BAUDRATE B115200
#define UART_TIMEOUT 2
#define INTER_BYTE_TIMEOUT 0.5
#define LINE_BUFFER_SIZE 256

static int uart_fd = -1;
static char line_buffer[LINE_BUFFER_SIZE];
static struct termios oldtio, newtio;

void close_uart(int signum) {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    tcsetattr(uart_fd, TCSANOW, &oldtio);
    exit(0);
}

int main() {
    struct sigaction sigIntHandler;
    sigIntHandler.sa_handler = close_uart;
    sigemptyset(&sigIntHandler.sa_mask);
    sigIntHandler.sa_flags = 0;
    sigaction(SIGINT, &sigIntHandler, NULL);
    sigaction(SIGTERM, &sigIntHandler, NULL);

    uart_fd = open(UART, O_RDONLY | O_NOCTTY);
    if (uart_fd < 0) {
        perror("Error opening UART");
        return -1;
    }

    tcgetattr(uart_fd, &oldtio);
    bzero(&newtio, sizeof(newtio));
    newtio.c_cflag = BAUDRATE | CS8 | CLOCAL | CREAD;
    newtio.c_iflag = IGNPAR;
    newtio.c_oflag = 0;
    newtio.c_lflag = 0;
    newtio.c_cc[VTIME] = INTER_BYTE_TIMEOUT;
    newtio.c_cc[VMIN] = 1;
    tcflush(uart_fd, TCIFLUSH);
    tcsetattr(uart_fd, TCSANOW, &newtio);

    while (1) {
        fd_set read_fds;
        struct timeval timeout;
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);
        timeout.tv_sec = UART_TIMEOUT;
        timeout.tv_usec = 0;
        int ret = select(uart_fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("Error in select");
            close_uart(0);
        } else if (ret == 0) {
            printf("No data received\n");
            continue;
        }

        int bytes_read = read(uart_fd, line_buffer, LINE_BUFFER_SIZE - 1);
        if (bytes_read < 0) {
            perror("Error reading UART");
            close_uart(0);
        }

        line_buffer[bytes_read] = '\0';
        printf("%s", line_buffer);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <termios.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUDRATE B115200
#define PERIOD 100 // 10 Hz

int uart_fd;
struct gpiod_chip *chip;
struct gpiod_line *lines[3];

void cleanup() {
    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_line_release(lines[2]);
    gpiod_chip_close(chip);
    close(uart_fd);
}

void signal_handler(int signum) {
    cleanup();
    exit(signum);
}

int main() {
    struct sigaction action;
    struct timespec req, rem;
    int left, middle, right;

    memset(&action, 0, sizeof(action));
    action.sa_handler = signal_handler;
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    lines[0] = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    lines[1] = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    lines[2] = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);

    for (int i = 0; i < 3; i++) {
        if (!gpiod_line_request_input(lines[i], "sensor_input")) {
            fprintf(stderr, "Failed to request line %d as input\n", i);
            cleanup();
            return 1;
        }
    }

    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        fprintf(stderr, "Failed to open UART device\n");
        cleanup();
        return 1;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);

    while (1) {
        nanosleep(&req, &rem);
        left = gpiod_line_get_value(lines[0]);
        middle = gpiod_line_get_value(lines[1]);
        right = gpiod_line_get_value(lines[2]);

        printf("%d %d %d\n", left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            write(uart_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n"));
        }
    }

    cleanup();
    return 0;
}
